window.ATLAS_READER_PAYLOAD={"id":"clasicos-Geoffrey Chaucer - Obras completas","title":"Title: The Canterbury Tales","libraryId":"clasicos","words":164832,"toc":[{"level":1,"title":"Title: The Canterbury Tales","anchor":"title-the-canterbury-tales","chunkIndex":0},{"level":2,"title":"Author: Geoffrey Chaucer","anchor":"author-geoffrey-chaucer","chunkIndex":0},{"level":2,"title":"Year: 1478","anchor":"year-1478","chunkIndex":0},{"level":3,"title":"Prologue","anchor":"prologue","chunkIndex":0},{"level":3,"title":"The Knight's Tale","anchor":"the-knight-s-tale","chunkIndex":0},{"level":3,"title":"The Miller's Prologue","anchor":"the-miller-s-prologue","chunkIndex":1},{"level":3,"title":"The Miller's Tale","anchor":"the-miller-s-tale","chunkIndex":1},{"level":3,"title":"The Reeve's Prologue","anchor":"the-reeve-s-prologue","chunkIndex":2},{"level":3,"title":"The Reeve's Tale","anchor":"the-reeve-s-tale","chunkIndex":2},{"level":3,"title":"The Cook's Prologue","anchor":"the-cook-s-prologue","chunkIndex":2},{"level":3,"title":"The Cook's Tale","anchor":"the-cook-s-tale","chunkIndex":2},{"level":3,"title":"Introduction To The Lawyer's Prologue","anchor":"introduction-to-the-lawyer-s-prologue","chunkIndex":2},{"level":3,"title":"The Lawyer's Prologue","anchor":"the-lawyer-s-prologue","chunkIndex":2},{"level":3,"title":"The Lawyer's Tale","anchor":"the-lawyer-s-tale","chunkIndex":2},{"level":3,"title":"The Wife of Bath's Prologue","anchor":"the-wife-of-bath-s-prologue","chunkIndex":3},{"level":3,"title":"The Tale of the Wife of Bath","anchor":"the-tale-of-the-wife-of-bath","chunkIndex":3},{"level":3,"title":"The Friar's Prologue","anchor":"the-friar-s-prologue","chunkIndex":4},{"level":3,"title":"The Friar's Tale","anchor":"the-friar-s-tale","chunkIndex":4},{"level":3,"title":"The Summoner's Prologue","anchor":"the-summoner-s-prologue","chunkIndex":4},{"level":3,"title":"The Summoner's Tale","anchor":"the-summoner-s-tale","chunkIndex":4},{"level":3,"title":"The Clerk's Prologue","anchor":"the-clerk-s-prologue","chunkIndex":4},{"level":3,"title":"The Clerk's Tale","anchor":"the-clerk-s-tale","chunkIndex":4},{"level":3,"title":"The Merchant's Prologue","anchor":"the-merchant-s-prologue","chunkIndex":5},{"level":3,"title":"The Merchant's Tale","anchor":"the-merchant-s-tale","chunkIndex":5},{"level":2,"title":"The Merchant's Epilogue","anchor":"the-merchant-s-epilogue","chunkIndex":6},{"level":3,"title":"The Squire's Prologue","anchor":"the-squire-s-prologue","chunkIndex":6},{"level":3,"title":"The Squire's Tale","anchor":"the-squire-s-tale","chunkIndex":6},{"level":3,"title":"The Words of Franklin and the Host","anchor":"the-words-of-franklin-and-the-host","chunkIndex":6},{"level":3,"title":"The Franklin's Prologue","anchor":"the-franklin-s-prologue","chunkIndex":6},{"level":3,"title":"The Franklin's Tale","anchor":"the-franklin-s-tale","chunkIndex":6},{"level":3,"title":"The Physician's Tale","anchor":"the-physician-s-tale","chunkIndex":7},{"level":3,"title":"The Words of the Host","anchor":"the-words-of-the-host","chunkIndex":7},{"level":3,"title":"The Pardoner's Prologue","anchor":"the-pardoner-s-prologue","chunkIndex":7},{"level":3,"title":"The Pardoner's Tale","anchor":"the-pardoner-s-tale","chunkIndex":7},{"level":3,"title":"The Shipman's Prologue","anchor":"the-shipman-s-prologue","chunkIndex":7},{"level":3,"title":"The Shipman's Tale","anchor":"the-shipman-s-tale","chunkIndex":7},{"level":3,"title":"The Words of the Host to the Prioress","anchor":"the-words-of-the-host-to-the-prioress","chunkIndex":8},{"level":3,"title":"The Prioress's Prologue","anchor":"the-prioress-s-prologue","chunkIndex":8},{"level":3,"title":"The Prioress's Tale","anchor":"the-prioress-s-tale","chunkIndex":8},{"level":3,"title":"Sir Topas's Prologue","anchor":"sir-topas-s-prologue","chunkIndex":8},{"level":3,"title":"Sir Topas's Tale","anchor":"sir-topas-s-tale","chunkIndex":8},{"level":3,"title":"Melibeus's Prologue","anchor":"melibeus-s-prologue","chunkIndex":8},{"level":3,"title":"The Tale of Melibeus","anchor":"the-tale-of-melibeus","chunkIndex":8},{"level":3,"title":"The Monk's Prologue","anchor":"the-monk-s-prologue","chunkIndex":9},{"level":3,"title":"The Monk's Tale","anchor":"the-monk-s-tale","chunkIndex":9},{"level":3,"title":"The Nun's Priest's Prologue","anchor":"the-nun-s-priest-s-prologue","chunkIndex":10},{"level":3,"title":"The Nun's Priest's Tale","anchor":"the-nun-s-priest-s-tale","chunkIndex":10},{"level":3,"title":"The Nun's Priest's Epilogue","anchor":"the-nun-s-priest-s-epilogue","chunkIndex":10},{"level":3,"title":"The Second Nun's Prologue","anchor":"the-second-nun-s-prologue","chunkIndex":10},{"level":3,"title":"The Second Nun's Tale","anchor":"the-second-nun-s-tale","chunkIndex":10},{"level":3,"title":"The Canon's Yeoman's Prologue","anchor":"the-canon-s-yeoman-s-prologue","chunkIndex":11},{"level":3,"title":"The Canon's Yeoman's Tale","anchor":"the-canon-s-yeoman-s-tale","chunkIndex":11},{"level":3,"title":"The Manciple's Prologue","anchor":"the-manciple-s-prologue","chunkIndex":11},{"level":3,"title":"The Manciple's Tale","anchor":"the-manciple-s-tale","chunkIndex":11},{"level":3,"title":"The Parson's Prologue","anchor":"the-parson-s-prologue","chunkIndex":12},{"level":3,"title":"The Parson's Tale","anchor":"the-parson-s-tale","chunkIndex":12},{"level":2,"title":"Prayer of Chaucer","anchor":"prayer-of-chaucer","chunkIndex":12}],"chunks":[{"index":0,"markdown":"# Title: The Canterbury Tales\n\n## Author: Geoffrey Chaucer\n\n## Year: 1478\n\n-------\n\n### Prologue\n\nWhen April with his showers sweet with fruit\nThe drought of March has pierced unto the root\nAnd bathed each vein with liquor that has power\nTo generate therein and sire the flower;\nWhen Zephyr also has, with his sweet breath,\nQuickened again, in every holt and heath,\nThe tender shoots and buds, and the young sun\nInto the Ram one half his course has run,\nAnd many little birds make melody\nThat sleep through all the night with open eye\n(So Nature pricks them on to ramp and rage)-\nThen do folk long to go on pilgrimage,\nAnd palmers to go seeking out strange strands,\nTo distant shrines well known in sundry lands.\nAnd specially from every shire's end\nOf England they to Canterbury wend,\nThe holy blessed martyr there to seek\nWho helped them when they lay so ill and weal\nBefell that, in that season, on a day\nIn Southwark, at the Tabard, as I lay\nReady to start upon my pilgrimage\nTo Canterbury, full of devout homage,\nThere came at nightfall to that hostelry\nSome nine and twenty in a company\nOf sundry persons who had chanced to fall\nIn fellowship, and pilgrims were they all\nThat toward Canterbury town would ride.\nThe rooms and stables spacious were and wide,\nAnd well we there were eased, and of the best.\nAnd briefly, when the sun had gone to rest,\nSo had I spoken with them, every one,\nThat I was of their fellowship anon,\nAnd made agreement that we'd early rise\nTo take the road, as you I will apprise.\nBut none the less, whilst I have time and space,\nBefore yet farther in this tale I pace,\nIt seems to me accordant with reason\nTo inform you of the state of every one\nOf all of these, as it appeared to me,\nAnd who they were, and what was their degree,\nAnd even how arrayed there at the inn;\nAnd with a knight thus will I first begin.\nA knight there was, and he a worthy man,\nWho, from the moment that he first began\nTo ride about the world, loved chivalry,\nTruth, honour, freedom and all courtesy.\nFull worthy was he in his liege-lord's war,\nAnd therein had he ridden (none more far)\nAs well in Christendom as heathenesse,\nAnd honoured everywhere for worthiness.\nAt Alexandria, he, when it was won;\nFull oft the table's roster he'd begun\nAbove all nations' knights in Prussia.\nIn Latvia raided he, and Russia,\nNo christened man so oft of his degree.\nIn far Granada at the siege was he\nOf Algeciras, and in Belmarie.\nAt Ayas was he and at Satalye\nWhen they were won; and on the Middle Sea\nAt many a noble meeting chanced to be.\nOf mortal battles he had fought fifteen,\nAnd he'd fought for our faith at Tramissene\nThree times in lists, and each time slain his foe.\nThis self-same worthy knight had been also\nAt one time with the lord of Palatye\nAgainst another heathen in Turkey:\nAnd always won he sovereign fame for prize.\nThough so illustrious, he was very wise\nAnd bore himself as meekly as a maid.\nHe never yet had any vileness said,\nIn all his life, to whatsoever wight.\nHe was a truly perfect, gentle knight.\nBut now, to tell you all of his array,\nHis steeds were good, but yet he was not gay.\nOf simple fustian wore he a jupon\nSadly discoloured by his habergeon;\nFor he had lately come from his voyage\nAnd now was going on this pilgrimage.\nWith him there was his son, a youthful squire,\nA lover and a lusty bachelor,\nWith locks well curled, as if they'd laid in press.\nSome twenty years of age he was, I guess.\nIn stature he was of an average length,\nWondrously active, aye, and great of strength.\nHe'd ridden sometime with the cavalry\nIn Flanders, in Artois, and Picardy,\nAnd borne him well within that little space\nIn hope to win thereby his lady's grace.\nPrinked out he was, as if he were a mead,\nAll full of fresh-cut flowers white and red.\nSinging he was, or fluting, all the day;\nHe was as fresh as is the month of May.\nShort was his gown, with sleeves both long and wide.\nWell could be sit on horse, and fairly ride.\nHe could make songs and words thereto indite,\nJoust, and dance too, as well as sketch and write.\nSo hot he loved that, while night told her tale,\nHe slept no more than does a nightingale.\nCourteous he, and humble, willing and able,\nAnd carved before his father at the table.\nA yeoman had he, nor more servants, no,\nAt that time, for he chose to travel so;\nAnd he was clad in coat and hood of green.\nA sheaf of peacock arrows bright and keen\nUnder his belt he bore right carefully\n(Well could he keep his tackle yeomanly:\nHis arrows had no draggled feathers low),\nAnd in his hand he bore a mighty bow.\nA cropped head had he and a sun-browned face.\nOf woodcraft knew he all the useful ways.\nUpon his arm he bore a bracer gay,\nAnd at one side a sword and buckler, yea,\nAnd at the other side a dagger bright,\nWell sheathed and sharp as spear point in the light;\nOn breast a Christopher of silver sheen.\nHe bore a horn in baldric all of green;\nA forester he truly was, I guess.\nThere was also a nun, a prioress,\nWho, in her smiling, modest was and coy;\nHer greatest oath was but By Saint Eloy!\nAnd she was known as Madam Eglantine.\nFull well she sang the services divine,\nIntoning through her nose, becomingly;\nAnd fair she spoke her French, and fluently,\nAfter the school of Stratford-at-the-Bow,\nFor French of Paris was not hers to know.\nAt table she had been well taught withal,\nAnd never from her lips let morsels fall,\nNor dipped her fingers deep in sauce, but ate\nWith so much care the food upon her plate\nThat never driblet fell upon her breast.\nIn courtesy she had delight and zest.\nHer upper lip was always wiped so clean\nThat in her cup was no iota seen\nOf grease, when she had drunk her draught of wine.\nBecomingly she reached for meat to dine.\nAnd certainly delighting in good sport,\nShe was right pleasant, amiable- in short.\nShe was at pains to counterfeit the look\nOf courtliness, and stately manners took,\nAnd would be held worthy of reverence.\nBut, to say something of her moral sense,\nShe was so charitable and piteous\nThat she would weep if she but saw a mouse\nCaught in a trap, though it were dead or bled.\nShe had some little dogs, too, that she fed\nOn roasted flesh, or milk and fine white bread.\nBut sore she'd weep if one of them were dead,\nOr if men smote it with a rod to smart:\nFor pity ruled her, and her tender heart.\nRight decorous her pleated wimple was;\nHer nose was fine; her eyes were blue as glass;\nHer mouth was small and therewith soft and red;\nBut certainly she had a fair forehead;\nIt was almost a full span broad, I own,\nFor, truth to tell, she was not undergrown.\nNeat was her cloak, as I was well aware.\nOf coral small about her arm she'd bear\nA string of beads and gauded all with green;\nAnd therefrom hung a brooch of golden sheen\nWhereon there was first written a crowned A,\nAnd under, Amor vincit omnia.\nAnother little nun with her had she,\nWho was her chaplain; and of priests she'd three.\nA monk there was, one made for mastery,\nAn outrider, who loved his venery;\nA manly man, to be an abbot able.\nFull many a blooded horse had he in stable:\nAnd when he rode men might his bridle hear\nA-jingling in the whistling wind as clear,\nAye, and as loud as does the chapel bell\nWhere this brave monk was of the cell.\nThe rule of Maurus or Saint Benedict,\nBy reason it was old and somewhat strict,\nThis said monk let such old things slowly pace\nAnd followed new-world manners in their place.\nHe cared not for that text a clean-plucked hen\nWhich holds that hunters are not holy men;\nNor that a monk, when he is cloisterless,\nIs like unto a fish that's waterless;\nThat is to say, a monk out of his cloister.\nBut this same text he held not worth an oyster;\nAnd I said his opinion was right good.\nWhat? Should he study as a madman would\nUpon a book in cloister cell? Or yet\nGo labour with his hands and swink and sweat,\nAs Austin bids? How shall the world be served?\nLet Austin have his toil to him reserved.\nTherefore he was a rider day and night;\nGreyhounds he had, as swift as bird in flight.\nSince riding and the hunting of the hare\nWere all his love, for no cost would he spare.\nI saw his sleeves were purfled at the hand\nWith fur of grey, the finest in the land;\nAlso, to fasten hood beneath his chin,\nHe had of good wrought gold a curious pin:\nA love-knot in the larger end there was.\nHis head was bald and shone like any glass,\nAnd smooth as one anointed was his face.\nFat was this lord, he stood in goodly case.\nHis bulging eyes he rolled about, and hot\nThey gleamed and red, like fire beneath a pot;\nHis boots were soft; his horse of great estate.\nNow certainly he was a fine prelate:\nHe was not pale as some poor wasted ghost.\nA fat swan loved he best of any roast.\nHis palfrey was as brown as is a berry.\nA friar there was, a wanton and a merry,\nA limiter, a very festive man.\nIn all the Orders Four is none that can\nEqual his gossip and his fair language.\nHe had arranged full many a marriage\nOf women young, and this at his own cost.\nUnto his order he was a noble post.\nWell liked by all and intimate was he\nWith franklins everywhere in his country,\nAnd with the worthy women of the town:\nFor at confessing he'd more power in gown\n(As he himself said) than it good curate,\nFor of his order he was licentiate.\nHe heard confession gently, it was said,\nGently absolved too, leaving naught of dread.\nHe was an easy man to give penance\nWhen knowing he should gain a good pittance;\nFor to a begging friar, money given\nIs sign that any man has been well shriven.\nFor if one gave (he dared to boast of this),\nHe took the man's repentance not amiss.\nFor many a man there is so hard of heart\nHe cannot weep however pains may smart.\nTherefore, instead of weeping and of prayer,\nMen should give silver to poor friars all bare.\nHis tippet was stuck always full of knives\nAnd pins, to give to young and pleasing wives.\nAnd certainly he kept a merry note:\nWell could he sing and play upon the rote.\nAt balladry he bore the prize away.\nHis throat was white as lily of the May;\nYet strong he was as ever champion.\nIn towns he knew the taverns, every one,\nAnd every good host and each barmaid too-\nBetter than begging lepers, these he knew.\nFor unto no such solid man as he\nAccorded it, as far as he could see,\nTo have sick lepers for acquaintances.\nThere is no honest advantageousness\nIn dealing with such poverty-stricken curs;\nIt's with the rich and with big victuallers.\nAnd so, wherever profit might arise,\nCourteous he was and humble in men's eyes.\nThere was no other man so virtuous.\nHe was the finest beggar of his house;\nA certain district being farmed to him,\nNone of his brethren dared approach its rim;\nFor though a widow had no shoes to show,\nSo pleasant was his In principio,\nHe always got a farthing ere he went.\nHe lived by pickings, it is evident.\nAnd he could romp as well as any whelp.\nOn love days could he be of mickle help.\nFor there he was not like a cloisterer,\nWith threadbare cope as is the poor scholar,\nBut he was like a lord or like a pope.\nOf double worsted was his semi-cope,\nThat rounded like a bell, as you may guess.\nHe lisped a little, out of wantonness,\nTo make his English soft upon his tongue;\nAnd in his harping, after he had sung,\nHis two eyes twinkled in his head as bright\nAs do the stars within the frosty night.\nThis worthy limiter was named Hubert.\nThere was a merchant with forked beard, and girt\nIn motley gown, and high on horse he sat,\nUpon his head a Flemish beaver hat;\nHis boots were fastened rather elegantly.\nHis spoke his notions out right pompously,\nStressing the times when he had won, not lost.\nHe would the sea were held at any cost\nAcross from Middleburgh to Orwell town.\nAt money-changing he could make a crown.\nThis worthy man kept all his wits well set;\nThere was no one could say he was in debt,\nSo well he governed all his trade affairs\nWith bargains and with borrowings and with shares.\nIndeed, he was a worthy man withal,\nBut, sooth to say, his name I can't recall.\nA clerk from Oxford was with us also,\nWho'd turned to getting knowledge, long ago.\nAs meagre was his horse as is a rake,\nNor he himself too fat, I'll undertake,\nBut he looked hollow and went soberly.\nRight threadbare was his overcoat; for he\nHad got him yet no churchly benefice,\nNor was so worldly as to gain office.\nFor he would rather have at his bed's head\nSome twenty books, all bound in black and red,\nOf Aristotle and his philosophy\nThan rich robes, fiddle, or gay psaltery.\nYet, and for all he was philosopher,\nHe had but little gold within his coffer;\nBut all that he might borrow from a friend\nOn books and learning he would swiftly spend,\nAnd then he'd pray right busily for the souls\nOf those who gave him wherewithal for schools.\nOf study took he utmost care and heed.\nNot one word spoke he more than was his need;\nAnd that was said in fullest reverence\nAnd short and quick and full of high good sense.\nPregnant of moral virtue was his speech;\nAnd gladly would he learn and gladly teach.\nA sergeant of the law, wary and wise,\nWho'd often gone to Paul's walk to advise,\nThere was also, compact of excellence.\nDiscreet he was, and of great reverence;\nAt least he seemed so, his words were so wise.\nOften he sat as justice in assize,\nBy patent or commission from the crown;\nBecause of learning and his high renown,\nHe took large fees and many robes could own.\nSo great a purchaser was never known.\nAll was fee simple to him, in effect,\nWherefore his claims could never be suspect.\nNowhere a man so busy of his class,\nAnd yet he seemed much busier than he was.\nAll cases and all judgments could he cite\nThat from King William's time were apposite.\nAnd he could draw a contract so explicit\nNot any man could fault therefrom elicit;\nAnd every statute he'd verbatim quote.\n\nHe rode but badly in a medley coat,\nBelted in a silken sash, with little bars,\nBut of his dress no more particulars.\nThere was a franklin in his company;\nWhite was his beard as is the white daisy.\nOf sanguine temperament by every sign,\nHe loved right well his morning sop in wine.\nDelightful living was the goal he'd won,\nFor he was Epicurus' very son,\nThat held opinion that a full delight\nWas true felicity, perfect and right.\nA householder, and that a great, was he;\nSaint Julian he was in his own country.\nHis bread and ale were always right well done;\nA man with better cellars there was none.\nBaked meat was never wanting in his house,\nOf fish and flesh, and that so plenteous\nIt seemed to snow therein both food and drink\nOf every dainty that a man could think.\nAccording to the season of the year\nHe changed his diet and his means of cheer.\nFull many a fattened partridge did he mew,\nAnd many a bream and pike in fish-pond too.\nWoe to his cook, except the sauces were\nPoignant and sharp, and ready all his gear.\nHis table, waiting in his hall alway,\nStood ready covered through the livelong day.\nAt county sessions was he lord and sire,\nAnd often acted as a knight of shire.\nA dagger and a trinket-bag of silk\nHung from his girdle, white as morning milk.\nHe had been sheriff and been auditor;\nAnd nowhere was a worthier vavasor.\nA haberdasher and a carpenter,\nAn arras-maker, dyer, and weaver\nWere with us, clothed in similar livery,\nAll of one sober, great fraternity.\nTheir gear was new and well adorned it was;\nTheir weapons were not cheaply trimmed with brass,\nBut all with silver; chastely made and well\nTheir girdles and their pouches too, I tell.\nEach man of them appeared a proper burges\nTo sit in guildhall on a high dais.\nAnd each of them, for wisdom he could span,\nWas fitted to have been an alderman;\nFor chattels they'd enough, and, too, of rent;\nTo which their goodwives gave a free assent,\nOr else for certain they had been to blame.\nIt's good to hear Madam before one's name,\nAnd go to church when all the world may see,\nHaving one's mantle borne right royally.\nA cook they had with them, just for the nonce,\nTo boil the chickens with the marrow-bones,\nAnd flavour tartly and with galingale.\nWell could he tell a draught of London ale.\nAnd he could roast and seethe and broil and fry,\nAnd make a good thick soup, and bake a pie.\nBut very ill it was, it seemed to me,\nThat on his shin a deadly sore had he;\nFor sweet blanc-mange, he made it with the best.\nThere was a sailor, living far out west;\nFor aught I know, he was of Dartmouth town.\nHe sadly rode a hackney, in a gown,\nOf thick rough cloth falling to the knee.\nA dagger hanging on a cord had he\nAbout his neck, and under arm, and down.\nThe summer's heat had burned his visage brown;\nAnd certainly he was a good fellow.\nFull many a draught of wine he'd drawn, I trow,\nOf Bordeaux vintage, while the trader slept.\nNice conscience was a thing he never kept.\nIf that he fought and got the upper hand,\nBy water he sent them home to every land.\nBut as for craft, to reckon well his tides,\nHis currents and the dangerous watersides,\nHis harbours, and his moon, his pilotage,\nThere was none such from Hull to far Carthage.\nHardy. and wise in all things undertaken,\nBy many a tempest had his beard been shaken.\nHe knew well all the havens, as they were,\nFrom Gottland to the Cape of Finisterre,\nAnd every creek in Brittany and Spain;\nHis vessel had been christened Madeleine.\nWith us there was a doctor of physic;\nIn all this world was none like him to pick\nFor talk of medicine and surgery;\nFor he was grounded in astronomy.\nHe often kept a patient from the pall\nBy horoscopes and magic natural.\nWell could he tell the fortune ascendent\nWithin the houses for his sick patient.\nHe knew the cause of every malady,\nWere it of hot or cold, of moist or dry,\nAnd where engendered, and of what humour;\nHe was a very good practitioner.\nThe cause being known, down to the deepest root,\nAnon he gave to the sick man his boot.\nReady he was, with his apothecaries,\nTo send him drugs and all electuaries;\nBy mutual aid much gold they'd always won-\nTheir friendship was a thing not new begun.\nWell read was he in Esculapius,\nAnd Deiscorides, and in Rufus,\nHippocrates, and Hali, and Galen,\nSerapion, Rhazes, and Avicen,\nAverrhoes, Gilbert, and Constantine,\nBernard and Gatisden, and John Damascene.\nIn diet he was measured as could be,\nIncluding naught of superfluity,\nBut nourishing and easy. It's no libel\nTo say he read but little in the Bible.\nIn blue and scarlet he went clad, withal,\nLined with a taffeta and with sendal;\nAnd yet he was right chary of expense;\nHe kept the gold he gained from pestilence.\nFor gold in physic is a fine cordial,\nAnd therefore loved he gold exceeding all.\nThere was a housewife come from Bath, or near,\nWho- sad to say- was deaf in either ear.\nAt making cloth she had so great a bent\nShe bettered those of Ypres and even of Ghent.\nIn all the parish there was no goodwife\nShould offering make before her, on my life;\nAnd if one did, indeed, so wroth was she\nIt put her out of all her charity.\nHer kerchiefs were of finest weave and ground;\nI dare swear that they weighed a full ten pound\nWhich, of a Sunday, she wore on her head.\nHer hose were of the choicest scarlet red,\nClose gartered, and her shoes were soft and new.\nBold was her face, and fair, and red of hue.\nShe'd been respectable throughout her life,\nWith five churched husbands bringing joy and strife,\nNot counting other company in youth;\nBut thereof there's no need to speak, in truth.\nThree times she'd journeyed to Jerusalem;\nAnd many a foreign stream she'd had to stem;\nAt Rome she'd been, and she'd been in Boulogne,\nIn Spain at Santiago, and at Cologne.\nShe could tell much of wandering by the way:\nGap-toothed was she, it is no lie to say.\nUpon an ambler easily she sat,\nWell wimpled, aye, and over all a hat\nAs broad as is a buckler or a targe;\nA rug was tucked around her buttocks large,\nAnd on her feet a pair of sharpened spurs.\nIn company well could she laugh her slurs.\nThe remedies of love she knew, perchance,\nFor of that art she'd learned the old, old dance.\nThere was a good man of religion, too,\nA country parson, poor, I warrant you;\nBut rich he was in holy thought and work.\nHe was a learned man also, a clerk,\nWho Christ's own gospel truly sought to preach;\nDevoutly his parishioners would he teach.\nBenign he was and wondrous diligent,\nPatient in adverse times and well content,\nAs he was ofttimes proven; always blithe,\nHe was right loath to curse to get a tithe,\nBut rather would he give, in case of doubt,\nUnto those poor parishioners about,\nPart of his income, even of his goods.\nEnough with little, coloured all his moods.\nWide was his parish, houses far asunder,\nBut never did he fail, for rain or thunder,\nIn sickness, or in sin, or any state,\nTo visit to the farthest, small and great,\nGoing afoot, and in his hand, a stave.\nThis fine example to his flock he gave,\nThat first he wrought and afterwards he taught;\nOut of the gospel then that text he caught,\nAnd this figure he added thereunto-\nThat, if gold rust, what shall poor iron do?\nFor if the priest be foul, in whom we trust,\nWhat wonder if a layman yield to lust?\nAnd shame it is, if priest take thought for keep,\nA shitty shepherd, shepherding clean sheep.\nWell ought a priest example good to give,\nBy his own cleanness, how his flock should live.\nHe never let his benefice for hire,\nLeaving his flock to flounder in the mire,\nAnd ran to London, up to old Saint Paul's\nTo get himself a chantry there for souls,\nNor in some brotherhood did he withhold;\nBut dwelt at home and kept so well the fold\nThat never wolf could make his plans miscarry;\nHe was a shepherd and not mercenary.\nAnd holy though he was, and virtuous,\nTo sinners he was not impiteous,\nNor haughty in his speech, nor too divine,\nBut in all teaching prudent and benign.\nTo lead folk into Heaven but by stress\nOf good example was his busyness.\nBut if some sinful one proved obstinate,\nBe who it might, of high or low estate,\nHim he reproved, and sharply, as I know.\nThere is nowhere a better priest, I trow.\nHe had no thirst for pomp or reverence,\nNor made himself a special, spiced conscience,\nBut Christ's own lore, and His apostles' twelve\nHe taught, but first he followed it himselve.\nWith him there was a plowman, was his brother,\nThat many a load of dung, and many another\nHad scattered, for a good true toiler, he,\nLiving in peace and perfect charity.\nHe loved God most, and that with his whole heart\nAt all times, though he played or plied his art,\nAnd next, his neighbour, even as himself.\nHe'd thresh and dig, with never thought of pelf,\nFor Christ's own sake, for every poor wight,\nAll without pay, if it lay in his might.\nHe paid his taxes, fully, fairly, well,\nBoth by his own toil and by stuff he'd sell.\nIn a tabard he rode upon a mare.\nThere were also a reeve and miller there;\nA summoner, manciple and pardoner,\nAnd these, beside myself, made all there were.\nThe miller was a stout churl, be it known,\nHardy and big of brawn and big of bone;\nWhich was well proved, for when he went on lam\nAt wrestling, never failed he of the ram.\nHe was a chunky fellow, broad of build;\nHe'd heave a door from hinges if he willed,\nOr break it through, by running, with his head.\nHis beard, as any sow or fox, was red,\nAnd broad it was as if it were a spade.\nUpon the coping of his nose he had\nA wart, and thereon stood a tuft of hairs,\nRed as the bristles in an old sow's ears;\nHis nostrils they were black and very wide.\nA sword and buckler bore he by his side.\nHis mouth was like a furnace door for size.\nHe was a jester and could poetize,\nBut mostly all of sin and ribaldries.\nHe could steal corn and full thrice charge his fees;\nAnd yet he had a thumb of gold, begad.\nA white coat and blue hood he wore, this lad.\nA bagpipe he could blow well, be it known,\nAnd with that same he brought us out of town.\nThere was a manciple from an inn of court,\nTo whom all buyers might quite well resort\nTo learn the art of buying food and drink;\nFor whether he paid cash or not, I think\nThat he so knew the markets, when to buy,\nHe never found himself left high and dry.\nNow is it not of God a full fair grace\nThat such a vulgar man has wit to pace\nThe wisdom of a crowd of learned men?\nOf masters had he more than three times ten,\nWho were in law expert and curious;\nWhereof there were a dozen in that house\nFit to be stewards of both rent and land\nOf any lord in England who would stand\nUpon his own and live in manner good,\nIn honour, debtless (save his head were wood),\nOr live as frugally as he might desire;\nThese men were able to have helped a shire\nIn any case that ever might befall;\nAnd yet this manciple outguessed them all.\nThe reeve he was a slender, choleric man\nWho shaved his beard as close as razor can.\nHis hair was cut round even with his ears;\nHis top was tonsured like a pulpiteer's.\nLong were his legs, and they were very lean,\nAnd like a staff, with no calf to be seen.\nWell could he manage granary and bin;\nNo auditor could ever on him win.\nHe could foretell, by drought and by the rain,\nThe yielding of his seed and of his grain.\nHis lord's sheep and his oxen and his dairy,\nHis swine and horses, all his stores, his poultry,\nWere wholly in this steward's managing;\nAnd, by agreement, he'd made reckoning\nSince his young lord of age was twenty years;\nYet no man ever found him in arrears.\nThere was no agent, hind, or herd who'd cheat\nBut he knew well his cunning and deceit;\nThey were afraid of him as of the death.\n\nHis cottage was a good one, on a heath;\nBy green trees shaded with this dwelling-place.\nMuch better than his lord could he purchase.\nRight rich he was in his own private right,\nSeeing he'd pleased his lord, by day or night,\nBy giving him, or lending, of his goods,\nAnd so got thanked- but yet got coats and hoods.\nIn youth he'd learned a good trade, and had been\nA carpenter, as fine as could be seen.\nThis steward sat a horse that well could trot,\nAnd was all dapple-grey, and was named Scot.\nA long surcoat of blue did he parade,\nAnd at his side he bore a rusty blade.\nOf Norfolk was this reeve of whom I tell,\nFrom near a town that men call Badeswell.\nBundled he was like friar from chin to croup,\nAnd ever he rode hindmost of our troop.\nA summoner was with us in that place,\nWho had a fiery-red, cherubic face,\nFor eczema he had; his eyes were narrow\nAs hot he was, and lecherous, as a sparrow;\nWith black and scabby brows and scanty beard;\nHe had a face that little children feared.\nThere was no mercury, sulphur, or litharge,\nNo borax, ceruse, tartar, could discharge,\nNor ointment that could cleanse enough, or bite,\nTo free him of his boils and pimples white,\nNor of the bosses resting on his cheeks.\nWell loved he garlic, onions, aye and leeks,\nAnd drinking of strong wine as red as blood.\nThen would he talk and shout as madman would.\nAnd when a deal of wine he'd poured within,\nThen would. he utter no word save Latin.\nSome phrases had he learned, say two or three,\nWhich he had garnered out of some decree;\nNo wonder, for he'd heard it all the day;\nAnd all you know right well that even a jay\nCan call out Wat as well as can the pope.\nBut when, for aught else, into him you'd grope,\n'Twas found he'd spent his whole philosophy;\nJust Questio quid juris would he cry.\nHe was a noble rascal, and a kind;\nA better comrade 'twould be hard to find.\nWhy, he would suffer, for a quart of wine,\nSome good fellow to have his concubine\nA twelve-month, and excuse him to the full\n(Between ourselves, though, he could pluck a gull).\nAnd if he chanced upon a good fellow,\nHe would instruct him never to have awe,\nIn such a case, of the archdeacon's curse,\nExcept a man's soul lie within his purse;\nFor in his purse the man should punished be.\nThe purse is the archdeacon's Hell, said he.\nBut well I know he lied in what he said;\nA curse ought every guilty man to dread\n(For curse can kill, as absolution save),\nAnd 'ware significavit to the grave.\nIn his own power had he, and at ease,\nThe boys and girls of all the diocese,\nAnd knew their secrets, and by counsel led.\nA garland had he set upon his head,\nLarge as a tavern's wine-bush on a stake;\nA buckler had he made of bread they bake.\nWith him there rode a gentle pardoner\nOf Rouncival, his friend and his compeer;\nStraight from the court of Rome had journeyed he.\nLoudly he sang Come hither, love, to me,\nThe summoner joining with a burden round;\nWas never horn of half so great a sound.\nThis pardoner had hair as yellow as wax,\nBut lank it hung as does a strike of flax;\nIn wisps hung down such locks as he'd on head,\nAnd with them he his shoulders overspread;\nBut thin they dropped, and stringy, one by one.\nBut as to hood, for sport of it, he'd none,\nThough it was packed in wallet all the while.\nIt seemed to him he went in latest style,\nDishevelled, save for cap, his head all bare.\nAs shiny eyes he had as has a hare.\nHe had a fine veronica sewed to cap.\nHis wallet lay before him in his lap,\nStuffed full of pardons brought from Rome all hot.\nA voice he had that bleated like a goat.\nNo beard had he, nor ever should he have,\nFor smooth his face as he'd just had a shave;\nI think he was a gelding or a mare.\nBut in his craft, from Berwick unto Ware,\nWas no such pardoner in any place.\nFor in his bag he had a pillowcase\nThe which, he said, was Our True Lady's veil:\nHe said he had a piece of the very sail\nThat good Saint Peter had, what time he went\nUpon the sea, till Jesus changed his bent.\nHe had a latten cross set full of stones,\nAnd in a bottle had he some pig's bones.\nBut with these relics, when he came upon\nSome simple parson, then this paragon\nIn that one day more money stood to gain\nThan the poor dupe in two months could attain.\nAnd thus, with flattery and suchlike japes,\nHe made the parson and the rest his apes.\nBut yet, to tell the whole truth at the last,\nHe was, in church, a fine ecclesiast.\nWell could he read a lesson or a story,\nBut best of all he sang an offertory;\nFor well he knew that when that song was sung,\nThen might he preach, and all with polished tongue.\nTo win some silver, as he right well could;\nTherefore he sang so merrily and so loud.\nNow have I told you briefly, in a clause,\nThe state, the array, the number, and the cause\nOf the assembling of this company\nIn Southwark, at this noble hostelry\nKnown as the Tabard Inn, hard by the Bell.\nBut now the time is come wherein to tell\nHow all we bore ourselves that very night\nWhen at the hostelry we did alight.\nAnd afterward the story I engage\nTo tell you of our common pilgrimage.\nBut first, I pray you, of your courtesy,\nYou'll not ascribe it to vulgarity\nThough I speak plainly of this matter here,\nRetailing you their words and means of cheer;\nNor though I use their very terms, nor lie.\nFor this thing do you know as well as I:\nWhen one repeats a tale told by a man,\nHe must report, as nearly as he can,\nEvery least word, if he remember it,\nHowever rude it be, or how unfit;\nOr else he may be telling what's untrue,\nEmbellishing and fictionizing too.\nHe may not spare, although it were his brother;\nHe must as well say one word as another.\nChrist spoke right broadly out, in holy writ,\nAnd, you know well, there's nothing low in it.\nAnd Plato says, to those able to read:\nThe word should be the cousin to the deed.\nAlso, I pray that you'll forgive it me\nIf I have not set folk, in their degree\nHere in this tale, by rank as they should stand.\nMy wits are not the best, you'll understand.\nGreat cheer our host gave to us, every one,\nAnd to the supper set us all anon;\nAnd served us then with victuals of the best.\nStrong was the wine and pleasant to each guest.\nA seemly man our good host was, withal,\nFit to have been a marshal in some hall;\nHe was a large man, with protruding eyes,\nAs fine a burgher as in Cheapside lies;\nBold in his speech, and wise, and right well taught,\nAnd as to manhood, lacking there in naught.\nAlso, he was a very merry man,\nAnd after meat, at playing he began,\nSpeaking of mirth among some other things,\nWhen all of us had paid our reckonings;\nAnd saying thus: Now masters, verily\nYou are all welcome here, and heartily:\nFor by my truth, and telling you no lie,\nI have not seen, this year, a company\nHere in this inn, fitter for sport than now.\nFain would I make you happy, knew I how.\nAnd of a game have I this moment thought\nTo give you joy, and it shall cost you naught.\nYou go to Canterbury; may God speed\nAnd the blest martyr soon requite your meed.\nAnd well I know, as you go on your way,\nYou'll tell good tales and shape yourselves to play;\nFor truly there's no mirth nor comfort, none,\nRiding the roads as dumb as is a stone;\nAnd therefore will I furnish you a sport,\nAs I just said, to give you some comfort.\nAnd if you like it, all, by one assent,\nAnd will be ruled by me, of my judgment,\nAnd will so do as I'll proceed to say,\nTomorrow, when you ride upon your way,\nThen, by my father's spirit, who is dead,\nIf you're not gay, I'll give you up my head.\nHold up your hands, nor more about it speak.\nOur full assenting was not far to seek;\nWe thought there was no reason to think twice,\nAnd granted him his way without advice,\nAnd bade him tell his verdict just and wise,\nMasters, quoth he, here now is my advice;\nBut take it not, I pray you, in disdain;\nThis is the point, to put it short and plain,\nThat each of you, beguiling the long day,\nShall tell two stories as you wend your way\nTo Canterbury town; and each of you\nOn coming home, shall tell another two,\nAll of adventures he has known befall.\nAnd he who plays his part the best of all,\nThat is to say, who tells upon the road\nTales of best sense, in most amusing mode,\nShall have a supper at the others' cost\nHere in this room and sitting by this post,\nWhen we come back again from Canterbury.\nAnd now, the more to warrant you'll be merry,\nI will myself, and gladly, with you ride\nAt my own cost, and I will be your guide.\nBut whosoever shall my rule gainsay\nShall pay for all that's bought along the way.\nAnd if you are agreed that it be so,\nTell me at once, or if not, tell me no,\nAnd I will act accordingly. No more.\nThis thing was granted, and our oaths we swore,\nWith right glad hearts, and prayed of him, also,\nThat he would take the office, nor forgo\nThe place of governor of all of us,\nJudging our tales; and by his wisdom thus\nArrange that supper at a certain price,\nWe to be ruled, each one, by his advice\nIn things both great and small; by one assent,\nWe stood committed to his government.\nAnd thereupon, the wine was fetched anon;\nWe drank, and then to rest went every one,\nAnd that without a longer tarrying.\nNext morning, when the day began to spring,\nUp rose our host, and acting as our cock,\nHe gathered us together in a flock,\nAnd forth we rode, a jog-trot being the pace,\nUntil we reached Saint Thomas' watering-place.\nAnd there our host pulled horse up to a walk,\nAnd said: Now, masters, listen while I talk.\nYou know what you agreed at set of sun.\nIf even-song and morning-song are one,\nLet's here decide who first shall tell a tale.\nAnd as I hope to drink more wine and ale,\nWhoso proves rebel to my government\nShall pay for all that by the way is spent.\nCome now, draw cuts, before we farther win,\nAnd he that draws the shortest shall begin.\nSir knight, said he, my master and my lord,\nYou shall draw first as you have pledged your word.\nCome near, quoth he, my lady prioress:\nAnd you, sir clerk, put by your bashfulness,\nNor ponder more; out hands, flow, every man!\nAt once to draw a cut each one began,\nAnd, to make short the matter, as it was,\nWhether by chance or whatsoever cause,\nThe truth is, that the cut fell to the knight,\nAt which right happy then was every wight.\nThus that his story first of all he'd tell,\nAccording to the compact, it befell,\nAs you have heard. Why argue to and fro?\nAnd when this good man saw that it was so,\nBeing a wise man and obedient\nTo plighted word, given by free assent,\nHe slid: Since I must then begin the game,\nWhy, welcome be the cut, and in God's name!\nNow let us ride, and hearken what I say.\nAnd at that word we rode forth on our way;\nAnd he began to speak, with right good cheer,\nHis tale anon, as it is written here.\n\n\n### The Knight's Tale\n\nOnce on a time, as old tales tell to us,\nThere was a duke whose name was Theseus:\nOf Athens he was lord and governor,\nAnd in his time was such a conqueror\nThat greater was there not beneath the sun.\nFull many a rich country had he won;\nWhat with his wisdom and his chivalry\nHe gained the realm of Femininity,\nThat was of old time known as Scythia.\nThere wedded he the queen, Hippolyta,\nAnd brought her home with him to his country.\nIn glory great and with great pageantry,\nAnd, too, her younger sister, Emily.\nAnd thus, in victory and with melody,\nLet I this noble duke to Athens ride\nWith all his armed host marching at his side.\nAnd truly, were it not too long to hear,\nI would have told you fully how, that year,\nWas gained the realm of Femininity\nBy Theseus and by his chivalry;\nAnd all of the great battle that was wrought\nWhere Amazons and the Athenians fought;\nAnd how was wooed and won Hippolyta,\nThat fair and hardy queen of Scythia;\nAnd of the feast was made at their wedding,\nAnd of the tempest at their home-coming;\nBut all of that I must for now forbear.\nI have, God knows, a large field for my share,\nAnd weak the oxen, and the soil is tough.\nThe remnant of the tale is long enough.\nI will not hinder any, in my turn;\nLet each man tell his tale, until we learn\nWhich of us all the most deserves to win;\nSo where I stopped, again I'll now begin.\nThis duke of whom I speak, of great renown,\nWhen he had drawn almost unto the town,\nIn all well-being and in utmost pride,\nHe grew aware, casting his eyes aside,\nThat right upon the road, as suppliants do,\nA company of ladies, two by two,\nKnelt, all in black, before his cavalcade;\nBut such a clamorous cry of woe they made\nThat in the whole world living man had heard\nNo such a lamentation, on my word;\nNor would they cease lamenting till at last\nThey'd clutched his bridle reins and held them fast.\nWhat folk are you that at my home-coming\nDisturb my triumph with this dolorous thing?\nCried Theseus. Do you so much envy\nMy honour that you thus complain and cry?\nOr who has wronged you now, or who offended?\nCome, tell me whether it may be amended;\nAnd tell me, why are you clothed thus, in black?\nThe eldest lady of them answered back,\nAfter she'd swooned, with cheek so deathly drear\nThat it was pitiful to see and hear,\nAnd said: Lord, to whom Fortune has but given\nVictory, and to conquer where you've striven,\nYour glory and your honour grieve not us;\nBut we beseech your aid and pity thus.\nHave mercy on our woe and our distress.\nSome drop of pity, of your gentleness,\nUpon us wretched women, oh, let fall!\nFor see, lord, there is no one of us all\nThat has not been a duchess or a queen;\nNow we are captives, as may well be seen:\nThanks be to Fortune and her treacherous wheel,\nThere's none can rest assured of constant weal.\nAnd truly, lord, expecting your return,\nIn Pity's temple, where the fires yet burn,\nWe have been waiting through a long fortnight;\nNow help us, lord, since it is in your might.\nI, wretched woman, who am weeping thus,\nWas once the wife of King Capaneus,\nWho died at Thebes, oh, cursed be the day!\nAnd all we that you see in this array,\nAnd make this lamentation to be known,\nAll we have lost our husbands at that town\nDuring the siege that round about it lay.\nAnd now the old Creon, ah welaway!\nThe lord and governor of Thebes city,\nFull of his wrath and all iniquity,\nHe, in despite and out of tyranny,\nTo do the dead a shame and villainy,\nOf all our husbands, lying among the slain,\nHas piled the bodies in a heap, amain,\nAnd will not suffer them, nor give consent,\nTo buried be, or burned, nor will relent,\nBut sets his dogs to eat them, out of spite.\nAnd on that word, at once, without respite,\nThey all fell prone and cried out piteously:\nHave on us wretched women some mercy,\nAnd let our sorrows sink into your heart!\nThis gentle duke down from his horse did start\nWith heart of pity, when he'd heard them speak.\nIt seemed to him his heart must surely break,\nSeeing them there so miserable of state,\nWho had been proud and happy but so late.\nAnd in his arms he took them tenderly,\nGiving them comfort understandingly:\nAnd swore his oath, that as he was true knight,\nHe would put forth so thoroughly his might\nAgainst the tyrant Creon as to wreak\nVengeance so great that all of Greece should speak\nAnd say how Creon was by Theseus served,\nAs one that had his death full well deserved.\nThis sworn and done, he no more there abode;\nHis banner he displayed and forth he rode\nToward Thebes, and all his host marched on beside;\nNor nearer Athens would he walk or ride,\nNor take his ease for even half a day,\nBut onward, and in camp that night he lay;\nAnd thence he sent Hippolyta the queen\nAnd her bright sister Emily, I ween,\nUnto the town of Athens, there to dwell\nWhile he went forth. There is no more to tell.\nThe image of red Mars, with spear and shield,\nSo shone upon his banner's snow-white field\nIt made a billowing glitter up and down;\nAnd by the banner borne was his pennon,\nOn which in beaten gold was worked, complete,\nThe Minotaur, which he had slain in Crete.\nThus rode this duke, thus rode this conqueror,\nAnd in his host of chivalry the flower,\nUntil he came to Thebes and did alight\nFull in the field where he'd intent to fight.\nBut to be brief in telling of this thing,\nWith Creon, who was Thebes' dread lord and king,\nHe fought and slew him, manfully, like knight,\nIn open war, and put his host to flight;\nAnd by assault he took the city then,\nLevelling wall and rafter with his men;\nAnd to the ladies he restored again\nThe bones of their poor husbands who were slain,\nTo do for them the last rites of that day.\nBut it were far too long a tale to say\nThe clamour of great grief and sorrowing\nThose ladies raised above the bones burning\nUpon the pyres, and of the great honour\nThat Theseus, the noble conqueror,\nPaid to the ladies when from him they went;\nTo make the story short is my intent.\nWhen, then, this worthy duke, this Theseus\nHad slain Creon and won Thebes city thus,\nStill on the field he took that night his rest,\nAnd dealt with all the land as he thought best.\nIn searching through the heap of enemy dead,\nStripping them of their gear from heel to head,\nThe busy pillagers could pick and choose,\nAfter the battle, what they best could use;\nAnd so befell that in a heap they found,\nPierced through with many a grievous, bloody wound,\nTwo young knights lying together, side by side,\nBearing one crest, wrought richly, of their pride,\nAnd of those two Arcita was the one,\nThe other knight was known as Palamon.\nNot fully quick, nor fully dead they were,\nBut by their coats of arms and by their gear\nThe heralds readily could tell, withal,\nThat they were of the Theban blood royal,\nAnd that they had been of two sisters born.\nOut of the heap the spoilers had them torn\nAnd carried gently over to the tent\nOf Theseus; who shortly had them sent\nTo Athens, there in prison cell to lie\nFor ever, without ransom, till they die.\nAnd when this worthy duke had all this done,\nHe gathered host and home he rode anon,\nWith laurel crowned again as conqueror;\nThere lived he in all joy and all honour\nHis term of life; what more need words express?\nAnd in a tower, in anguish and distress,\nPalamon and Arcita, day and night,\nDwelt whence no gold might help them to take flight.\nThus passed by year by year and day by day,\nTill it fell out, upon a morn in May,\nThat Emily, far fairer to be seen\nThan is the lily on its stalk of green,\nAnd fresher than is May with flowers new\n(For with the rose's colour strove her hue,\nI know not which was fairer of the two),\nBefore the dawn, as was her wont to do,\nShe rose and dressed her body for delight;\nFor May will have no sluggards of the night.\nThat season rouses every gentle heart\nAnd forces it from winter's sleep to start,\nSaying: Arise and show thy reverence.\nSo Emily remembered to go thence\nIn honour of the May, and so she rose.\nClothed, she was sweeter than any flower that blows;\nHer yellow hair was braided in one tress\nBehind her back, a full yard long, I guess.\nAnd in the garden, as the sun up-rose,\nShe sauntered back and forth and through each close,\nGathering many a flower, white and red,\nTo weave a delicate garland for her head;\nAnd like a heavenly angel's was her song.\nThe tower tall, which was so thick and strong,\nAnd of the castle was the great donjon,\n(Wherein the two knights languished in prison,\nOf whom I told and shall yet tell, withal),\nWas joined, at base, unto the garden wall\nWhereunder Emily went dallying.\nBright was the sun and clear that morn in spring,\nAnd Palamon, the woeful prisoner,\nAs was his wont, by leave of his gaoler,\nWas up and pacing round that chamber high,\nFrom which the noble city filled his eye,\nAnd, too, the garden full of branches green,\nWherein bright Emily, fair and serene,\nWent walking and went roving up and down.\nThis sorrowing prisoner, this Palamon,\nBeing in the chamber, pacing to and fro,\nAnd to himself complaining of his woe,\nCursing his birth, he often cried Alas!\nAnd so it was, by chance or other pass,\nThat through a window, closed by many a bar\nOf iron, strong and square as any spar,\nHe cast his eyes upon Emilia,\nAnd thereupon he blenched and cried out Ah!\nAs if he had been smitten to the heart.\nAnd at that cry Arcita did up-start,\nAsking: My cousin, why what ails you now\nThat you've so deathly pallor on your brow?\nWhy did you cry out? Who's offended you?\nFor God's love, show some patience, as I do,\nWith prison, for it may not different be;\nFortune has given this adversity.\nSome evil disposition or aspect\nOf Saturn did our horoscopes affect\nTo bring us here, though differently 'twere sworn;\nBut so the stars stood when we two were born;\nWe must endure it; that, in brief, is plain.\nThis Palamon replied and said again:\nCousin, indeed in this opinion now\nYour fancy is but vanity, I trow.\nIt's not our prison that caused me to cry.\nBut I was wounded lately through the eye\nDown to my heart, and that my bane will be.\nThe beauty of the lady that I see\nThere in that garden, pacing to and fro,\nIs cause of all my crying and my woe.\nI know not if she's woman or goddess;\nBut Venus she is verily, I guess.\nAnd thereupon down on his knees he fell,\nAnd said: O Venus, if it be thy will\nTo be transfigured in this garden, thus\nBefore me, sorrowing wretch, oh now help us\nOut of this prison to be soon escaped.\nAnd if it be my destiny is shaped,\nBy fate, to die in durance, in bondage,\nHave pity, then, upon our lineage\nThat has been brought so low by tyranny.\nAnd on that word Arcita looked to see\nThis lady who went roving to and fro.\nAnd in that look her beauty struck him so\nThat, if poor Palamon is wounded sore,\nArcita is as deeply hurt, and more.\nAnd with a sigh he said then, piteously:\nThe virgin beauty slays me suddenly\nOf her that wanders yonder in that place;\nAnd save I have her pity and her grace,\nThat I at least may see her day by day,\nI am but dead; there is no more to say.\nThis Palamon, when these words he had heard,\nPitilessly he watched him, and answered:\nDo you say this in earnest or in play?\nNay, quoth Arcita, earnest, now, I say!\nGod help me, I am in no mood for play!\nPalamon knit his brows and stood at bay.\nIt will not prove, he said, to your honour\nAfter so long a time to turn traitor\nTo me, who am your cousin and your brother,\nSworn as we are, and each unto the other,\nThat never, though for death in any pain,\nNever, indeed, till death shall part us twain,\nEither of us in love shall hinder other,\nNo, nor in any thing, O my dear brother;\nBut that, instead, you shall so further me\nAs I shall you. All this we did agree.\nSuch was your oath and such was mine also.\nYou dare not now deny it, well I know.\nThus you are of my party, beyond doubt.\nAnd now you would all falsely go about\nTo love my lady, whom I love and serve,\nAnd shall while life my heart's blood may preserve.\nNay, false Arcita, it shall not be so.\nI loved her first, and told you all my woe,\nAs to a brother and to one that swore\nTo further me, as I have said before.\nFor which you are in duty bound, as knight,\nTo help me, if the thing lie in your might,\nOr else you're false, I say, and downfallen.\nThen this Arcita proudly spoke again:\nYou shall, he said, be rather false than I;\nAnd that you're so, I tell you utterly;\nFor par amour I loved her first, you know.\nWhat can you say? You know not, even now,\nWhether she is a woman or goddess!\nYours is a worship as of holiness,\nWhile mine is love, as of a mortal maid;\nWherefore I told you of it, unafraid,\nAs to my cousin and my brother sworn.\nLet us assume you loved her first, this morn;\nKnow you not well the ancient writer's saw\nOf 'Who shall give a lover any law?'\nLove is a greater law, aye by my pan,\nThan man has ever given to earthly man.\nAnd therefore statute law and such decrees\nAre broken daily and in all degrees.\nA man must needs have love, maugre his head.\nHe cannot flee it though he should be dead,\nAnd be she maid, or widow, or a wife.\nAnd yet it is not likely that, in life,\nYou'll stand within her graces; nor shall I;\nFor you are well aware, aye verily,\nThat you and I are doomed to prison drear\nPerpetually; we gain no ransom here.\nWe strive but as those dogs did for the bone;\nThey fought all day, and yet their gain was none.\nTill came a kite while they were still so wroth\nAnd bore the bone away between them both.\nAnd therefore, at the king's court, O my brother,\nIt's each man for himself and not for other.\nLove if you like; for I love and aye shall;\nAnd certainly, dear brother, that is all.\nHere in this prison cell must we remain\nAnd each endure whatever fate ordain.\n\nGreat was the strife, and long, betwixt the two,\nIf I had but the time to tell it you,\nSave in effect. It happened on a day\n(To tell the tale as briefly as I may),\nA worthy duke men called Pirithous,\nWho had been friend unto Duke Theseus\nSince each had been a little child, a chit,\nWas come to visit Athens and visit\nHis play-fellow, as he was wont to do,\nFor in this whole world he loved no man so;\nAnd Theseus loved him as truly- nay,\nSo well each loved the other, old books say,\nThat when one died (it is but truth I tell),\nThe other went and sought him down in Hell;\nBut of that tale I have no wish to write.\nPirithous loved Arcita, too, that knight,\nHaving known him in Thebes full many a year;\nAnd finally, at his request and prayer,\nAnd that without a coin of ransom paid,\nDuke Theseus released him out of shade,\nFreely to go where'er he wished, and to\nHis own devices, as I'll now tell you.\nThe compact was, to set it plainly down,\nAs made between those two of great renown:\nThat if Arcita, any time, were found,\nEver in life, by day or night, on ground\nOf any country of this Theseus,\nAnd he were caught, it was concerted thus,\nThat by the sword he straight should lose his head.\nHe had no choice, so taking leave he sped\nHomeward to Thebes, lest by the sword's sharp edge\nHe forfeit life. His neck was under pledge.\nHow great a sorrow is Arcita's now!\nHow through his heart he feels death's heavy blow,\nHe weeps, he wails, he cries out piteously;\nHe thinks to slay himself all privily.\nSaid he: Alas, the day that I was born!\nI'm in worse prison, now, and more forlorn;\nNow am I doomed eternally to dwell\nNo more in Purgatory, but in Hell.\nAlas, that I have known Pirithous!\nFor else had I remained with Theseus,\nFettered within that cell; but even so\nThen had I been in bliss and not in woe.\nOnly the sight of her that I would serve,\nThough I might never her dear grace deserve,\nWould have sufficed, oh well enough for me!\nO my dear cousin Palamon, said he,\nYours is the victory, and that is sure,\nFor there, full happily, you may endure.\nIn prison? Never, but in Paradise!\nOh, well has Fortune turned for you the dice,\nWho have the sight of her, I the absence.\nFor possible it is, in her presence,\nYou being a knight, a worthy and able,\nThat by some chance, since Fortune's changeable.\nYou may to your desire sometime attain.\nBut I, that am in exile and in pain,\nStripped of all hope and in so deep despair\nThat there's no earth nor water, fire nor air,\nNor any creature made of them there is\nTo help or give me comfort, now, in this-\nSurely I'll die of sorrow and distress;\nFarewell, my life, my love, my joyousness!\nAlas! Why is it men so much complain\nOf what great God, or Fortune, may ordain,\nWhen better is the gift, in any guise,\nThan men may often for themselves devise?\nOne man desires only that great wealth\nWhich may but cause his death or long ill-health.\nOne who from prison gladly would be free,\nAt home by his own servants slain might be.\nInfinite evils lie therein, 'tis clear;\nWe know not what it is we pray for here.\nWe fare as he that's drunken as a mouse;\nA drunk man knows right well he has a house,\nBut he knows not the right way leading thither;\nAnd a drunk man is sure to slip and slither.\nAnd certainly, in this world so fare we;\nWe furiously pursue felicity,\nYet we go often wrong before we die.\nThis may we all admit, and specially I,\nWho deemed and held, as I were under spell,\nThat if I might escape from prison cell,\nThen would I find again what might heal,\nWho now am only exiled from my weal.\nFor since I may not see you, Emily,\nI am but dead; there is no remedy.\nAnd on the other hand, this Palamon,\nWhen that he found Arcita truly gone,\nSuch lamentation made he, that the tower\nResounded of his crying, hour by hour.\nThe very fetters on his legs were yet\nAgain with all his bitter salt tears wet.\nAlas! said he, Arcita, cousin mine,\nWith all our strife, God knows, you've won the wine.\nYou're walking, now, in Theban streets, at large,\nAnd all my woe you may from mind discharge.\nYou may, too, since you've wisdom and manhood,\nAssemble all the people of our blood\nAnd wage a war so sharp on this city\nThat by some fortune, or by some treaty,\nYou shall yet have that lady to your wife\nFor whom I now must needs lay down my life.\nFor surely 'tis in possibility,\nSince you are now at large, from prison free,\nAnd are a lord, great is your advantage\nAbove my own, who die here in a cage.\nFor I must weep and wail, the while I live,\nIn all the grief that prison cell may give,\nAnd now with pain that love gives me, also,\nWhich doubles all my torment and my woe.\nTherewith the fires of jealousy up-start\nWithin his breast and burn him to the heart\nSo wildly that he seems one, to behold,\nLike seared box tree, or ashes, dead and cold.\nThen said he: O you cruel Gods, that sway\nThis world in bondage of your laws, for aye,\nAnd write upon the tablets adamant\nYour counsels and the changeless words you grant,\nWhat better view of mankind do you hold\nThan of the sheep that huddle in the fold?\nFor man must die like any other beast,\nOr rot in prison, under foul arrest,\nAnd suffer sickness and misfortune sad,\nAnd still be ofttimes guiltless, too, by gad!\nWhat management is in this prescience\nThat, guiltless, yet torments our innocence?\nAnd this increases all my pain, as well,\nThat man is bound by law, nor may rebel,\nFor fear of God, but must repress his will,\nWhereas a beast may all his lust fulfill.\nAnd when a beast is dead, he feels no pain;\nBut, after death, man yet must weep amain,\nThough in this world he had but care and woe:\nThere is no doubt that it is even so.\nThe answer leave I to divines to tell,\nBut well I know this present world is hell.\nAlas! I see a serpent or a thief,\nThat has brought many a true man unto grief,\nGoing at large, and where he wills may turn,\nBut I must lie in gaol, because Saturn,\nAnd Juno too, both envious and mad,\nHave spilled out well-nigh all the blood we had\nAt Thebes, and desolated her wide walls.\nAnd Venus slays me with the bitter galls\nOf fear of Arcita, and jealousy.\nNow will I leave this Palamon, for he\nIs in his prison, where he still must dwell,\nAnd of Arcita will I forthwith tell.\nSummer being passed away and nights grown long,\nIncreased now doubly all the anguish strong\nBoth of the lover and the prisoner.\nI know not which one was the woefuller.\nFor, to be brief about it, Palamon\nIs doomed to lie for ever in prison,\nIn chains and fetters till he shall be dead;\nAnd exiled (on the forfeit of his head)\nArcita must remain abroad, nor see,\nFor evermore, the face of his lady.\nYou lovers, now I ask you this question:\nWho has the worse, Arcita or Palamon?\nThe one may see his lady day by day,\nBut yet in prison must he dwell for aye.\nThe other, where he wishes, he may go,\nBut never see his lady more, ah no.\nNow answer as you wish, all you that can.\nFor I will speak right on as I began.\nExplicit prima pars.\nSequitur pars secunda.\nNow when Arcita unto Thebes was come,\nHe lay and languished all day in his home,\nSince he his lady nevermore should see,\nBut telling of his sorrow brief I'll be.\nHad never any man so much torture,\nNo, nor shall have while this world may endure.\nBereft he was of sleep and meat and drink,\nThat lean he grew and dry as shaft, I think.\nHis eyes were hollow and ghastly to behold,\nHis face was sallow, all pale and ashen-cold,\nAnd solitary kept he and alone,\nWailing the whole night long, making his moan.\nAnd if he heard a song or instrument,\nThen he would weep ungoverned and lament;\nSo feeble were his spirits, and so low,\nAnd so changed was he, that no man could know\nHim by his words or voice, whoever heard.\nAnd in this change, for all the world he fared\nAs if not troubled by malady of love,\nBut by that humor dark and grim, whereof\nSprings melancholy madness in the brain,\nAnd fantasy unbridled holds its reign.\nAnd shortly, all was turned quite upside-down,\nBoth habits and the temper all had known\nOf him, this woeful lover, Dan Arcite.\nWhy should I all day of his woe indite?\nWhen he'd endured all this a year or two,\nThis cruel torment and this pain and woe,\nAt Thebes, in his own country, as I said,\nUpon a night, while sleeping in his bed,\nHe dreamed of how the winged God Mercury\nBefore him stood and bade him happier be.\nHis sleep-bestowing wand he bore upright;\nA hat he wore upon his ringlets bright.\nArrayed this god was (noted at a leap)\nAs he'd been when to Argus he gave sleep.\nAnd thus he spoke: To Athens shall you wend;\nFor all your woe is destined there to end.\nAnd on that word Arcita woke and started.\nNow truly, howsoever sore I'm smarted,\nSaid he, to Athens right now will I fare;\nNor for the dread of death will I now spare\nTo see my lady, whom I love and serve;\nI will not reck of death, with her, nor swerve.\nAnd with that word he caught a great mirror,\nAnd saw how changed was all his old colour,\nAnd saw his visage altered from its kind.\nAnd right away it ran into his mind\nThat since his face was now disfigured so,\nBy suffering endured (as well we know),\nHe might, if he should bear him low in town,\nLive there in Athens evermore, unknown,\nSeeing his lady well-nigh every day.\nAnd right anon he altered his array,\nLike a poor labourer in mean attire,\nAnd all alone, save only for a squire,\nWho knew his secret heart and all his case,\nAnd who was dressed as poorly as he was,\nTo Athens was he gone the nearest way.\nAnd to the court he went upon a day,\nAnd at the gate he proffered services\nTo drudge and drag, as any one devises.\nAnd to be brief herein, and to be plain,\nHe found employment with a chamberlain\nWas serving in the house of Emily;\nFor he was sharp and very soon could see\nWhat every servant did who served her there.\nRight well could he hew wood and water bear,\nFor he was young and mighty, let me own,\nAnd big of muscle, aye and big of bone,\nTo do what any man asked, in a trice.\nA year or two he was in this service,\nPage of the chamber of Emily the bright;\nHe said Philostrates would name him right.\nBut half so well beloved a man as he\nWas never in that court, of his degree;\nHis gentle nature was so clearly shown,\nThat throughout all the court spread his renown.\nThey said it were but kindly courtesy\nIf Theseus should heighten his degree\nAnd put him in more honourable service\nWherein he might his virtue exercise.\nAnd thus, anon, his name was so up-sprung,\nBoth for his deeds and sayings of his tongue,\nThat Theseus had brought him nigh and nigher\nAnd of the chamber he had made him squire,\nAnd given him gold to maintain dignity.\nBesides, men brought him, from his own country,\nFrom year to year, clandestinely, his rent;\nBut honestly and slyly it was spent,\nAnd no man wondered how he came by it.\nAnd three years thus he lived, with much profit,\nAnd bore him so in peace and so in war\nThere was no man that Theseus loved more.\nAnd in such bliss I leave Arcita now,\nAnd upon Palamon some words bestow.\nIn darksome, horrible, and strong prison\nThese seven years has now sat Palamon,\nWasted by woe and by his long distress.\nWho has a two-fold evil heaviness\nBut Palamon? whom love yet tortures so\nThat half out of his wits he is for woe;\nAnd joined thereto he is a prisoner,\nPerpetually, not only for a year.\nAnd who could rhyme in English, properly,\nHis martyrdom? Forsooth, it is not I;\nAnd therefore I pass lightly on my way.\nIt fell out in the seventh year, in May,\nOn the third night (as say the books of old\nWhich have this story much more fully told),\nWere it by chance or were it destiny\n(Since, when a thing is destined, it must be),\nThat, shortly after midnight, Palamon,\nBy helping of a friend, broke from prison,\nAnd fled the city, fast as he might go;\nFor he had given his guard a drink that so\nWas mixed of spice and honey and certain wine\nAnd Theban opiate and anodyne,\nThat all that night, although a man might shake\nThis gaoler, he slept on, nor could awake.\nAnd thus he flees as fast as ever he may.\nThe night was short and it was nearly day,\n\nWherefore he needs must find a place to hide;\nAnd to a grove that grew hard by, with stride\nOf furtive foot, went fearful Palamon.\nIn brief, he'd formed his plan, as he went on,\nThat in the grove he would lie fast all day,\nAnd when night came, then would he take his way\nToward Thebes, and there find friends, and of them pray\nTheir help on Theseus in war's array;\nAnd briefly either he would lose his life,\nOr else win Emily to be his wife;\nThis is the gist of his intention plain.\nNow I'll return to Arcita again,\nWho little knew how near to him was care\nTill Fortune caught him in her tangling snare.\nThe busy lark, the herald of the day,\nSalutes now in her song the morning grey;\nAnd fiery Phoebus rises up so bright\nThat all the east is laughing with the light,\nAnd with his streamers dries, among the greves,\nThe silver droplets hanging on the leaves.\nAnd so Arcita, in the court royal\nWith Theseus and his squire principal,\nIs risen, and looks on the merry day.\nAnd now, to do his reverence to May,\nCalling to mind the point of his desire,\nHe on a courser, leaping high like fire,\nIs ridden to the fields to muse and play,\nOut of the court, a mile or two away;\nAnd to the grove, whereof I lately told,\nBy accident his way began to hold,\nTo make him there the garland that one weaves\nOf woodbine leaves and of green hawthorn leaves.\nAnd loud he sang within the sunlit sheen:\nO May, with all thy flowers and all thy green,\nWelcome be thou, thou fair and freshening May:\nI hope to pluck some garland green today.\nAnd from his courser, with a lusty heart,\nInto the grove right hastily did start,\nAnd on a path he wandered up and down,\nNear which, and as it chanced, this Palamon\nLay in the thicket, where no man might see,\nFor sore afraid of finding death was be.\nHe knew not that Arcita was so near:\nGod knows he would have doubted eye and ear,\nBut it has been a truth these many years\nThat Fields have eyes and every wood has ears.\nIt's well for one to bear himself with poise;\nFor every day unlooked-for chance annoys.\nAnd little knew Arcita of his friend,\nWho was so near and heard him to the end,\nWhere in the bush lie sat now, keeping still.\nArcita, having roamed and roved his fill,\nAnd having sung his rondel, lustily,\nInto a study fell he, suddenly,\nAs do these lovers in their strange desires,\nNow in the trees, now down among the briers,\nNow up, now down, like bucket in a well.\nEven as on a Friday, truth to tell,\nThe sun shines now, and now the rain comes fast,\nEven so can fickle Venus overcast\nThe spirits of her people; as her day,\nIs changeful, so she changes her array.\nSeldom is Friday quite like all the week.\nArcita, having sung, began to speak,\nAnd sat him down, sighing like one forlorn.\nAlas, said he, the day that I was born!\nHow long, O Juno, of thy cruelty,\nWilt thou wage bitter war on Thebes city?\nAlas! Confounded beyond all reason\nThe blood of Cadmus and of Amphion;\nOf royal Cadmus, who was the first man\nTo build at Thebes, and first the town began,\nAnd first of all the city to be king;\nOf his lineage am I, and his offspring,\nBy true descent, and of the stock royal:\nAnd now I'm such a wretched serving thrall,\nThat he who is my mortal enemy,\nI serve him as his squire, and all humbly.\nAnd even more does Juno give me shame,\nFor I dare not acknowledge my own name;\nBut whereas I was Arcita by right,\nNow I'm Philostrates, not worth a mite.\nAlas, thou cruel Mars! Alas, Juno!\nThus have your angers all our kin brought low,\nSave only me, and wretched Palamon,\nWhom Theseus martyrs yonder in prison.\nAnd above all, to slay me utterly,\nLove has his fiery dart so burningly\nStruck through my faithful and care-laden heart,\nMy death was patterned ere my swaddling-shirt.\nYou slay me with your two eyes, Emily;\nYou are the cause for which I now must die.\nFor on the whole of all my other care\nI would not set the value of a tare,\nSo I could do one thing to your pleasance!\nAnd with that word he fell down in a trance\nThat lasted long; and then he did up-start.\nThis Palamon, who thought that through his heart\nHe felt a cold and sudden sword blade glide,\nFor rage he shook, no longer would he hide.\nBut after he had heard Arcita's tale,\nAs he were mad, with face gone deathly pale,\nHe started up and sprang out of the thicket,\nCrying: Arcita, oh you traitor wicked,\nNow are you caught, that crave my lady so,\nFor whom I suffer all this pain and woe,\nAnd are my blood, and know my secrets' store,\nAs I have often told you heretofore,\nAnd have befooled the great Duke Thesues,\nAnd falsely changed your name and station thus:\nEither I shall be dead or you shall die.\nYou shall not love my lady Emily,\nBut I will love her, and none other, no;\nFor I am Palamon, your mortal foe.\nAnd though I have no weapon in this place,\nBeing but out of prison by God's grace,\nI say again, that either you shall die\nOr else forgo your love for Emily.\nChoose which you will, for you shall not depart.\nThis Arcita, with scornful, angry heart,\nWhen he knew him and all the tale had heard,\nFierce as a lion, out he pulled a sword,\nAnd answered thus: By God that sits above!\nWere it not you are sick and mad for love,\nAnd that you have no weapon in this place,\nOut of this grove you'd never move a pace,\nBut meet your death right now, and at my hand.\nFor I renounce the bond and its demand\nWhich you assert that I have made with you.\nWhat, arrant fool, love's free to choose and do,\nAnd I will have her, spite of all your might!\nBut in as much as you're a worthy knight\nAnd willing to defend your love, in mail,\nHear now this word: tomorrow I'll not fail\n(Without the cognizance of any wight)\nTo come here armed and harnessed as a knight,\nAnd to bring arms for you, too, as you'll see;\nAnd choose the better and leave the worse for me.\nAnd meat and drink this very night I'll bring,\nEnough for you, and clothes for your bedding.\nAnd if it be that you my lady win\nAnd slay me in this wood that now I'm in,\nThen may you have your lady, for all of me.\nThis Palamon replied: I do agree.\nAnd thus they parted till the morrow morn,\nWhen each had pledged his honour to return.\nO Cupido, that know'st not charity!\nO despot, that no peer will have with thee!\nTruly, 'tis said, that love, like all lordship,\nDeclines, with little thanks, a partnership.\nWell learned they that, Arcite and Palamon.\nArcita rode into the town anon,\nAnd on the morrow, ere the dawn, he bore,\nSecretly, arms and armour out of store,\nEnough for each, and proper to maintain\nA battle in the field between the twain.\nSo on his horse, alone as he was born,\nHe carried out that harness as he'd sworn;\nAnd in the grove, at time and place they'd set,\nArcita and this Palamon were met.\nEach of the two changed colour in the face.\nFor as the hunter in the realm of Thrace\nStands at the clearing with his ready spear,\nWhen hunted is the lion, or the bear,\nAnd through the forest hears him rushing fast,\nBreaking the boughs and leaves, and thinks aghast.\nHere comes apace my mortal enemy!\nNow, without fail, he must be slain, or I;\nFor either I must kill him ere he pass,\nOr he will make of me a dead carcass-\nSo fared these men, in altering their hue,\nSo far as each the strength of other knew.\nThere was no good-day given, no saluting,\nBut without word, rehearsal, or such thing,\nEach of them helping, so they armed each other\nAs dutifully as he were his own brother;\nAnd afterward, with their sharp spears and strong,\nThey thrust each at the other wondrous long.\nYou might have fancied that this Palamon,\nIn battle, was a furious, mad lion,\nAnd that Arcita was a tiger quite:\nLike very boars the two began to smite,\nLike boars that froth for anger in the wood.\nUp to the ankles fought they in their blood.\nAnd leaving them thus fighting fast and fell,\nForthwith of Theseus I now will tell.\nGreat destiny, minister-general,\nThat executes in this world, and for all,\nThe needs that God foresaw ere we were born,\nSo strong it is that, though the world had sworn\nThe contrary of a thing, by yea or nay,\nYet sometime it shall fall upon a day,\nThough not again within a thousand years.\nFor certainly our wishes and our fears,\nWhether of war or peace, or hate or love,\nAll, all are ruled by that Foresight above.\nThis show I now by mighty Theseus,\nWho to go hunting is so desirous,\nAnd specially of the hart of ten, in May,\nThat, in his bed, there dawns for him no day\nThat he's not clothed and soon prepared to ride\nWith hound and horn and huntsman at his side.\nFor in his hunting has he such delight,\nThat it is all his joy and appetite\nTo be himself the great hart's deadly bane:\nFor after Mars, he serves Diana's reign.\nClear was the day, as I have told ere this,\nWhen Theseus, compact of joy and bliss,\nWith his Hippolyta, the lovely queen,\nAnd fair Emilia, clothed all in green,\nA-hunting they went riding royally.\nAnd to the grove of trees that grew hard by,\nIn which there was a hart, as men had told,\nDuke Theseus the shortest way did hold.\nAnd to the glade he rode on, straight and right,\nFor there the hart was wont to go in flight,\nAnd over a brook, and so forth on his way.\nThis duke would have a course at him today,\nWith such hounds as it pleased him to command.\nAnd when this duke was come upon that land,\nUnder the slanting sun he looked, anon,\nAnd there saw Arcita and Palamon,\nWho furiously fought, as two boars do;\nThe bright swords went in circles to and fro\nSo terribly, that even their least stroke\nSeemed powerful enough to fell an oak;\nBut who the two were, nothing did he note.\nThis duke his courser with the sharp spurs smote,\nAnd in one bound he was between the two,\nAnd lugged his great sword out, and cried out: Ho!\nNo more, I say, on pain of losing head!\nBy mighty Mars, that one shall soon be dead\nWho smites another stroke that I may see!\nBut tell me now what manner of men ye be\nThat are so hardy as to fight out here\nWithout a judge or other officer,\nAs if you-rode in lists right royally?\nThis Palamon replied, then, hastily,\nSaying: O Sire, what need for more ado?\nWe have deserved our death at hands of you.\nTwo woeful wretches are we, two captives\nThat are encumbered by our own sad lives;\nAnd as you are a righteous lord and judge,\nGive us not either mercy or refuge,\nBut slay me first, for sacred charity;\nBut slay my fellow here, as well, with me.\nOr slay him first; for though you learn it late,\nThis is your mortal foe, Arcita- wait!-\nThat from the land was banished, on his head.\nAnd for the which he merits to be dead.\nFor this is he who came unto your gate,\nCalling himself Philostrates- nay, wait!-\nThus has he fooled you well this many a year,\nAnd you have made him your chief squire, I hear:\nAnd this is he that loves fair Emily.\nFor since the day is come when I must die,\nI make confession plainly and say on,\nThat I am that same woeful Palamon\nWho has your prison broken, viciously.\nI am your mortal foe, and it is I\nWho love so hotly Emily the bright\nThat I'll die gladly here within her sigh!\nTherefore do I ask death as penalty,\nBut slay my fellow with the same mercy,\nFor both of us deserve but to be slain.\nThis worthy duke presently spoke again,\nSaying: This judgment needs but a short session:\nYour own mouth, aye, and by your own confession,\nHas doomed and damned you, as I shall record.\nThere is no need for torture, on my word.\nBut you shall die, by mighty Mars the red!\nBut then the queen, whose heart for pity bled,\nBegan to weep, and so did Emily\nAnd all the ladies in the company.\nGreat pity must it be, so thought they all,\nThat ever such misfortune should befall:\nFor these were gentlemen, of great estate,\nAnd for no thing, save love, was their debate.\nThey saw their bloody wounds, so sore and wide,\nAnd all cried out- greater and less, they cried:\nHave mercy, lord, upon us women all!\nAnd down upon their bare knees did they fall,\nAnd would have kissed his feet there where he stood,\nTill at the last assuaged was his high mood;\nFor soon will pity flow through gentle heart.\nAnd though he first for ire did shake and start,\nHe soon considered, to state the case in brief,\nWhat cause they had for fighting, what for grief;\nAnd though his anger still their guilt accused,\nYet in his reason he held them both excused;\nIn such wise: he thought well that every man\nWill help himself in love, if he but can,\nAnd will himself deliver from prison;\nAnd, too, at heart he had compassion on\nThose women, for they cried and wept as one,\nAnd in his gentle heart he thought anon,\nAnd softly to himself he said then: Fie\nUpon a lord that will have no mercy,\nBut acts the lion, both in word and deed,\nTo those repentant and in fear and need,\nAs well as to the proud and pitiless man\nThat still would do the thing that he began!\nThat lord must surely in discretion lack\nWho, in such case, can no distinction make,\nBut weighs both proud and humble in one scale.\nAnd shortly, when his ire was thus grown pale,\nHe looked up to the sky, with eyes alight,\nAnd spoke these words, as he would promise plight:\nThe god of love, ah benedicite!\nHow mighty and how great a lord is he!\nAgainst his might may stand no obstacles,\nA true god is he by his miracles;\nFor he can manage, in his own sweet wise,\nThe heart of anyone as he devise.\nLo, here, Arcita and this Palamon,\nThat were delivered out of my prison,\nAnd might have lived in Thebes right royally,\nKnowing me for their mortal enemy,\nAnd also that their lives lay in my hand;\nAnd yet their love has wiled them to this land,\nAgainst all sense, and brought them here to die!\nLook you now, is not that a folly high?\nWho can be called a fool, except he love?\nAnd see, for sake of God who sits above,\nSee how they bleed! Are they not well arrayed?\nThus has their lord, the god of love, repaid\nTheir wages and their fees for their service!\nAnd yet they are supposed to be full wise\nWho serve love well, whatever may befall!\nBut this is yet the best jest of them all,\nThat she for whom they have this jollity\nCan thank them for it quite as much as me;\nShe knows no more of all this fervent fare,\nBy God! than knows a cuckoo or a hare.\nBut all must be essayed, both hot and cold,\nA man must play the fool, when young or old;\nI know it of myself from years long gone:\nFor of love's servants I've been numbered one.\nAnd therefore, since I know well all love's pain,\nAnd know how sorely it can man constrain,\nAs one that has been taken in the net,\nI will forgive your trespass, and forget,\nAt instance of my sweet queen, kneeling here,\nAye, and of Emily, my sister dear.\nAnd you shall presently consent to swear\nThat nevermore will you my power dare,\nNor wage war on me, either night or day,\nBut will be friends to me in all you may;\nI do forgive this trespass, full and fair.\n\nAnd then they swore what he demanded there,\nAnd, of his might, they of his mercy prayed,\nAnd he extended grace, and thus he said:\nTo speak for royalty's inheritress,\nAlthough she be a queen or a princess,\nEach of you both is worthy, I confess,\nWhen comes the time to wed: but nonetheless,\nI speak now of my sister Emily,\nThe cause of all this strife and jealousy-\nYou know yourselves she may not marry two,\nAt once, although you fight or what you do:\nOne of you, then, and be he loath or lief,\nMust pipe his sorrows in an ivy leaf.\nThat is to say, she cannot have you both,\nHowever jealous one may be, or wroth.\nTherefore I put you both in this decree,\nThat each of you shall learn his destiny\nAs it is cast; and hear, now, in what wise\nThe word of fate shall speak through my device.\nMy will is this, to draw conclusion flat,\nWithout reply, or plea, or caveat\n(In any case, accept it for the best),\nThat each of you shall follow his own quest,\nFree of all ransom or of fear from me;\nAnd this day, fifty weeks hence, both shall be\nHere once again, each with a hundred knights,\nArmed for the lists, who stoutly for your rights\nWill ready be to battle, to maintain\nYour claim to love. I promise you, again,\nUpon my word, and as I am a knight,\nThat whichsoever of you wins the fight,\nThat is to say, whichever of you two\nMay with his hundred, whom I spoke of, do\nHis foe to death, or out of boundary drive,\nThen he shall have Emilia to wive\nTo whom Fortune gives so fair a grace.\nThe lists shall be erected in this place.\nAnd God so truly on my soul have ruth\nAs I shall prove an honest judge, in truth.\nYou shall no other judgment in me waken\nThan that the one shall die or else be taken.\nAnd if you think the sentence is well said,\nSpeak your opinion, that you're well repaid.\nThis is the end, and I conclude hereon.\nWho looks up lightly now but Palamon?\nWho leaps for you but Arcita the knight?\nAnd who could tell, or who could ever write\nThe jubilation made within that place\nWhere Theseus has shown so fair a grace?\nBut down on knee went each one for delight\nAnd thanked him there with all his heart and might,\nAnd specially those Thebans did their part.\nAnd thus, with high hopes, being blithe of heart,\nThey took their leave; and homeward did they ride\nTo Thebes that sits within her old walls wide.\nExplicit secunda pars.\nSequitur pars tercia.\nI think that men would deem it negligence\nIf I forgot to tell of the expense\nOf Theseus, who went so busily\nTo work upon the lists, right royally;\nFor such an amphitheatre he made,\nIts equal never yet on earth was laid.\nThe circuit, rising, hemmed a mile about,\nWalled all of stone and moated deep without.\nRound was the shape as compass ever traces,\nAnd built in tiers, the height of sixty paces,\nThat those who sat in one tier, or degree,\nShould hinder not the folk behind to see.\nEastward there stood a gate of marble white.\nAnd westward such another, opposite.\nIn brief, no place on earth, and so sublime,\nWas ever made in so small space of time;\nFor in the land there was no craftsman quick\nAt plane geometry or arithmetic,\nNo painter and no sculptor of hard stone,\nBut Theseus pressed meat and wage upon\nTo build that amphitheatre and devise.\nAnd to observe all rites and sacrifice,\nOver the eastern gate, and high above,\nFor worship of Queen Venus, god of love,\nHe built an altar and an oratory;\nAnd westward, being mindful of the glory\nOf Mars, he straightway builded such another\nAs cost a deal of gold and many a bother.\nAnd northward, in a turret on the wall,\nOf alabaster white and red coral,\nAn oratory splendid as could be,\nIn honour of Diana's chastity,\nDuke Theseus wrought out in noble wise.\nBut yet have forgot to advertise\nThe noble carvings and the portraitures,\nThe shapes, the countenances, the figures\nThat all were in these oratories three.\nFirst, in the fane of Venus, one might see,\nWrought on the wall, and piteous to behold,\nThe broken slumbers and the sighing cold,\nThe sacred tears and the lamenting dire,\nThe fiery throbbing of the strong desire,\nThat all love's servants in this life endure;\nThe vows that all their promises assure;\nPleasure and hope, desire, foolhardiness,\nBeauty, youth, bawdiness, and riches, yes,\nCharms, and all force, and lies, and flattery,\nExpense, and labour; aye, and Jealousy\nThat wore of marigolds a great garland\nAnd had a cuckoo sitting on her hand;\nCarols and instruments and feasts and dances,\nLust and array, and all the circumstances\nOf love that I may reckon or ever shall,\nIn order they were painted on the wall,\nAye, and more, too, than I have ever known.\nFor truly, all the Mount of Citheron,\nWhere Venus has her chief and favoured dwelling,\nWas painted on that wall, beyond my telling,\nWith all the gardens in their loveliness.\nNor was forgot the gate-guard Idleness,\nNor fair Narcissus of the years long gone,\nNor yet the folly of King Solomon,\nNo, nor the giant strength of Hercules,\nNor Circe's and Medea's sorceries,\nNor Turnus with his hardy, fierce courage,\nNor the rich Croesus, captive in his age.\nThus may be seen that wisdom, nor largess,\nBeauty, nor skill, nor strength, nor hardiness,\nMay with Queen Venus share authority;\nFor as she wills, so must the whole world be.\nLo, all these folk were so caught in her snare\nThey cried aloud in sorrow and in care.\nHere let suffice examples one or two,\nThough I might give a thousand more to you.\nThe form of Venus, glorious as could be,\nWas naked, floating on the open sea,\nAnd from the navel down all covered was\nWith green waves, bright as ever any glass.\nA citole in her small right hand had she,\nAnd on her head, and beautiful to see,\nA garland of red roses, sweet smelling,\nAbove her swirled her white doves, fluttering.\nBefore her stood her one son, Cupido,\nWhose two white wings upon his shoulders grow;\nAnd blind he was, as it is often seen;\nA bow he bore, and arrows bright and keen.\nWhy should I not as well, now, tell you all\nThe portraiture that was upon the wall\nWithin the fane of mighty Mars the red?\nIn length and breadth the whole wall was painted\nLike the interior of that grisly place,\nThe mighty temple of great Mars in Thrace,\nIn that same cold and frosty region where\nMars to his supreme mansion may repair.\nFirst, on the wall was limned a vast forest\nWherein there dwelt no man nor any beast,\nWith knotted, gnarled, and leafless trees, so old\nThe sharpened stumps were dreadful to behold;\nThrough which there ran a rumbling, even now,\nAs if a storm were breaking every bough;\nAnd down a hill, beneath a sharp descent,\nThe temple stood of Mars armipotent,\nWrought all of burnished steel, whereof the gate\nWas grim like death to see, and long, and strait.\nAnd therefrom raged a wind that seemed to shake\nThe very ground, and made the great doors quake.\nThe northern light in at those same doors shone,\nFor window in that massive wall was none\nThrough which a man might any light discern.\nThe doors were all of adamant eterne,\nRivetted on both sides, and all along,\nWith toughest iron; and to make it strong,\nEach pillar that sustained this temple grim\nWas thick as tun, of iron bright and trim.\nThere saw I first the dark imagining\nOf felony, and all the compassing;\nAnd cruel anger, red as burning coal;\nPickpurses, and the dread that eats the soul;\nThe smiling villain, hiding knife in cloak;\nThe farm barns burning, and the thick black smoke;\nThe treachery of murder done in bed;\nThe open battle, with the wounds that bled;\nContest, with bloody knife and sharp menace;\nAnd loud with creaking was that dismal place.\nThe slayer of himself, too, saw I there,\nHis very heart's blood matted in his hair;\nThe nail that's driven in the skull by night;\nThe cold plague-corpse, with gaping mouth upright\nIn middle of the temple sat Mischance,\nWith gloomy, grimly woeful countenance.\nAnd saw I Madness laughing in his rage;\nArmed risings, and outcries, and fierce outrage;\nThe carrion in the bush, with throat wide carved;\nA thousand slain, nor one by plague, nor starved.\nThe tyrant, with the spoils of violent theft;\nThe town destroyed, in ruins, nothing left.\nAnd saw I burnt the ships that dance by phares,\nThe hunter strangled by the fierce wild bears;\nThe sow chewing the child right in the cradle;\nThe cook well scalded, spite of his long ladle.\nNothing was lacking of Mars' evil part:\nThe carter over-driven by his cart,\nUnder a wheel he lay low in the dust.\nThere were likewise in Mars' house, as needs must,\nThe surgeon, and the butcher, and the smith\nWho forges sharp swords and great ills therewith.\nAnd over all, depicted in a tower,\nSat Conquest, high in honour and in power,\nYet with a sharp sword hanging o'er his head\nBut by the tenuous twisting of a thread.\nDepicted was the death of Julius,\nOf Nero great, and of Antonius;\nAnd though at that same time they were unborn,\nThere were their deaths depicted to adorn\nThe menacing of Mars, in likeness sure;\nThings were so shown, in all that portraiture,\nAs are fore-shown among the stars above,\nWho shall be slain in war or dead for love.\nSuffice one instance from old plenitude,\nI could not tell them all, even if I would.\nMars' image stood upon a chariot,\nArmed, and so grim that mad he seemed, God wot;\nAnd o'er his head two constellations shone\nOf stars that have been named in writings known.\nOne being Puella, and one Rubeus.\nThis god of armies was companioned thus:\nA wolf there was before him, at his feet,\nRed-eyed, and of a dead man he did eat.\nA cunning pencil there had limned this story\nIn reverence of Mars and of his glory.\nNow to the temple of Diana chaste,\nAs briefly as I can, I'll pass in haste,\nTo lay before you its description well.\nIn pictures, up and down, the wall could tell\nOf hunting and of modest chastity.\nThere saw I how Callisto fared when she\n(Diana being much aggrieved with her)\nWas changed from woman into a she-bear,\nAnd after, made into the lone Pole Star;\nThere was it; I can't tell how such things are.\nHer son, too, is a star, as men may see.\nThere saw I Daphne turned into a tree\n(I do not mean Diana, no, but she,\nPeneus' daughter, who was called Daphne)\nI saw Actaeon made a hart all rude\nFor punishment of seeing Diana nude;\nI saw, too, how his fifty hounds had caught\nAnd him were eating, since they knew him not.\nAnd painted farther on, I saw before\nHow Atalanta hunted the wild boar;\nAnd Meleager, and many another there,\nFor which Diana wrought him woe and care.\nThere saw I many another wondrous tale\nFrom which I will not now draw memory's veil.\nThis goddess on an antlered hart was set,\nWith little hounds about her feet, and yet\nBeneath her perfect feet there was a moon,\nWaxing it was, but it should wane full soon.\nIn robes of yellowish green her statue was,\nShe'd bow in hand and arrows in a case.\nHer eyes were downcast, looking at the ground.\nWhere Pluto in his dark realm may be found.\nBefore her was a woman travailing,\nWho was so long in giving birth, poor thing,\nThat pitifully Lucina did she call,\nPraying, Oh help, for thou may'st best of all!\nWell could he paint, who had this picture wrought,\nWith many a florin he'd his colours bought,\nBut now the lists were done, and Theseus,\nWho at so great cost had appointed thus\nThe temples and the circus, as I tell,\nWhen all was done, he liked it wondrous well.\nBut hold I will from Theseus, and on\nTo speak of Arcita and Palamon.\nThe day of their return is forthcoming,\nWhen each of them a hundred knights must bring\nThe combat to support, as I have told;\nAnd into Athens, covenant to uphold,\nHas each one ridden with his hundred knights,\nWell armed for war, at all points, in their mights.\nAnd certainly, 'twas thought by many a man\nThat never, since the day this world began,\nSpeaking of good knights hardy of their hands,\nWherever God created seas and lands,\nWas, of so few, so noble company.\nFor every man that loved all chivalry,\nAnd eager was to win surpassing fame,\nHad prayed to play a part in that great game;\nAnd all was well with him who chosen was.\nFor if there came tomorrow such a case,\nYou know right well that every lusty knight\nWho loves the ladies fair and keeps his might,\nBe it in England, aye or otherwhere,\nWould wish of all things to be present there\nTo fight for some fair lady. Ben'cite!\n'Twould be a pleasant goodly sight to see!\nAnd so it was with those with Palamon.\nWith him there rode of good knights many a one;\nSome would be armoured in a habergeon\nAnd in a breastplate, under light jupon;\nAnd some wore breast-and back-plates thick and large;\nAnd some would have a Prussian shield, or targe;\nSome on their very legs were armoured well,\nAnd carried axe, and some a mace of steel.\nThere is no new thing, now, that is not old.\nAnd so they all were armed, as I have told,\nTo his own liking and design, each one.\nThere might you see, riding with Palamon,\nLycurgus' self, the mighty king of Thrace;\nBlack was his beard and manly was his face.\nThe eyeballs in the sockets of his head,\nThey glowed between a yellow and a red.\nAnd like a griffon glared he round about\nFrom under bushy eyebrows thick and stout.\nHis limbs were large, his muscles hard and strong.\nHis shoulders broad, his arms both big and long,\nAnd, as the fashion was in his country,\nHigh in a chariot of gold stood he,\nWith four white bulls in traces, to progress.\nInstead of coat-of-arms above harness,\nWith yellow claws preserved and bright as gold,\nHe wore a bear-skin, black and very old.\nHis long combed hair was hanging down his back,\nAs any raven's feather it was black:\nA wreath of gold, arm-thick, of heavy weight,\nWas on his head, and set with jewels great,\nOf rubies fine and perfect diamonds.\nAbout his car there circled huge white hounds,\nTwenty or more, as large as any steer,\nTo hunt the lion or the antlered deer;\nAnd so they followed him, with muzzles bound,\nWearing gold collars with smooth rings and round.\nA hundred lords came riding in his rout,\nAll armed at point, with hearts both stern and stout\nWith Arcita, in tales men call to mind,\nThe great Emetreus, a king of Ind,\nUpon a bay steed harnessed all in steel,\nCovered with cloth of gold, all diapered well,\nCame riding like the god of arms, great Mars.\nHis coat-of-arms was cloth of the Tartars,\nBegemmed with pearls, all white and round and great.\nOf beaten gold his saddle, burnished late;\nA mantle from his shoulders hung, the thing\nClose-set with rubies red, like fire blazing.\nHis crisp hair all in bright ringlets was run,\nYellow as gold and gleaming as the sun.\nHis nose was high, his eyes a bright citrine,\nHis lips were full, his colouring sanguine.\nAnd a few freckles on his face were seen,\nNone either black or yellow, but the mean;\nAnd like a lion he his glances cast.\nNot more than five-and-twenty years he'd past.\nHis beard was well beginning, now, to spring;\nHis voice was as a trumpet thundering.\nUpon his brows he wore, of laurel green,\nA garland, fresh and pleasing to be seen.\nUpon his wrist he bore, for his delight,\nAn eagle tame, as any lily white.\nA hundred lords came riding with him there,\nAll armed, except their heads, in all their gear,\nAnd wealthily appointed in all things.\nFor, trust me well, that dukes and earls and kings\nWere gathered in this noble company\nFor love and for increase of chivalry.\nAbout this king there ran, on every side,\nMany tame lions and leopards in their pride.\nAnd in such wise these mighty lords, in sum,\nWere, of a Sunday, to the city come\nAbout the prime, and in the town did light."},{"index":1,"markdown":"\nThis Theseus, this duke, this noble knight,\nWhen he'd conducted them to his city,\nAnd quartered them, according to degree,\nHe feasted them, and was at so much pains\nTo give them ease and honour, of his gains,\nThat men yet hold that never human wit,\nOf high or low estate, could better it.\nThe minstrelsy, the service at the feast,\nThe great gifts to the highest and the least,\nThe furnishings of Theseus, rich palace,\nWho highest sat or lowest on the dais,\nWhat ladies fairest were or best dandling,\nOr which of them could dance the best, or sing,\nOr who could speak most feelingly of love,\nOr what hawks sat upon the perch above,\nOr what great hounds were lying on the floor-\nOf all these I will make no mention more;\nBut tell my tale, for that, I think, is best;\nNow comes the point, and listen if you've zest.\nThat Sunday night, ere day began to spring,\nWhen Palamon the earliest lark heard sing,\nAlthough it lacked two hours of being day,\nYet the lark sang, and Palamon sang a lay.\nWith pious heart and with a high courage\nHe rose, to go upon a pilgrimage\nUnto the blessed Cytherea's shrine\n(I mean Queen Venus, worthy and benign).\nAnd at her hour he then walked forth apace\nOut to the lists wherein her temple was,\nAnd down he knelt in manner to revere,\nAnd from a full heart spoke as you shall hear.\nFairest of fair, O lady mine, Venus,\nDaughter of Jove and spouse to Vulcanus,\nThou gladdener of the Mount of Citheron,\nBy that great love thou borest to Adon,\nHave pity on my bitter tears that smart\nAnd hear my humble prayer within thy heart.\nAlas! I have no words in which to tell\nThe effect of all the torments of my hell;\nMy heavy heart its evils can't bewray;\nI'm so confused I can find naught to say.\nBut mercy, lady bright, that knowest well\nMy heart, and seest all the ills I feel,\nConsider and have ruth upon my sore\nAs truly as I shall, for evermore,\nWell as I may, thy one true servant be,\nAnd wage a war henceforth on chastity.\nIf thou wilt help, thus do I make my vow,\nTo boast of knightly skill I care not now,\nNor do I ask tomorrow's victory,\nNor any such renown, nor vain glory\nOf prize of arms, blown before lord and churl,\nBut I would have possession of one girl,\nOf Emily, and die in thy service;\nFind thou the manner how, and in what wise.\nFor I care not, unless it better be,\nWhether I vanquish them or they do me,\nSo I may have my lady in my arms.\nFor though Mars is the god of war's alarms,\nThy power is so great in Heaven above,\nThat, if it be thy will, I'll have my love.\nIn thy fane will I worship always, so\nThat on thine altar, where'er I ride or go,\nI will lay sacrifice and thy fires feed.\nAnd if thou wilt not so, O lady, cede,\nI pray thee, that tomorrow, with a spear,\nArcita bear me through the heart, just here.\nFor I'll care naught, when I have lost my life,\nThat Arcita may win her for his wife.\nThis the effect and end of all my prayer,\nGive me my love, thou blissful lady fair.\nNow when he'd finished all the orison,\nHis sacrifice he made, this Palamon,\nRight piously, with all the circumstance,\nAlbeit I tell not now his observance.\nBut at the last the form of Venus shook\nAnd gave a sign, and thereupon he took\nThis as acceptance of his prayer that day.\nFor though the augury showed some delay,\nYet he knew well that granted was his boon;\nAnd with glad heart he got him home right soon.\nThree hours unequal after Palamon\nTo Venus' temple at the lists had gone,\nUp rose the sun and up rose Emily,\nAnd to Diana's temple did she hie.\nHer maidens led she thither, and with them\nThey carefully took fire and each emblem,\nAnd incense, robes, and the remainder all\nOf things for sacrifice ceremonial.\nThere was not one thing lacking; I'll but add\nThe horns of mead, as was a way they had.\nIn smoking temple, full of draperies fair,\nThis Emily with young heart debonnaire,\nHer body washed in water from a well;\nBut how she did the rite I dare not tell,\nExcept it be at large, in general;\nAnd yet it was a thing worth hearing all;\nWhen one's well meaning, there is no transgression;\nBut it is best to speak at one's discretion.\nHer bright hair was unbound, but combed withal;\nShe wore of green oak leaves a coronal\nUpon her lovely head. Then she began\nTwo fires upon the altar stone to fan,\nAnd did her ceremonies as we're told\nIn Statius' Thebaid and books as old.\nWhen kindled was the fire, with sober face\nUnto Diana spoke she in that place.\nO thou chaste goddess of the wildwood green,\nBy whom all heaven and earth and sea are seen,\nQueen of the realm of Pluto, dark and low,\nGoddess of maidens, that my heart dost know\nFor all my years, and knowest what I desire,\nOh, save me from thy vengeance and thine ire\nThat on Actaeon fell so cruelly.\nChaste goddess, well indeed thou knowest that I\nDesire to be a virgin all my life,\nNor ever wish to be man's love or wife.\nI am, thou know'st, yet of thy company,\nA maid, who loves the hunt and venery,\nAnd to go rambling in the greenwood wild,\nAnd not to be a wife and be with child.\nI do not crave the company of man.\nNow help me, lady, since thou may'st and can,\nBy the three beings who are one in thee.\nFor Palamon, who bears such love to me,\nAnd for Arcita, loving me so sore,\nThis grace I pray thee, without one thing more,\nTo send down love and peace between those two,\nAnd turn their hearts away from me: so do\nThat all their furious love and their desire,\nAnd all their ceaseless torment and their fire\nBe quenched or turned into another place;\nAnd if it be thou wilt not show this grace,\nOr if my destiny be moulded so\nThat I must needs have one of these same two,\nThen send me him that most desires me.\nBehold, O goddess of utter chastity,\nThe bitter tears that down my two cheeks fall.\nSince thou art maid and keeper of us all,\nMy maidenhead keep thou, and still preserve,\nAnd while I live a maid, thee will I serve.\nThe fires blazed high upon the altar there,\nWhile Emily was saying thus her prayer,\nBut suddenly she saw a sight most quaint,\nFor there, before her eyes, one fire went faint,\nThen blazed again; and after that, anon,\nThe other fire was quenched, and so was gone.\nAnd as it died it made a whistling sound,\nAs do wet branches burning on the ground,\nAnd from the brands' ends there ran out, anon,\nWhat looked like drops of blood, and many a one;\nAt which so much aghast was Emily\nThat she was near dazed, and began to cry,\nFor she knew naught of what it signified;\nBut only out of terror thus she cried\nAnd wept, till it was pitiful to hear.\nBut thereupon Diana did appear,\nWith bow in hand, like any right huntress,\nAnd said: My daughter, leave this heaviness.\nAmong the high gods it has been affirmed,\nAnd by eternal written word confirmed,\nThat you shall be the wife of one of those\nWho bear for you so many cares and woes;\nBut unto which of them may not tell.\nI can no longer tarry, so farewell.\nThe fires that on my altar burn incense\nShould tell you everything, ere you go hence,\nOf what must come of love in this your case.\nAnd with that word the arrows of the chase\nThe goddess carried clattered and did ring,\nAnd forth she went in mystic vanishing;\nAt which this Emily astonished was,\nAnd said she then: Ah, what means this, alas!\nI put myself in thy protection here,\nDiana, and at thy disposal dear.\nAnd home she wended, then, the nearest way.\nThis is the purport; there's no more to say.\nAt the next hour of Mars, and following this,\nArcita to the temple walked, that is\nDevoted to fierce Mars, to sacrifice\nWith all the ceremonies, pagan-wise.\nWith sobered heart and high devotion, on\nThis wise, right thus he said his orison.\nO mighty god that in the regions cold\nOf Thrace art honoured, where thy lordships hold,\nAnd hast in every realm and every land\nThe reins of battle in thy guiding hand,\nAnd givest fortune as thou dost devise,\nAccept of me my pious sacrifice.\nIf so it be that my youth may deserve,\nAnd that my strength be worthy found to serve\nThy godhead, and be numbered one of thine,\nThen pray I thee for ruth on pain that's mine.\nFor that same pain and even that hot fire\nWherein thou once did'st burn with deep desire,\nWhen thou did'st use the marvelous beauty\nOf fair young wanton Venus, fresh and free,\nAnd had'st her in thine arms and at thy will\n(Howbeit with thee, once, all the chance fell ill,\nAnd Vulcan caught thee in his net, whenas\nHe found thee lying with his wife, alas!)-\nFor that same sorrow that was in thy heart,\nHave pity, now, upon my pains that smart.\nI'm young, and little skilled, as knowest thou,\nWith love more hurt and much more broken now\nThan ever living creature was, I'm sure;\nFor she who makes me all this woe endure,\nWhether I float or sink cares not at all,\nAnd ere she'll hear with mercy when I call,\nI must by prowess win her in this place;\nAnd well I know, too, without help and grace\nOf thee, my human strength shall not avail\nThen help me, lord, tomorrow not to fail,\nFor sake of that same fire that once burned thee,\nThe which consuming fire so now burns me;\nAnd grant, tomorrow, I have victory.\nMine be the toil, and thine the whole glory!\nThy sovereign temple will I honour most\nOf any spot, and toil and count no cost\nTo pleasure thee and in thy craft have grace,\nAnd in thy fane my banner will I place,\nAnd all the weapons of my company;\nAnd evermore, until the day I die,\nEternal fire shalt thou before thee find.\nMoreover, to this vow myself I bind:\nMy beard, my hair that ripples down so long,\nThat never yet has felt the slightest wrong\nOf razor or of shears, to thee I'll give,\nAnd be thy loyal servant while I live.\nNow, lord, have pity on my sorrows sore;\nGive me the victory. I ask no more.\nWith ended prayer of Arcita the young,\nThe rings that on the temple door were hung,\nAnd even the doors themselves, rattled so fast\nThat this Arcita found himself aghast.\nThe fires blazed high upon the altar bright,\nUntil the entire temple shone with light;\nAnd a sweet odour rose up from the ground;\nAnd Arcita whirled then his arm around,\nAnd yet more incense on the fire he cast,\nAnd did still further rites; and at the last\nThe armour of God Mars began to ring,\nAnd with that sound there came a murmuring,\nLow and uncertain, saying: Victory!\nFor which he gave Mars honour and glory.\nAnd thus in joy and hope, which all might dare,\nArcita to his lodging then did fare,\nFain of the fight as fowl is of the sun.\nBut thereupon such quarrelling was begun,\nFrom this same granting, in the heaven above,\n'Twixt lovely Venus, goddess of all love,\nAnd Mars, the iron god armipotent,\nThat Jove toiled hard to make a settlement;\nUntil the sallow Saturn, calm and cold,\nWho had so many happenings known of old,\nFound from his full experience the art\nTo satisfy each party and each part.\nFor true it is, age has great advantage;\nExperience and wisdom come with age;\nMen may the old out-run, but not out-wit.\nThus Saturn, though it scarcely did befit\nHis nature so to do, devised a plan\nTo quiet all the strife, and thus began:\nNow my dear daughter Venus, quoth Saturn,\nMy course, which has so wide a way to turn,\nHas power more than any man may know.\nMine is the drowning in sea below;\nMine is the dungeon underneath the moat;\nMine is the hanging and strangling by the throat;\nRebellion, and the base crowd's murmuring,\nThe groaning and the private poisoning,\nAnd vengeance and amercement- all are mine,\nWhile yet I dwell within the Lion's sign.\nMine is the ruining of all high halls,\nAnd tumbling down of towers and of walls\nUpon the miner and the carpenter.\nI struck down Samson, that pillar shaker;\nAnd mine are all the maladies so cold,\nThe treasons dark, the machinations old;\nMy glance is father of all pestilence.\nNow weep no more. I'll see, with diligence,\nThat Palamon, who is your own true knight,\nShall have his lady, as you hold is right.\nThough Mars may help his man, yet none the less\nBetween you two there must come sometime peace,\nAnd though you be not of one temperament,\nCausing each day such violent dissent,\nI am your grandsire and obey your will;\nWeep then no more, your pleasure I'll fulfill.\nNow will I cease to speak of gods above,\nOf Mars and Venus, goddess of all love,\nAnd tell you now, as plainly as I can,\nThe great result, for which I first began.\nExplicit tercia pars.\nSequitur pars quarta.\n\nGreat was the fete in Athens on that day,\nAnd too, the merry season of the May\nGave everyone such joy and such pleasance\nThat all that Monday they'd but joust and dance,\nOr spend the time in Venus' high service.\nBut for the reason that they must arise\nBetimes, to see the heralded great fight,\nAll they retired to early rest that night.\nAnd on the morrow, when that day did spring,\nOf horse and harness, noise and clattering,\nThere was enough in hostelries about.\nAnd to the palace rode full many a rout\nOf lords, bestriding steeds and on palfreys.\nThere could you see adjusting of harness,\nSo curious and so rich, and wrought so well\nOf goldsmiths' work, embroidery, and of steel;\nThe shields, the helmets bright, the gay trappings,\nThe gold-hewn casques, the coats-of-arms, the rings,\nThe lords in vestments rich, on their coursers,\nKnights with their retinues and also squires;\nThe rivetting of spears, the helm-buckling,\nThe strapping of the shields, and. thong-lacing-\nIn their great need, not one of them was idle;\nThe frothing steeds, champing the golden bridle,\nAnd the quick smiths, and armourers also,\nWith file and hammer spurring to and fro;\nYeoman, and peasants with short staves were out,\nCrowding as thick as they could move about;\nPipes, trumpets, kettledrums, and clarions,\nThat in the battle sound such grim summons;\nThe palace full of people, up and down,\nHere three, there ten, debating the renown\nAnd questioning about these Theban knights,\nSome put it thus, some said, It's so by rights.\nSome held with him who had the great black beard,\nSome with the bald-heads, some with the thick haired;\nSome said, He looks grim, and he'll fight like hate;\nHe has an axe of twenty pound in weight.\nAnd thus the hall was full of gossiping\nLong after the bright sun began to spring.\nThe mighty Theseus, from sleep awakened\nBy songs and all the noise that never slackened,\nKept yet the chamber of this rich palace,\nTill the two Theban knights, with equal grace\nAnd honour, were ushered in with flourish fitting.\nDuke Theseus was at a window sitting,\nArrayed as he were god upon a throne.\nThen pressed the people thitherward full soon,\nTo see him and to do him reverence,\nAye, and to hear commands of sapience.\nA herald on a scaffold cried out Ho!\nTill all the people's noise was stilled; and so,\nWhen he observed that all were fallen still,\nHe then proclaimed the mighty ruler's will.\nThe duke our lord, full wise and full discreet,\nHolds that it were but wanton waste to meet\nAnd fight, these gentle folk, all in the guise\nOf mortal battle in this enterprise.\nWherefore, in order that no man may die,\nHe does his earlier purpose modify.\nNo man, therefore, on pain of loss of life,\nShall any arrow, pole-axe, or short knife\nSend into lists in any wise, or bring;\nNor any shortened sword, for point-thrusting,\nShall a man draw, or bear it by his side.\nNor shall knight against opponent ride,\nSave one full course, with any sharp-ground spear;\nUnhorsed, a man may thrust with any gear.\nAnd he that's overcome, should this occur,\nShall not be slain, but brought to barrier,\nWhereof there shall be one on either side;\nLet him be forced to go there and abide.\nAnd if by chance the leader there must go,\nOf either side, or slay his equal foe,\nNo longer, then, shall tourneying endure.\nGod speed you; go forth now, and lay on sure.\nWith long sword and with maces fight your fill.\nGo now your ways; this is the lord duke's will.\nThe voices of the people rent the skies,\nSuch was the uproar of their merry cries:\nNow God save such a lord, who is so good\nHe will not have destruction of men's blood!\nUp start the trumpets and make melody.\nAnd to the lists rode forth the company,\nIn marshalled ranks, throughout the city large,\nAll hung with cloth of gold, and not with serge.\nFull like a lord this noble duke did ride,\nWith the two Theban knights on either side;\nAnd, following, rode the queen and Emily,\nAnd, after, came another company\nOf one and other, each in his degree.\nAnd thus they went throughout the whole city,\nAnd to the lists they came, all in good time.\nThe day was not yet fully come to prime\nWhen throned was Theseus full rich and high,\nAnd Queen Hippolyta and Emily,\nWhile other ladies sat in tiers about.\nInto the seats then pressed the lesser rout.\nAnd westward, through the gate of Mars, right hearty,\nArcita and the hundred of his party\nWith banner red is entering anon;\nAnd in that self-same moment, Palamon\nIs under Venus, eastward in that place,\nWith banner white, and resolute of face.\nIn all the world, searching it up and down,\nSo equal were they all, from heel to crown,\nThere were no two such bands in any way.\nFor there was no man wise enough to say\nHow either had of other advantage\nIn high repute, or in estate, or age,\nSo even were they chosen, as I guess.\nAnd in two goodly ranks, they did then dress.\nAnd when the name was called of every one,\nThat cheating in their number might be none,\nThen were the gates closed, and the cry rang loud:\nNow do your devoir, all you young knights proud!\nThe heralds cease their spurring up and down;\nNow ring the trumpets as the charge is blown;\nAnd there's no more to say, for east and west\nTwo hundred spears are firmly laid in rest;\nAnd the sharp spurs are thrust, now, into side.\nNow see men who can joust and who can ride!\nNow shivered are the shafts on bucklers thick;\nOne feels through very breast-bone the spear's prick;\nLances are flung full twenty feet in height;\nOut flash the swords like silver burnished bright.\nHelmets are hewed, the lacings ripped and shred;\nOut bursts the blood, gushing in stern streams red.\nWith mighty maces bones are crushed in joust.\nOne through the thickest throng begins to thrust.\nThere strong steeds stumble now, and down goes all.\nOne rolls beneath their feet as rolls a ball.\nOne flails about with club, being overthrown,\nAnother, on a mailed horse, rides him down.\nOne through the body's hurt, and haled, for aid.\nSpite of his struggles, to the barricade,\nAs compact was, and there he must abide;\nAnother's captured by the other side.\nAt times Duke Theseus orders them to rest,\nTo eat a bite and drink what each likes best.\nAnd many times that day those Thebans two\nMet in the fight and wrought each other woe;\nUnhorsed each has the other on that day.\nNo tigress in the vale of Galgophey,\nWhose little whelp is stolen in the light,\nIs cruel to the hunter as Arcite\nFor jealousy is cruel to Palamon;\nNor in Belmarie, when the hunt is on\nIs there a lion, wild for want of food,\nThat of his prey desires so much the blood\nAs Palamon the death of Arcite there.\nTheir jealous blows fall on their helmets fair;\nOut leaps the blood and makes their two sides red.\nBut sometime comes the end of every deed;\nAnd ere the sun had sunk to rest in gold,\nThe mighty King Emetreus did hold\nThis Palamon, as he fought with Arcite,\nAnd made his sword deep in the flesh to bite;\nAnd by the force of twenty men he's made,\nUnyielded, to withdraw to barricade.\nAnd, trying hard to rescue Palamon,\nThe mighty King Lyburgus is borne down;\nAnd King Emetreus, for all his strength,\nIs hurled out of the saddle a sword's length,\nSo hits out Palamon once more, or ere\n(But all for naught) he's brought to barrier.\nHis hardy heart may now avail him naught;\nHe must abide there now, being fairly caught\nBy force of arms, as by provision known.\nWho sorrows now but woeful Palamon,\nWho may no more advance into the fight?\nAnd when Duke Theseus had seen this sight,\nUnto the warriors fighting, every one,\nHe cried out: Hold! No more! For it is done!\nNow will I prove true judge, of no party.\nTheban Arcita shall have Emily,\nWho, by his fortune, has her fairly won.\nAnd now a noise of people is begun\nFor joy of this, so loud and shrill withal,\nIt seems as if the very lists will fall.\nBut now, what can fair Venus do above?\nWhat says she now? What does this queen of love\nBut weep so fast, for thwarting of her will,\nHer tears upon the lists begin to spill.\nShe said: Now am I shamed and over-flung.\nBut Saturn said: My daughter, hold your tongue.\nMars has his will, his knight has all his boon,\nAnd, by my head, you shall be eased, and soon.\nThe trumpeters and other minstrelsy,\nThe heralds that did loudly yell and cry,\nWere at their best for joy of Arcita.\nBut hear me further while I tell you- ah!-\nThe miracle that happened there anon.\nThis fierce Arcita doffs his helmet soon,\nAnd mounted on a horse, to show his face,\nHe spurs from end to end of that great place,\nLooking aloft to gaze on Emily;\nAnd she cast down on him a friendly eye\n(For women, generally speaking, go\nWherever Fortune may her favor show)\nAnd she was fair to see, and held his heart.\nBut from the ground infernal furies start,\nFrom Pluto sent, at instance of Saturn,\nWhereat his horse, for fear, began to turn\nAnd leap aside, all suddenly falling there;\nAnd Arcita before he could beware\nWas pitched upon the ground, upon his head,\nAnd lay there, moving not, as he were dead,\nHis chest crushed in upon the saddle-bow.\nAnd black he lay as ever coal, or crow,\nSo ran the surging blood into his face.\nAnon they carried him from out that place,\nWith heavy hearts, to Theseus' palace.\nThere was his harness cut away, each lace,\nAnd swiftly was he laid upon a bed,\nFor he was yet alive and some words said,\nCrying and calling after Emily.\nDuke Theseus, with all his company,\nIs come again to Athens, his city,\nWith joyous heart and great festivity.\nAnd though sore grieved for this unhappy fall,\nHe would not cast a blight upon them all.\nMen said, too, that Arcita should not die,\nBut should be healed of all his injury.\nAnd of another thing they were right fain,\nWhich was, that of them all no one was slain,\nThough each was sore, and hurt, and specially one\nWho'd got a lance-head thrust through his breastbone.\nFor other bruises, wounds and broken arms,\nSome of them carried salves and some had charms;\nAnd medicines of many herbs, and sage\nThey drank, to keep their limbs from hemorrhage.\nIn all of which this duke, as he well can,\nNow comforts and now honours every man,\nAnd makes a revelry the livelong night\nFor all these foreign lords, as was but right.\nNor was there held any discomfiting,\nSave from the jousts and from the tourneying.\nFor truly, there had been no cause for shame,\nSince being thrown is fortune of the game;\nNor is it, to be led to barrier,\nUnyielded, and by twenty knights' power,\nOne man alone, surrounded by the foe,\nDriven by arms, and dragged out, heel and toe,\nAnd with his courser driven forth with staves\nOf men on foot, yeomen and serving knaves-\nAll this imputes to one no kind of vice,\nAnd no man may bring charge of cowardice.\nFor which, anon, Duke Theseus bade cry,\nTo still all rancour and all keen envy,\nThe worth, as well of one side as the other,\nAs equal both, and each the other's brother;\nAnd gave them gifts according to degree,\nAnd held a three days' feast, right royally;\nAnd then convoyed these kings upon their road\nFor one full day, and to them honour showed.\nAnd home went every man on his right way.\nThere was naught more but Farewell and Good-day.\nI'll say no more of war, but turn upon\nMy tale of Arcita and Palamon.\nSwells now Arcita's breast until the sore\nIncreases near his heart yet more and more.\nThe clotted blood, in spite of all leech-craft,\nRots in his bulk, and there is must be left,\nSince no device of skillful blood-letting,\nNor drink of herbs, can help him in this thing.\nThe power expulsive, or virtue animal\nCalled from its use the virtue natural,\nCould not the poison void, nor yet expel.\nThe tubes of both his lungs began to swell,\nAnd every tissue in his breast, and down,\nIs foul with poison and all rotten grown.\nHe gains in neither, in his strife to live,\nBy vomiting or taking laxative;\nAll is so broken in that part of him,\nNature Tetains no vigour there, nor vim.\nAnd certainly, where Nature will not work,\nIt's farewell physic, bear the man to kirk!\nThe sum of all is, Arcita must die,\nAnd so he sends a word to Emily,\nAnd Palamon, who was his cousin dear;\nAnd then he said to them as you shall hear.\nNaught may the woeful spirit in my heart\nDeclare one point of how my sorrows smart\nTo you, my lady, whom I love the most;\nBut I bequeath the service of my ghost\nTo you above all others, this being sure\nNow that my life may here no more endure.\nAlas, the woe! Alas, the pain so strong\nThat I for you have suffered, and so long!\nAlas for death! Alas, my Emily!\nAlas, the parting of our company!\nAlas, my heart's own queen! Alas, my wife!\nMy soul's dear lady, ender of my life!\nWhat is this world? What asks a man to have?\nNow with his love, now in the cold dark grave\nAlone, with never any company.\nFarewell, my sweet foe! O my Emily!\nOh, take me in your gentle arms, I pray,\nFor love of God, and hear what I will say.\n\nI have here, with my cousin Palamon,\nHad strife and rancour many a day that's gone,\nFor love of you and for my jealousy.\nMay Jove so surely guide my soul for me,\nTo speak about a lover properly,\nWith all the circumstances, faithfully-\nThat is to say, truth, honour, and knighthood,\nWisdom, humility and kinship good,\nAnd generous soul and all the lover's art-\nSo now may Jove have in my soul his part\nAs in this world, right now, I know of none\nSo worthy to be loved as Palamon,\nWho serves you and will do so all his life.\nAnd if you ever should become a wife,\nForget not Palamon, the noble man.\nAnd with that word his speech to fail began,\nFor from his feet up to his breast had come\nThe cold of death, making his body numb.\nAnd furthermore, from his two arms the strength\nWas gone out, now, and he was lost, at length.\nOnly the intellect, and nothing more.\nWhich dwelt within his heart so sick and sore,\nBegan to fail now, when the heart felt death,\nAnd his eyes darkened, and he failed of breath.\nBut on his lady turned he still his eye,\nAnd his last word was, Mercy, Emily!\nHis spirit changed its house and went away.\nAs I was never there, I cannot say\nWhere; so I stop, not being a soothsayer;\nOf souls here naught shall I enregister;\nNor do I wish their notions, now, to tell\nWho write of them, though they say where they dwell.\nArcita's cold; Mars guides his soul on high;\nNow will I speak forthwith of Emily.\nShrieked Emily and howled now Palamon,\nTill Theseus his sister took, anon,\nAnd bore her, swooning, from the corpse away.\nHow shall it help, to dwell the livelong day\nIn telling how she wept both night and morrow?\nFor in like cases women have such sorrow,\nWhen their good husband from their side must go,\nAnd, for the greater part, they take on so,\nOr else they fall into such malady\nThat, at the last, and certainly, they die.\nInfinite were the sorrows and the tears\nOf all old folk and folk of tender years\nThroughout the town, at death of this Theban;\nFor him there wept the child and wept the man;\nSo great a weeping was not, 'tis certain,\nWhen Hector was brought back, but newly slain,\nTo Troy. Alas, the sorrow that was there!\nTearing of cheeks and rending out of hair.\nOh why will you be dead, these women cry,\nWho had of gold enough, and Emily?\nNo man might comfort then Duke Theseus,\nExcepting his old father, AEgeus,\nWho knew this world's mutations, and men's own.\nSince he had seen them changing up and down,\nJoy after woe, and woe from happiness:\nHe showed them, by example, the process.\nJust as there never died a man, quoth he,\nBut he had lived on earth in some degree,\nJust so there never lived a man, he said,\nIn all this world, but must be sometime dead.\nThis world is but a thoroughfare of woe,\nAnd we are pilgrims passing to and fro;\nDeath is the end of every worldly sore.\nAnd after this, he told them yet much more\nTo that effect, all wisely to exhort\nThe people that they should find some comfort.\nDuke Theseus now considered and with care\nWhat place of burial he should prepare\nFor good Arcita, as it best might be,\nAnd one most worthy of his high degree.\nAnd at the last concluded, hereupon,\nThat where at first Arcita and Palamon\nHad fought for love, with no man else between,\nThere, in that very grove, so sweet and green,\nWhere he mused on his amorous desires\nComplaining of love's hot and flaming fires,\nHe'd make a pyre and have the funeral\nAccomplished there, and worthily in all.\nAnd so he gave command to hack and hew\nThe ancient oaks, and lay them straight and true\nIn split lengths that would kindle well and burn.\nHis officers, with sure swift feet, they turn\nAnd ride away to do his whole intent.\nAnd after this Duke Theseus straightway sent\nFor a great bier, and had it all o'er-spread\nWith cloth of gold, the richest that he had.\nArcita clad he, too, in cloth of gold;\nWhite gloves were on his hands where they did fold;\nUpon his head a crown of laurel green,\nAnd near his hand a sword both bright and keen.\nThen, having bared the dead face on the bier,\nThe duke so wept, 'twas pitiful to hear.\nAnd, so that folk might see him, one and all,\nWhen it was day he brought them to the hall,\nWhich echoed of their wailing cries anon.\nThen came this woeful Theban, Plamon,\nWith fluttery beard and matted, ash-strewn hair,\nAll in black clothes wet with his tears; and there,\nSurpassing all in weeping, Emily,\nThe most affected of the company.\nAnd so that every several rite should be\nNoble and rich, and suiting his degree,\nDuke Theseus commanded that they bring\nThree horses, mailed in steel all glittering,\nAnd covered with Arcita's armour bright.\nUpon these stallions, which were large and white,\nThere rode three men, whereof one bore the shield.\nAnd one the spear he'd known so well to wield;\nThe third man bore his Turkish bow, nor less\nOf burnished gold the quiver than harness;\nAnd forth they slowly rode, with mournful cheer,\nToward that grove, as you shall further hear.\nThe noblest Greeks did gladly volunteer\nTo bear upon their shoulders that great bier,\nWith measured pace and eyes gone red and wet,\nThrough all the city, by the wide main street,\nWhich was all spread with black, and, wondrous high,\nCovered with this same cloth were houses nigh.\nUpon the right hand went old AEgeus,\nAnd on the other side Duke Theseus,\nWith vessels in their hands, of gold right fine,\nAll filled with honey, milk, and blood, and wine;\nAnd Palamon with a great company;\nAnd after that came woeful Emily,\nWith fire in hands, as use was, to ignite\nThe sacrifice and set the pyre alight.\nGreat labour and full great apparelling\nWent to the service and the fire-making,\nFor to the skies that green pyre reached its top,\nAnd twenty fathoms did the arms out-crop,\nThat is to say, the branches went so wide.\nFull many a load of straw they did provide.\nBut how the fire, was made to climb so high;\nOr what names all the different trees went by.\nAs oak, fir, birch, asp, alder, poplar, holm,\nWillow, plane, ash, box, chestnut, linden, elm,\nLaurel, thorn, maple, beech, yew, dogwood tree,\nOr how they were felled, sha'n't be told by me.\nNor how the wood-gods scampered up and down,\nDriven from homes that they had called their own,\nWherein they'd lived so long at ease, in peace,\nThe nymphs, the fauns, the hamadryades;\nNor how the beasts, for fear, and the birds, all\nFled, when that ancient wood began to fall;\nNor how aghast the ground was in the light,\nNot being used to seeing the sun so bright;\nNor how the fire was started first with straw,\nAnd then with dry wood, riven thrice by saw,\nAnd then with green wood and with spicery,\nAnd then with cloth of gold and jewellery,\nAnd garlands hanging with full many a flower,\nAnd myrrh, and incense, sweet as rose in bower;\nNor how Arcita lies among all this,\nNor what vast wealth about his body is;\nNor how this Emily, as was their way,\nLighted the sacred funeral fire, that day,\nNor how she swooned when men built up the fire,\nNor what she said, nor what was her desire;\nNo, nor what gems men on the fire then cast,\nWhen the white flame went high and burned so fast;\nNor how one cast his shield, and one his spear,\nAnd some their vestments, on that burning bier,\nWith cups of wine, and cups of milk, and blood,\nInto that flame, which burned as wild-fire would;\nNor how the Greeks, in one huge wailing rout,\nRode slowly three times all the fire about,\nUpon the left hand, with a loud shouting,\nAnd three times more, with weapons clattering,\nWhile thrice the women there raised up a cry;\nNor how was homeward led sad Emily;\nNor how Arcita burned to ashes cold;\nNor aught of how the lichwake they did hold\nAll that same night, nor how the Greeks did play\nThe Funeral Games, I will not say,\nWho, naked, wrestled best, with oil anointed,\nNor who best bore himself in deeds appointed.\nI will not even tell how they were gone\nHome, into Athens, when the play was done;\nBut briefly to the point, now, will I wend\nAnd make of this, my lengthy tale, an end.\nWith passing in their length of certain years,\nAll put by was the mourning and the tears\nOf Greeks, as by one general assent;\nAnd then it seems there was a parliament\nAt Athens, upon certain points in case;\nAmong the which points spoken of there was\nThe ratifying of alliances\nThat should hold Thebes from all defiances.\nWhereat this noble Theseus, anon,\nInvited there the gentle Palamon,\nNot telling him what was the cause, and why;\nBut in his mourning clothes, and sorrowfully,\nHe came upon that bidding, so say I.\nAnd then Duke Theseus sent for Emily.\nWhen they were seated and was hushed the place,\nAnd Theseus had mused a little space,\nEre any word came from his full wise breast,\nHis two eyes fixed on whoso pleased him best,\nThen with a sad face sighed he deep and still,\nAnd after that began to speak his will.\nThe Primal Mover and the Cause above,\nWhen first He forged the goodly chain of love,\nGreat the effect, and high was His intent;\nWell knew He why, and what thereof He meant;\nFor with that goodly chain of love He bound\nThe fire, the air, the water, and dry ground\nIn certain bounds, the which they might not flee;\nThat same First Cause and Mover, then quoth he,\nHas stablished in this base world, up and down,\nA certain length of days to call their own\nFor all that are engendered in this place,\nBeyond the which not one day may they pace,\nThough yet all may that certain time abridge;\nAuthority there needs none, I allege,\nFor it is well proved by experience,\nSave that I please to clarify my sense.\nThen may men by this order well discern\nThis Mover to be stable and eterne.\nWell may man know, unless he be a fool,\nThat every part derives but from the whole.\nFor Nature has not taken his being\nFrom any part and portion of a thing,\nBut from a substance perfect, stable aye,\nAnd so continuing till changed away.\nAnd therefore, of His Wisdom's Providence,\nHas He so well established ordinance\nThat species of all things and all progressions,\nIf they'd endure, it must be by successions,\nNot being themselves eternal, 'tis no lie:\nThis may you understand and see by eye.\nLo now, the oak, that has long nourishing\nEven from the time that it begins to spring,\nAnd has so long a life, as we may see,\nYet at the last all wasted is the tree.\nConsider, too, how even the hard stone\nUnder our feet we tread each day upon\nYet wastes it, as it lies beside the way.\nAnd the broad river will be dry some day.\nAnd great towns wane; we see them vanishing.\nThus may we see the end to everything.\nOf man and woman just the same is true:\nNeeds must, in either season of the two,\nThat is to say, in youth or else in age,\nAll men perish, the king as well as page;\nSome in their bed, and some in the deep sea,\nAnd some in the wide field- as it may be;\nThere's naught will help; all go the same way. Aye,\nThen may I say that everything must die.\nWho causes this but Jupiter the King?\nHe is the Prince and Cause of everything,\nConverting all back to that primal well\nFrom which it was derived, 'tis sooth to tell.\nAnd against this, for every thing alive,\nOf any state, avalls it not to strive.\nThen is it wisdom, as it seems to me,\nTo make a virtue of necessity,\nAnd calmly take what we may not eschew,\nAnd specially that which to all is due.\nWhoso would balk at aught, he does folly,\nAnd thus rebels against His potency.\nAnd certainly a man has most honour\nIn dying in his excellence and flower,\nWhen he is certain of his high good name;\nFor then he gives to friend, and self, no shame.\nAnd gladder ought a friend be of his death\nWhen, in much honour, he yields up his breath,\nThan when his name's grown feeble with old age;\nFor all forgotten, then, is his courage.\nHence it is best for all of noble name\nTo die when at the summit of their fame.\nThe contrary of this is wilfulness.\nWhy do we grumble? Why have heaviness\nThat good Arcita, chivalry's fair flower,\nIs gone, with honour, in his best-lived hour.\nOut of the filthy prison of this life?\nWhy grumble here his cousin and his wife\nAbout his welfare, who loved them so well?\nCan he thank them? Nay, God knows, not! Nor tell\nHow they his soul and their own selves offend,\nThough yet they may not their desires amend.\nWhat may I prove by this long argument\nSave that we all turn to merriment,\nAfter our grief, and give Jove thanks for grace.\nAnd so, before we go from out this place,\nI counsel that we make, of sorrows two\nOne perfect joy, lasting for aye, for you;\nAnd look you now, where most woe is herein,\nThere will we first amend it and begin.\nSister, quoth he, you have my full consent,\nWith the advice of this my Parliament,\nThat gentle Palamon, your own true knight,\nWho serves you well with will and heart and might,\nAnd so has ever, since you knew him first-\nThat you shall, of your grace, allay his thirst\nBy taking him for husband and for lord:\nLend me your hand, for this is our accord.\nLet now your woman's pity make him glad.\nFor he is a king's brother's son, by gad;\nAnd though he were a poor knight bachelor,\nSince he has served you for so many a year,\nAnd borne for you so great adversity,\nThis ought to weigh with you, it seems to me,\nFor mercy ought to dominate mere right.\nThen said he thus to Palamon the knight:\nI think there needs but little sermoning\nTo make you give consent, now, to this thing.\nCome near, and take your lady by the hand.\nBetween them, then, was tied that nuptial band,\nWhich is called matrimony or marriage,\nBy all the council and the baronage.\nAnd thus, in all bliss and with melody,\nHas Palamon now wedded Emily.\nAnd God Who all this universe has wrought,\nSend him His love, who has it dearly bought.\nFor now has Palamon, in all things, wealth,\nLiving in bliss, in riches, and in health;\nAnd Emily loved him so tenderly,\nAnd he served her so well and faithfully,\nThat never word once marred their happiness,\nNo jealousy, nor other such distress.\nThus ends now Palamon and Emily;\nAnd may God save all this fair company! Amen.\n\n\n### The Miller's Prologue\n\nNow when the knight had thus his story told,\nIn all the rout there was nor young nor old\nBut said it was a noble story, well\nWorthy to be kept in mind to tell;\nAnd specially the gentle folk, each one.\nOur host, he laughed and swore, So may I run,\nBut this goes well; unbuckled is the mail;\nLet's see now who can tell another tale:\nFor certainly the game is well begun.\nNow shall you tell, sir monk, if't can be done,\nSomething with which to pay for the knight's tale.\nThe miller, who with drinking was all pale,\nSo that unsteadily on his horse he sat,\nHe would not take off either hood or hat,\nNor wait for any man, in courtesy,\nBut all in Pilate's voice began to cry,\nAnd by the Arms and Blood and Bones he swore,\nI have a noble story in my store,\nWith which I will requite the good knight's tale.\nOur host saw, then, that he was drunk with ale,\nAnd said to him: Wait, Robin, my dear brother,\nSome better man shall tell us first another:\nSubmit and let us work on profitably.\nNow by God's soul, cried he, that will not I!\nFor I will speak, or else I'll go my way.\nOur host replied: Tell on, then, till doomsday!\nYou are a fool, your wit is overcome.\nNow hear me, said the miller, all and some!\nBut first I make a protestation round\nThat I'm quite drunk, I know it by my sound:\nAnd therefore, if I slander or mis-say,\nBlame it on ale of Southwark, so I pray;\nFor I will tell a legend and a life\nBoth of a carpenter and of his wife,\nAnd how a scholar set the good wright's cap.\nThe reeve replied and said: Oh, shut your trap,\nLet be your ignorant drunken ribaldry!\nIt is a sin, and further, great folly\nTo asperse any man, or him defame,\nAnd, too, to bring upon a man's wife shame.\nThere are enough of other things to say.\nThis drunken miller spoke on in his way,\nAnd said: Oh, but my dear brother Oswald,\nThe man who has no wife is no cuckold.\nBut I say not, thereby, that you are one:\nMany good wives there are, as women run,\nAnd ever a thousand good to one that's bad,\nAs well you know yourself, unless you're mad.\nWhy are you angry with my story's cue?\nI have a wife, begad, as well as you,\nYet I'd not, for the oxen of my plow,\nTake on my shoulders more than is enow,\nBy judging of myself that I am one;\nI will believe full well that I am none.\nA husband must not be inquisitive\nOf God, nor of his wife, while she's alive.\nSo long as he may find God's plenty there,\nFor all the rest he need not greatly care.\nWhat should I say, except this miller rare\nHe would forgo his talk for no man there,\nBut told his churlish tale in his own way:\nI think I'll here re-tell it, if I may.\nAnd therefore, every gentle soul, I pray\nThat for God's love you'll hold not what I say\nEvilly meant, but that I must rehearse,\nAll of their tales, the better and the worse,\nOr else prove false to some of my design.\nTherefore, who likes not this, let him, in fine,\nTurn over page and choose another tale:\nFor he shall find enough, both great and small,\nOf stories touching on gentility,\nAnd holiness, and on morality;\nAnd blame not me if you do choose amiss.\nThe miller was a churl, you well know this;\nSo was the reeve, and many another more,\nAnd ribaldry they told from plenteous store.\nBe then advised, and hold me free from blame;\nMen should not be too serious at a game.\n\n\n### The Miller's Tale\n\nOnce on a time was dwelling in Oxford\nA wealthy lout who took in guests to board,\nAnd of his craft he was a carpenter.\nA poor scholar was lodging with him there,\nWho'd learned the arts, but all his phantasy\nWas turned to study of astrology;\nAnd knew a certain set of theorems\nAnd could find out by various stratagems,\nIf men but asked of him in certain hours\nWhen they should have a drought or else have showers,\nOr if men asked of him what should befall\nTo anything- I cannot reckon them all.\nThis clerk was called the clever Nicholas;\nOf secret loves he knew and their solace;\nAnd he kept counsel, too, for he was sly\nAnd meek as any maiden passing by.\nHe had a chamber in that hostelry,\nAnd lived alone there, without company,\nAll garnished with sweet herbs of good repute;\nAnd he himself sweet-smelling as the root\nOf licorice, valerian, or setwall.\nHis Almagest, and books both great and small,\nHis astrolabe, belonging to his art,\nHis algorism stones- all laid apart\nOn shelves that ranged beside his lone bed's head;\nHis press was covered with a cloth of red.\nAnd over all there lay a psaltery\nWhereon he made an evening's melody,\nPlaying so sweetly that the chamber rang;\nAnd Angelus ad virginem he sang;\nAnd after that he warbled the King's Note:\nOften in good voice was his merry throat.\nAnd thus this gentle clerk his leisure spends\nSupported by some income and his friends.\nThis carpenter had lately wed a wife\nWhom lie loved better than he loved his life;\nAnd she was come to eighteen years of age.\nJealous he was and held her close in cage.\nFor she was wild and young, and he was old,\nAnd deemed himself as like to be cuckold.\nHe knew not Cato, for his lore was rude:\nThat vulgar man should wed similitude.\nA man should wed according to estate,\nFor youth and age are often in debate.\nBut now, since he had fallen in the snare,\nHe must endure, like other folk, his care.\nFair was this youthful wife, and therewithal\nAs weasel's was her body slim and small.\nA girdle wore she, barred and striped, of silk.\nAn apron, too, as white as morning milk\nAbout her loins, and full of many a gore;\nWhite was her smock, embroidered all before\nAnd even behind, her collar round about,\nOf coal-black silk, on both sides, in and out;\nThe strings of the white cap upon her head\nWere, like her collar, black silk worked with thread,\nHer fillet was of wide silk worn full high:\nAnd certainly she had a lickerish eye.\nShe'd thinned out carefully her eyebrows two,\nAnd they were arched and black as any sloe.\nShe was a far more pleasant thing to see\nThan is the newly budded young pear-tree;\nAnd softer than the wool is on a wether.\nDown from her girdle hung a purse of leather,\nTasselled with silk, with latten beading sown.\nIn all this world, searching it up and down,\nSo gay a little doll, I well believe,\nOr such a wench, there's no man can conceive.\nFar brighter was the brilliance of her hue\nThan in the Tower the gold coins minted new.\nAnd songs came shrilling from her pretty head\nAs from a swallow's sitting on a shed.\nTherewith she'd dance too, and could play and sham\nLike any kid or calf about its dam.\nHer mouth was sweet as bragget or as mead\nOr hoard of apples laid in hay or weed.\nSkittish she was as is a pretty colt,\nTall as a staff and straight as cross-bow bolt.\nA brooch she wore upon her collar low,\nAs broad as boss of buckler did it show;\nHer shoes laced up to where a girl's legs thicken.\nShe was a primrose, and a tender chicken\nFor any lord to lay upon his bed,\nOr yet for any good yeoman to wed.\nNow, sir, and then, sir, go befell the case,\nThat on a day this clever Nicholas\nFell in with this young wife to toy and play,\nThe while her husband was down Osney way,\nClerks being as crafty as the best of us;\nAnd unperceived he caught her by the puss,\nSaying: Indeed, unless I have my will,\nFor secret love of you, sweetheart, I'll spill.\nAnd held her hard about the hips, and how!\nAnd said: O darling, love me, love me now,\nOr I shall die, and pray you God may save!\nAnd she leaped as a colt does in the trave,\nAnd with her head she twisted fast away,\nAnd said: I will not kiss you, by my fay!\nWhy, let go, cried she, let go, Nicholas!\nOr I will call for help and cry 'alas!'\nDo take your hands away, for courtesy!\nThis Nicholas for mercy then did cry,\nAnd spoke so well, importuned her so fast\nThat she her love did grant him at the last,\nAnd swore her oath, by Saint Thomas of Kent,\nThat she would be at his command, content,\nAs soon as opportunity she could spy.\nMy husband is so full of jealousy,\nUnless you will await me secretly,\nI know I'm just as good as dead, said she.\nYou must keep all quite hidden in this case.\nNay, thereof worry not, said Nicholas,\nA clerk has lazily employed his while\nIf he cannot a carpenter beguile.\nAnd thus they were agreed, and then they swore\nTo wait a while, as I have said before.\nWhen Nicholas had done thus every whit\nAnd patted her about the loins a bit,\nHe kissed her sweetly, took his psaltery,\nAnd played it fast and made a melody.\nThen fell it thus, that to the parish kirk,\nThe Lord Christ Jesus' own works for to work,\nThis good wife went, upon a holy day;\nHer forehead shone as bright as does the May,\nSo well she'd washed it when she left off work.\nNow there was of that church a parish clerk\nWhose name was (as folk called him) Absalom.\nCurled was his hair, shining like gold, and from\nHis head spread fanwise in a thick bright mop;\n'Twas parted straight and even on the top;\nHis cheek was red, his eyes grey as a goose;\nWith Saint Paul's windows cut upon his shoes,\nHe stood in red hose fitting famously.\nAnd he was clothed full well and properly\nAll in a coat of blue, in which were let\nHoles for the lacings, which were fairly set.\nAnd over all he wore a fine surplice\nAs white as ever hawthorn spray, and nice.\nA merry lad he was, so God me save,\nAnd well could he let blood, cut hair, and shave,\nAnd draw a deed or quitclaim, as might chance.\nIn twenty manners could he trip and dance,\nAfter the school that reigned in Oxford, though,\nAnd with his two legs swinging to and fro;\nAnd he could play upon a violin;\nThereto he sang in treble voice and thin;\nAnd as well could he play on his guitar.\nIn all the town no inn was, and no bar,\nThat he'd not visited to make good cheer,\nEspecially were lively barmaids there.\nBut, truth to tell, he was a bit squeamish\nOf farting and of language haughtyish.\nThis Absalom, who was so light and gay,\nWent with a censer on the holy day,\nCensing the wives like an enthusiast;\nAnd on them many a loving look he cast,\nEspecially on this carpenter's goodwife.\nTo look at her he thought a merry life,\nShe was so pretty, sweet, and lickerous.\nI dare well say, if she had been a mouse\nAnd he a cat, he would have mauled her some.\nThis parish clerk, this lively Absalom\nHad in his heart, now, such a love-longing\nThat from no wife took he an offering;\nFor courtesy, he said, he would take none.\nThe moon, when it was night, full brightly shone,\nAnd his guitar did Absalom then take,\nFor in love-watching he'd intent to wake.\nAnd forth he went, jolly and amorous,\nUntil he came unto the carpenter's house\nA little after cocks began to crow;\nAnd took his stand beneath a shot-window\nThat was let into the good wood-wright's wall.\nHe sang then, in his pleasant voice and small,\nOh now, dear lady, if your will it be,\nI pray that you will have some ruth on me,\nThe words in harmony with his string-plucking.\nThis carpenter awoke and heard him sing,\nAnd called unto his wife and said, in sum:\nWhat, Alison! Do you hear Absalom,\nWho plays and sings beneath our bedroom wall?\nAnd she said to her husband, therewithal:\nYes, God knows, John, I hear it, truth to tell.\nSo this went on; what is there better than well?\nFrom day to day this pretty Absalom\nSo wooed her he was woebegone therefrom.\nHe lay awake all night and all the day;\nHe combed his spreading hair and dressed him gay;\nBy go-betweens and agents, too, wooed he,\nAnd swore her loyal page he'd ever be.\nHe sang as tremulously as nightingale;\nHe sent her sweetened wine and well-spiced ale\nAnd waffles piping hot out of the fire,\nAnd, she being town-bred, mead for her desire.\nFor some are won by means of money spent,\nAnd some by tricks, and some by long descent.\nOnce, to display his versatility,\nHe acted Herod on a scaffold high.\nBut what availed it him in any case?\nShe was enamoured so of Nicholas\nThat Absalom might go and blow his horn;\nHe got naught for his labour but her scorn.\nAnd thus she made of Absalom her ape,\nAnd all his earnestness she made a jape.\nFor truth is in this proverb, and no lie,\nMen say well thus: It's always he that's nigh\nThat makes the absent lover seem a sloth.\nFor now, though Absalom be wildly wroth,\nBecause he is so far out of her sight,\nThis handy Nicholas stands in his light.\nNow bear you well, you clever Nicholas!\nFor Absalom may wail and sing Alas!\nAnd so it chanced that on a Saturday\nThis carpenter departed to. Osney;\nAnd clever Nicholas and Alison\nWere well agreed to this effect: anon\nThis Nicholas should put in play a wile\nThe simple, jealous husband to beguile;\nAnd if it chanced the game should go a-right,\nShe was to sleep within his arms all night,\nFor this was his desire, and hers also.\nPresently then, and without more ado,\nThis Nicholas, no longer did he tarry,\nBut softly to his chamber did he carry\nBoth food and drink to last at least a day,\nSaying that to her husband she should say-\nIf he should come to ask for Nicholas-\nWhy, she should say she knew not where he was,\nFor all day she'd not seen him, far or nigh;\nShe thought he must have got some malady,\nBecause in vain her maid would knock and call;\nHe'd answer not, whatever might befall.\n\nAnd so it was that all that Saturday\nThis Nicholas quietly in chamber lay,\nAnd ate and slept, or did what pleased him best,\nTill Sunday when the sun had gone to rest.\nThis simple man with wonder heard the tale,\nAnd marvelled what their Nicholas might ail,\nAnd said: I am afraid, by Saint Thomas,\nThat everything's not well with Nicholas.\nGod send he be not dead so suddenly!\nThis world is most unstable, certainly;\nI saw, today, the corpse being borne to kirk\nOf one who, but last Monday, was at work.\nGo up, said he unto his boy anon,\nCall at his door, or knock there with a stone,\nLearn how it is and boldly come tell me.\nThe servant went up, then, right sturdily,\nAnd at the chamber door, the while he stood,\nHe cried and knocked as any madman would-\nWhat! How! What do you, Master Nicholay?\nHow can you sleep through all the livelong day?\nBut all for naught, he never heard a word;\nA hole he found, low down upon a board,\nThrough which the house cat had been wont to creep;\nAnd to that hole he stooped, and through did peep,\nAnd finally he ranged him in his sight.\nThis Nicholas sat gaping there, upright,\nAs if he'd looked too long at the new moon.\nDownstairs he went and told his master soon\nIn what array he'd found this self-same man.\nThis carpenter to cross himself began,\nAnd said: Now help us, holy Frideswide!\nLittle a man can know what shall betide.\nThis man is fallen, with his astromy,\nInto some madness or some agony;\nI always feared that somehow this would be!\nMen should not meddle in God's privity.\nAye, blessed always be the ignorant man,\nWhose creed is, all he ever has to scan!\nSo fared another clerk with astromy;\nHe walked into the meadows for to pry\nInto the stars, to learn what should befall,\nUntil into a clay-pit he did fall;\nHe saw not that. But yet, by Saint Thomas,\nI'm sorry for this clever Nicholas.\nHe shall be scolded for his studying,\nIf not too late, by Jesus, Heaven's King!\nGet me a staff, that I may pry before,\nThe while you, Robin, heave against the door.\nWe'll take him from this studying, I guess.\nAnd on the chamber door, then, he did press.\nHis servant was a stout lad, if a dunce,\nAnd by the hasp he heaved it up at once;\nUpon the floor that portal fell anon.\nThis Nicholas sat there as still as stone,\nGazing, with gaping mouth, straight up in air.\nThis carpenter thought he was in despair,\nAnd took him by the shoulders, mightily,\nAnd shook him hard, and cried out, vehemently:\nWhat! Nicholay! Why how now! Come, look down!\nAwake, and think on Jesus' death and crown!\nI cross you from all elves and magic wights!\nAnd then the night-spell said he out, by rights,\nAt the four corners of the house about,\nAnd at the threshold of the door, without:-\nO Jesus Christ and good Saint Benedict,\nProtect this house from all that may afflict,\nFor the night hag the white Paternoster!-\nWhere hast thou gone, Saint Peter's sister?\nAnd at the last this clever Nicholas\nBegan to sigh full sore, and said: Alas!\nShall all the world be lost so soon again?\nThis carpenter replied: What say you, then?\nWhat! Think on God, as we do, men that swink.\nThis Nicholas replied: Go fetch me drink;\nAnd afterward I'll tell you privately\nA certain thing concerning you and me;\nI'll tell it to no other man or men.\nThis carpenter went down and came again,\nAnd brought of potent ale a brimming quart;\nAnd when each one of them had drunk his part,\nNicholas shut the door fast, and with that\nHe drew a seat and near the carpenter sat.\nHe said: Now, John, my good host, lief and dear,\nYou must upon your true faith swear, right here,\nThat to no man will you this word betray;\nFor it is Christ's own word that I will say,\nAnd if you tell a man, you're ruined quite;\nThis punishment shall come to you, of right,\nThat if you're traitor you'll go mad- and should!\nNay, Christ forbid it, for His holy blood!\nSaid then this simple man: I am no blab,\nNor, though I say it, am I fond of gab.\nSay what you will, I never will it tell\nTo child or wife, by Him that harried Hell!\nNow, John, said Nicholas, I will not lie;\nBut I've found out, from my astrology,\nAs I have looked upon the moon so bright,\nThat now, come Monday next, at nine of night,\nShall fall a rain so wildly mad as would\nHave been, by half, greater than Noah's flood.\nThis world, he said, in less time than an hour,\nShall all be drowned, so terrible is this shower;\nThus shall all mankind drown and lose all life.\nThis carpenter replied: Alas, my wife!\nAnd shall she drown? Alas, my Alison!\nFor grief of this he almost fell. Anon\nHe said: Is there no remedy in this case?\nWhy yes, good luck, said clever Nicholas,\nIf you will work by counsel of the wise;\nYou must not act on what your wits advise.\nFor so says Solomon, and it's all true,\n'Work by advice and thou shalt never rue.'\nAnd if you'll act as counselled and not fail,\nI undertake, without a mast or sail,\nTo save us all, aye you and her and me.\nHaven't you heard of, Noah, how saved was he,\nBecause Our Lord had warned him how to keep\nOut of the flood that covered earth so deep?\nYes, said this carpenter, long years ago.\nHave you not heard, asked Nicholas, also\nThe sorrows of Noah and his fellowship\nIn getting his wife to go aboard the ship?\nHe would have rather, I dare undertake,\nAt that time, and for all the weather black,\nThat she had one ship for herself alone.\nTherefore, do you know what would best be done?\nThis thing needs haste, and of a hasty thing\nMen must not preach nor do long tarrying.\nPresently go, and fetch here to this inn\nA kneading-tub, or brewing vat, and win\nOne each for us, but see that they are large,\nWherein we may swim out as in a barge,\nAnd have therein sufficient food and drink\nFor one day only; that's enough, I think.\nThe water will dry up and flow away\nAbout the prime of the succeeding day.\nBut Robin must not know of this, your knave,\nAnd even Jill, your maid, I may not save;\nAsk me not why, for though you do ask me,\nI will not tell you of God's privity.\nSuffice you, then, unless your wits are mad,\nTo have as great a grace as Noah had.\nYour wife I shall not lose, there is no doubt,\nGo, now, your way, and speedily about,\nBut when you have, for you and her and me,\nProcured these kneading-tubs, or beer-vats, three,\nThen you shall hang them near the roof-tree high,\nThat no man our purveyance may espy.\nAnd when you thus have done, as I have said,\nAnd have put in our drink and meat and bread,\nAlso an axe to cut the ropes in two\nWhen the flood comes, that we may float and go,\nAnd cut a hole, high up, upon the gable,\nUpon the garden side, over the stable,\nThat we may freely pass forth on our way\nWhen the great rain and flood are gone that day-\nThen shall you float as merrily, I'll stake,\nAs does the white duck after the white drake.\nThen I will call, 'Ho, Alison! Ho, John!\nBe cheery, for the flood will pass anon.'\nAnd you will say, 'Hail. Master Nicholay!\nGood morrow, I see you well, for it is day!'\nAnd then shall we be barons all our life\nOf all the world, like Noah and his wife.\nBut of one thing I warn you now, outright.\nBe well advised, that on that very night\nWhen we have reached our ships and got aboard,\nNot one of us must speak or whisper word,\nNor call, nor cry, but sit in silent prayer;\nFor this is God's own bidding, hence- don't dare!\nYour wife and you must hang apart, that in\nThe night shall come no chance for you to sin\nEither in looking or in carnal deed.\nThese orders I have told you, go, God speed!\nTomorrow night, when all men are asleep,\nInto our kneading-tubs will we three creep\nAnd sit there, still, awaiting God's high grace.\nGo, now, your way, I have no longer space\nOf time to make a longer sermoning.\nMen say thus: 'Send the wise and say no thing.'\nYou are so wise it needs not that I teach;\nGo, save our lives, and that I do beseech.\nThis silly carpenter went on his way.\nOften he cried Alas! and Welaway!\nAnd to his wife he told all, privately;\nBut she was better taught thereof than he\nHow all this rigmarole was to apply.\nNevertheless she acted as she'd die,\nAnd said: Alas! Go on your way anon,\nHelp us escape, or we are lost, each one;\nI am your true and lawfully wedded wife;\nGo, my dear spouse, and help to save our life.\nLo, what a great thing is affection found!\nMen die of imagination, I'll be bound,\nSo deep an imprint may the spirit take.\nThis hapless carpenter began to quake;\nHe thought now, verily, that he could see\nOld Noah's flood come wallowing like the sea\nTo drown his Alison, his honey dear.\nHe wept, he wailed, he made but sorry cheer,\nHe sighed and made full many a sob and sough.\nHe went and got himself a kneading-trough\nAnd, after that, two tubs he somewhere found\nAnd to his dwelling privately sent round,\nAnd hung them near the roof, all secretly.\nWith his own hand, then, made he ladders three,\nTo climb up by the rungs thereof, it seems,\nAnd reach the tubs left hanging to the beams;\nAnd those he victualled, tubs and kneading-trough,\nWith bread and cheese and good jugged ale, enough\nTo satisfy the needs of one full day.\nBut ere he'd put all this in such array,\nHe sent his servants, boy and maid, right down\nUpon some errand into London town.\nAnd on the Monday, when it came on night,\nHe shut his door, without a candle-light,\nAnd ordered everything as it should be.\nAnd shortly after up they climbed, all three;\nThey sat while one might plow a furlong-way.\nNow, by Our Father, hush! said Nicholay,\nAnd Hush! said John, and Hush! said Alison.\nThis carpenter, his loud devotions done,\nSat silent, saying mentally a prayer,\nAnd waiting for the rain, to hear it there.\nThe deathlike sleep of utter weariness\nFell on this wood-wright even. (as I guess)\nAbout the curfew time, or little more;\nFor travail of his spirit he groaned sore,\nAnd soon he snored, for badly his head lay.\nDown by the ladder crept this Nicholay,\nAnd Alison, right softly down she sped.\nWithout more words they went and got in bed\nEven where the carpenter was wont to lie.\nThere was the revel and the melody!\nAnd thus lie Alison and Nicholas,\nIn joy that goes by many an alias,\nUntil the bells for lauds began to ring\nAnd friars to the chancel went to sing.\nThis parish clerk, this amorous Absalom,\nWhom love has made so woebegone and dumb,\nUpon the Monday was down Osney way,\nWith company, to find some sport and play;\nAnd there he chanced to ask a cloisterer,\nPrivately, after John the carpenter.\nThis monk drew him apart, out of the kirk,\nAnd said: I have not seen him here at work.\nSince Saturday; I think well that he went\nFor timber, that the abbot has him sent;\nFor he is wont for timber thus to go,\nRemaining at the grange a day or so;\nOr else he's surely at his house today;\nBut which it is I cannot truly say.\nThis Absalom right happy was and light,\nAnd thought: Now is the time to wake all night;\nFor certainly I saw him not stirring\nAbout his door since day began to spring.\nSo may I thrive, as I shall, at cock's crow,\nKnock cautiously upon that window low\nWhich is so placed upon his bedroom wall.\nTo Alison then will I tell of all\nMy love-longing, and thus I shall not miss\nThat at the least I'll have her lips to kiss.\nSome sort of comfort shall I have, I say,\nMy mouth's been itching all this livelong day;\nThat is a sign of kissing at the least.\nAll night I dreamed, too, I was at a feast.\nTherefore I'll go and sleep two hours away\nAnd all this night then will I wake and play.\nAnd so when time of first cock-crow was come,\nUp rose this merry lover, Absalom,\nAnd dressed him gay and all at point-device,\nBut first he chewed some licorice and spice\nSo he'd smell sweet, ere he had combed his hair.\nUnder his tongue some bits of true-love rare,\nFor thereby thought he to be more gracious.\nHe went, then, to the carpenter's dark house.\nAnd silent stood beneath the shot-window;\nUnto his breast it reached, it was so low;\nAnd he coughed softly, in a low half tone:\nWhat do you, honeycomb, sweet Alison?\nMy cinnamon, my fair bird, my sweetie,\nAwake, O darling mine, and speak to me!\nIt's little thought you give me and my woe,\nWho for your love do sweat where'er I go.\nYet it's no wonder that I faint and sweat;\nI long as does the lamb for mother's teat.\nTruly, sweetheart, I have such love-longing\nThat like a turtle-dove's my true yearning;\nAnd I can eat no more than can a maid.\nGo from the window, Jack-a-napes, she said,\nFor, s'help me God, it is not 'come kiss me.'\nI love another, or to blame I'd be,\nBetter than you, by Jesus, Absalom!\nGo on your way, or I'll stone you therefrom,\nAnd let me sleep, the fiends take you away!\nAlas, quoth Absalom, and welaway!\nThat true love ever was so ill beset!\nBut kiss me, since you'll do no more, my pet,\nFor Jesus' love and for the love of me.\nAnd will you go, then, on your way? asked she,\nYes truly, darling, said this Absalom.\nThen make you ready, said she, and I'll come!\nAnd unto Nicholas said she, low and still:\nBe silent now, and you shall laugh your fill.\nThis Absalom plumped down upon his knees,\nAnd said: I am a lord in all degrees;\nFor after this there may be better still\nDarling, my sweetest bird, I wait your will.\nThe window she unbarred, and that in haste.\nHave done, said she, come on, and do it fast,\nBefore we're seen by any neighbour's eye.\nThis Absalom did wipe his mouth all dry;\nDark was the night as pitch, aye dark as coal,\nAnd through the window she put out her hole.\nAnd Absalom no better felt nor worse,\nBut with his mouth he kissed her naked arse\nRight greedily, before he knew of this.\nAback he leapt- it seemed somehow amiss,\nFor well he knew a woman has no beard;\nHe'd felt a thing all rough and longish haired,\nAnd said, Oh fie, alas! What did I do?\nTeehee! she laughed, and clapped the, window to;\nAnd Absalom went forth a sorry pace.\nA beard! A beard! cried clever Nicholas,\nNow by God's corpus, this goes fair and well!\nThis hapless Absalom, he heard that yell,\nAnd on his lip, for anger, he did bite;\nAnd to himself he said, I will requite!\nWho vigorously rubbed and scrubbed his lips\nWith dust, with sand, with straw, with cloth, with chips,\nBut Absalom, and often cried Alas!\nMy soul I give now unto Sathanas,\nFor rather far than own this town, said he,\nFor this despite, it's well revenged I'd be.\nAlas, said he, from her I never blenched!\nHis hot love was grown cold, aye and all quenched;\nFor, from the moment that he'd kissed her arse,\nFor paramours he didn't care a curse,\nFor he was healed of all his malady;\nIndeed all paramours he did defy,\nAnd wept as does a child that has been beat.\nWith silent step he went across the street\nUnto a smith whom men called Dan Jarvis,\nWho in his smithy forged plow parts, that is\nHe sharpened shares and coulters busily.\nThis Absalom he knocked all easily,\nAnd said: Unbar here, Jarvis, for I come.\nWhat! Who are you? It's I, it's Absalom.\nWhat! Absalom! For Jesus Christ's sweet tree,\nWhy are you up so early? Ben'cite!\nWhat ails you now, man? Some gay girl, God knows,\nHas brought you on the jump to my bellows;\nBy Saint Neot, you know well what I mean.\nThis Absalom cared not a single bean\nFor all this play, nor one word back he gave;\nHe'd more tow on his distaff, had this knave,\nThan Jarvis knew, and said he: Friend so dear,\nThis red-hot coulter in the fireplace here,\nLend it to me, I have a need for it,\nAnd I'll return it after just a bit.\nJarvis replied: Certainly, were it gold\nOr a purse filled with yellow coins untold,\nYet should you have it, as I am true smith;\nBut eh, Christ's foe! What will you do therewith?\nLet that, said Absalom, be as it may;\nI'll tell you all tomorrow, when it's day-\nAnd caught the coulter then by the cold steel\nAnd softly from the smithy door did steal\nAnd went again up to the wood-wright's wall.\nHe coughed at first, and then he knocked withal\nUpon the window, as before, with care.\nThis Alison replied: Now who is there?\nAnd who knocks so? I'll warrant it's a thief.\nWhy no, quoth he, God knows, my sweet roseleaf,\nI am your Absalom, my own darling!\nOf gold, quoth he, I have brought you a ring;\nMy mother gave it me, as I'll be saved;\nFine gold it is, and it is well engraved;\nThis will I give you for another kiss.\nThis Nicholas had risen for a piss,\nAnd thought that it would carry on the jape\nTo have his arse kissed by this jack-a-nape.\nAnd so he opened window hastily,\nAnd put his arse out thereat, quietly,\nOver the buttocks, showing the whole bum;\nAnd thereto said this clerk, this Absalom,\nO speak, sweet bird, I know not where thou art.\nThis Nicholas just then let fly a fart\nAs loud as it had been a thunder-clap,\nAnd well-nigh blinded Absalom, poor chap;\nBut he was ready with his iron hot\nAnd Nicholas right in the arse he got.\nOff went the skin a hand's-breadth broad, about,\nThe coulter burned his bottom so, throughout,\nThat for the pain he thought that he should die.\nAnd like one mad he started in to cry,\nHelp! Water! Water! For God's dear heart!\nThis carpenter out of his sleep did start,\nHearing that Water! cried as madman would,\nAnd thought, Alas, now comes down Noel's flood!\nHe struggled up without another word\nAnd with his axe he cut in two the cord,\nAnd down went all; he did not stop to trade\nIn bread or ale till he'd the journey made,\nAnd there upon the floor he swooning lay.\nUp started Alison and Nicholay\nAnd shouted Help! and Hello! down the street.\nThe neighbours, great and small, with hastening feet\nSwarmed in the house to stare upon this man,\nWho lay yet swooning, and all pale and wan;\nFor in the falling he had smashed his arm.\nHe had to suffer, too, another harm,\nFor when he spoke he was at once borne down\nBy clever Nicholas and Alison.\nFor they told everyone that he was odd;\nHe was so much afraid of Noel's flood,\nThrough fantasy, that out of vanity\nHe'd gone and bought these kneading-tubs, all three,\nAnd that he'd hung them near the roof above;\nAnd that he had prayed them, for God's dear love,\nTo sit with him and bear him company.\nThe people laughed at all this fantasy;\nUp to the roof they looked, and there did gape,\nAnd so turned all his injury to a jape.\nFor when this carpenter got in a word,\n'Twas all in vain, no man his reasons heard;\nWith oaths imprenive he was so sworn down,\nThat he was held for mad by all the town;\nFor every clerk did side with every other.\nThey said: The man is crazy, my dear brother.\nAnd everyone did laugh at all this strife.\nThus futtered was the carpenter's goodwife,\nFor all his watching and his jealousy;\nAnd Absalom has kissed her nether eye;\nAnd Nicholas is branded on the butt.\nThis tale is done, and God save all the rout!\n\n"},{"index":2,"markdown":"### The Reeve's Prologue\n\nWhen folk had laughed their fill at this nice pass\nOf Absalom and clever Nicholas,\nThen divers folk diversely had their say;\nAnd most of them were well amused and gay,\nNor at this tale did I see one man grieve,\nSave it were only old Oswald the reeve,\nBecause he was a carpenter by craft.\nA little anger in his heart was left,\nAnd he began to grouse and blame a bit.\nS' help me, said he, full well could I be quit\nWith blearing of a haughty miller's eye,\nIf I but chose to speak of ribaldry.\nBut I am old; I will not play, for age;\nGrass time is done, my fodder is rummage,\nThis white top advertises my old years,\nMy heart, too, is as mouldy as my hairs,\nUnless I fare like medlar, all perverse.\nFor that fruit's never ripe until it's worse,\nAnd falls among the refuse or in straw.\nWe ancient men, I fear, obey this law:\nUntil we're rotten, we cannot be ripe;\nWe dance, indeed, the while the world will pipe.\nliesire sticks in our nature like a nail\nTo have, if hoary head, a verdant tail,\nAs has the leek; for though our strength be gone,\nOur wish is yet for folly till life's done.\nFor when we may not act, then will we speak;\nYet in our ashes is there fire to reek\nFour embers have we, which I shall confess:\nBoasting and lying, anger, covetousness;\nThese four remaining sparks belong to eld.\nOur ancient limbs may well be hard to wield,\nBut lust will never fail us, that is truth.\nAnd yet I have had always a colt's tooth,\nAs many years as now are past and done\nSince first my tap of life began to run.\nFor certainly, when I was born, I know\nDeath turned my tap of life and let it flow;\nAnd ever since that day the tap has run\nTill nearly empty now is all the tun.\nThe stream of life now drips upon the chime;\nThe silly tongue may well ring out the time\nOf wretchedness that passed so long before;\nFor oldsters, save for dotage, there's no more.\nNow when our host had heard this sermoning,\nThen did he speak as lordly as a king;\nHe said: To what amounts, now, all this wit?\nWhy should we talk all day of holy writ?\nThe devil makes a steward for to preach,\nAnd of a cobbler, a sailor or a leech.\nTell, forth your tale, and do not waste the time.\nHere's Deptford! And it is half way to prime.\nThere's Greenwich town that many a scoundrel's in;\nIt is high time your story should begin.\nNow, sirs, then said this Oswald called the reeve,\nI pray you all, now, that you will not grieve\nThough I reply and somewhat twitch his cap;\nIt's lawful to meet force with force, mayhap.\nThis drunken miller has related here\nHow was beguiled and fooled a carpenter-\nPerchance in scorn of me, for I am one.\nSo, by your leave, I'll him requite anon;\nAll in his own boor's language will I speak.\nI only pray to God his neck may break.\nFor in my eye he well can see the mote,\nBut sees not in his own the beam, you'll note.\n\n\n### The Reeve's Tale\n\nAt Trumpington, not far from Cambridge town,\nThere is a bridge wherethrough a brook runs down,\nUpon the side of which brook stands a mill;\nAnd this is very truth that now I tell.\nA miller dwelt there, many and many a day;\nAs any peacock he was proud and gay.\nHe could mend nets, and he could fish, and flute,\nDrink and turn cups, and wrestle well, and shoot;\nAnd in his leathern belt he did parade\nA cutlass with a long trenchant blade.\nA pretty dagger had he in his pouch;\nThere was no man who durst this man to touch.\nA Sheffield whittler bore he in his hose;\nRound was his face and turned-up was his nose.\nAs bald as any ape's head was his skull;\nHe was a market-swaggerer to the full.\nThere durst no man a hand on him to lay,\nBecause he swore he'd make the beggar pay.\nA thief he was, forsooth, of corn and meal,\nAnd sly at that, accustomed well to steal.\nHis name was known as arrogant Simpkin.\nA wife he had who came of gentle kin;\nThe parson of the town her father was.\nWith her he gave full many a pan of brass,\nTo insure that Simpkin with his blood ally.\nShe had been bred up in a nunnery;\nFor Simpkin would not have a wife, he said,\nSave she were educated and a maid\nTo keep up his estate of yeomanry.\nAnd she was proud and bold as is a pie.\nA handsome sight it was to see those two;\nOn holy days before her he would go\nWith a broad tippet bound about his head;\nAnd she came after in a skirt of red,\nWhile Simpkin's hose were dyed to match that same.\nThere durst no man to call her aught but dame;\nNor was there one so hardy, in the way,\nAs durst flirt with her or attempt to play,\nUnless he would be slain by this Simpkin\nWith cutlass or with knife or with bodkin.\nFor jealous folk are dangerous, you know,\nAt least they'd have their wives to think them so.\nBesides, because she was a dirty bitch,\nShe was as high as water in a ditch;\nAnd full of scorn and full of back-biting.\nShe thought a lady should be quite willing\nTo greet her for her kin and culture, she\nHaving been brought up in that nunnery.\nA daughter had they got between the two,\nOf twenty years, and no more children, no,\nSave a boy baby that was six months old;\nIt lay in cradle and was strong and bold.\nThis girl right stout and well developed was,\nWith nose tip-tilted and eyes blue as glass,\nWith buttocks broad, and round breasts full and high,\nBut golden was her hair, I will not lie.\nThe parson of the town, since she was fair,\nWas purposeful to make of her his heir,\nBoth of his chattels and of his estate,\nBut all this hinged upon a proper mate.\nHe was resolved that he'd bestow her high\nInto some blood of worthy ancestry;\nFor Holy Church's goods must be expended\nOn Holy Church's blood, as it's descended.\nTherefore he'd honour thus his holy blood,\nThough Holy Church itself became his food.\nLarge tolls this miller took, beyond a doubt,\nWith wheat and malt from all the lands about;\nOf which I'd specify among them all\nA Cambridge college known as Soler Hall;\nHe ground their wheat and all their malt he ground.\nAnd on a day it happened, as they found,\nThe manciple got such a malady\nThat all men surely thought that he should die.\nWhereon this miller stole both flour and wheat\nA hundredfold more than he used to cheat;\nFor theretofore he stole but cautiously,\nBut now he was a thief outrageously,\nAt which the warden scolded and raised hell;\nThe miller snapped his fingers, truth to tell,\nAnd cracked his brags and swore it wasn't so.\nThere were two poor young clerks, whose names I know,\nThat dwelt within this Hall whereof I say.\nWillful they were and lusty, full of play,\nAnd (all for mirth and to make reverly)\nAfter the warden eagerly did they cry\nTo give them leave, at least for this one round,\nTo go to mill and see their produce ground;\nAnd stoutly they proclaimed they'd bet their neck\nThe miller should not steal one half a peck\nOf grain, by trick, nor yet by force should thieve;\nAnd at the last the warden gave them leave.\nJohn was the one and Alain was that other;\nIn one town were they born, and that called Strother,\nFar in the north, I cannot tell you where.\nThis Alain, he made ready all his gear,\nAnd on a horse loaded the sack anon.\nForth went Alain the clerk, and also John,\nWith good sword and with buckler at their side.\nJohn knew the way and didn't need a guide,\nAnd at the mill he dropped the sack of grain.\nAh, Simon, hail, good morn, first spoke Alain.\nHow fares it with your fair daughter and wife?\nAlain! Welcome, said Simpkin, by my life,\nAnd John also. How now? What do you here?\nSimon, said John, by God, need makes no peer;\nHe must himself serve who's no servant, eh?\nOr else he's but a fool, as all clerks say.\nOur manciple- I hope he'll soon be dead,\nSo aching are the grinders in his head-\nAnd therefore am I come here with Alain\nTo grind our corn and carry it home again;\nI pray you speed us thither, as you may.\nIt shall be done, said Simpkin, by my fay.\nWhat will you do the while it is in hand?\nBy God, right by the hopper will I stand,\nSaid John, and see just how the corn goes in;\nI never have seen, by my father's kin,\nJust how the hopper waggles to and fro.\nAlain replied: Well, John, and will you so?\nThen will I get beneath it, by my crown,\nTo see there how the meal comes sifting down\nInto the trough; and that shall be my sport.\nFor, John, in faith, I must be of your sort;\nI am as bad a miller as you be.\nThe miller smiled at this, their delicacy,\nAnd thought: All this is done but for a wile;\nThey think there is no man may them beguile;\nBut, by my thrift, I will yet blear their eyes,\nFor all the tricks in their philosophies.\nThe more odd tricks and stratagems they make,\nThe more I'll steal when I begin to take.\nIn place of flour I'll give them only bran.\n'The greatest clerk is not the wisest man,'\nAs once unto the grey wolf said the mare.\nBut all their arts- I rate them not a tare.\nOut of the door he went, then, secretly,\nWhen he had seen his chance, and quietly;\nHe looked up and looked down, until he found\nThe clerks' horse where it stood, securely bound.\nBehind the mill, under an arbour green;\nAnd to the horse he went, then, all unseen;\nHe took the bridle off him and anon,\nWhen the said horse was free, why he was gone\nToward the fen, for wild mares ran therein,\nAnd with a neigh he went, through thick and thin.\nThis miller straight went back and no word said,\nBut did his business and with these clerks played,\nUntil their corn was fairly, fully ground.\nBut when the flour was sacked and the ears bound,\nThis John went out, to find his horse away,\nAnd so he cried: Hello! and Weladay!\nOur horse is lost! Alain, for Jesus' bones\nGet to your feet, come out, man, now, at once!\nAlas, our warden's palfrey's lost and lorn!\nThis Alain forgot all, both flour and corn,\nClean out of mind was all his husbandry,\nWhat? Which way did he go? began to cry.\nThe wife came bounding from the house, and then\nShe said: Alas! Your horse went to the fen,\nWith the wild mares, as fast as he could go.\nA curse light on the hand that tied him so,\nAnd him that better should have knotted rein!\nAlas! quoth John, Alain, for Jesus' pain,\nLay off your sword, and I will mine also;\nI am as fleet, God knows, as is a roe;\nBy God's heart, he shall not escape us both!\nWhy didn't you put him in the barn? My oath!\nBad luck, by God, Alain, you are a fool!\nThese foolish clerks began to run and roll\nToward the marshes, both Alain and John.\nAnd when the miller saw that they were gone,\nHe half a bushel of their flour did take\nAnd bade his wife go knead it and bread make.\nHe said: I think those clerks some trickery feared;\nYet can a miller match a clerkling's beard,\nFor all his learning; let them go their way.\nLook where they go, yea, let the children play,\nThey'll catch him not so readily, by my crown!\n\nThose simple clerks went running up and down\nWith Look out! Halt! Halt! here! 'Ware the rear!\nGo whistle, you, and I will watch him here!\nBut briefly, till it came to utter night\nThey could not, though they put forth all their might,\nThat stallion catch, he always ran so fast,\nTill in a ditch they trapped him at the last.\nWeary and wet, as beast is in the rain,\nCame foolish John and with him came Alain.\nAlas, said John, the day that I was born!\nNow are we bound toward mockery and scorn.\nOur corn is stolen, folk will call us fools,\nThe warden and the fellows at the schools,\nAnd specially this miller. Weladay!\nThus John complained as he went on his way\nToward the mill, with Bayard once more bound.\nThe miller sitting by the fire he found,\nFor it was night, and farther could they not;\nBut, for the love of God, they him besought\nFor shelter and for supper, for their penny.\nThe miller said to them: If there be any,\nSuch as it is, why you shall have your part.\nMy house is small, but you have learned your art;\nYou can, by metaphysics, make a place\nA full mile wide in twenty feet of space.\nLet us see now if this place will suffice,\nOr make more room with speech, by some device.\nNow, Simon, said John, by Saint Cuthbert's beard,\nYou're always merry and have well answered.\nAs I've heard, man shall take one of two things:\nSuch as he finds, or take such as he brings.\nBut specially, I pray you, mine host dear,\nGive us some meat and drink and some good cheer,\nAnd we will pay you, truly, to the full.\nWith empty hand no man takes hawk or gull;\nWell, here's our silver, ready to be spent.\nThis miller to the town his daughter sent\nFor ale and bread, and roasted them a goose,\nAnd tied their horse, that it might not go loose;\nAnd then in his own chamber made a bed,\nWith sheets and with good blankets fairly spread,\nNot from his bed more than twelve feet, or ten.\nThe daughter made her lone bed near the men,\nIn the same chamber with them, by and by;\nIt could not well be bettered, and for why?\nThere was no larger room in all the place.\nThey supped and talked, and gained some small solace,\nAnd drank strong ale, that evening, of the best.\nThen about midnight all they went to rest.\nWell had this miller varnished his bald head,\nFor pale he was with drinking, and not red.\nHe hiccoughed and he mumbled through his nose,\nAs he were chilled, with humours lachrymose.\nTo bed he went, and with him went his wife.\nAs any jay she was with laughter rife,\nSo copiously was her gay whistle wet.\nThe cradle near her bed's foot-board was set,\nHandy for rocking and for giving suck.\nAnd when they'd drunk up all there was in crock,\nTo bed went miller's daughter, and anon\nTo bed went Alain and to bed went John.\nThere was no more; they did not need a dwale.\nThis miller had so roundly bibbed his ale\nThat, like a horse, he snorted in his sleep,\nWhile of his tail behind he kept no keep.\nHis wife joined in his chorus, and so strong,\nMen might have heard her snores a full furlong;\nAnd the girl snored, as well, for company.\nAlain the clerk, who heard this melody,\nHe poked at John and said: Asleep? But how?\nDid you hear ever such a song ere now?\nLo, what a compline is among them all!\nNow may the wild-fire on their bodies fall!\nWho ever heard so outlandish a thing?\nBut they shall have the flour of ill ending.\nThrough this long night there'll be for me no rest;\nBut never mind, 'twill all be for the best.\nFor, John, said he, so may I ever thrive,\nAs, if I can, that very wench I'll swive.\nSome recompense the law allows to us;\nFor, John, there is a statute which says thus,\nThat if a man in one point be aggrieved,\nYet in another shall he be relieved.\nOur corn is stolen, to that there's no nay,\nAnd we have had an evil time this day.\nBut since I may not have amending, now,\nAgainst my loss I'll set some fun- and how!\nBy God's great soul it shan't be otherwise!\nThis John replied: Alain, let me advise.\nThe miller is a dangerous man, he said,\nAnd if he be awakened, I'm afraid\nHe may well do us both an injury.\nBut Alain said: I count him not a fly.\nAnd up he rose and to the girl he crept.\nThis wench lay on her back and soundly slept,\nUntil he'd come so near, ere she might spy,\nIt was too late to struggle, then, or cry;\nAnd, to be brief, these two were soon alone.\nNow play, Alain! For I will speak of John.\nThis John lay still a quarter-hour, or so,\nPitied himself and wept for all his woe.\nAlas, said he, this is a wicked jape!\nNow may I say that I am but an ape.\nYet has my friend, there, something for his harm;\nHe has the miller's daughter on his arm.\nHe ventured, and his pains are now all fled,\nWhile I lie like a sack of chaff in bed;\nAnd when this jape is told, another day,\nI shall be held an ass, a milksop, yea!\nI will arise and chance it, by my fay!\n'Unhardy is unhappy,' as they say.\nAnd up he rose, and softly then he went\nTo find the cradle for expedient,\nAnd bore it over to his own foot-board.\nSoon after this the wife no longer snored,\nBut woke and rose and went outside to piss,\nAnd came again and did the cradle miss,\nAnd groped round, here and there, but found it not.\nAlas! thought she, my way I have forgot.\nI nearly found myself in the clerks' bed.\nEh, ben'cite, but that were wrong! she said.\nAnd on, until by cradle she did stand.\nAnd, groping a bit farther with her hand,\nShe found the bed, and thought of naught but good,\nBecause her baby's cradle by it stood,;\nAnd knew not where she was, for it was dark;\nBut calmly then she crept in by the clerk,\nAnd lay right still, and would have gone to sleep.\nBut presently this John the clerk did leap,\nAnd over on this goodwife did he lie.\nNo such gay time she'd known in years gone by.\nHe pricked her hard and deep, like one gone mad.\nAnd so a jolly life these two clerks had\nTill the third cock began to crow and sing.\nAlain grew weary in the grey dawning,\nFor he had laboured hard through all the night;\nAnd said: Farewell, now, Maudy, sweet delight!\nThe day is come, I may no longer bide;\nBut evermore, whether I walk or ride,\nI am your own clerk, so may I have weal.\nNow, sweetheart, said she, go and fare you well!\nBut ere you go, there's one thing I must tell.\nWhen you go walking homeward past the mill,\nRight at the entrance, just the door behind,\nYou shall a loaf of half a bushel find\nThat was baked up of your own flour, a deal\nOf which I helped my father for to steal.\nAnd, darling, may God save you now and keep!\nAnd with that word she almost had to weep.\nAlain arose and thought: Ere it be dawn,\nI will go creep in softly by friend John.\nAnd found the cradle with his hand, anon.\nBy God! thought he, all wrong I must have gone;\nMy head is dizzy from my work tonight,\nAnd that's why I have failed to go aright.\nI know well, by this cradle, I am wrong,\nFor here the miller and his wife belong.\nAnd on he went, and on the devil's way,\nUnto the bed wherein the miller lay.\nHe thought to have crept in by comrade John,\nSo, to the miller, in he got anon,\nAnd caught him round the neck, and softly spake,\nSaying: You, John, you old swine's head, awake,\nFor Christ's own soul, and hear a noble work,\nFor by Saint James, and as I am a clerk,\nI have, three times in this short night, no lack,\nSwived that old miller's daughter on her back,\nWhile you, like any coward, were aghast.\nYou scoundrel, cried the miller, you trespassed?\nAh, traitor false and treacherous clerk! cried he,\nYou shall be killed, by God's own dignity!\nWho dares be bold enough to bring to shame\nMy daughter, who is born of such a name?\nAnd by the gullet, then, he caught Alain.\nAnd pitilessly he handled him amain,\nAnd on the nose he smote him with his fist.\nDown ran the bloody stream upon his breast;\nAnd on the floor, with nose and mouth a-soak,\nThey wallowed as two pigs do in a poke.\nAnd up they came, and down they both went, prone,\nUntil the miller stumbled on a stone,\nAnd reeled and fell down backwards on his wife,\nWho nothing knew of all this silly strife;\nFor she had fallen into slumber tight\nWith John the clerk, who'd been awake all night.\nBut at the fall, from sleep she started out.\nHelp, holy Cross of Bromholm! did she shout,\nIn manus tuas, Lord, to Thee I call!\nSimon, awake, the Fiend is on us all\nMy heart is broken, help, I am but dead!\nThere lies one on my womb, one on my head!\nHelp, Simpkin, for these treacherous clerks do fight!\nJohn started up, as fast as well he might,\nAnd searched along the wall, and to and fro,\nTo find a staff; and she arose also,\nAnd knowing the room better than did John,\nShe found a staff against the wall, anon;\nAnd then she saw a little ray of light,\nFor through a hole the moon was shining bright;\nAnd by that light she saw the struggling two,\nBut certainly she knew not who was who,\nExcept she saw a white thing with her eye.\nAnd when she did this same white thing espy,\nShe thought the clerk had worn a nightcap here.\nAnd with the staff she nearer drew, and near,\nAnd, thinking to hit Alain on his poll,\nShe fetched the miller on his bald white skull,\nAnd down he went, crying out, Help, help, I die!\nThe two clerks beat him well and let him lie;\nAnd clothed themselves, and took their horse anon,\nAnd got their flour, and on their way were gone.\nAnd at the mill they found the well-made cake\nWhich of their meal the miller's wife did bake.\nThus is the haughty miller soundly beat,\nAnd thus he's lost his pay for grinding wheat,\nAnd paid for the two suppers, let me tell,\nOf Alain, and of John, who've tricked him well.\nHis wife is taken, also his daughter sweet;\nThus it befalls a miller who's a cheat.\nAnd therefore is this proverb said with truth,\nAn evil end to evil man, forsooth.\nThe cheater shall himself well cheated be.\nAnd God, Who sits on high in majesty,\nSave all this company, both strong and frail!\nThus have I paid this miller with my tale.\n\n\n### The Cook's Prologue\n\nThe cook from London, while the reeve yet spoke,\nPatted his back with pleasure at the joke.\nHa, ha! laughed he, by Christ's great suffering,\nThis miller had a mighty sharp ending\nUpon his argument of harbourage!\nFor well says Solomon, in his language,\n'Bring thou not every man into thine house;'\nFor harbouring by night is dangerous.\nWell ought a man to know the man that he\nHas brought into his own security.\nI pray God give me sorrow and much care\nIf ever, since I have been Hodge of Ware,\nHeard I of miller better brought to mark.\nA wicked jest was played him in the dark.\nBut God forbid that we should leave off here;\nAnd therefore, if you'll lend me now an ear,\nFrom what I know, who am but a poor man,\nI will relate, as well as ever I can,\nA little trick was played in our city.\nOur host replied: I grant it readily.\nNow tell on, Roger; see that it be good;\nFor many a pasty have you robbed of blood,\nAnd many a Jack of Dover have you sold\nThat has been heated twice and twice grown cold.\nFrom many a pilgrim have you had Christ's curse,\nFor of your parsley they yet fare the worse,\nWhich they have eaten with your stubble goose;\nFor in your shop full many a fly is loose.\nNow tell on, gentle Roger, by your name.\nBut yet, I pray, don't mind if I make game,\nA man may tell the truth when it's in play.\nYou say the truth, quoth Roger, by my fay!\nBut 'true jest, bad jest' as the Fleming saith.\nAnd therefore, Harry Bailey, on your faith,\nBe you not angry ere we finish here,\nIf my tale should concern an inn-keeper.\nNevertheless, I'll tell not that one yet,\nBut ere we part your jokes will I upset.\nAnd thereon did he laugh, in great good cheer,\nAnd told his tale, as you shall straightway hear.\n\n\n### The Cook's Tale\n\nThere lived a 'prentice, once, in our city,\nAnd of the craft of victuallers was he;\nHappy he was as goldfinch in the glade,\nBrown as a berry, short, and thickly made,\nWith black hair that he combed right prettily.\nHe could dance well, and that so jollily,\nThat he was nicknamed Perkin Reveller.\nHe was as full of love, I may aver,\nAs is a beehive full of honey sweet;\nWell for the wench that with him chanced to meet.\nAt every bridal would he sing and hop,\nLoving the tavern better than the shop.\nWhen there was any festival in Cheap,\nOut of the shop and thither would he leap,\nAnd, till the whole procession he had seen,\nAnd danced his fill, he'd not return again.\nHe gathered many fellows of his sort\nTo dance and sing and make all kinds of sport.\nAnd they would have appointments for to meet\nAnd play at dice in such, or such, a street.\nFor in the whole town was no apprentice\nWho better knew the way to throw the dice\nThan Perkin; and therefore he was right free\nWith money, when in chosen company.\nHis master found this out in business there;\nFor often-times he found the till was bare.\nFor certainly a revelling bond-boy\nWho loves dice, wine, dancing, and girls of joy-\nHis master, in his shop, shall feel the effect,\nThough no part have he in this said respect;\nFor theft and riot always comrades are,\nAnd each alike he played on gay guitar.\nRevels and truth, in one of low degree,\nDo battle always, as all men may see.\nThis 'prentice shared his master's fair abode\nTill he was nigh out of his 'prenticehood,\nThough he was checked and scolded early and late,\nAnd sometimes led, for drinking, to Newgate;\nBut at the last his master did take thought,\nUpon a day, when he his ledger sought,\nOn an old proverb wherein is found this word:\nBetter take rotten apple from the hoard\nThan let it lie to spoil the good ones there.\nSo with a drunken servant should it fare;\nIt is less ill to let him go, apace,\nThan ruin all the others in the place.\nTherefore he freed and cast him loose to go\nHis own road unto future care and woe;\nAnd thus this jolly 'prentice had his leave.\nNow let him riot all night long, or thieve.\nBut since there's never thief without a buck\nTo help him waste his money and to suck\nAll he can steal or borrow by the way,\nAnon he sent his bed and his array\nTo one he knew, a fellow of his sort,\nWho loved the dice and revels and all sport,\nAnd had a wife that kept, for countenance,\nA shop, and whored to gain her sustenance.\n\n\n### Introduction To The Lawyer's Prologue\n\nOur good host saw well that the shining sun\nThe are of artificial day had run\nA quarter part, plus half an hour or more;\nAnd though not deeply expert in such lore,\nHe reckoned that it was the eighteenth day\nOf April, which is harbinger to May;\nAnd saw well that the shadow of each tree\nWas, as to length, of even quantity\nAs was the body upright causing it.\nAnd therefore by the shade he had the wit\nTo know that Phoebus, shining there so bright,\nHad climbed degrees full forty-five in height;\nAnd that, that day, and in that latitude,\nIt was ten of the clock, he did conclude,\nAnd suddenly he put his horse about.\nMasters, quoth he, I warn all of this rout,\nA quarter of this present day is gone;\nNow for the love of God and of Saint John,\nLose no more time, or little as you may;\nMasters, the time is wasting night and day,\nAnd steals away from us, what with our sleeping\nAnd with our sloth, when we awake are keeping,\nAs does the stream, that never turns again,\nDescending from the mountain to the plain.\nAnd well may Seneca, and many more,\nBewail lost time far more than gold in store.\n'For chattels lost may yet recovered be,\nBut time lost ruins us for aye,' says he.\nIt will not come again, once it has fled,\nNot any more than will Mag's maidenhead\nWhen she has lost it in her wantonness;\nLet's not grow mouldy thus in idleness.\nSir Lawyer, said he, as you have hope of bliss,\nTell us a tale, as our agreement is;\nYou have submitted, by your free assent,\nTo stand, in this case, to my sole judgment;\nAcquit yourself, keep promise with the rest,\nAnd you'll have done your duty, at the least.\nMine host, said he, by the gods, I consent;\nTo break a promise is not my intent.\nA promise is a debt, and by my fay\nI keep all mine; I can no better say.\nFor such law as man gives to other wight,\nHe should himself submit to it, by right;\nThus says our text; nevertheless, 'tis true\nI can relate no useful tale to you,\nBut Chaucer, though he speaks but vulgarly\nIn metre and in rhyming dextrously,\nHas told them in such English as he can,\nIn former years, as knows full many a man.\nFor if he has not told them, my dear brother,\nIn one book, why he's done so in another.\nFor he has told of lovers, up and down,\nMore than old Ovid mentions, of renown,\nIn his Epistles, that are now so old.\nWhy should I then re-tell what has been told?\nIn youth he told of Ceyx and Alcyon,\nAnd has since then spoken of everyone-\nOf noble wives and lovers did he speak.\nAnd whoso will that weighty volume seek\nCalled Legend of Good Women, need not chide;\nThere may be ever seen the large wounds wide\nOf Lucrece, Babylonian Thisbe;\nDido's for false Aeneas when fled he;\nDemophoon and Phyllis and her tree;\nThe plaint of Deianira and Hermione;\nOf Ariadne and Hypsipyle;\nThe barren island standing in the sea;\nThe drowned Leander and his fair Hero;\nThe tears of Helen and the bitter woe\nOf Briseis and that of Laodomea;\nThe cruelty of that fair Queen Medea,\nHer little children hanging by the neck\nWhen all her love for Jason came to wreck!\nO Hypermnestra, Penelope, Alcestis,\nYour wifehood does he honour, since it best is!\nBut certainly no word has written he\nOf that so wicked woman, Canace,\nWho loved her own blood brother sinfully.\nOf suchlike cursed tales, I say 'Let be!'\nNor yet of Tyrian Apollonius;\nNor how the wicked King Antiochus\nBereft his daughter of her maidenhead\n(Which is so horrible a tale to read),\nWhen down he flung her on the paving stones\nAnd therefore he, advisedly, truth owns,\nWould never write, in one of his creations,\nOf such unnatural abominations.\nAnd I'll refuse to tell them, if I may.\nBut for my tale, what shall I do this day?\nAny comparison would me displease\nTo Muses whom men call Pierides\n(The Metamorphoses show what I mean).\nNevertheless, I do not care a bean\nThough I come after him with my plain fare.\nI'll stick to prose. Let him his rhymes prepare.\nAnd thereupon, with sober face and cheer,\nHe told his tale, as you shall read it here.\n\n\n### The Lawyer's Prologue\n\nO Hateful evil! State of Poverty!\nWith thirst, with cold, with hunger so confounded!\nTo ask help shameth thy heart's delicacy;\nIf none thou ask, by need thou art so wounded\nThat need itself uncovereth all the wound hid!\nSpite of thy will thou must, for indigence,\nGo steal, or beg, or borrow thine expense.\nThou blamest Christ, and thou say'st bitterly,\nHe misdistributes riches temporal;\nThy neighbour dost thou censure, sinfully,\nSaying thou hast too little and he hath all.\nMy faith, sayest thou, sometime the reckoning shall\nCome on him, when his tail shall burn for greed,\nNot having helped the needy in their need.\nHear now what is the judgment of the wise:\nBetter to die than live in indigence;\nThy very pauper neighbours thee despise.\nIf thou be poor, farewell thy reverence!\nStill of the wise man take this full sentence:\nThe days of the afflicted are all sin.\nBeware, therefore, that thou come not therein!\nIf thou be poor, thy brother hateth thee,\nAnd all thy friends will flee from thee, alas!\nO wealthy merchants, full of weal ye be,\nO noble, prudent folk in happier case!\nYour dice-box doth not tumble out ambsace,\nBut with six-cinq ye throw against your chance;\nAnd so, at Christmas, merrily may ye dance!\nYe search all land and sea for your winnings,\nAnd, as wise folk, ye know well the estate\nOf all realms; ye are sires of happenings\nAnd tales of peace and tales of war's debate.\nBut I were now of tales all desolate,\nWere 't not a merchant, gone this many a year,\nTaught me the story which you now shall hear.\n\n\n### The Lawyer's Tale\n\nIn Syria, once, there dwelt a company\nOf traders rich, all sober men and true,\nThat far abroad did send their spicery,\nAnd cloth of gold, and satins rich in hue;\nTheir wares were all so excellent and new\nThat everyone was eager to exchange\nWith them, and sell them divers things and strange,\nIt came to pass, the masters of this sort\nDecided that to Rome they all would wend,\nWere it for business or for only sport;\nNo other message would they thither send,\nBut went themselves to Rome; this is the end.\nAnd there they found an inn and took their rest\nAs seemed to their advantage suited best.\nSojourned have now these merchants in that town\nA certain time, as fell to their pleasance.\nAnd so it happened that the high renown\nOf th' emperor's daughter, called the fair Constance.\nReported was, with every circumstance,\nUnto these Syrian merchants, in such wise,\nFrom day to day, as I will now apprise.\nThis was the common voice of every man:\nOur emperor of Rome, God save and see,\nA daughter has that since the world began.\nTo reckon as well her goodness as beauty,\nWas never such another as is she;\nI pray that God her fame will keep, serene,\nAnd would she were of all Europe the queen.\nIn her is beauty high, and without pride;\nYouth, without crudity or levity;\nIn an endeavours, virtue is her guide;\nMeekness in her has humbled tyranny;\nShe is the mirror of all courtesy;\nHer heart's a very shrine of holiness;\nHer hand is freedom's agent for largess.\nAnd all this voice said truth, as God is true.\nBut to our story let us turn again.\nThese merchants all have freighted ships anew,\nAnd when they'd seen the lovely maid, they fain\nWould seek their Syrian homes with all their train,\nTo do their business as they'd done yore,\nAnd live in weal; I cannot tell you more.\nNow so it was, these merchants stood in grace\nOf Syria's sultan; and so wise was he\nThat when they came from any foreign place\nHe would, of his benignant courtesy,\nMake them good cheer, inquiring earnestly\nFor news of sundry realms, to learn, by word,\nThe wonders that they might have seen and heard.\nAmong some other things, especially\nThese merchants told him tales of fair Constance;\nFrom such nobility, told of earnestly,\nThis sultan caught a dream of great pleasance,\nAnd she so figured in his remembrance\nThat all his wish and all his busy care\nWere, throughout life, to love that lady fair.\nNow peradventure, in that mighty book\nWhich men call heaven, it had come to pass,\nIn stars, when first a living breath he took,\nThat he for love should get his death, alas!\nFor in the stars, far dearer than is glass,\nIs written, God knows, read it he who can,-\nAnd truth it is- the death of every man.\nIn stars, full many a winter over-worn,\nWas written the death of Hector, Achilles,\nOf Pompey, Julius, long ere they were born;\nThe strife at Thebes; and of great Hercules,\nOf Samson, of Turnus, of Socrates,\nThe death to each; but men's wits are so dull\nThere is no man may read this to the full.\nThis sultan for his privy-council sent,\nAnd, but to tell it briefly in this place,\nHe did to them declare his whole intent,\nAnd said that, surely, save he might have grace\nTo gain Constance within a little space,\nHe was but dead; and charged them, speedily\nTo find out, for his life, some remedy.\nBy divers men, then, divers things were said;\nThey reasoned, and they argued up and down;\nFull much with subtle logic there they sped;\nThey spoke of spells, of treachery in Rome town;\nBut finally, as to an end foreknown,\nThey were agreed that nothing should gainsay\nA marriage, for there was no other way.\nThen saw they therein so much difficulty,\nWhen reasoning of it, (to make all plain,\nBecause such conflict and diversity\nBetween the laws of both lands long had lain)\nThey held: No Christian emperor were fain\nTo have his child wed under our sweet laws,\nGiven us by Mahomet for God's cause.\nBut he replied: Nay, rather then than lose\nThe Lady Constance, I'll be christened, yes!\nI must be hers, I can no other choose.\nI pray you let be no rebelliousness;\nSave me my life, and do not be careless\nIn getting her who thus alone may cure\nThe woe whereof I cannot long endure.\nWhat needs a copious dilation now?\nI say: By treaties and by embassy,\nAnd the pope's mediation, high and low,\nAnd all the Church and all the chivalry,\nThat, to destruction of Mahometry\nAnd to augmenting Christian faith so dear,\nThey were agreed, at last, as you shall hear.\nThe sultan and his entire baronage\nAnd all his vassals, they must christened be,\nAnd he shall have Constance in true marriage,\nAnd gold (I know not in what quantity),\nFor which was found enough security;\nThis, being agreed, was sworn by either side.\nNow, Constance fair, may great God be your guide!\nNow would some men expect, as I may guess,\nThat I should tell of all the purveyance\nThe emperor, of his great nobleness,\nHas destined for his daughter, fair Constance.\nBut men must know that so great ordinance\nMay no one tell within a little clause\nAs was arrayed there for so high a cause.\nBishops were named who were with her to wend,\nLadies and lords and knights of high renown,\nAnd other folk- but I will make an end,\nExcept that it was ordered through the town\nThat everyone, with great devotion shown,\nShould pray to Christ that He this marriage lead\nTo happy end, and the long voyage speed.\nThe day is come, at last, for leave-taking,\nI say, the woeful, fatal day is come,\nWhen there may be no longer tarrying,\nBut to go forth make ready all and some;\nConstance, who was with sorrow overcome,\nRose, sad and pale, and dressed herself to wend;\nFor well she saw there was no other end.\nAlas! What wonder is it that she wept?\nShe shall be sent to a strange. country, far\nFrom friends that her so tenderly have kept,\nAnd bound to one her joy to make or mar\nWhom she knows not, nor what his people are.\nHusbands are all good, and have been of yore,\nThat know their wives, but I dare say no more.\nFather, she said, your wretched child, Constance,\nYour daughter reared in luxury so soft,\nAnd you, my mother, and my chief pleasance,\nAbove all things, save Christ Who rules aloft,\nConstance your child would be remembered oft\nWithin your prayers, for I to Syria go,\nNor shall I ever see you more, ah no!\nUnto the land of Barbary my fate\nCompels me now, because it is your will;\nBut Christ, Who died to save our sad estate,\nSo give me grace, His mandates I'll fulfill;\nI, wretched woman, though I die, 'tis nil.\nWomen are born to slave and to repent,\nAnd to be subject to man's government.\nI think, at Troy, when Pyrrhus broke the wall;\nWhen Ilium burned; when Thebes fell, that city;\nAt Rome, for all the harm from Hannibal,\nWho vanquished Roman arms in campaigns three-\nI think was heard no weeping for pity\nAs in the chamber at her leave-taking;\nYet go she must, whether she weep or sing.\nO primal-moving, cruel Firmament,\nWith thy diurnal pressure, that doth sway\nAnd hurl all things from East to Occident,\nWhich otherwise would hold another way,\nThy pressure set the heavens in such array,\nAt the beginning of this wild voyage,\nThat cruel Mars hath murdered this marriage.\nUnfortunate ascendant tortuous,\nOf which the lord has helpless fall'n, alas,\nOut of his angle to the darkest house!\nO Mars! O Atazir in present case!\nO feeble Moon, unhappy is thy pace!\nThou'rt in conjunction where thou'rt not received,\nAnd where thou should'st go, thou hast not achieved.\nImprudent emperor of Rome, alas!\nWas no philosopher in all thy town?\nIs one time like another in such case?\nIndeed, can there be no election shown,\nEspecially to folk of high renown,\nAnd when their dates of birth may all men know?\nAlas! We are too ignorant or too slow.\nTo ship is brought this fair and woeful maid,\nFull decorously, with every circumstance.\nNow Jesus Christ be with you all, she said;\nAnd there's no more, save Farewell, fair Constance!\nShe strove to keep a cheerful countenance,\nAnd forth I let her sail in this manner,\nAnd turn again to matters far from her.\nThe mother of the sultan, well of vices,\nHas heard the news of her son's full intent,\nHow he will leave the ancient sacrifices;\nAnd she at once for her own council sent;\nAnd so they came to learn what thing she meant.\nAnd when they were assembled, each compeer,\nShe took her seat and spoke as you shall hear.\nMy lords, said she, you know well, every man,\nMy son intends to forgo and forget\nThe holy precepts of our Alkoran,\nGiven by God's own prophet, Mahomet.\nBut I will make one vow to great God yet:\nThe life shall rather from my body start\nThan Islam's laws out of my faithful heart!\nWhat should we get from taking this new creed\nBut thralldom for our bodies and penance?\nAnd afterward, be drawn to Hell, indeed,\nFor thus denying our faith's inheritance?\nBut, lords, if you will give your sustenance,\nAnd join me for the wisdom I've in store,\nI swear to save us all for evermore.\nThey swore and they assented, every man,\nTo live by her and die, and by her stand;\nAnd each of them, in what best wise he can,\nShall gather friends and followers into band;\nAnd she shall take the enterprise in hand,\nThe form of which I soon will you apprise,\nAnd to them all she spoke, then, in this wise.\nWe will first feign the Christian faith to take;\nCold water will not harm us from the rite;\nAnd I will such a feast and revel make\nAs will, I trust, to lull be requisite.\nFor though his wife be christened ever so white,\nShe shall have need to wash away the red,\nThough a full font of water be there sped.\nO sultana, root of iniquity!\nVirago, you Semiramis second!\nO serpent hid in femininity,\nJust as the Serpent deep in Hell is bound!\nO pseudo-woman, all that may confound\nVirtue and innocence, through your malice,\nIs bred in you, the nest of every vice!\nO Satan, envious since that same day\nWhen thou wert banished from our heritage,\nWell know'st thou unto woman thine old way!\nThou made'st Eve bring us into long bondage.\nThou wilt destroy this Christian marriage.\nThine instrument- ah welaway the while!-\nMake'st thou of woman when thou wilt beguile!\nNow this sultana whom I blame and harry,\nLet, secretly, her council go their way.\nWhy should I longer in my story tarry?\nShe rode unto the sultan, on a day,\nAnd told him she'd renounce her old faith, yea,\nBe christened at priests' hands, with all the throng,\nRepentant she'd been heathen for so long.\nBeseeching him to do her the honour\nTo let her have the Christian men to feast:\nTo entertain them will be my labour.\nThe sultan said: I'll be at your behest.\nAnd, kneeling, thanked her for that fair request,\nSo glad he was he knew not what to say;\nShe kissed her son, and homeward went her way.\nExplicit prima pars.\nSequitur pars secunda.\nArrived now are these Christian folk at land,\nIn Syria, with a great stately rout,\nAnd hastily this sultan gave command,\nFirst to his mother and all the realm about,\nSaying his wife was come, beyond a doubt,\nAnd prayed her that she ride to meet the queen,\nThat all due honour might be shown and seen.\nGreat was the crush and rich was the array\nOf Syrians and Romans, meeting here;\nThe mother of the sultan, rich and gay,\nReceived her open-armed, with smiling cheer,\nAs any mother might a daughter dear;\nAnd to the nearest city, with the bride,\nAt gentle pace, right festively they ride.\nI think the triumph of great Julius,\nWhereof old Lucan make so long a boast,\nWas not more royal nor more curious\nThan was the assembling of this happy host.\nBut this same Scorpion, this wicked ghost-\nThe old sultana, for all her flattering,\nChose in that sign full mortally to sting.\nThe sultan came himself, soon after this,\nSo regally 'twere wonderful to tell,\nAnd welcomed her into all joy and bliss.\nAnd thus in such delight I let them dwell.\nThe fruit of all is what I now shall tell.\nWhen came the time, men thought it for the best\nTheir revels cease, and got them home to rest.\nThe time came when this old sultana there\nHas ordered up the feast of which I told,\nWhereto the Christian folk did them prepare,\nThe company together, young and old.\nThere men might feast and royalty behold,\nWith dainties more than I can e'en surmise;\nBut all too dear they've bought it, ere they rise.\nO sudden woe! that ever will succeed\nOn worldly bliss, infused with bitterness;\nThat ends the joy of earthly toil, indeed;\nWoe holds at last the place of our gladness.\nHear, now, this counsel for your certainness:\nUpon your most glad day, bear then in mind\nThe unknown harm and woe that come behind.\nFor, but to tell you briefly, in one word-\nThe sultan and the Christians, every one,\nWere all hewed down and thrust through at the board,\nSave the fair Lady Constance, she alone.\nThis old sultana, aye, this cursed crone\nHas, with her followers, done this wicked deed,\nFor she herself would all the nation lead.\nThere was no Syrian that had been converted,\nBeing of the sultan's council resolute,\nBut was struck down, ere from the board he'd started\nAnd Constance have they taken now, hot-foot,\nAnd on a ship, of rudder destitute,\nThey her have placed, bidding her learn to sail\nFrom Syria to Italy- or fail.\nA certain treasure that she'd brought, they add,\nAnd, truth to tell, of food great quantity\nThey have her given, and clothing too she had;\nAnd forth she sails upon the wide salt sea.\nO Constance mine, full of benignity,\nO emperor's young daughter, from afar\nHe that is Lord of fortune be your star!\nShe crossed herself, and in a pious voice\nUnto the Cross of Jesus thus said she:\nO bright, O blessed Altar of my choice,\nRed with the Lamb's blood full of all pity,\nThat washed the world from old iniquity,\nMe from the Fiend and from his claws, oh keep\nThat day when I shall drown within the deep!\nVictorious Tree, Protection of the true,\nThe only thing that worthy was to bear\nThe King of Heaven with His wounds so new,\nThe White Lamb Who was pierced through with the spear,\nDriver of devils out of him and her\nWho on Thine arms do lay themselves in faith,\nKeep me and give me grace before my death!\nFor years and days drifted this maiden pure,\nThrough all the seas of Greece and to the strait\nOf dark Gibraltar dier she adventure;\nOn many a sorry meal now may she bait;\nUpon her death full often may she wait\nBefore the wild waves and the winds shall drive\nHer vessel where it shall some day arrive.\nMen might well ask: But why was she not slain?\nAnd at that feast who could her body save?\nAnd I reply to that demand, again:\nWho saved young Daniel in the dreadful cave\nWhere every other man, master and knave,\nWas killed by lions ere he might up-start?\nNo one, save God, Whom he bore in his heart.\nGod willed to show this wondrous miracle\nThrough her, that we should see His mighty works;\nAnd Christ Who every evil can dispel,\nBy certain means does oft, as know all clerks,\nDo that whereof the end in darkness lurks\nFor man's poor wit, which of its ignorance\nCannot conceive His careful purveyance.\n\nNow, since she was not slain at feast we saw,\nWho kept her that she drowned not in the sea?\nBut who kept Jonah in the fish's maw\nTill he was spewed forth there at Nineveh?\nWell may men know it was no one but He\nWho saved the Hebrew people from drowning\nWhen, dry-shod, through the sea they went walking.\nWho bade the four great spirits of tempest,\nThat power have to harry land and sea,\nNot north, nor south, nor yet to east, nor west\nShall ye molest the ocean, land, or tree?\nTruly, the Captain of all this was He\nWho from the storm has aye this woman kept,\nAs well when waking as in hours she slept.\nWhere might this woman get her drink and meat?\nThree years and more, how lasted her supply?\nWho gave Egyptian Mary food to eat\nIn cave desert? None but Christ, say I.\nFive thousand folk, the gospels testify,\nOn five loaves and two fishes once did feed.\nAnd thus God sent abundance for her need.\nForth into our own ocean then she came,\nThrough all our wild white seas, until at last,\nUnder a keep, whose name I cannot name,\nFar up Northumberland, her ship was cast,\nAnd on the sands drove hard and stuck so fast\nThat thence it moved not, no, for all the tide,\nIt being Christ's will that she should there abide.\nThe warden of the castle down did fare\nTo view this wreck, and through the ship he sought\nAnd found this weary woman, full of care;\nHe found, also, the treasure she had brought.\nIn her own language mercy she besought\nThat he would help her soul from body win\nTo free her from the plight that she was in.\nA kind of bastard Latin did she speak,\nBut, nevertheless, these folk could understand;\nThe constable no longer thought to seek,\nBut led the sorrowing woman to the land;\nThere she knelt down and thanked God, on the sand.\nBut who or what she was, she would not say,\nFor threat or promise, though she died that day.\nShe said she'd been bewildered by the sea,\nAnd had lost recollection, by her truth;\nThe warden had for her so great pity,\nAs had his wife, that both they wept for ruth.\nShe was so diligent to toil, in sooth,\nTo serve and please all folk within that place,\nThat all loved her who looked upon her face.\nThis warden and Dame Hermengild, his wife,\nWere pagans, and that country, everywhere;\nBut Hermengild now loved her as her life,\nAnd Constance has so long abided there,\nAnd prayed so oft, with many a tearful prayer,\nThat Jesus has converted, through His grace,\nDame Hermengild, the lady of that place.\nIn all that land no Christian dared speak out\nAll Christians having fled from that country,\nFor pagan men had conquered all about\nThe regions of the north, by land and sea;\nTo Wales was fled the Christianity\nOf the old Britons dwelling in this isle;\nThat was their refuge in the wild meanwhile.\nYet ne'er were Christian Britons so exiled\nBut some of them assembled, privately,\nTo honour Christ, and heathen folk beguiled;\nAnd near the castle dwelt of such men three.\nBut one of them was blind and could not see,\nSave with the inner optics of his mind,\nWherewith all men see after they go blind.\nBright was the sun upon that summer's day\nWhen went the warden and his wife also,\nAnd Constance, down the hill, along the way\nToward the sea, a furlong off, or so,\nTo frolic and to wander to and fro;\nAnd in their walk on this blind man they came,\nWith eyes fast shut, a creature old and lame.\nIn name of Christ! this blind old Briton cried,\nDame Hermengild, give me my sight again.\nBut she was frightened of the words, and sighed,\nLest that her husband, briefly to be plain,\nShould have her, for her love of Jesus, slain;\nTill Constance strengthened her and bade her work\nThe will of God, as daughter of His kirk.\nThe warden was confounded by that sight,\nAnd asked: What mean these words and this affair?\nConstance replied: Sir, it is Jesus' might\nThat helps all poor folk from the foul Fiend's snare.\nAnd so far did she our sweet faith declare\nThat she the constable, before 'twas eve,\nConverted, and in Christ made him believe.\nThis constable, though not lord of that place\nWhere he'd found Constance, wrecked upon the sand,\nHad held it well for many a winter's space,\nFor Alla, king of all Northumberland,\nWho was full wise and hardy of his hand\nAgainst the Scots, as men may read and hear,\nBut I will to my tale again- give ear.\nSatan, that ever waits, men to beguile,\nSaw now, in Constance, all perfection grown,\nAnd wondering how to be revenged the while,\nHe made a young knight, living in the town,\nLove her so madly, with foul passion flown,\nThat verily he thought his life should spill,\nSave that, of her, be once might have his will.\nHe wooed her, but it all availed him naught;\nShe would not sin in any wise or way;\nAnd, for despite, he plotted in his thought\nTo make her die a death of shame some day.\nHe waited till the warden was away,\nAnd, stealthily by night, he went and crept\nTo Hermengild's bed-chamber, while she slept.\nWeary with waking for her orisons,\nSlept Constance, and Dame Hermengild also.\nThis knight, by Satan's tempting, came at once\nAnd softly to the bedside he did go.\nAnd cut the throat of Hermengild, and so\nLaid the hot reeking knife by fair Constance,\nAnd went his way- where God give him mischance!\nSoon after came the warden home again,\nAnd with him Alla, king of all that land,\nAnd saw his wife so pitilessly slain,\nFor which he wept and cried and wrung his hand;\nAnd in the bed the bloody dagger, and\nThe Lady Constance. Ah! What could she say?\nFor very woe her wits went all away.\nKing Alla was apprised of this sad chance,\nAnd told the time, and where, and in what wise\nWas found in a wrecked ship the fair Constance,\nAs heretofore you've heard my tale apprise.\nBut in the king's heart pity did arise\nWhen he saw so benignant a creature\nFallen in distress of such misadventure.\nFor as the lamb unto his death is brought,\nSo stood this innocent before the king;\nAnd the false knight that had this treason wrought,\nHe swore that it was she had done this thing.\nNevertheless, there was much sorrowing\nAmong the people, saying, We cannot gues\nThat she has done so great a wickedness.\nFor we have seen her always virtuous,\nAnd loving Hermengild as she loved life.\nTo this bore witness each one in that house,\nSave he that slew the victim with his knife.\nThe gentle king suspected. motive rife\nIn that man's heart; and thought he would inquire\nDeeper therein, the truth to learn entire.\nAlas, Constance! You have no champion,\nAnd since you cannot fight, it's welaway!\nBut He Who died for us the cross upon,\nAnd Satan bound (who lies yet where he lay),\nSo be your doughty Champion this day!\nFor, except Christ a miracle make known,\nYou shall be slain, though guiltless, and right soon.\nShe dropped upon her knees and thus she prayed:\nImmortal God, Who saved the fair Susanna\nFrom lying blame, and Thou, O gracious Maid\n(Mary, I mean, the daughter of Saint Anna),\nBefore Child the angels sing hosanna,\nIf I be guiltless of this felony,\nMy succour be, for otherwise I die!\nHave you not sometime seen a pallid face\nAmong the crowd, of one that's being led\nToward his death- one who had got no grace?\nAnd such a pallor on his face was spread\nAll men must mark it, full of horrid dread,\nAmong the other faces in the rout.\nSo stood fair Constance there and looked about.\nO queens that live in all prosperity,\nDuchesses, and you ladies, every one,\nHave pity, now, on her adversity;\nAn emperor's young daughter stands alone;\nShe has no one to whom to make her moan.\nO royal blood that stands there in such dread,\nFar are your friends away in your great need!\nThis King Alla has such compassion shown\n(Since gentle heart is full of all pity),\nThat from his two eyes ran the tears right down.\nNow hastily go fetch a book, quoth he,\nAnd if this knight will swear that it was she\nWho slew the woman, then will we make clear\nThe judge we shall appoint the case to hear.\nA book of Gospels writ in British tongue\nWas brought, and on this Book he swore anon\nHer guilt; but then the people all among\nA clenched hand smote him on the shoulder-bone,\nAnd down he fell, as stunned as by a stone,\nAnd both his eyes burst forth out of his face\nIn sight of everybody in that place.\nA voice was heard by all that audience,\nSaying: You have here slandered the guiltless\nDaughter of Holy Church, in high Presence;\nThus have you done, and further I'll not press.\nWhereat were all the folk aghast, no less;\nAs men amazed they stand there, every one,\nFor dread of vengeance, save Constance alone.\nGreat was the fear and, too, the repentance\nOf those that held a wrong suspicion there\nAgainst this simple innocent Constance;\nAnd by this miracle so wondrous fair,\nAnd by her mediation and her prayer,\nThe king, with many another in that place,\nWas there converted, thanks to Christ His grace!\nThis lying knight was slain for his untruth,\nBy sentence of King Alla, hastily;\nYet Constance had upon his death great ruth.\nAnd after this, Jesus, of His mercy,\nCaused Alla take in marriage, solemnly,\nThis holy maiden, so bright and serene,\nAnd thus has Christ made fair Constance a queen.\nBut who was sad, if I am not to lie,\nAt this but Lady Donegild, she who\nWas the king's mother, full of tyranny?\nShe thought her wicked heart must burst in two;\nShe would he'd never thought this thing to do;\nAnd so she hugged her anger that he'd take\nSo strange a wife as this creature must make.\nNeither with chaff nor straw it pleases me\nTo make a long tale, here, but with the corn.\nWhy should I tell of all the royalty\nAt that wedding, or who went first, well-born,\nOr who blew out a trumpet or a horn?\nThe fruit of every tale is but to say,\nThey eat and drink and dance and sing and play.\nThey went to bed, as was but just and right,\nFor though some wives are pure and saintly things,\nThey must endure, in patience, in the night,\nSuch necessaries as make pleasurings\nTo men whom they have wedded well with rings,\nAnd lay their holiness a while aside;\nThere may no better destiny betide.\nOn her he got a man-child right anon;\nAnd to a bishop and the warden eke\nHe gave his wife to guard, while he was gone\nTo Scotland, there his enemies to seek;\nNow Constance, who so humble is, and meek,\nSo long is gone with child that, hushed and still,\nShe keeps her chamber, waiting on Christ's will.\nThe time was come, a baby boy she bore;\nMauritius they did name him at the font;\nThis constable sent forth a messenger\nAnd wrote unto King Alla at the front\nOf all this glad event, a full account,\nAnd other pressing matters did he say.\nHe took the letter and went on his way.\nThis messenger, to forward his own ends,\nTo the king's mother rode with swiftest speed,\nHumbly saluting her as down he bends:\nMadam, quoth he, be joyful now indeed!\nTo God a hundred thousand thanks proceed.\nThe queen has borne a child, beyond all doubt,\nTo joy and bliss of all this land about.\nLo, here are letters sealed that say this thing,\nWhich I must bear with all the speed I may;\nIf you will send aught to your son, the king,\nI am your humble servant, night and day.\nDonegild answered: As for this time, nay;\nBut here tonight I'd have you take your rest;\nTomorrow I will say what I think best.\nThis messenger drank deep of ale and wine,\nAnd stolen were his letters, stealthily,\nOut of his box, while slept he like a swine;\nAnd counterfeited was, right cleverly,\nAnother letter, wrought full sinfully,\nUnto the king; of this event so near,\nAll from the constable, as you shall hear.\nThe letter said, the queen delivered was\nOf such a fiendish, horrible creature,\nThat in the castle none so hardy as\nDurst, for a lengthy time, there to endure.\nThe mother was an elf or fairy, sure,\nCome there by chance of charm, or sorcery,\nAnd all good men hated her company.\nSad was the king when this letter he'd seen;\nBut to no man he told his sorrows sore,\nBut with his own hand he wrote back again:\nWelcome what's sent from Christ, for evermore,\nTo me, who now am learned in His lore;\nLord, welcome be Thy wish, though hidden still,\nMy own desire is but to do Thy will.\nGuard well this child, though foul it be or fair,\nAnd guard my wife until my home-coming;\nChrist, when He wills it, may send me an heir\nMore consonant than this with my liking.\nThis letter sealed, and inwardly weeping,\nTo the same messenger 'twas taken soon,\nAnd forth he went; there's no more to be done.\nO messenger, possessed of drunkenness,\nStrong is your breath, your limbs do falter aye,\nAnd you betray all secrets, great and less;\nYour mind is gone, you jangle like a jay;\nYour face is mottled in a new array!\nWhere drunkenness can reign, in any rout,\nThere is no counsel kept, beyond a doubt.\nO Donegild, there is no English mine\nFit for your malice and your tyranny!\nTherefore you to the Fiend I do resign,\nLet him go write of your foul treachery!\nFie, mannish women! Nay, by God, I lie!\nFie, fiendish spirit, for I dare well tell,\nThough you walk here, your spirit is in Hell!\nThis messenger came from the king again,\nAnd at the king's old mother's court did light,\nAnd she was of this messenger full fain\nTo please him in whatever way she might.\nHe drank until his girdle was too tight,\nHe slept and snored and mumbled, drunken-wise,\nAll night, until the sun began to rise.\nAgain were his letters stolen, every one,\nAnd others counterfeited, in this wise:\nThe king commands his constable, anon,\nOn pain of hanging by the high justice,\nThat he shall suffer not, in any guise,\nConstance within the kingdom to abide\nBeyond three days and quarter of a tide.\nBut in the ship wherein she came to strand\nShe and her infant son and all her gear\nShall be embarked and pushed out from the land,\nAnd charge her that she never again come here.\nO Constance mine, well might your spirit fear,\nAnd, sleeping, in your dream have great grievance\nWhen Donegild arranged this ordinance.\nThis messenger, the morrow, when he woke,\nUnto the castle held the nearest way,\nAnd to the constable the letter took;\nAnd when he'd read and learned what it did say,\nOften he cried Alas! and Welaway!\nLord Christ, quoth he, how may this world endure?\nSo full of sin is many a bad creature.\nO mighty God, and is it then Thy will?\nSince Thou art righteous judge, how can it be\nThat innocence may suffer so much ill\nAnd wicked folk reign in prosperity?\nO good Constance, alas! Ah, woe is me\nThat I must be your torturer, or die\nA shameful death! There is no other way.\nWept both the young and old of all that place\nBecause the king this cursed letter sent,\nAnd Constance, with a deathly pallid face,\nUpon the fourth day to the ship she went.\n\nNevertheless, she took as good intent\nThe will of Christ, and kneeling on the strand,\nShe said: Lord, always welcome Thy command!\nHe that did keep me from all lying blame\nThe while I lived among you, sun and snow,\nHe can still guard me from all harm and shame\nUpon salt seas, albeit I see not how.\nAs strong as ever He was, so is He now.\nIn Him I trust and in His Mother dear,\nHe is my sail, the star by which I steer.\nHer little child lay crying in her arm,\nAnd kneeling, piteously to him she said:\nPeace, little son, I will do you no harm.\nWith that the kerchief took she from her braid,\nAnd binding it across his eyes, she laid\nAgain her arm about and lulled him fast\nAsleep, and then to Heaven her eyes up-cast.\nMother, she said, O Thou bright Maid, Mary,\nTrue is it that through woman's incitement\nMankind was banished and is doomed to die,\nFor which Thy Son upon the cross was rent;\nThy blessed eyes saw all of His torment;\nWherefore there's no comparison between\nThy woe and any woe of man, though keen.\nThou sawest them slay Thy Son before Thine eyes;\nAnd yet lives now my little child, I say!\nO Lady bright, to Whom affliction cries,\nThou glory of womanhood, O Thou fair May,\nHaven of refuge, bright star of the day,\nPity my child, Who of Thy gentleness\nHast pity on mankind in all distress!\nO little child, alas! What is your guilt,\nWho never wrought the smallest sin? Ah me,\nWhy will your too hard father have you killed?\nHave mercy, O dear constable! cried she,\nAnd let my little child bide, safe from sea;\nAnd if you dare not save him, lest they blame\nThen kiss him once in his dear father's name!\nTherewith she gazed long backward at the land,\nAnd said: Farewell, my husband merciless!\nAnd up she rose and walked right down the strand\nToward the ship; followed her all the press;\nAnd ever she prayed her child to cry the less;\nAnd took her leave; and with a high intent\nShe crossed herself; and aboard ship she went.\nVictualled had been the ship, 'tis true- indeed\nAbundantly- for her, and for long space;\nOf many other things that she should need\nShe had great plenty, thanks be to God's grace!\nThrough wind and weather may God find her place\nAnd bring her home! I can no better say;\nBut out to sea she stood upon her way.\nExplicit secunda pars.\nSequitur pars tercia.\nAlla the king came home soon after this\nUnto his castle, of the which I've told,\nAnd asked for wife and child, whom he did miss.\nThe constable about his heart grew cold,\nAnd plainly all the story he then told,\nAs you have heard, I cannot tell it better,\nAnd showed the king his seal and the false letter.\nAnd said: My lord, as you commanded me,\nOn pain of death, so have I done- in vain!\nThe messenger was tortured until he\nMade known the facts to all men, full and plain,\nFrom night to night, in what beds he had lain.\nAnd thus, by dint of subtle questioning,\n'Twas reasoned out from whom this harm did spring.\nThe hand was known, now, that the letter wrote,\nAnd all the venom of this cursed deed,\nBut in what wise I certainly know not,\nThe effect is this, that Alla, for her meed,\nHis mother slew, as men may plainly read,\nShe being false to her sworn allegiance,\nAnd thus old Donegild ended with mischance.\nThe sorrow that this Alla, night and day,\nFelt for his wife, and for his child also,\nThere is no human tongue on earth to say.\nBut now will I back to fair Constance go,\nWho drifted on the seas, in pain and woe,\nFive years and more, as was Lord Christ's command,\nBefore her ship approached to any land.\nUnder a heathen castle, at the last,\nWhereof the name not in my text I find,\nConstance and her young son the sea did cast.\nAlmighty God, Redeemer of mankind,\nHave Constance and her little child in mind!\nWho must fall into heathen hands and soon\nBe near to death, as I shall tell anon.\nDown from the castle came full many a wight\nTo stare upon the ship and on Constance.\nBut briefly, from the castle, on a night,\nThe warden's steward- God give him mischance!-\nA thief who had renounced allegiance\nTo Christ, came to the ship and said he should\nPossess her body, whether or not she would.\nWoe for this wretched woman then began,\nHer child cried out and she cried, piteously;\nBut blessed Mary helped her soon; the man\nWith whom she struggled well and mightily,\nThis thief fell overboard all suddenly,\nAnd in the sea was drowned by God's vengeance;\nAnd thus has Christ unsullied kept Constance.\nO foul desire of lechery, lo thine end!\nNot only dost thou cripple a man's mind,\nBut verily dost thou his body rend;\nThe end of all thy work and thy lusts blind\nIs bitterness; how many may we find\nThat not for actions but for mere intent\nTo do this sin, to shame or death are sent.\nHow could this poor weak woman have the strength\nTo keep herself against that renegade?\nGoliath of immeasurable length,\nHow could young David such a death have made,\nSo slight and without armour? How arrayed\nHimself to look upon that dreadful face?\nMen may well see, it was but God's own grace!\nWho gave to Judith courage all reckless\nTo slay him, Holofernes, in his tent,\nAnd to deliver out of wretchedness\nThe folk of God? I say, for this intent\nThat just as God a soul of vigour sent\nTo them, and saved them out of their mischance,\nSo sent He might and vigour to Constance.\nForth went her ship and through the narrow mouth\nOf Ceuta and Gibraltar, on its way,\nSometimes to west, and sometimes north or south,\nAye and sometimes east, many a weary day,\nUntil Christ's Mother (blest be She for aye!)\nDid destine, out of good that is endless,\nTo make an end of Constance' heaviness.\nBut let us leave this Constance now, and turn\nTo speak of that same Roman emperor\nWho does, from Syria, by letters, learn\nThe slaughter of Christians and the dishonour\nDone to his daughter by a vile traitor-\nI mean that old sultana, years ago,\nWho, at the feast, slew all men, high and low.\nFor which this emperor did send anon\nA senator, with royal ordinance,\nAnd other lords, God knows, and many a one,\nOn Syrians to take full high vengeance.\nThey burn, they slay, they give them all mischance\nThrough many a day; but, briefly to make end,\nHomeward to Rome, at last, the victors wend.\nThis senator returned with victory\nTo Rome again, sailing right royally,\nAnd spoke the ship (so goes the old story)\nIn which our Constance sat so piteously,\nNothing he knew of who she was, or why\nShe was in such a plight; nor would she say\nAught of herself, though she might die that day.\nHe took her into Rome, and to his wife\nGave her in charge, and her young son also;\nAnd in his house she lived awhile her life.\nThus can Our Lady bring from deepest woe\nMost woeful Constance, aye and more, we know.\nAnd for a long time dwelt she in that place,\nEngaged in God's good works, such was her grace.\nThe senator's good wife her own aunt was,\nYet for all that she knew her never the more;\nI will no longer tarry in this case,\nBut to King Alla, whom we left, of yore,\nWeeping for his lost wife and sighing sore.\nI will return, and I will leave Constance\nUnder the senator's roof and governance.\nKing Alla, who had had his mother slain,\nUpon a day fell to such repentance,\nThat, but to tell it briefly and be plain,\nTo Rome he came to pay his just penance\nAnd put himself in the pope's ordinance,\nIn high and low; and Jesus Christ he sought\nTo pardon all the wicked deeds he'd wrought.\nThe news anon through all Rome town was borne,\nHow King Alla would come on pilgrimage,\nBy harbingers that unto him were sworn;\nWhereat the senator, as was usage,\nRode out to him, with many of his lineage,\nAs well to show his own magnificence\nAs do to any king a reverence.\nGreat welcome gave this noble senator\nTo King Alla, and he to him also;\nEach of them showed the other much honour;\nAnd so befell that, in a day or so,\nThis senator to King Alla did go\nTo feast, and briefly, if I may not lie,\nConstance' young son went in his company.\nSome men would say, 'twas instance of Constance\nThat sent him with the senator to feast;\nI cannot tell you every circumstance,\nBe it as may be, he was there, at least.\nBut truth is that, at his mother's behest,\nBefore the king, during the banquet's space,\nThe child stood, looking in King Alla's face.\nThis child aroused within the king great wonder,\nAnd to the senator he said, anon:\nWhose is the fair child that is standing yonder?\nI know not, quoth he, by God and Saint John!\nA mother he has, but father has he none\nThat I know of- and briefly, at a bound,\nHe told King Alla how this child was found.\nBut God knows, said this senator, as well,\nSo virtuous a liver, in my life\nI never saw, as she is, nor heard tell\nOf earthly woman, maiden, no nor wife.\nI dare say, she would rather have a knife\nThrust through her breast than play a female trick;\nThere is no man could bring her to the prick.\nNow this boy was as like unto Constance\nAs it was possible for one to be.\nAlla had kept the face in remembrance\nOf Dame Constance, and thereon now mused he:\nMayhap the mother of the child was she\nWho was his wife. And inwardly he sighed,\nAnd left the table with a hasty stride.\nIn faith, thought he, a phantom's in my head!\nI ought to hold, by any right judgment,\nThat in the wide salt sea my wife is dead.\nAnd afterward he made this argument:\nHow know I but that Christ has hither sent\nMy wife by sea, as surely as she went\nTo my own land, the which was evident?\nAnd, after noon, home with the senator\nWent Alla, all to test this wondrous chance.\nThe senator did Alla great honour,\nAnd hastily he sent for fair Constance.\nBut, trust me, she was little fain to dance\nWhen she had heard the cause of that command.\nScarcely upon her two feet could she stand.\nWhen Alla saw his wife, he greeted her,\nThen wept till it was a sad thing to see.\nFor, at the first glance, when she entered there,\nHe knew full verily that it was she.\nAnd she for grief stood dumb as ever tree;\nSo was her heart shut up in her distress\nWhen she remembered his unkindliness.\nTwice did she swoon away there, in his sight;\nHe wept and he protested piteously.\nNow God, quoth he, and all His angels bright\nSo truly on my spirit have mercy\nAs of your ills all innocent am I,\nAs is Maurice, my son, so like your face,\nOr may the foul Fiend take me from this place!\nLong was the sobbing and the bitter pain\nBefore their woeful hearts could find surcease;\nGreat was the pity to hear them complain,\nWhereof their sorrows surely did increase.\nI pray you all my labour to release;\nI cannot tell their grief until tomorrow,\nI am so weary, speaking long of sorrow.\nBut, truth being known and all doubt now dismissed,\nAnd Alla proven guiltless of her woe,\nI think a hundred times they must have kissed,\nAnd such great bliss there was between the two\nThat, save the joy that nevermore shall go,\nThere was naught like it, present time or past,\nNor shall be, ever, while the world shall last.\nThen prayed she of her husband, all meekly,\nAs for her pain a splendid anodyne,\nThat he would pray her father, specially,\nThat, of his majesty, he would incline\nAnd that, some day, would come with him to dine;\nShe prayed him, also, he should in no way\nUnto her father one word of her say.\nSome men would say, it was the child Maurice\nDid bear this message to the emperor;\nBut, as I guess, King Alla was too nice\nIn etiquette to one of such honour\nAs he that was of Christendom the flower,\nTo send a child; and it is best to deem\nHe went himself, and so it well may seem.\nThis emperor has granted, graciously,\nTo come to dinner, as he's been besought,\nAnd, well I think, he pondered busily\nUpon the child, and on his daughter thought.\nAlla went to his inn, and, as he ought,\nMade ready for the feast in every wise\nAs far as his experience could devise.\nThe morrow came, and Alla rose to dress,\nAnd, too, his wife, the emperor to meet;\nAnd forth they rode in joy and happiness.\nAnd when she saw her father in the street,\nShe lighted down, and falling at his feet,\nFather, quoth she, your young child, your Constance,\nIs now gone clean out of your remembrance.\nI am your daughter Constance, then said she,\nThat once you sent to Syria. 'Tis I.\nIt is I, father, who, on the salt sea,\nWas sent, alone to drift and doomed to die.\nBut now, good father, mercy must I cry:\nSend me no more to heathendom, godless,\nBut thank my lord, here, for his kindliness.\nBut all the tender joy, who'll tell it all\nThat was between the three who thus are met?\nBut of my tale, now, make an end I shall;\nThe day goes fast, I will no longer fret.\nThese happy folk at dinner are all set,\nAnd there, in joy and bliss, I let them dwell;\nHappier a thousand fold than I can tell.\nThis child Maurice was, since then, emperor\nMade by the pope, and lived right christianly.\nUnto Christ's Church he did a great honour;\nBut I let all his story pass me by.\nOf Constance is my tale, especially.\nIn ancient Roman histories men may find\nThe life of Maurice; I've it not in mind.\nThis King Alla, when came the proper day,\nWith his Constance, his saintly wife so sweet,\nTo England went again, by the straight way,\nWhere they did live in joy and quiet meet.\nBut little while it lasts us, thus complete.\nJoy of this world, for time will not abide;\nFrom day to day it changes as the tide.\nWho ever lived in such delight one day\nThat was not stirred therefrom by his conscience,\nDesire, or anger, or some kindred fray,\nEnvy, or pride, or passion, or offense?\nI say but to one ending this sentence:\nThat but a little while in joy's pleasance\nLasted the bliss of Alla and Constance.\nFor death, that takes from high and low his rent,\nWhen but a year had passed, as I should guess,\nOut of the world King Alla quickly sent,\nFor whom Constance felt heavy wretchedness.\nNow let us pray that God his soul will bless!\nAnd of Dame Constance, finally to say,\nTowards the town of Rome she took her way.\nTo Rome is come this holy one and pure,\nAnd finds that all her friends are safe and sound;\nFor now she's done with all her adventure;\nAnd when she'd come there, and her father found,\nDown on her two knees fell she to the ground,\nWeeping but joyful gave she God her praise\nA hundred thousand times for all His ways.\nIn virtue, and with alms and holy deed,\nThey all live there, nor ever asunder wend;\nTill death does part them, such a life they lead.\nAnd fare now well, my tale is at an end.\nAnd Jesus Christ, Who of His might may send\nJoy after woe, govern us by His grace\nAnd keep us all that now are in this place! Amen.\n\n"},{"index":3,"markdown":"### The Wife of Bath's Prologue\n\nExperience, though no authority\nWere in this world, were good enough for me,\nTo speak of woe that is in all marriage;\nFor, masters, since I was twelve years of age,\nThanks be to God Who is for aye alive,\nOf husbands at church door have I had five;\nFor men so many times have wedded me;\nAnd all were worthy men in their degree.\nBut someone told me not so long ago\nThat since Our Lord, save once, would never go\nTo wedding (that at Cana in Galilee),\nThus, by this same example, showed He me\nI never should have married more than once.\nLo and behold! What sharp words, for the nonce,\nBeside a well Lord Jesus, God and man,\nSpoke in reproving the Samaritan:\n'For thou hast had five husbands,' thus said He,\n'And he whom thou hast now to be with thee\nIs not thine husband.' Thus He said that day,\nBut what He meant thereby I cannot say;\nAnd I would ask now why that same fifth man\nWas not husband to the Samaritan?\nHow many might she have, then, in marriage?\nFor I have never heard, in all my age,\nClear exposition of this number shown,\nThough men may guess and argue up and down.\nBut well I know and say, and do not lie,\nGod bade us to increase and multiply;\nThat worthy text can I well understand.\nAnd well I know He said, too, my husband\nShould father leave, and mother, and cleave to me;\nBut no specific number mentioned He,\nWhether of bigamy or octogamy;\nWhy should men speak of it reproachfully?\nLo, there's the wise old king Dan Solomon;\nI understand he had more wives than one;\nAnd now would God it were permitted me\nTo be refreshed one half as oft as he!\nWhich gift of God he had for all his wives!\nNo man has such that in this world now lives.\nGod knows, this noble king, it strikes my wit,\nThe first night he had many a merry fit\nWith each of them, so much he was alive!\nPraise be to God that I have wedded five!\nWelcome the sixth whenever come he shall.\nForsooth, I'll not keep chaste for good and all;\nWhen my good husband from the world is gone,\nSome Christian man shall marry me anon;\nFor then, the apostle says that I am free\nTo wed, in God's name, where it pleases me.\nHe says that to be wedded is no sin;\nBetter to marry than to burn within.\nWhat care I though folk speak reproachfully\nOf wicked Lamech and his bigamy?\nI know well Abraham was holy man,\nAnd Jacob, too, as far as know I can;\nAnd each of them had spouses more than two;\nAnd many another holy man also.\nOr can you say that you have ever heard\nThat God has ever by His express word\nMarriage forbidden? Pray you, now, tell me.\nOr where commanded He virginity?\nI read as well as you no doubt have read\nThe apostle when he speaks of maidenhead;\nHe said, commandment of the Lord he'd none.\nMen may advise a woman to be one,\nBut such advice is not commandment, no;\nHe left the thing to our own judgment so.\nFor had Lord God commanded maidenhood,\nHe'd have condemned all marriage as not good;\nAnd certainly, if there were no seed sown,\nVirginity- where then should it be grown?\nPaul dared not to forbid us, at the least,\nA thing whereof his Master'd no behest.\nThe dart is set up for virginity;\nCatch it who can; who runs best let us see.\nBut this word is not meant for every wight,\nBut where God wills to give it, of His might.\nI know well that the apostle was a maid;\nNevertheless, and though he wrote and said\nHe would that everyone were such as he,\nAll is not counsel to virginity;\nAnd so to be a wife he gave me leave\nOut of permission; there's no shame should grieve\nIn marrying me, if that my mate should die,\nWithout exception, too, of bigamy.\nAnd though 'twere good no woman flesh to touch,\nHe meant, in his own bed or on his couch;\nFor peril 'tis fire and tow to assemble;\nYou know what this example may resemble.\nThis is the sum: he held virginity\nNearer perfection than marriage for frailty.\nAnd frailty's all, I say, save he and she\nWould lead their lives throughout in chastity.\nI grant this well, I have no great envy\nThough maidenhood's preferred to bigamy;\nLet those who will be clean, body and ghost,\nOf my condition I will make no boast.\nFor well you know, a lord in his household,\nHe has not every vessel all of gold;\nSome are of wood and serve well all their days.\nGod calls folk unto Him in sundry ways,\nAnd each one has from God a proper gift,\nSome this, some that, as pleases Him to shift.\nVirginity is great perfection known,\nAnd continence e'en with devotion shown.\nBut Christ, Who of perfection is the well,\nBade not each separate man he should go sell\nAll that he had and give it to the poor\nAnd follow Him in such wise going before.\nHe spoke to those that would live perfectly;\nAnd, masters, by your leave, such am not I.\nI will devote the flower of all my age\nTo all the acts and harvests of marriage.\nTell me also, to what purpose or end\nThe genitals were made, that I defend,\nAnd for what benefit was man first wrought?\nTrust you right well, they were not made for naught.\nExplain who will and argue up and down\nThat they were made for passing out, as known,\nOf urine, and our two belongings small\nWere just to tell a female from a male,\nAnd for no other cause- ah, say you no?\nExperience knows well it is not so;\nAnd, so the clerics be not with me wroth,\nI say now that they have been made for both,\nThat is to say, for duty and for ease\nIn getting, when we do not God displease.\nWhy should men otherwise in their books set\nThat man shall pay unto his wife his debt?\nNow wherewith should he ever make payment,\nExcept he used his blessed instrument?\nThen on a creature were devised these things\nFor urination and engenderings.\nBut I say not that every one is bound,\nWho's fitted out and furnished as I've found,\nTo go and use it to beget an heir;\nThen men would have for chastity no care.\nChrist was a maid, and yet shaped like a man,\nAnd many a saint, since this old world began,\nYet has lived ever in perfect chastity.\nI bear no malice to virginity;\nLet such be bread of purest white wheat-seed,\nAnd let us wives be called but barley bread;\nAnd yet with barley bread (if Mark you scan)\nJesus Our Lord refreshed full many a man.\nIn such condition as God places us\nI'll persevere, I'm not fastidious.\nIn wifehood I will use my instrument\nAs freely as my Maker has it sent.\nIf I be niggardly, God give me sorrow!\nMy husband he shall have it, eve and morrow,\nWhen he's pleased to come forth and pay his debt.\nI'll not delay, a husband I will get\nWho shall be both my debtor and my thrall\nAnd have his tribulations therewithal\nUpon his flesh, the while I am his wife.\nI have the power during all my life\nOver his own good body, and not he.\nFor thus the apostle told it unto me;\nAnd bade our husbands that they love us well.\nAnd all this pleases me whereof I tell.\nUp rose the pardoner, and that anon.\nNow dame, said he, by God and by Saint John,\nYou are a noble preacher in this case!\nI was about to wed a wife, alas!\nWhy should I buy this on my flesh so dear?\nNo, I would rather wed no wife this year.\nBut wait, said she, my tale is not begun;\nNay, you shall drink from out another tun\nBefore I cease, and savour worse than ale.\nAnd when I shall have told you all my tale\nOf tribulation that is in marriage,\nWhereof I've been an expert all my age,\nThat is to say, myself have been the whip,\nThen may you choose whether you will go sip\nOut of that very tun which I shall broach.\nBeware of it ere you too near approach;\nFor I shall give examples more than ten.\nWhoso will not be warned by other men\nBy him shall other men corrected be,\nThe self-same words has written Ptolemy;\nRead in his Almagest and find it there.\nLady, I pray you, if your will it were,\nSpoke up this pardoner, as you began,\nTell forth your tale, nor spare for any man,\nAnd teach us younger men of your technique.\nGladly, said she, since it may please, not pique.\nBut yet I pray of all this company\nThat if I speak from my own phantasy,\nThey will not take amiss the things I say;\nFor my intention's only but to play.\nNow, sirs, now will I tell you forth my tale.\nAnd as I may drink ever wine and ale,\nI will tell truth of husbands that I've had,\nFor three of them were good and two were bad.\nThe three were good men and were rich and old.\nNot easily could they the promise hold\nWhereby they had been bound to cherish me.\nYou know well what I mean by that, pardie!\nSo help me God, I laugh now when I think\nHow pitifully by night I made them swink;\nAnd by my faith I set by it no store.\nThey'd given me their gold, and treasure more;\nI needed not do longer diligence\nTo win their love, or show them reverence.\nThey all loved me so well, by God above,\nI never did set value on their love!\nA woman wise will strive continually\nTo get herself loved, when she's not, you see.\nBut since I had them wholly in my hand,\nAnd since to me they'd given all their land,\nWhy should I take heed, then, that I should please,\nSave it were for my profit or my ease?\nI set them so to work, that, by my fay,\nFull many a night they sighed out 'Welaway!'\nThe bacon was not brought them home, I trow,\nThat some men have in Essex at Dunmowe.\nI governed them so well, by my own law,\nThat each of them was happy as a daw,\nAnd fain to bring me fine things from the fair.\nAnd they were right glad when I spoke them fair;\nFor God knows that I nagged them mercilessly.\nNow hearken how I bore me properly,\nAll you wise wives that well can understand.\nThus shall you speak and wrongfully demand;\nFor half so brazenfacedly can no man\nSwear to his lying as a woman can.\nI say not this to wives who may be wise,\nExcept when they themselves do misadvise.\nA wise wife, if she knows what's for her good,\nWill swear the crow is mad, and in this mood\nCall up for witness to it her own maid;\nBut hear me now, for this is what I said.\n'Sir Dotard, is it thus you stand today?\nWhy is my neighbour's wife so fine and gay?\nShe's honoured over all where'er she goes;\nI sit at home, I have no decent clo'es.\nWhat do you do there at my neighbour's house?\nIs she so fair? Are you so amorous?\nWhy whisper to our maid? Benedicite!\nSir Lecher old, let your seductions be!\nAnd if I have a gossip or a friend,\nInnocently, you blame me like a fiend\nIf I but walk, for company, to his house!\nYou come home here as drunken as a mouse,\nAnd preach there on your bench, a curse on you!\nYou tell me it's a great misfortune, too,\nTo wed a girl who costs more than she's worth;\nAnd if she's rich and of a higher birth,\nYou say it's torment to abide her folly\nAnd put up with her pride and melancholy.\nAnd if she be right fair, you utter knave,\nYou say that every lecher will her have;\nShe may no while in chastity abide\nThat is assailed by all and on each side.\n'You say, some men desire us for our gold,\nSome for our shape and some for fairness told:\nAnd some, that she can either sing or dance,\nAnd some, for courtesy and dalliance;\nSome for her hands and for her arms so small;\nThus all goes to the devil in your tale.\n\nYou say men cannot keep a castle wall\nThat's long assailed on all sides, and by all.\n'And if that she be foul, you say that she\nHankers for every man that she may see;\nFor like a spaniel will she leap on him\nUntil she finds a man to be victim;\nAnd not a grey goose swims there in the lake\nBut finds a gander willing her to take.\nYou say, it is a hard thing to enfold\nHer whom no man will in his own arms hold.\nThis say you, worthless, when you go to bed;\nAnd that no wise man needs thus to be wed,\nNo, nor a man that hearkens unto Heaven.\nWith furious thunder-claps and fiery levin\nMay your thin, withered, wrinkled neck be broke:\n'You say that dripping eaves, and also smoke,\nAnd wives contentious, will make men to flee\nOut of their houses; ah, benedicite!\nWhat ails such an old fellow so to chide?\n'You say that all we wives our vices hide\nTill we are married, then we show them well;\nThat is a scoundrel's proverb, let me tell!\n'You say that oxen, asses, horses, hounds\nAre tried out variously, and on good grounds;\nBasins and bowls, before men will them buy,\nAnd spoons and stools and all such goods you try.\nAnd so with pots and clothes and all array;\nBut of their wives men get no trial, you say,\nTill they are married, base old dotard you!\nAnd then we show what evil we can do.\n'You say also that it displeases me\nUnless you praise and flatter my beauty,\nAnd save you gaze always upon my face\nAnd call me lovely lady every place;\nAnd save you make a feast upon that day\nWhen I was born, and give me garments gay;\nAnd save due honour to my nurse is paid\nAs well as to my faithful chambermaid,\nAnd to my father's folk and his allies-\nThus you go on, old barrel full of lies!\n'And yet of our apprentice, young Jenkin,\nFor his crisp hair, showing like gold so fine,\nBecause he squires me walking up and down,\nA false suspicion in your mind is sown;\nI'd give him naught, though you were dead tomorrow.\n'But tell me this, why do you hide, with sorrow,\nThe keys to your strong-box away from me?\nIt is my gold as well as yours, pardie.\nWhy would you make an idiot of your dame?\nNow by Saint James, but you shall miss your aim,\nYou shall not be, although like mad you scold,\nMaster of both my body and my gold;\nOne you'll forgo in spite of both your eyes;\nWhy need you seek me out or set on spies?\nI think you'd like to lock me in your chest!\nYou should say: Dear wife, go where you like best,\nAmuse yourself, I will believe no tales;\nYou're my wife Alis true, and truth prevails.\nWe love no man that guards us or gives charge\nOf where we go, for we will be at large.\n'Of all men the most blessed may he be,\nThat wise astrologer, Dan Ptolemy,\nWho says this proverb in his Almagest:\nOf all men he's in wisdom the highest\nThat nothing cares who has the world in hand.\nAnd by this proverb shall you understand:\nSince you've enough, why do you reck or care\nHow merrily all other folks may fare?\nHe is too much a niggard who's so tight\nThat from his lantern he'll give none a light.\nFor he'll have never the less light, by gad;\nSince you've enough, you need not be so sad.\n'You say, also, that if we make us gay\nWith clothing, all in costliest array,\nThat it's a danger to our chastity;\nAnd you must back the saying up, pardie!\nRepeating these words in the apostle's name:\nIn habits meet for chastity, not shame,\nYour women shall be garmented, said he,\nAnd not with broidered hair, or jewellery,\nOr pearls, or gold, or costly gowns and chic;\nAfter your text and after your rubric\nI will not follow more than would a gnat.\nYou said this, too, that I was like a cat;\nFor if one care to singe a cat's furred skin,\nThen would the cat remain the house within;\nAnd if the cat's coat be all sleek and gay,\nShe will not keep in house a half a day,\nBut out she'll go, ere dawn of any day,\nTo show her skin and caterwaul and play.\nThis is to say, if I'm a little gay,\nTo show my rags I'll gad about all day.\n'Sir Ancient Fool, what ails you with your spies?\nThough you pray Argus, with his hundred eyes,\nTo be my body-guard and do his best,\nFaith, he sha'n't hold me, save I am modest;\nI could delude him easily- trust me!\n'You said, also, that there are three things- three-\nThe which things are a trouble on this earth,\nAnd that no man may ever endure the fourth:\nO dear Sir Rogue, may Christ cut short your life!\nYet do you preach and say a hateful wife\nIs to be reckoned one of these mischances.\nAre there no other kinds of resemblances\nThat you may liken thus your parables to,\nBut must a hapless wife be made to do?\n'You liken woman's love to very Hell,\nTo desert land where waters do not well.\nYou liken it, also, unto wildfire;\nThe more it burns, the more it has desire\nTo consume everything that burned may be.\nYou say that just as worms destroy a tree,\nJust so a wife destroys her own husband;\nMen know this who are bound in marriage band.'\nMasters, like this, as you must understand,\nDid I my old men charge and censure, and\nClaim that they said these things in drunkenness;\nAnd all was false, but yet I took witness\nOf Jenkin and of my dear niece also.\nO Lord, the pain I gave them and the woe,\nAll guiltless, too, by God's grief exquisite!\nFor like a stallion could I neigh and bite.\nI could complain, though mine was all the guilt,\nOr else, full many a time, I'd lost the tilt.\nWhoso comes first to mill first gets meal ground;\nI whimpered first and so did them confound.\nThey were right glad to hasten to excuse\nThings they had never done, save in my ruse.\nWith wenches would I charge him, by this hand,\nWhen, for some illness, he could hardly stand.\nYet tickled this the heart of him, for he\nDeemed it was love produced such jealousy.\nI swore that all my walking out at night\nWas but to spy on girls he kept outright;\nAnd under cover of that I had much mirth.\nFor all such wit is given us at birth;\nDeceit, weeping, and spinning, does God give\nTo women, naturally, the while they live.\nAnd thus of one thing I speak boastfully,\nI got the best of each one, finally,\nBy trick, or force, or by some kind of thing,\nAs by continual growls or murmuring;\nEspecially in bed had they mischance,\nThere would I chide and give them no pleasance;\nI would no longer in the bed abide\nIf I but felt his arm across my side,\nTill he had paid his ransom unto me;\nThen would I let him do his nicety.\nAnd therefore to all men this tale I tell,\nLet gain who may, for everything's to sell.\nWith empty hand men may no falcons lure;\nFor profit would I all his lust endure,\nAnd make for him a well-feigned appetite;\nYet I in bacon never had delight;\nAnd that is why I used so much to chide.\nFor if the pope were seated there beside\nI'd not have spared them, no, at their own board.\nFor by my truth, I paid them, word for word.\nSo help me the True God Omnipotent,\nThough I right now should make my testament,\nI owe them not a word that was not quit.\nI brought it so about, and by my wit,\nThat they must give it up, as for the best,\nOr otherwise we'd never have had rest.\nFor though he glared and scowled like lion mad,\nYet failed he of the end he wished he had.\nThen would I say: 'Good dearie, see you keep\nIn mind how meek is Wilkin, our old sheep;\nCome near, my spouse, come let me kiss your cheek!\nYou should be always patient, aye, and meek,\nAnd have a sweetly scrupulous tenderness,\nSince you so preach of old Job's patience, yes.\nSuffer always, since you so well can preach;\nAnd, save you do, be sure that we will teach\nThat it is well to leave a wife in peace.\nOne of us two must bow, to be at ease;\nAnd since a man's more reasonable, they say,\nThan woman is, you must have patience aye.\nSuch were the words I had at my command.\nNow will I tell you of my fourth husband.\nMy fourth husband, he was a reveller,\nThat is to say, he kept a paramour;\nAnd young and full of passion then was I,\nStubborn and strong and jolly as a pie.\nWell could I dance to tune of harp, nor fail\nTo sing as well as any nightingale\nWhen I had drunk a good draught of sweet wine.\nMetellius, the foul churl and the swine,\nDid with a staff deprive his wife of life\nBecause she drank wine; had I been his wife\nHe never should have frightened me from drink;\nFor after wine, of Venus must I think:\nFor just as surely as cold produces hail,\nA liquorish mouth must have a lickerish tail.\nIn women wine's no bar of impotence,\nThis know all lechers by experience.\nBut Lord Christ! When I do remember me\nUpon my youth and on my jollity,\nIt tickles me about my heart's deep root.\nTo this day does my heart sing in salute\nThat I have had my world in my own time.\nBut age, alas! that poisons every prime,\nHas taken away my beauty and my pith;\nLet go, farewell, the devil go therewith!\nThe flour is gone, there is no more to tell,\nThe bran, as best I may, must I now sell;\nBut yet to be right merry I'll try, and\nNow will I tell you of my fourth husband.\nI say that in my heart I'd great despite\nWhen he of any other had delight.\nBut he was quit by God and by Saint Joce!\nI made, of the same wood, a staff most gross;\nNot with my body and in manner foul,\nBut certainly I showed so gay a soul\nThat in his own thick grease I made him fry\nFor anger and for utter jealousy.\nBy God, on earth I was his purgatory,\nFor which I hope his soul lives now in glory.\nFor God knows, many a time he sat and sung\nWhen the shoe bitterly his foot had wrung.\nThere was no one, save God and he, that knew\nHow, in so many ways, I'd twist the screw.\nHe died when I came from Jerusalem,\nAnd lies entombed beneath the great rood-beam,\nAlthough his tomb is not so glorious\nAs was the sepulchre of Darius,\nThe which Apelles wrought full cleverly;\n'Twas waste to bury him expensively.\nLet him fare well. God give his soul good rest,\nHe now is in the grave and in his chest.\nAnd now of my fifth husband will I tell.\nGod grant his soul may never get to Hell!\nAnd yet he was to me most brutal, too;\nMy ribs yet feel as they were black and blue,\nAnd ever shall, until my dying day.\nBut in our bed he was so fresh and gay,\nAnd therewithal he could so well impose,\nWhat time he wanted use of my belle chose,\nThat though he'd beaten me on every bone,\nHe could re-win my love, and that full soon.\nI guess I loved him best of all, for he\nGave of his love most sparingly to me.\nWe women have, if I am not to lie,\nIn this love matter, a quaint fantasy;\nLook out a thing we may not lightly have,\nAnd after that we'll cry all day and crave.\nForbid a thing, and that thing covet we;\nPress hard upon us, then we turn and flee.\nSparingly offer we our goods, when fair;\nGreat crowds at market for dearer ware,\nAnd what's too common brings but little price;\nAll this knows every woman who is wise.\nMy fifth husband, may God his spirit bless!\nWhom I took all for love, and not riches,\nHad been sometime a student at Oxford,\nAnd had left school and had come home to board\nWith my best gossip, dwelling in our town,\nGod save her soul! Her name was Alison.\nShe knew my heart and all my privity\nBetter than did our parish priest, s'help me!\nTo her confided I my secrets all.\nFor had my husband pissed against a wall,\nOr done a thing that might have cost his life,\nTo her and to another worthy wife,\nAnd to my niece whom I loved always well,\nI would have told it- every bit I'd tell,\nAnd did so, many and many a time, God wot,\nWhich made his face full often red and hot\nFor utter shame; he blamed himself that he\nHad told me of so deep a privity.\nSo it befell that on a time, in Lent\n(For oftentimes I to my gossip went,\nSince I loved always to be glad and gay\nAnd to walk out, in March, April, and May,\nFrom house to house, to hear the latest malice),\nJenkin the clerk, and my gossip Dame Alis,\nAnd I myself into the meadows went.\nMy husband was in London all that Lent;\nI had the greater leisure, then, to play,\nAnd to observe, and to be seen, I say,\nBy pleasant folk; what knew I where my face\nWas destined to be loved, or in what place?\nTherefore I made my visits round about\nTo vigils and processions of devout,\nTo preaching too, and shrines of pilgrimage,\nTo miracle plays, and always to each marriage,\nAnd wore my scarlet skirt before all wights.\nThese worms and all these moths and all these mites,\nI say it at my peril, never ate;\nAnd know you why? I wore it early and late.\nNow will I tell you what befell to me.\n\nI say that in the meadows walked we three\nTill, truly, we had come to such dalliance,\nThis clerk and I, that, of my vigilance,\nI spoke to him and told him how that he,\nWere I a widow, might well marry me.\nFor certainly I say it not to brag,\nBut I was never quite without a bag\nFull of the needs of marriage that I seek.\nI hold a mouse's heart not worth a leek\nThat has but one hole into which to run,\nAnd if it fail of that, then all is done.\nI made him think he had enchanted me;\nMy mother taught me all that subtlety.\nAnd then I said I'd dreamed of him all night,\nHe would have slain me as I lay upright,\nAnd all my bed was full of very blood;\nBut yet I hoped that he would do me good,\nFor blood betokens gold, as I was taught.\nAnd all was false, I dreamed of him just- naught,\nSave as I acted on my mother's lore,\nAs well in this thing as in many more.\nBut now, let's see, what was I going to say?\nAha, by God, I know! It goes this way.\nWhen my fourth husband lay upon his bier,\nI wept enough and made but sorry cheer,\nAs wives must always, for it's custom's grace,\nAnd with my kerchief covered up my face;\nBut since I was provided with a mate,\nI really wept but little, I may state.\nTo church my man was borne upon the morrow\nBy neighbours, who for him made signs of sorrow;\nAnd Jenkin, our good clerk, was one of them.\nSo help me God, when rang the requiem\nAfter the bier, I thought he had a pair\nOf legs and feet so clean-cut and so fair\nThat all my heart I gave to him to hold.\nHe was, I think, but twenty winters old,\nAnd I was forty, if I tell the truth;\nBut then I always had a young colt's tooth.\nGap-toothed I was, and that became me well;\nI had the print of holy Venus' seal.\nSo help me God, I was a healthy one,\nAnd fair and rich and young and full of fun;\nAnd truly, as my husbands all told me,\nI had the silkiest quoniam that could be.\nFor truly, I am all Venusian\nIn feeling, and my brain is Martian.\nVenus gave me my lust, my lickerishness,\nAnd Mars gave me my sturdy hardiness.\nTaurus was my ascendant, with Mars therein.\nAlas, alas, that ever love was sin!\nI followed always my own inclination\nBy virtue of my natal constellation;\nWhich wrought me so I never could withdraw\nMy Venus-chamber from a good fellow.\nYet have I Mars's mark upon my face,\nAnd also in another private place.\nFor God so truly my salvation be\nAs I have never loved for policy,\nBut ever followed my own appetite,\nThough he were short or tall, or black or white;\nI took no heed, so that he cared for me,\nHow poor he was, nor even of what degree.\nWhat should I say now, save, at the month's end,\nThis jolly, gentle, Jenkin clerk, my friend,\nHad wedded me full ceremoniously,\nAnd to him gave I all the land in fee\nThat ever had been given me before;\nBut, later I repented me full sore.\nHe never suffered me to have my way.\nBy God, he smote me on the ear, one day,\nBecause I tore out of his book a leaf,\nSo that from this my ear is grown quite deaf.\nStubborn I was as is a lioness,\nAnd with my tongue a very jay, I guess,\nAnd walk I would, as I had done before,\nFrom house to house, though I should not, he swore.\nFor which he oftentimes would sit and preach\nAnd read old Roman tales to me and teach\nHow one Sulpicius Gallus left his wife\nAnd her forsook for term of all his life\nBecause he saw her with bared head, I say,\nLooking out from his door, upon a day.\nAnother Roman told he of by name\nWho, since his wife was at a summer-game\nWithout his knowing, he forsook her eke.\nAnd then would he within his Bible seek\nThat proverb of the old Ecclesiast\nWhere he commands so freely and so fast\nThat man forbid his wife to gad about;\nThen would he thus repeat, with never doubt:\n'Whoso would build his whole house out of sallows,\nAnd spur his blind horse to run over fallows,\nAnd let his wife alone go seeking hallows,\nIs worthy to be hanged upon the gallows.'\nBut all for naught, I didn't care a haw\nFor all his proverbs, nor for his old saw,\nNor yet would I by him corrected be.\nI hate one that my vices tells to me,\nAnd so do more of us- God knows!- than I.\nThis made him mad with me, and furiously,\nThat I'd not yield to him in any case.\nNow will I tell you truth, by Saint Thomas,\nOf why I tore from out his book a leaf,\nFor which he struck me so it made me deaf.\nHe had a book that gladly, night and day,\nFor his amusement he would read alway.\nHe called it 'Theophrastus' and 'Valerius',\nAt which book would he laugh, uproarious.\nAnd, too, there sometime was a clerk at Rome,\nA cardinal, that men called Saint Jerome,\nWho made a book against Jovinian;\nIn which book, too, there was Tertullian,\nChrysippus, Trotula, and Heloise\nWho was abbess near Paris' diocese;\nAnd too, the Proverbs of King Solomon,\nAnd Ovid's Art, and books full many a one.\nAnd all of these were bound in one volume.\nAnd every night and day 'twas his custom,\nWhen he had leisure and took some vacation\nFrom all his other worldly occupation,\nTo read, within this book, of wicked wives.\nHe knew of them more legends and more lives\nThan are of good wives written in the Bible.\nFor trust me, it's impossible, no libel,\nThat any cleric shall speak well of wives,\nUnless it be of saints and holy lives,\nBut naught for other women will they do.\nWho painted first the lion, tell me who?\nBy God, if women had but written stories,\nAs have these clerks within their oratories,\nThey would have written of men more wickedness\nThan all the race of Adam could redress.\nThe children of Mercury and of Venus\nAre in their lives antagonistic thus;\nFor Mercury loves wisdom and science,\nAnd Venus loves but pleasure and expense.\nBecause they different dispositions own,\nEach falls when other's in ascendant shown.\nAnd God knows Mercury is desolate\nIn Pisces, wherein Venus rules in state;\nAnd Venus falls when Mercury is raised;\nTherefore no woman by a clerk is praised.\nA clerk, when he is old and can naught do\nOf Venus' labours worth his worn-out shoe,\nThen sits he down and writes, in his dotage,\nThat women cannot keep vow of marriage!\nBut now to tell you, as I started to,\nWhy I was beaten for a book, pardieu.\nUpon a night Jenkin, who was our sire,\nRead in his book, as he sat by the fire,\nOf Mother Eve who, by her wickedness,\nFirst brought mankind to all his wretchedness,\nFor which Lord Jesus Christ Himself was slain,\nWho, with His heart's blood, saved us thus again.\nLo here, expressly of woman, may you find\nThat woman was the ruin of mankind.\nThen read he out how Samson lost his hairs,\nSleeping, his leman cut them with her shears;\nAnd through this treason lost he either eye.\nThen read he out, if I am not to lie,\nOf Hercules, and Deianira's desire\nThat caused him to go set himself on fire.\nNothing escaped him of the pain and woe\nThat Socrates had with his spouses two;\nHow Xantippe threw piss upon his head;\nThis hapless man sat still, as he were dead;\nHe wiped his head, no more durst he complain\nThan 'Ere the thunder ceases comes the rain.'\nThen of Pasiphae, the queen of Crete,\nFor cursedness he thought the story sweet;\nFie! Say no more- it is an awful thing-\nOf her so horrible lust and love-liking.\nOf Clytemnestra, for her lechery,\nWho caused her husband's death by treachery,\nHe read all this with greatest zest, I vow.\nHe told me, too, just when it was and how\nAmphiaraus at Thebes lost his life;\nMy husband had a legend of his wife\nEriphyle who, for a brooch of gold,\nIn secrecy to hostile Greeks had told\nWhereat her husband had his hiding place,\nFor which he found at Thebes but sorry grace.\nOf Livia and Lucia told he me,\nFor both of them their husbands killed, you see,\nThe one for love, the other killed for hate;\nLivia her husband, on an evening late,\nMade drink some poison, for she was his foe.\nLucia, lecherous, loved her husband so\nThat, to the end he'd always of her think,\nShe gave him such a, philtre, for love-drink,\nThat he was dead or ever it was morrow;\nAnd husbands thus, by same means, came to sorrow.\nThen did he tell how one Latumius\nComplained unto his comrade Arrius\nThat in his garden grew a baleful tree\nWhereon, he said, his wives, and they were three,\nHad hanged themselves for wretchedness and woe.\n'O brother,' Arrius said, 'and did they so?\nGive me a graft of that same blessed tree\nAnd in my garden planted it shall be!'\nOf wives of later date he also read,\nHow some had slain their husbands in their bed\nAnd let their lovers shag them all the night\nWhile corpses lay upon the floor upright.\nAnd some had driven nails into the brain\nWhile husbands slept and in such wise were slain.\nAnd some had given them poison in their drink.\nHe told more evil than the mind can think.\nAnd therewithal he knew of more proverbs\nThan in this world there grows of grass or herbs.\n'Better,' he said, 'your habitation be\nWith lion wild or dragon foul,' said he,\n'Than with a woman who will nag and chide.'\n'Better,' he said, 'on the housetop abide\nThan with a brawling wife down in the house;\nSuch are so wicked and contrarious\nThey hate the thing their husband loves, for aye.'\nHe said, 'a woman throws her shame away\nWhen she throws off her smock,' and further, too:\n'A woman fair, save she be chaste also,\nIs like a ring of gold in a sow's nose.'\nWho would imagine or who would suppose\nWhat grief and pain were in this heart of mine?\nAnd when I saw he'd never cease, in fine,\nHis reading in this cursed book at night,\nThree leaves of it I snatched and tore outright\nOut of his book, as he read on; and eke\nI with my fist so took him on the cheek\nThat in our fire he reeled and fell right down.\nThen he got up as does a wild lion,\nAnd with his fist he struck me on the head,\nAnd on the floor I lay as I were dead.\nAnd when he saw how limp and still I lay,\nHe was afraid and would have run away,\nUntil at last, out of my swoon I made:\n'Oh, have you slain me, you false thief?' I said,\n'And for my land have you thus murdered me?\nKiss me before I die, and let me be.'\nHe came to me and near me he knelt down,\nAnd said: 'O my dear sister Alison,\nSo help me God, I'll never strike you more;\nWhat I have done, you are to blame therefor.\nBut all the same forgiveness now I seek!'\nAnd thereupon I hit him on the cheek,\nAnd said: 'Thief, so much vengeance do I wreak!\nNow will I die; I can no longer speak!'\nBut at the last, and with much care and woe,\nWe made it up between ourselves. And so\nHe put the bridle reins within my hand\nTo have the governing of house and land;\nAnd of his tongue and of his hand, also;\nAnd made him burn his book, right then, oho!\nAnd when I had thus gathered unto me\nMasterfully, the entire sovereignty,\nAnd he had said: 'My own true wedded wife,\nDo as you please the term of all your life,\nGuard your own honour and keep fair my state'-\nAfter that day we never had debate.\nGod help me now, I was to him as kind\nAs any wife from Denmark unto Ind,\nAnd also true, and so was he to me.\nI pray to God, Who sits in majesty,\nTo bless his soul, out of His mercy dear!\nNow will I tell my tale, if you will hear.\nThe friar laughed when he had heard all this.\nNow dame, said he, so have I joy or bliss\nThis is a long preamble to a tale!\nAnd when the summoner heard this friar's hail,\nLo, said the summoner, by God's arms two!\nA friar will always interfere, mark you.\nBehold, good men, a housefly and a friar\nWill fall in every dish and matters higher.\nWhy speak of preambling; you in your gown?\nWhat! Amble, trot, hold peace, or go sit down;\nYou hinder our diversion thus to inquire.\nAye, say you so, sir summoner? said the friar,\nNow by my faith I will, before I go,\nTell of a summoner such a tale, or so,\nThat all the folk shall laugh who're in this place'\nOtherwise, friar, I beshrew your face,\nReplied this summoner, and beshrew me\nIf I do not tell tales here, two or three,\nOf friars ere I come to Sittingbourne,\nThat certainly will give you cause to mourn,\nFor well I know your patience will be gone.\nOur host cried out, Now peace, and that anon!\nAnd said he: Let the woman tell her tale.\nYou act like people who are drunk with ale.\nDo, lady, tell your tale, and that is best.\nAll ready, sir, said she, as you request,\nIf I have license of this worthy friar.\nYes, dame, said he, to hear you's my desire.\n\n\n### The Tale of the Wife of Bath\n\nNow in the olden days of King Arthur,\nOf whom the Britons speak with great honour,\nAll this wide land was land of faery.\nThe elf-queen, with her jolly company,\nDanced oftentimes on many a green mead;\nThis was the old opinion, as I read.\nI speak of many hundred years ago;\nBut now no man can see the elves, you know.\nFor now the so-great charity and prayers\nOf limiters and other holy friars\nThat do infest each land and every stream\nAs thick as motes are in a bright sunbeam,\nBlessing halls, chambers, kitchens, ladies' bowers,\nCities and towns and castles and high towers,\nManors and barns and stables, aye and dairies-\nThis causes it that there are now no fairies.\nFor where was wont to walk full many an elf,\nRight there walks now the limiter himself\nIn noons and afternoons and in mornings,\nSaying his matins and such holy things,\nAs he goes round his district in his gown.\nWomen may now go safely up and down,\nIn every copse or under every tree;\nThere is no other incubus, than he,\nAnd would do them nothing but dishonour.\nAnd so befell it that this King Arthur\nHad at his court a lusty bachelor\nWho, on a day, came riding from river;\nAnd happened that, alone as she was born,\nHe saw a maiden walking through the corn,\nFrom whom, in spite of all she did and said,\nStraightway by force he took her maidenhead;\nFor which violation was there such clamour,\nAnd such appealing unto King Arthur,\nThat soon condemned was this knight to be dead\nBy course of law, and should have lost his head,\nPeradventure, such being the statute then;\nBut that the other ladies and the queen\nSo long prayed of the king to show him grace,\nHe granted life, at last, in the law's place,\nAnd gave him to the queen, as she should will,\nWhether she'd save him, or his blood should spill.\nThe queen she thanked the king with all her might,\nAnd after this, thus spoke she to the knight,\nWhen she'd an opportunity, one day:\nYou stand yet, said she, in such poor a way\nThat for your life you've no security.\nI'll grant you life if you can tell to me\nWhat thing it is that women most desire.\nBe wise, and keep your neck from iron dire!\nAnd if you cannot tell it me anon,\nThen will I give you license to be gone\nA twelvemonth and a day, to search and learn\nSufficient answer in this grave concern.\nAnd your knight's word I'll have, ere forth you pace,\nTo yield your body to me in this place.\nGrieved was this knight, and sorrowfully he sighed;\nBut there! he could not do as pleased his pride.\nAnd at the last he chose that he would wend\nAnd come again upon the twelvemonth's end,\nWith such an answer as God might purvey;\nAnd so he took his leave and went his way.\nHe sought out every house and every place\nWherein he hoped to find that he had grace\nTo learn what women love the most of all;\nBut nowhere ever did it him befall\nTo find, upon the question stated here,\nTwo, persons who agreed with statement clear.\nSome said that women all loved best riches,\nSome said, fair fame, and some said, prettiness;\nSome, rich array, some said 'twas lust abed\nAnd often to be widowed and re-wed.\nSome said that our poor hearts are aye most eased\nWhen we have been most flattered and thus pleased\nAnd he went near the truth, I will not lie;\nA man may win us best with flattery;\nAnd with attentions and with busyness\nWe're often limed, the greater and the less.\nAnd some say, too, that we do love the best\nTo be quite free to do our own behest,\nAnd that no man reprove us for our vice,\nBut saying we are wise, take our advice.\nFor truly there is no one of us all,\nIf anyone shall rub us on a gall,\nThat will not kick because he tells the truth.\nTry, and he'll find, who does so, I say sooth.\nNo matter how much vice we have within,\nWe would be held for wise and clean of sin.\nAnd some folk say that great delight have we\nTo be held constant, also trustworthy,\nAnd on one purpose steadfastly to dwell,\nAnd not betray a thing that men may tell.\nBut that tale is not worth a rake's handle;\nBy God, we women can no thing conceal,\nAs witness Midas. Would you hear the tale?\nOvid, among some other matters small,\nSaid Midas had beneath his long curled hair,\nTwo ass's ears that grew in secret there,\nThe which defect he hid, as best he might,\nFull cunningly from every person's sight,\nAnd, save his wife, no one knew of it, no.\nHe loved her most, and trusted her also;\nAnd he prayed of her that to no creature\nShe'd tell of his disfigurement impure.\nShe swore him: Nay, for all this world to win\nShe would do no such villainy or sin\nAnd cause her husband have so foul a name;\nNor would she tell it for her own deep shame.\nNevertheless, she thought she would have died\nBecause so long the secret must she hide;\nIt seemed to swell so big about her heart\nThat some word from her mouth must surely start;\nAnd since she dared to tell it to no man,\nDown to a marsh, that lay hard by, she ran;\nTill she came there her heart was all afire,\nAnd as a bittern booms in the quagmire,\nShe laid her mouth low to the water down:\nBetray me not, you sounding water blown,\nSaid she, I tell it to none else but you:\nLong ears like asses' has my husband two!\nNow is my heart at ease, since that is out;\nI could no longer keep it, there's no doubt.\nHere may you see, though for a while we bide,\nYet out it must; no secret can we hide.\nThe rest of all this tale, if you would hear,\nRead Ovid: in his book does it appear.\nThis knight my tale is chiefly told about\nWhen what he went for he could not find out,\nThat is, the thing that women love the best,\nMost saddened was the spirit in his breast;\nBut home he goes, he could no more delay.\nThe day was come when home he turned his way;\nAnd on his way it chanced that he should ride\nIn all his care, beneath a forest's side,\nAnd there he saw, a-dancing him before,\nFull four and twenty ladies, maybe more;\nToward which dance eagerly did he turn\nIn hope that there some wisdom he should learn.\nBut truly, ere he came upon them there,\nThe dancers vanished all, he knew not where.\nNo creature saw he that gave sign of life,\nSave, on the greensward sitting, an old wife;\nA fouler person could no man devise.\nBefore the knight this old wife did arise,\nAnd said: Sir knight, hence lies no travelled way.\nTell me what thing you seek, and by your fay.\nPerchance you'll find it may the better be;\nThese ancient folk know many things, said she.\nDear mother, said this knight assuredly,\nI am but dead, save I can tell, truly,\nWhat thing it is that women most desire;\nCould you inform me, I'd pay well your hire.\nPlight me your troth here, hand in hand, said she,\nThat you will do, whatever it may be,\nThe thing I ask if it lie in your might;\nAnd I'll give you your answer ere the night.\nHave here my word, said he. That thing I grant.\nThen, said the crone, of this I make my vaunt,\nYour life is safe; and I will stand thereby,\nUpon my life, the queen will say as I.\nLet's see which is the proudest of them all\nThat wears upon her hair kerchief or caul,\nShall dare say no to that which I shall teach;\nLet us go now and without longer speech.\nThen whispered she a sentence in his ear,\nAnd bade him to be glad and have no fear.\nWhen they were come unto the court, this knight\nSaid he had kept his promise as was right,\nAnd ready was his answer, as he said.\nFull many a noble wife, and many a maid,\nAnd many a widow, since they are so wise,\nThe queen herself sitting as high justice,\nAssembled were, his answer there to hear;\nAnd then the knight was bidden to appear.\nCommand was given for silence in the hall,\nAnd that the knight should tell before them all\nWhat thing all worldly women love the best.\nThis knight did not stand dumb, as does a beast,\nBut to this question presently answered\nWith manly voice, so that the whole court heard:\nMy liege lady, generally, said he,\nWomen desire to have the sovereignty\nAs well upon their husband as their love,\nAnd to have mastery their man above;\nThis thing you most desire, though me you kill\nDo as you please, I am here at your will.\nIn all the court there was no wife or maid\nOr widow that denied the thing he said,\nBut all held, he was worthy to have life.\nAnd with that word up started the old wife\nWhom he had seen a-sitting on the green.\nMercy, cried she, my sovereign lady queen!\nBefore the court's dismissed, give me my right.\n'Twas I who taught the answer to this knight;\nFor which he did plight troth to me, out there,\nThat the first thing I should of him require\nHe would do that, if it lay in his might.\nBefore the court, now, pray I you, sir knight,\nSaid she, that you will take me for your wife;\nFor well you know that I have saved your life.\nIf this be false, say nay, upon your fay!\nThis knight replied: Alas and welaway!\nThat I so promised I will not protest.\nBut for God's love pray make a new request.\nTake all my wealth and let my body go.\nNay then, said she, beshrew us if I do!\nFor though I may be foul and old and poor,\nI will not, for all metal and all ore\nThat from the earth is dug or lies above,\nBe aught except your wife and your true love.\nMy love? cried he, nay, rather my damnation!\nAlas! that any of my race and station\nShould ever so dishonoured foully be!\nBut all for naught; the end was this, that he\nWas so constrained he needs must go and wed,\nAnd take his ancient wife and go to bed.\nNow, peradventure, would some men say here,\nThat, of my negligence, I take no care\nTo tell you of the joy and all the array\nThat at the wedding feast were seen that day.\nMake a brief answer to this thing I shall;\nI say, there was no joy or feast at all;\nThere was but heaviness and grievous sorrow;\nFor privately he wedded on the morrow,\nAnd all day, then, he hid him like an owl;\nSo sad he was, his old wife looked so foul.\nGreat was the woe the knight had in his thought\nWhen he, with her, to marriage bed was brought;\nHe rolled about and turned him to and fro.\nHis old wife lay there, always smiling so,\nAnd said: O my dear husband, ben'cite!\nFares every knight with wife as you with me?\nIs this the custom in King Arthur's house?\nAre knights of his all so fastidious?\nI am your own true love and, more, your wife;\nAnd I am she who saved your very life;\nAnd truly, since I've never done you wrong,\nWhy do you treat me so, this first night long?\nYou act as does a man who's lost his wit;\nWhat is my fault? For God's love tell me it,\nAnd it shall be amended, if I may.\nAmended! cried this knight, Alas, nay, nay!\nIt will not be amended ever, no!\nYou are so loathsome, and so old also,\nAnd therewith of so low a race were born,\nIt's little wonder that I toss and turn.\nWould God my heart would break within my breast!\nIs this, asked she, the cause of your unrest?\nYes, truly, said he, and no wonder 'tis.\nNow, sir, said she, I could amend all this,\nIf I but would, and that within days three,\nIf you would bear yourself well towards me.\nBut since you speak of such gentility\nAs is descended from old wealth, till ye\nClaim that for that you should be gentlemen,\nI hold such arrogance not worth a hen.\nFind him who is most virtuous alway,\nAlone or publicly, and most tries aye\nTo do whatever noble deeds he can,\nAnd take him for the greatest gentleman.\nChrist wills we claim from Him gentility,\nNot from ancestors of landocracy.\nFor though they give us all their heritage,\nFor which we claim to be of high lineage,\nYet can they not bequeath, in anything,\nTo any of us, their virtuous living,\nThat made men say they had gentility,\nAnd bade us follow them in like degree.\nWell does that poet wise of great Florence,\nCalled Dante, speak his mind in this sentence;\nSomewhat like this may it translated be:\n'Rarely unto the branches of the tree\nDoth human worth mount up: and so ordains\nHe Who bestows it; to Him it pertains.'\nFor of our fathers may we nothing claim\nBut temporal things, that man may hurt and maim\nAnd everyone knows this as well as I,\nIf nobleness were implanted naturally\nWithin a certain lineage, down the line,\nIn private and in public, I opine,\nThe ways of gentleness they'd alway show\nAnd never fall to vice and conduct low.\nTake fire and carry it in the darkest house\nBetween here and the Mount of Caucasus,\nAnd let men shut the doors and from them turn;\nYet will the fire as fairly blaze and burn\nAs twenty thousand men did it behold;\nIts nature and its office it will hold,\nOn peril of my life, until it die.\nFrom this you see that true gentility\nIs not allied to wealth a man may own,\nSince folk do not their deeds, as may be shown,\nAs does the fire, according to its kind.\nFor God knows that men may full often find\nA lord's son doing shame and villainy;\nAnd he that prizes his gentility\nIn being born of some old noble house,\nWith ancestors both noble and virtuous,\nBut will himself do naught of noble deeds\nNor follow him to whose name he succeeds,\nHe is not gentle, be he duke or earl;\nFor acting churlish makes a man a churl.\nGentility is not just the renown\nOf ancestors who have some greatness shown,\nIn which you have no portion of your own.\nYour own gentility comes from God alone;\nThence comes our true nobility by grace,\nIt was not willed us with our rank and place\nThink how noble, as says Valerius,\nWas that same Tullius Hostilius,\nWho out of poverty rose to high estate.\nSeneca and Boethius inculcate,\nExpressly (and no doubt it thus proceeds),\nThat he is noble who does noble deeds;\nAnd therefore, husband dear, I thus conclude:\nAlthough my ancestors mayhap were rude,\nYet may the High Lord God, and so hope I,\nGrant me the grace to live right virtuously.\nThen I'll be gentle when I do begin\nTo live in virtue and to do no sin.\nAnd when you me reproach for poverty,\nThe High God, in Whom we believe, say I,\nIn voluntary poverty lived His life.\nAnd surely every man, or maid, or wife\nMay understand that Jesus, Heaven's King,\nWould not have chosen vileness of living.\nGlad poverty's an honest thing, that's plain,\nWhich Seneca and other clerks maintain.\nWhoso will be content with poverty,\nI hold him rich, though not a shirt has he.\nAnd he that covets much is a poor wight,\nFor he would gain what's all beyond his might,\nBut he that has not, nor desires to have,\nIs rich, although you hold him but a knave.\nTrue poverty, it sings right naturally;\nJuvenal gaily says of poverty:\n'The poor man, when he walks along the way,\nBefore the robbers he may sing and play.'\nPoverty's odious good, and, as I guess,\nIt is a stimulant to busyness;\nA great improver, too, of sapience\nIn him that takes it all with due patience.\nPoverty's this, though it seem misery-\nIts quality may none dispute, say I.\nPoverty often, when a man is low,\nMakes him his God and even himself to know.\nAnd poverty's an eye-glass, seems to me,\nThrough which a man his loyal friends may see.\nSince you've received no injury from me,\nThen why reproach me for my poverty.\nNow, sir, with age you have upbraided me;\nAnd truly, sir, though no authority\nWere in a book, you gentles of honour\nSay that men should the aged show favour,\nAnd call him father, of your gentleness;\nAnd authors could I find for this, I guess.\nNow since you say that I am foul and old,\nThen fear you not to be made a cuckold;\nFor dirt and age, as prosperous I may be,\nAre mighty wardens over chastity.\nNevertheless, since I know your delight,\nI'll satisfy your worldly appetite.\nChoose, now, said she, one of these two things, aye,\nTo have me foul and old until I die,\nAnd be to you a true and humble wife,\nAnd never anger you in all my life;\nOr else to have me young and very fair\nAnd take your chance with those who will repair\nUnto your house, and all because of me,\nOr in some other place, as well may be.\nNow choose which you like better and reply.\nThis knight considered, and did sorely sigh,\nBut at the last replied as you shall hear:\nMy lady and my love, and wife so dear,\nI put myself in your wise governing;\nDo you choose which may be the more pleasing,\nAnd bring most honour to you, and me also.\nI care not which it be of these things two;\nFor if you like it, that suffices me.\nThen have I got of you the mastery,\nSince I may choose and govern, in earnest?\nYes, truly, wife, said he, I hold that best.\nKiss me, said she, we'll be no longer wroth,\nFor by my truth, to you I will be both;\nThat is to say, I'll be both good and fair.\nI pray God I go mad, and so declare,\nIf I be not to you as good and true\nAs ever wife was since the world was new.\nAnd, save I be, at dawn, as fairly seen\nAs any lady, empress, or great queen\nThat is between the east and the far west,\nDo with my life and death as you like best.\nThrow back the curtain and see how it is.\nAnd when the knight saw verily all this,\nThat she so very fair was, and young too,\nFor joy he clasped her in his strong arms two,\nHis heart bathed in a bath of utter bliss;\nA thousand times, all in a row, he'd kiss.\nAnd she obeyed his wish in everything\nThat might give pleasure to his love-liking.\nAnd thus they lived unto their lives' fair end,\nIn perfect joy; and Jesus to us send\nMeek husbands, and young ones, and fresh in bed,\nAnd good luck to outlive them that we wed.\nAnd I pray Jesus to cut short the lives\nOf those who'll not be governed by their wives;\nAnd old and querulous niggards with their pence,\nAnd send them soon a mortal pestilence!\n\n"},{"index":4,"markdown":"### The Friar's Prologue\n\nThis worthy limiter, this noble friar,\nHe turned always a lowering face, and dire,\nUpon the summoner, but for courtesy\nNo rude and insolent word as yet spoke he.\nBut at the last he said unto the wife:\nLady, said he, God grant you a good life!\nYou have here touched, as I may prosperous be,\nUpon school matters of great difficulty;\nYou have said many things right well, I say;\nBut, lady, as we ride along our way,\nWe need but talk to carry on our game,\nAnd leave authorities, in good God's name,\nTo preachers and to schools for clergymen.\nBut if it pleases all this company, then,\nI'll tell you of a summoner, to make game.\nBy God, you could surmise it by the name\nThat of a summoner may no good be said;\nI pray that no one will be angry made.\nA summoner is a runner up and down\nWith summonses for fornication known,\nAnd he is beaten well at each town's end.\nOur host then spoke: O sir, you should attend\nTo courtesy, like man of your estate;\nIn company here we will have no debate.\nTell forth your tale and let the summoner be.\nNay, said the summoner, let him say to me\nWhat pleases him; when it falls to my lot,\nBy God I'll then repay him, every jot.\nI'll then make plain to him what great honour\nIt is to be a flattering limiter;\nI'll certainly tell him what his business is.\nOur host replied: Oh peace, no more of this!\nAnd after that he said unto the friar:\nTell now your tale to us, good master dear.\n\n\n### The Friar's Tale\n\nOnce on a time there dwelt in my country\nAn archdeacon, a man of high degree,\nWho boldly executed the Church's frown\nIn punishment of fornication known,\nAnd of witchcraft and of all known bawdry,\nAnd defamation and adultery\nOf church-wardens, and of fake testaments\nAnd contracts, and the lack of sacraments,\nAnd usury and simony also.\nBut unto lechers gave he greatest woe;\nThey should lament if they were apprehended;\nAnd payers of short tithes to shame descended.\nIf anyone informed of such, 'twas plain\nHe'd not escape pecuniary pain.\nFor all short tithes and for small offering\nHe made folk pitifully to howl and sing.\nFor ere the bishop caught them with his crook,\nThey were already in the archdeacon's book.\nThen had he, by his competent jurisdiction,\nPower to punish them by such infliction.\nHe had a summoner ready to his hand,\nA slyer rogue was not in all England;\nFor cunningly he'd espionage to trail\nAnd bring reports of all that might avail.\nHe could protect of lechers one or two\nTo learn of four and twenty more, mark you.\nFor though this man were wild as is a hare,\nTo tell his evil deeds I will not spare;\nFor we are out of his reach of infliction;\nThey have of us no competent jurisdiction,\nNor ever shall for term of all their lives.\nPeter! So are the women of the dives,\nThe summoner said, likewise beyond my cure!\nPeace, with mischance and with misadventure!\nThus spoke our host, and let him tell his tale.\nNow tell it on, despite the summoner's wail,\nNor spare in anything, my master dear.\nThis false thief, then, this summoner (said the friar)\nHad always panders ready to his hand,\nFor any hawk to lure in all England,\nWho told him all the scandal that they knew;\nFor their acquaintances were nothing new.\nThey were all his informers privily;\nAnd he took to himself great gain thereby;\nHis master knew not how his profits ran.\nWithout an order, and an ignorant man,\nYet would he summon, on pain of Christ's curse,\nThose who were glad enough to fill his purse\nAnd feast him greatly at the taverns all.\nAnd just as Judas had his purses small\nAnd was a thief, just such a thief was he.\nHis master got but half of every fee.\nHe was, if I'm to give him proper laud,\nA thief, and more, a summoner, and a bawd.\nHe'd even wenches in his retinue,\nAnd whether 'twere Sir Robert, or Sir Hugh,\nOr Jack, or Ralph, or whosoever 'twere\nThat lay with them, they told it in his ear;\nThus were the wench and he in partnership.\nAnd he would forge a summons from his scrip,\nAnd summon to the chapter-house those two\nAnd fleece the man and let the harlot go.\nThen would he say: My friend, and for your sake,\nHer name from our blacklist will I now take;\nTrouble no more for what this may entail;\nI am your friend in all where 'twill avail.\nHe knew more ways to fleece and blackmail you\nThan could be told in one year or in two.\nFor in this world's no dog trained to the bow\nThat can a hurt deer from a sound one know\nBetter than this man knew a sly lecher,\nOr fornicator, or adulterer.\nAnd since this was the fruit of all his rent,\nTherefore on it he fixed his whole intent.\nAnd so befell that once upon a day\nThis summoner, ever lurking for his prey,\nRode out to summon a widow, an old rip,\nFeigning a cause, for her he planned to strip.\nIt happened that he saw before him ride\nA yeoman gay along a forest's side.\nA bow he bore, and arrows bright and keen;\nHe wore a short coat of the Lincoln green,\nAnd hat upon his head, with fringes black.\nSir, said the summoner, hail and well met, Jack!\nWelcome, said he, and every comrade good!\nWhither do you ride under this greenwood?\nSaid this yeoman, Will you go far today?\nThis summoner replied to him with: Nay,\nHard by this place, said he, 'tis my intent\nTo ride, sir, to collect a bit of rent\nPertaining to my lord's temporality.\nAnd are you then a bailiff? Aye, said he.\nHe dared not, no, for very filth and shame,\nSay that he was a summoner, for the name.\nIn God's name, said this yeoman then, dear brother,\nYou are a bailiff and I am another.\nI am a stranger in these parts, you see;\nOf your acquaintance I'd be glad, said he,\nAnd of your brotherhood, if 'tis welcome.\nI've gold and silver in my chest at home.\nAnd if you chance to come into our shire,\nAll shall be yours, just as you may desire.\nMany thanks, said this summoner, by my faith!\nAnd they struck hands and made their solemn oath\nTo be sworn brothers till their dying day.\nGossiping then they rode upon their way.\nThis summoner, who was as full of words\nAs full of malice are these butcher birds,\nAnd ever enquiring after everything,\nBrother, asked he, where now is your dwelling,\nIf some day I should wish your side to reach?\nThis yeoman answered him in gentle speech,\nBrother, said he, far in the north country,\nWhere, as I hope, some day you'll come to me.\nBefore we part I will direct you so\nYou'll never miss it when that way you go.\nNow, brother, said this summoner, I pray\nYou'll teach me, while we ride along our way,\nSince that you are a bailiff, as am I,\nA trick or two, and tell me faithfully\nHow, in my office, I may most coin win;\nAnd spare not for nice conscience, nor for sin,\nBut as my brother tell your arts to me.\nNow by my truth, dear brother, then said he,\nIf I am to relate a faithful tale,\nMy wages are right scanty, and but small.\nMy lord is harsh to me and niggardly,\nMy job is most laborious, you see;\nAnd therefore by extortion do I live.\nForsooth, I take all that these men will give;\nBy any means, by trick or violence,\nFrom year to year I win me my expense.\nI can no better tell you faithfully.\nNow truly, said this summoner, so do I.\nI never spare to take a thing, God wot,\nUnless it be too heavy or too hot.\nWhat I get for myself, and privately,\nNo kind of conscience for such things have I.\nBut for extortion, I could not well live,\nNor of such japes will I confession give.\nStomach nor any conscience have I, none;\nA curse on father-confessors, every one.\nWell are we met, by God and by Saint James!\nBut, my dear brother, tell your name or names.\nThus said the summoner, and in meanwhile\nThe yeoman just a little began to smile.\nBrother, said he, and will you that I tell?\nI am a fiend, my dwelling is in Hell.\nBut here I ride about in hope of gain\nAnd that some little gift I may obtain.\nMy only income is what so is sent.\nI see you ride with much the same intent\nTo win some wealth, you never care just how;\nEven so do I, for I would ride, right now,\nUnto the world's end, all to get my prey.\nAh, cried he, ben'cite! What do you say?\nI took you for a yeoman certainly.\nYou have a human shape as well as I;\nHave you a figure then determinate\nIn Hell, where you are in your proper state?\nNay, said he, there of figure we have none;\nBut when it pleases us we can take one,\nOr else we make you think we have a shape,\nSometimes like man, or sometimes like an ape;\nOr like an angel can I seem, you know.\nIt is no wondrous thing that this is so;\nA lousy juggler can deceive, you see,\nAnd by gad, I have yet more craft than he.\nWhy, asked the summoner, ride you then, or go,\nIn sundry shapes, and not in one, you know?\nBecause, said he, we will such figures make\nAs render likely that our prey we'll take.\nWhat causes you to have all this labour?\nFull many a cause, my dear sir summoner,\nReplied the fiend, but each thing has its time.\nThe day is short, and it is now past prime,\nAnd yet have I won not a thing this day.\nI will attend to winning, if I may,\nAnd not our different notions to declare.\nFor, brother mine, your wits are all too bare\nTo understand, though I told mine fully.\nBut since you ask me why thus labour we-\nWell, sometimes we are God's own instruments\nAnd means to do His orders and intents,\nWhen so He pleases, upon all His creatures,\nIn divers ways and shapes, and divers features.\nWithout Him we've no power, 'tis certain,\nIf He be pleased to stand against our train.\nAnd sometimes, at our instance, have we leave\nOnly the body, not the soul, to grieve;\nAs witness job, to whom we gave such woe.\nAnd sometimes have we power of both, you know,\nThat is to say, of soul and body too.\nAnd sometimes we're allowed to search and do\nThat to a man which gives his soul unrest,\nAnd not his body, and all is for the best.\nAnd when one does withstand all our temptation,\nIt is the thing that gives his soul salvation;\nAlbeit that it was not our intent\nHe should be saved; we'd have him impotent.\nAnd sometimes we are servants unto man,\nAs to that old archbishop, Saint Dunstan,\nAnd to the apostles servant once was I.\nYet tell me, said the summoner, faithfully,\nMake you yourselves new bodies thus alway\nOf elements? The fiend replied thus: Nay.\nSometimes we feign them, sometimes we arise\nIn bodies that are dead, in sundry wise,\nAnd speak as reasonably and fair and well\nAs to the witch at En-dor Samuel.\nAnd yet some men maintain it was not he;\nI do not care for your theology.\nBut of one thing I warn, nor will I jape,\nYou shall in all ways learn our proper shape;\nYou shall hereafter come, my brother dear,\nWhere you'll not need to ask of me, as here.\nFor you shall, of your own experience,\nIn a red chair have much more evidence\nThan Virgil ever did while yet alive,\nOr ever Dante; now let's swiftly drive.\nFor I will hold with you my company\nTill it shall come to pass you part from me.\nNay, said the other, that shall not betide;\nI am a bailiff, known both far and wide;\nMy promise will I keep in this one case.\nFor though you were the devil Sathanas,\nMy troth will I preserve to my dear brother,\nAs I have sworn, and each of us to other,\nThat we will be true brothers in this case;\nAnd let us both about our business pace.\nTake your own part, of what men will you give,\nAnd I will mine; and thus may we both live.\nAnd if that either of us gets more than other,\nLet him be true and share it with his brother.\nAgreed, then, said the devil, by my fay.\nAnd with that word they rode upon their way.\nAs they drew near the town- it happened so-\nTo which this summoner had planned to go,\nThey saw a cart that loaded was with hay,\nThe which a carter drove along the way.\nDeep was the mire; for which the cart now stood.\nThe carter whipped and cried as madman would,\nHi, Badger, Scot! What care you for the stones?\nThe Fiend, he cried, take body of you and bones,\nAs utterly as ever you were foaled!\nMore trouble you've caused me than can be told!\nDevil take all, the horses, cart, and hay!\nThis summoner thought, Here shall be played a play.\nAnd near the fiend he drew, as naught were there,\nAnd unobserved he whispered in his ear:\nListen, my brother, listen, by your faith;\nHear you not what the carter says in wrath?\nTake all, at once, for he has given you\nBoth hay and cart, and this three horses too.\nNay, said the devil, God knows, never a bit.\nIt is not his intention, trust to it.\nAsk him yourself, if you believe not me,\nOr else withhold a while, and you shall see.\nThis carter stroked his nags upon the croup,\nAnd they began in collars low to stoop.\nHi now! cried he, May Jesus Christ you bless\nAnd all His creatures, greater, aye and less!\nThat was well pulled, old horse, my own grey boy!\nI pray God save you, and good Saint Eloy!\nNow is my cart out of the slough, by gad!\nLo, brother, said the fiend, what said I, lad?\nHere may you see, my very own dear brother,\nThe peasant said one thing, but thought another.\nLet us go forth upon our travellers' way;\nHere win I nothing I can take today.\nWhen they had come a little out of town,\nThis summoner whispered, to his brother drawn,\nBrother, said he, here lives an ancient crone\nWho'd quite as gladly lose her neck as own\nShe must give up a penny, good or bad.\nBut I'll have twelvepence, though it drive her mad\nOr I will summon her to our office;\nAnd yet God knows I know of her no vice.\nBut since you cannot, in this strange country,\nMake your expenses, here take note of me.\nThis summoner knocked on the widow's gate.\nCome out, cried he, you old she-reprobate!\nI think you've got some friar or priest there, eh?\nWho knocks then? said the widow. Ben'cite!\nGod save you, master, what is your sweet will?\nI have, said he, a summons here, a bill;\nOn pain of excommunication be\nTomorrow morn at the archdeacon's knee\nTo answer to the court for certain things.\nNow, lord, said she, Christ Jesus, King of kings,\nSo truly keep me as I cannot; nay,\nI have been sick, and that for many a day.\nI cannot walk so far, said she, nor ride,\nSave I were dead, such aches are in my side.\nWill you not give a writ, sir summoner,\nAnd let my proctor for me there appear\nTo meet this charge, whatever it may be?\nYes, said this summoner, pay anon- let's see-\nTwelvepence to me, and I'll have you acquitted.\nSmall profit there for me, be it admitted;\nMy master gets the profit, and not I.\nCome then, and let me ride on, speedily;\nGive me twelvepence, I may no longer tarry.\nTwelvepence! cried she, Our Lady Holy Mary\nSo truly keep me out of care and sin,\nAnd though thereby I should the wide world win,\nI have not twelvepence in my house all told.\nYou know right well that I am poor and old;\nShow mercy unto me, a poor old wretch!\nNay, then, said he, the foul Fiend may me fetch\nIf I excuse you, though your life be spilt!\nAlas! cried she, God knows I have no guilt!\nPay me, he cried, or by the sweet Saint Anne\nI'll take away with me your brand-new pan\nFor debt that you have owed to me of old,\nWhen you did make your husband a cuckold;\nI paid at home that fine to save citation.\nYou lie, she cried then, by my own salvation!\nNever was I, till now, widow or wife,\nSummoned unto your court in all my life;\nNor ever of my body was I untrue!\nUnto the Devil rough and black of hue\nGive I your body and my pan also!\nAnd when the devil heard her cursing so\nUpon her knees, he said to her just here:\nNow, Mabely, my own old mother dear,\nIs this your will, in earnest, that you say?\nThe Devil, said she, take him alive today,\nAnd pan and all, unless he will repent!\nNay, you old heifer, it's not my intent,\nThe summoner said, for pardon now to sue\nBecause of aught that I have had from you;\nI would I had your smock and all your clo'es.\nNay, brother, said the devil, easy goes;\nYour body and this pan are mine by right.\nAnd you shall come to Hell with me tonight,\nWhere you shall learn more of our privity\nThan any doctor of divinity.\nAnd with that word this foul fiend to him bent;\nBody and soul he with the devil went\nWhere summoners have their rightful heritage.\nAnd God, Who made after His own image\nMankind, now save and guide us, all and some;\nAnd grant that summoners good men become!\nMasters, I could have told you, said this friar,\nWere I not pestered by this summoner dire,\nAfter the texts of Christ and Paul and John,\nAnd of our other doctors, many a one,\nSuch torments that your hearts would shake with dread,\nAlbeit by no tongue can half be said,\nAlthough I might a thousand winters tell,\nOf pains in that same cursed house of Hell.\nBut all to keep us from that horrid place,\nWatch, and pray Jesus for His holy grace,\nAnd so reject the tempter Sathanas.\nHearken this word, be warned by this one case;\nThe lion lies in wait by night and day\nTo slay the innocent, if he but may.\nDispose your hearts in grace, that you withstand\nThe Fiend, who'd make you thrall among his band.\nHe cannot tempt more than beyond your might;\nFor Christ will be your champion and knight.\nAnd pray that all these summoners repent\nOf their misdeeds, before the Fiend torment.\n\n\n### The Summoner's Prologue\n\nHigh in his stirrups, then, the summoner stood;\nAgainst the friar his heart, as madman's would,\nShook like very aspen leaf, for ire.\nMasters, said he, but one thing I desire;\nI beg of you that, of your courtesy,\nSince you have heard this treacherous friar lie,\nYou suffer it that I my tale may tell!\nThis friar he boasts he knows somewhat of Hell,\nAnd God He knows that it is little wonder;\nFriars and fiends are never far asunder.\nFor, by gad, you have oftentimes heard tell\nHow such a friar was snatched down into Hell\nIn spirit, once, and by a vision blown;\nAnd as an angel led him up and down\nTo show the pains and torments that there were,\nIn all the place he saw no friar there.\nOf other folk he saw enough in woe;\nAnd to the angel then he questioned so:\n'Now, sir,' said he, 'have friars such a grace\nThat none of them shall come into this place?'\n'Nay,' said the angel, 'millions here are thrown!'\nAnd unto Sathanas he led him down.\n'And now has Sathanas,' said he, 'a tail\nBroader than of a galleon is the sail.\nHold up thy tail, thou Sathanas!' said he,\n'Show forth thine arse and let the friar see\nWhere is the nest of friars in this place!'\nAnd ere one might go half a furlong's space,\nJust as the bees come swarming from a hive,\nOut of the Devil's arse-hole there did drive\nFull twenty thousand friars in a rout,\nAnd through all Hell they swarmed and ran about.\nAnd came again, as fast as they could run,\nAnd in his arse they crept back, every one.\nHe clapped his tail to and then lay right still.\nThis friar, when he'd looked at length his fill\nUpon the torments of that sorry place,\nHis spirit God restored, of His high grace,\nInto his body, and he did awake;\nNevertheless for terror did he quake\nSo was the Devil's arse-hole in his mind,\nWhich is his future home, and like in kind.\nGod save all but this cursed friar here;\nMy prologue ends thus; to my tale give ear.\n\n\n### The Summoner's Tale\n\nMasters, there is in Yorkshire, as I guess,\nA marshy region that's called Holderness,\nWherein there went a limiter about\nTo preach, and to beg too, beyond a doubt.\nAnd so befell that on a day this friar\nHad preached in church in his own manner dire,\nAnd specially, and above everything,\nIncited he the people, by preaching,\nTo trentals, and to give, for God's own sake,\nThe means wherewith men might new churches make,\nThat there the services of God might flower,\nAnd not to them who waste and wealth devour,\nNor where there's no necessity to give,\nAs to the monks, who easily may live-\nThanks be to God!- and need no wealth to gain.\nTrentals, said he, deliver from their pain\nThe souls of friends who're dead, the old and young,\nYea, even when they have been hastily sung;\nNot that I hold as frivolous and gay,\nA priest who only sings one mass a day.\nAct quickly now, said he, their souls redeem,\nFor hard it is, with spikes and hooks, I deem,\nTo be so torn, aye, or to burn or bake;\nNow speed you all to this, for Christ's own sake!\nAnd when this friar had said all that he meant,\nWith cui cum patre on his way he went.\nWhen folk in church had given at his behest,\nHe went his way, no longer would he rest,\nWith scrip and ferruled staff and skirts tucked high;\nIn every house he went to peer and pry,\nAnd beg for flour and cheese, or else for corn.\nHis fellow had a staff was tipped with horn,\nA set of tablets all of ivory,\nAnd stylus that was polished elegantly,\nAnd wrote the names down always as he stood,\nOf those that gave him anything of good,\nAs if for them he later meant to pray.\nGive us of wheat or malt or rye, he'd say,\nA bushel; or a God's cake; or some cheese;\nWe may not choose, so give us what you please;\nGive us God's halfpenny or a mass-penny,\nOr give us of your brawn, if you have any;\nA small piece of your blanket, my dear dame,\nOur sister dear, lo, here I write your name;\nBacon or beef, or such thing as you find.\nA sturdy menial went these two behind-\nThe servant of their host- and bore a sack,\nAnd what men gave them, laid it on his back.\nAnd when they'd left the house, why, then anon\nHe planed away the names of folk, each one,\nThat he before had written on his tables;\nAnd thus he served them mockeries and fables.\n(Nay, there you lie, you summoner! cried the friar.\nPeace, for Christ's Mother's sake, call no one liar!\nOur host said. Tell your tale, nor spare at all.\nSo thrive I, said this summoner, that I shall.)\nAlong he went from house to house, till he\nCame to a house where he was wont to be\nRefreshed more than in hundred places round.\nAnd sick the goodman of the place he found;\nBedridden on a couch he prostrate lay.\nDeus hic, said he. Thomas, my friend, good day,\nSaid he, this friar, courteously and soft.\nThomas, said he, may God repay you! Oft\nHave I sat on this bench and fared right well.\nHere have I eaten many a merry meal.\nAnd from the bench he drove away the cat,\nAnd laid down there his steel-tipped staff and hat\nAnd his scrip, too, and sat him softly down.\nHis fellow had gone walking into town,\nWith the said menial, to a hostelry\nWherein he thought that very night to lie.\nO my dear master, whispered this sick man,\nHow have you fared since this month March began?\nI've seen you not this fortnight, aye or more.\nGod knows, said he, that I have toiled full sore;\nAnd very specially for your salvation\nHave I said precious prayers, and at each station,\nAnd for our other friends, whom may God bless!\nI have today been to your church, at Mass,\nAnd preached a sermon after my poor wit,\nNot wholly from the text of holy writ,\nFor that is hard and baffling in the main;\nAnd therefore all its meaning I'll explain.\nGlosing's a glorious thing, and that's certain,\nFor letters kill, as scholars say with pain.\nThus have I taught them to be charitable,\nAnd spend their money reasonably, as well.\nAnd there I saw your dame- ah, where is she?\nYonder within the yard I think she'll be,\nSaid this sick man, and she will come anon.\nEh, master! Welcome be you, by Saint John!\nExclaimed the wife. How fare you, heartily?\nThe friar arose, and that full courteously,\nAnd her embraced within his two arms narrow,\nAnd kissed her sweetly, chirping like a sparrow\nWith his two lips. Ah, dame, said he, right well\nAs one that is your servant, let me tell,\nThanks be to God Who gave you soul and life,\nFor saw I not this day so fair a wife\nIn all the congregation, God save me!\nYea, God correct all faults, sir, answered she,\nBut you are always welcome, by my fay!\nMany thanks, dame, this have I found alway.\nBut of your innate goodness, by your leave,\nI'd beg of you, be cross or grieve\nIf I with Thomas speak a little now.\nThese curates are right negligent and slow\nIn searching tenderly into conscience.\nTo preach confession is my diligence,\nAnd I do study Peter's words and Paul's.\nI walk and fish for Christian persons' souls\nTo yield to Jesus Christ His increment;\nTo spread His gospel is my whole intent.\nNow, by your leave, O my dear sir, said she,\nBerate him well, for Holy Trinity.\nHe is as crabbed as an old pismire,\nThough he has everything he can desire.\nThough him I cover at night, and make him warm,\nAnd lay my leg across him, or my arm,\nHe grunts and groans like our old boar in sty\nAnd other sport- just none from him have I.\nI cannot please him, no, in any case.\nO Thomas, je vous dis, Thomas, Thomas!\nThis is the Fiend's work, this must be amended,\nAnger's a thing that makes High God offended,\nAnd thereof will I speak a word or two.\nNow, master, said the wife, before I go,\nWhat will you eat? I will about it scoot.\nNow, dame, said he then, je vous dis, sans doute,\nHad I of a fat capon but the liver,\nAnd of your soft white bread naught but a sliver,\nAnd after that a pig's head well roasted\n(Save that I would no beast for me were dead),\nThen had I with you plain sufficiency.\nI am a man of little gluttony.\nMy spirit has its nourishment in the Bible.\nMy body is so inured and so pliable\nTo watching, that my appetite's destroyed.\nI pray you, lady, be you not annoyed\nThough I so intimately my secret show;\nBy God, I would reveal it to but few.\nNow, sir, said she, but one word ere I go;\nMy child has died within this fortnight- oh,\nSoon after you left town last, it did die.\nHis death saw I by revelation, aye,\nReplied this friar, at home in dormitory\nLess than an hour, I dare say, ere to glory,\nAfter his death, I saw him borne in bliss\nIn vision mine, may God me guide in this!\nSo did our sexton and infirmarian,\nWho have been true friars fifty years, each man;\nAnd may now, God be thanked for mercy shown,\nObserve their jubilee and walk alone.\nAnd I rose up and did my brothers seek,\nWith many a tear down trickling on my cheek,\nAnd without noise or clashing of the bells;\nTe deum was our song and nothing else,\nSave that to Christ I said an orison,\nAnd thanked Him for the vision he had shown\nFor, sir and dame, trust me full well in all,\nOur orisons are more effectual,\nAnd more we see of Christ's own secret things\nThan folk of the laity, though they were kings.\nWe live in poverty and abstinence\nAnd laymen live in riches and expense\nOf meat and drink, and in their gross delight.\nThis world's desires we hold in great despite.\nDives and Lazarus lived differently,\nAnd different recompense they had thereby.\nWhoso would pray, he must fast and be clean,\nFatten his soul and keep his body lean.\nWe fare as says the apostle; clothes and food\nSuffice us, though they be not over-good.\nThe cleanness and the fasting of us friars\nResult in Christ's accepting all our prayers.\nLo, Moses forty days and forty nights\nFasted before the mightiest God of mights\nSpoke with him on the Mountain of Sinai.\nWith empty belly, fasting long, say I,\nReceived he there the law that had been writ\nBy God's hand; and Elias (you know of it)\nOn Mount Horeb, ere he had any speech\nWith the High God, Who is our spirits' leech,\nHe fasted long and deep his contemplation.\nAaron, who ruled the temple of his nation,\nAnd all the other great priests, every one,\nWhen they into the temple would be gone\nTo pray there for the folk and do their rites.\nThey would not drink of that which man excites\nAnd makes him drunk or stirs in any way,\nBut there in abstinence they'd watch and pray\nLest they should die- to what I say take heed!-\nWere they not sober when they prayed, indeed.\nBeware my words. No more! for it suffices.\nOur Lord Christ, as the holy writ apprises,\nGave us example of fasting and of prayers.\nTherefore we mendicants, we simple friars,\nAre sworn to poverty and continence,\nTo charity, meekness, and abstinence,\nTo persecution for our righteousness,\nTo weeping, pity, and to cleanliness.\nAnd therefore may you see that all our prayers-\nI speak of us, we mendicants, we friars-\nAre to the High God far more acceptable\nThan yours, with all the feasts you make at table.\nFrom Paradise, if I am not to lie,\nWas man chased out because of gluttony;\nAnd chaste was man in Paradise, that's plain.\nBut hear now, Thomas, lest I speak in vain.\nI have no text for it, I must admit,\nBut by analogy the words will fit,\nThat specially our sweet Lord Christ Jesus\nSpoke of the begging friars when He said thus:\n'Blest are the poor in spirit.' So said He,\nAnd so through all the gospel may you see\nWhether the Word fit better our profession\nOr theirs, the monks', who swim in rich possession,\nFie on their pomp and on their gluttony!\nAnd for their lewdness do I them defy.\nIt seems to me they're like Jovinian,\nFat as a whale and waddling as a swan;\nAs full of wine as bottle in the spence.\nTheir prayers are always of great reverence,\nWhen they for souls that psalm of David say:\n'Cor meum eructavit- bouf!'- that way!\nWho follow Christ's Word going on before\nBut we who are so humble, chaste, and poor,\nAnd doers of God's Word, not hearers, merely?\nAs falcons rise to heaven, just so clearly\nSpring up into the air the holy prayers\nOf charitable and chaste and toiling friars\nMake their way upward into God's ears two.\nThomas, O Thomas! As I ride or go,\nAnd by that lord whom all we call Saint Yve,\nWere you not brother to us, you'd not thrive!\nIn our chapter we pray both day and night\nTo Christ, that He will send you health and might\nTo move about again, and speedily.\n'God knows, said he, nothing thereof feel I;\nSo help me Christ as I, these last few years,\nHave spent on divers friars, it appears,\nFull many a pound; and I'm no better yet.\nTruly my wealth have I almost upset.\nFarewell my gold! for it has slipped away.\nThe friar replied: Ah, Thomas, so you say!\nBut why need you to different friars reach?\nWhy should he need, who has a perfect leech,\nTo call in other leeches from the town?\nYour trouble from your fickleness has grown.\nThink you that I, or at least our convent,\nCould not suffice to pray? That's what I meant.\nThomas, your feeble joke's not worth a tittle;\nYour illness lasts because you've given too little.\n'Ah, give that convent bushels four of oats!'\n'Ah, give that convent four and twenty groats!'\n'Ah, give that friar a penny and let him go!'\nNay, nay, Thomas, the thing should not be so!\nWhat is a farthing worth, when split twelve ways?\nA thing in its integrity displays\nFar greater strength than does a unit scattered.\nThomas, by me you shall not here be flattered;\nYou would you had our labour all for naught.\nBut the High God, Who all this world has wrought,\nSays that the workman's worthy of his hire.\n\nThomas! Naught of your treasure I desire\nAs for myself, but that all our convent\nTo pray for you is always diligent,\nAnd also to build up Christ's holy kirk.\nThomas! If you will learn the way to work,\nOf building up of churches you may find\n(If it be good) in Thomas' life, of Inde.\nYou lie here, full of anger and of ire,\nWherewith the Devil set your heart afire,\nAnd you chide here this hapless innocent,\nYour wife, who is so meek and so patient.\nAnd therefore, Thomas, trust me if you please,\nScold not your wife, who tries to give you ease;\nAnd bear this word away now, by your faith,\nTouching this thing, lo what the wise man saith:\n'Within thy house do not the lion play,\nOppress thy subjects in no kind of way,\nNor cause thine equals and thy friends to flee.'\nAnd Thomas, yet again I charge you, be\nWary of her that in your bosom sleeps;\nBeware the serpent that so slyly creeps\nUnder the grass and stings so treacherously.\nBeware, my son, and hear this patiently,\nThat twenty thousand men have lost their lives\nFor quarrelling with their sweet ones, and their wives.\nNow, since you have so holy and meek a wife,\nWhy need you, Thomas, so to stir up strife?\nThere is, indeed, no serpent so cruel,\nWhen man treads on his tail, nor half so fell,\nAs woman is when she is filled with ire;\nVengeance is then the whole of her desire.\nAnger's a sin, one of the deadly seven,\nAbominable unto the God of Heaven;\nAnd it is sure destruction unto one.\nThis every vulgar vicar or parson\nCan say, how anger leads to homicide.\nTruth, anger's the executant of pride.\nI could of anger tell you so much sorrow\nMy tale should last until it were tomorrow.\nAnd therefore I pray God both day and night,\nAn ireful man, God send him little might!\nIt is great harm and truly great pity\nTo set an ireful man in high degree.\nFor once there was an ireful potentate,\n(As Seneca says) and while he ruled the state,\nUpon a day out riding went knights two,\nAnd as Dame Fortune willed it, it was so\nThat one of them came home, and one did not.\nAnon that knight before the judge was brought,\nWho said thus: 'Sir, you have your fellow slain,\nFor which I doom you to the death, amain.'\nAnd to another knight commanded he,\n'Go lead him to his death, so I charge ye.'\nIt happened, as they went along their way,\nToward the place where he must die that day,\nThey met the knight that men had thought was dead\nThen thought they, it were best not go ahead,\nAnd so led both unto the judge again.\nThey said: 'O lord, this knight, he has not slain\nHis fellow; for he stands here sound, alive.'\n'You shall die then,' he cried, 'so may I thrive!\nThat is to say, you shall all die, all three!'\nAnd then to the first knight 'twas thus said he:\n'I doomed you, and therefore you must be dead.\nAnd you, also, must needs now lose your head,\nSince you're the causing of your fellow's end.'\nAnd then on the third knight did he descend:\n'You have not done what I ordained should be!'\nAnd thus he did away with all the three.\nIreful Cambyses was a drunkard too,\nAnd much delighted dirty deeds to do.\nAnd so befell, a lord of his household,\nWho loved all moral virtue, we are told,\nSaid on a day, when they were talking, thus:\n'A lord is lost if he be too vicious;\nAnd drunkenness is foul thing to record\nOf any man, and specially of a lord.\nThere is full many an eye and many an ear\nWaiting upon a lord, nor knows he where.\nFor God's dear love, sir, drink more moderately;\nWine causes man to lose, and wretchedly,\nHis mind, and his limbs' usage, every one.'\n'The opposite you'll see,' said he, 'anon;\nAnd you'll prove, by your own experience,\nThat wine does not to men such foul offence.\nThere is no wine can rob me of my might\nOf hand or foot, nor yet of my eyesight!'\nAnd for despite he drank much wine the more,\nA hundred times, than he had drunk before;\nAnd then anon this ireful wicked wretch\nSent one this knight's young son to go and fetch,\nAnd ordered that before him he should stand.\nAnd suddenly he took his bow in hand,\nAnd drew the string thereof up to his ear,\nAnd with an arrow slew the child right there.\n'Now tell me whether I've sure hand, or none!'\nHe said, 'And are my might and mind all gone?\nHas wine deprived me of my good eyesight?'\nHow shall I tell the answer of the knight?\nHis son was slain, there is no more to say.\nBeware, therefore, with lords look how you play.\nBut sing placebo, and 'I shall, if I can,'\nUnless it be unto a helpless man.\nTo a poor man men should his vices tell,\nBut to a lord, no, though he go to Hell.\nLo, ireful Cyrus, that great Persian king,\nDestroyed the river Gyndes at its spring,\nBecause a horse of his was drowned therein\nWhen he went forth old Babylon to win.\nHe caused the river to become so small\nThat women could go wading through it all.\nLo, what said he whose teaching all commend?\n'An angry man take never for a friend,\nNor with a madman walk along the way,\nLest you repent.' There is no more to say.\nNow, Thomas, my dear brother, leave your ire;\nYou shall find me as just as is a squire.\nHold not the Devil's knife against your heart;\nYour anger does too sorely burn and smart;\nBut show me all, now, in confession, son.\nNay, said the sick man, by Saint Simeon!\nI have been shriven today by my curate;\nI have him told the whole truth of my state;\nThere's no more need to speak of it, said he,\nSave as I please, of my humility.\nThen give me of your gold to build our cloister,\nSaid he, for many a mussel and an oyster,\nWhen other men have been well at their ease,\nHave been our food, that building should not cease,\nAnd yet, God knows, is finished nothing more\nThan the foundation, while of all the floor\nThere's not a tile yet laid to call our own;\nBy God, we owe full forty pounds for stone!\nNow help, Thomas, for Him that harried Hell!\nElse must we turn about and our books sell.\nAnd if you laymen lack our high instruction,\nThen will the world go all to its destruction.\nFor whoso shall deny us right to live,\nSo may God save me, Thomas, by your leave,\nHe'll have deprived the whole world of the sun.\nFor who can teach and work as we have done?\nAnd that's not been for little time, said he;\nElias and Elisha used to be\nFriars, you'll find the scriptures do record,\nAnd beggars too, thanks be to the good Lord!\nNow, Thomas, help for holy charity!\nAnd down he went then, kneeling on one knee.\nThis sick man, he went well-nigh mad for ire;\nHe would have had that friar set afire\nFor the hypocrisy that he had shown.\nSuch things as I possess and are my own,\nSaid he, those may I give you and no other.\nYou tell me that I am as your own brother?\nYea, truly, said the friar, trust me well;\nI gave your wife a letter with our seal.\nThat's well, said he, and something will I give\nUnto your holy convent while I live,\nAnd right anon you'll have it in your hand,\nOn this condition only, understand,\nThat you divide it so, my own dear brother,\nThat every friar shall have as much as other.\nThis shall you swear upon the faith you own,\nAnd without fraud or cavil, be it known.\nI swear it, said this friar, on my faith!\nAnd on the sick man's laid his hand therewith.\nLo, hear my oath! In me shall truth not lack.\nNow then, come put your hand right down my back,\nReplied this man, and grope you well behind;\nFor underneath my buttocks shall you find\nA thing that I have hid in privity.\nAh, thought the friar, this shall go with me!\nAnd down he thrust his hand right to the cleft,\nIn hope that he should find there some good gift.\nAnd when the sick man felt the friar here\nGroping about his hole and all his rear,\nInto his hand he let the friar a fart.\nThere is no stallion drawing loaded cart\nThat might have let a fart of such a sound.\nThe friar leaped up as with wild lion's bound:\nAh, treacherous churl, he cried, by God's own bones,\nI'll see that he who scorns me thus atones;\nYou'll suffer for this fart- I'll find a way!\nThe servants, who had heard all this affray,\nCame leaping in and chased the friar out;\nAnd forth he scowling went, with angry shout,\nAnd found his fellow, where he'd left his store.\nHe glared about as he were some wild boar;\nHe ground and gnashed his teeth, so wroth was he.\nHe quickly sought the manor, there to see\nThe lord thereof, whose honour was the best,\nAnd always to the friar he confessed;\nThis worthy man was lord of that village.\nThe friar came, as he were in a rage,\nWhere sat the lord at dinner at his board.\nAnd hardly could the friar speak a word,\nTill at the last he said, God be with ye!\nThis lord looked up and said then, Ben'cite!\nWhat, Friar John! What kind of world is this?\nI see right well that something is amiss.\nYou look as if the wood were full of thieves,\nSit down, and tell me what it is that grieves,\nAnd it shall be amended, if I may.\nI have, said he, insulted been today-\nMay God reward you!- down in your village.\nAnd in this world is not so poor a page\nAs would not feel the insult, if 'twere thrown\nAt him, that I have suffered in your town.\nYet nothing grieves me in this matter more\nThan that this peasant, with his long locks hoar,\nHas thus blasphemed our holy convent too.\nNow, master, said his lordship, I pray you-\nNo master, sir, said he, but servitor,\nThough true, I had in school such honour, sir.\nBut rabbi- God's not pleased that men so call\nUs, in the public square or your wide hall.\nNo matter, said he, tell me all your grief.\nSir, said this friar, an odious mischief\nWas this day done to my order and me,\nAnd so, per consequens, to each degree\nOf Holy Church, may God it soon amend!\nSir, said the lord, the story I attend.\nAs my confessor, pray your wrath control;\nSalt of the earth are you- the savour whole.\nFor love of God, I beg you patience hold;\nTell me your grievance. And anon he told\nAs you have heard before, you know well what.\nThe lady of the house right silent sat\nTill she had heard all that the friar said:\nEh, by God's Mother, cried she, Blessed Maid!\nIs there aught else? A point that we did miss?\nMadam, asked he, what do you think of this?\nWhat do I think? she asked, So God me speed,\nI say, a churl has done a churlish deed.\nWhat should I say? May God desert him! See-\nWhy his sick head is full of vanity.\nThe man, no doubt, is more or less insane.\nMadam, said he, I will not lie or feign:\nIf otherwise I cannot vengeance wreak,\nI will defame him wheresoe'er I speak,\nThis false blasphemer who has dared charge me\nThus to divide what won't divided be,\nTo every man alike, and with mischance!\nThe lord sat still as he were in a trance,\nAnd in his mind he rolled it up and down:\nHow had this churl imagination grown\nTo pose so fine a problem to the friar?\nI never heard the like, or I'm a liar;\nI think the devil stuck it in his mind.\nAnd in arithmetic did no man find,\nBefore this day, such puzzling question shown.\nWho could be able, now, to make it known\nHow every man should have an equal part\nOf both the sound and savour of a fart?\nO scrupulous proud churl, beshrew his face!\nLo, sirs, this lord said then, with hard grimace,\nWho ever heard of such a thing ere now?\nTo every man alike? But tell me how!\nWhy it's impossible, it cannot be!\nExacting churl, God give him never glee!\nThe rumbling of a fart, and every sound,\nIs but the air's reverberation round,\nAnd ever it wastes, by little and little, away.\nThere is no man can judge, aye, by my fay,\nWhether it were divided equally.\nBehold, my church And yet how cursedly\nTo my confessor has he made this crack!\nI hold him surely a demoniac!\nNow eat your meat and let the churl go play,\nLet him go hang himself, the devil's way!\nNow the lord's squire stood ready near the board\nTo carve his meat, and he heard, word for word,\nAll of the things that I to you have said.\nMy lord, said he, be not ill pleased indeed;\nFor I could tell, for cloth to make a gown,\nTo you, sir friar, so you do not frown,\nHow this said fart evenly doled could be\nAmong your fellows, if the thing pleased me.\nTell, said the lord, and you shall have anon\nCloth for a gown, by God and by Saint John!\nMy lord, said he, when next the weather's fair,\nAnd there's no wind to stir the quiet air,\nLet someone bring a cartwheel to this hall,\nBut see there are no missing spokes at all.\nTwelve spokes a cartwheel has, sir, commonly.\nAnd bring me then twelve friars, and know you why?\nBecause a convent's thirteen, as I guess.\nThe present confessor, for his worthiness,\nHe shall complete the tale of this convent.\nThen shall they all kneel down, by one assent,\nAnd at each spoke's end, in this manner, sire,\nLet the nose be laid firmly of a friar.\nYour noble sir confessor, whom God save,\nShall hold his nose upright beneath the nave.\nThen shall this churl, with belly stiff and taut\nAs any tabour- let him here be brought;\nAnd set him on the wheel of this same cart,\nUpon the hub, and make him let a fart.\nAnd you shall see, on peril of my life,\nWith proof so clear that there shall be no strife,\nThat equally the sound of it will wend,\nAnd the stink too, to each spoke's utter end;\nSave that this worthy man, your confessor,\nBecause he is a man of great honour,\nShall have first fruits, as reasonable it is;\nThe noble custom of all friars is this,\nThe worthy men of them shall be first served;\nAnd certainly this has he well deserved.\nHe has today taught us so much of good,\nWith preaching in the pulpit where he stood,\nThat for my part I gladly should agree,\nHe might well have the first smell of farts three,\nAnd so would all his convent, generously,\nHe bears himself so well and holily.\nThe lord, the lady, and each man, save the friar,\nAgreed that Jenkin spoke, as classifier,\nAs well as Euclid or as Ptolemy.\nTouching the churl, they said that subtlety\nAnd great wit taught him how to make his crack.\nHe was no fool, nor a demoniac.\nAnd Jenkin by this means has won a gown.\nMy tale is done, we're almost into town.\n\n\n### The Clerk's Prologue\n\nSir clerk of Oxford, our good host then said,\nYou ride as quiet and still as is a maid\nBut newly wedded, sitting at the board;\nThis day I've heard not from your tongue a word.\nPerhaps you mull a sophism that's prime,\nBut Solomon says, each thing to its own time.\nFor God's sake, smile and be of better cheer,\nIt is no time to think and study here.\nTell us some merry story, if you may;\nFor whatsoever man will join in play,\nHe needs must to the play give his consent.\nBut do not preach, as friars do in Lent,\nTo make us, for our old sins, wail and weep,\nAnd see your tale shall put us not to sleep.\nTell us some merry thing of adventures.\nYour terms, your colours, and your speech-figures,\nKeep them in store till so be you indite\nHigh style, as when men unto kings do write.\nSpeak you so plainly, for this time, I pray,\n'That we can understand what things you say.\nThis worthy clerk, benignly he answered.\nGood host, said he, I am under your yard;\nYou have of us, for now, the governance,\nAnd therefore do I make you obeisance\nAs far as reason asks it, readily.\nI will relate to you a tale that\nLearned once, at Padua, of a worthy clerk,\nAs he proved by his words and by his work.\nHe's dead, now, and nailed down-within his chest,\nAnd I pray God to give his soul good rest!\nFrancis Petrarch, the laureate poet,\nWas this clerk's name, whose rhetoric so sweet\nIllumed all Italy with poetry,\nAs did Lignano with philosophy,\nOr law, or other art particular;\nBut Death, that suffers us not very far,\nNor more, as 'twere, than twinkling of an eye,\nHas slain them both, as all of us shall die.\nBut forth, to tell you of this worthy man,\nWho taught this tale to me, as I began,\nI say that first, with high style he indites,\nBefore the body of his tale he writes,\nA proem to describe those lands renowned,\nSaluzzo, Piedmont, and the region round,\nAnd speaks of Apennines, those hills so high\nThat form the boundary of West Lombardy,\nAnd of Mount Viso, specially, the tall,\nWhereat the Po, out of a fountain small,\nTakes its first springing and its tiny source\nThat eastward ever increases in its course\nToward Emilia, Ferrara, and Venice;\nThe which is a long story to devise.\nAnd truly, in my judgment reluctant\nIt is a thing not wholly relevant,\nSave that he introduces thus his gear:\nBut this is his tale, which you now may hear.\n\n\n### The Clerk's Tale\n\nThere is, in the west side of Italy,\nDown at the foot of Mount Viso the cold,\nA pleasant plain that yields abundantly,\nWhere many a tower and town one may behold,\nThat were there founded in the times of old.\nWith many another fair delightful sight;\nSaluzzo is this noble region bright.\nA marquis once was lord of all that land,\nAs were his noble ancestors before;\nObedient and ready to his hand\nWere all his lieges, both the less and more.\nThus in delight he lived, and had of yore,\nBeloved and feared, through favour of Fortune,\nBoth by his lords and by the common run.\nTherewith he was, to speak of lineage,\nBorn of the noblest blood of Lombardy,\nWith person fair, and strong, and young of age,\nAnd full of honour and of courtesy;\nDiscreet enough to lead his nation, he;\nSave in some things wherein he was to blame,\nAnd Walter was this young lord's Christian name.\nI blame him thus, that he considered naught\nOf what in coming time might him betide,\nBut on his present wish was all his thought,\nAs, he would hunt and hawk on every side;\nWell-nigh all other cares would he let slide,\nAnd would not, and this was the worst of all,\nMarry a wife, for aught that might befall.\nThat point alone his people felt so sore\nThat in a flock one day to him they went,\nAnd one of them, the wisest in all lore,\nOr else because the lord would best consent\nThat he should tell him what the people meant,\nOr else that he could make the matter clear,\nHe to the marquis spoke as you shall hear.\nO noble marquis, your humanity\nAssures us, aye, and gives us hardiness\nAs often as there is necessity\nThat we to you may tell our heaviness.\nAccept, lord, now of your great nobleness\nThat we with sincere hearts may here complain,\nNor let your ears my humble voice disdain.\nThough I have naught to do in this matter\nMore than another man has in this place,\nYet for as much as you, most honoured sir,\nHave always showed me favour and much grace,\nI dare the more to ask of you a space\nOf audience, to set forth our request,\nAnd you, my lord, will do as you like best.\nFor truly, lord, so well do we like you\nAnd all your works (and ever have), that we-\nWe could not, of ourselves, think what to do\nTo make us live in more felicity,\nSave one thing, lord, and if your will it be,\nThat to be wedded man you hold it best,\nThen were your people's hearts at utter rest.\nBut bow your neck beneath that blessed yoke\nOf sovereignty and not of hard service,\nThe which men call espousal or wedlock;\nAnd pray think, lord, among your thoughts so wise,\nHow our days pass and each in different guise;\nFor though we sleep or wake or roam or ride,\nTime flies, and for no man will it abide.\nAnd though your time of green youth flower as yet,\nAge creeps in always, silent as a stone;\nDeath threatens every age, nor will forget\nFor any state, and there escapes him none:\nAnd just as surely as we know, each one,\nThat we shall die, uncertain are we all\nWhat day it is when death shall on us fall.\nAccept then of us, lord, the true intent,\nThat never yet refused you your behest,\nAnd we will, lord, if you will give consent,\nChoose you a wife without delay, at least,\nBorn of the noblest blood and the greatest\nOf all this land, so that it ought to seem\nHonour to God and you, as we shall deem.\nDeliver us from all our constant dread\nAnd take yourself a wife, for High God's sake;\nFor if it so befell, which God forbid,\nThat by your death your noble line should break\nAnd that a strange successor should come take\nYour heritage, woe that we were alive!\nWherefore we pray you speedily to wive.\nTheir humble prayer and their so earnest cheer\nRoused in the marquis' heart great sympathy.\nYou'd have me, he replied, my people dear,\nDo what I've never yet thought necessary.\nI have rejoiced in my fond liberty,\nThat men so seldom find in their marriage;\nWhere I was free, I must be in bondage.\nNevertheless, I see your true intent,\nAnd know there's always sense in what you say;\nWherefore of my free will, will I consent\nTo wed a wife, as soon as ever I may.\nBut whereas you have offered here today\nTo choose a wife for me, I you release\nFrom that, and pray that you thereof will cease.\nFor God knows well that children oft retain\nNaught of their worthy elders gone before;\nGoodness comes all from God, not of the strain\nWhereof they were engendered; furthermore\nI trust in God's great goodness, and therefore\nMy marriage and my state and all my ease\nI leave to Him to do with as He please.\nLet me alone in choosing of my wife,\nThat burden on my own back I'll endure;\nBut I pray you, and charge you on your life,\nThat what wife I may take, me you'll assure\nYou'll honour her life's tenure,\nIn word and deed, both here and everywhere,\nAs if she were an emperor's daughter fair.\nAnd furthermore, this shall you swear, that you\nAgainst my choice shall neither grouse nor strive;\nSince I'm forgoing liberty, and woo\nAt your request, so may I ever thrive\nAs, where my heart is set, there will I wive;\nAnd save you give consent in such manner,\nI pray you speak no more of this matter.\nWith hearty will they swore and gave assent\nTo all this, and no one of them said nay;\nPraying him, of his grace, before they went,\nThat he would set for them a certain day\nFor his espousal, soon as might be; yea,\nFor still the people had a little dread\nLest that the marquis would no woman wed.\nHe granted them the day that pleased him best\nWhereon he would be married, certainly,\nAnd said he did all this at their request;\nAnd they with humble hearts, obediently,\nKneeling upon their knees full reverently,\nAll thanked him there, and thus they made an end\nOf their design and homeward did they wend.\nAnd thereupon he to his officers\nOrdered that for the fete they should provide,\nAnd to his household gentlemen and squires,\nSuch charges gave as pleased him to decide;\nAnd all obeyed him: let him praise or chide,\nAnd each of them did all his diligence\nTo show unto the fete his reverence.\nExplicit prima pars.\nIncipit secunda pars.\nNot far from that same honoured palace where\nThis marquis planned his marriage, at this tide,\nThere stood a hamlet, on a site most fair,\nWherein the poor folk of the countryside\nStabled their cattle and did all abide,\nAnd where their labour gave them sustenance\nAfter the earth had yielded abundance.\nAmongst these humble folk there dwelt a man\nWho was considered poorest of them all;\nBut the High God of Heaven sometimes can\nSend His grace to a little ox's stall;\nJanicula men did this poor man call.\nA daughter had he, fair enough to sight;\nGriselda was this young maid's name, the bright.\nIf one should speak of virtuous beauty,\nThen was she of the fairest under sun;\nSince fostered in dire poverty was she,\nNo lust luxurious in her heart had run;\nMore often from the well than from the tun\nShe drank, and since she would chaste virtue please,\nShe knew work well, but knew not idle ease.\nBut though this maiden tender was of age,\nYet in the breast of her virginity\nThere was enclosed a ripe and grave courage;\nAnd in great reverence and charity\nHer poor old father fed and fostered she;\nA few sheep grazing in a field she kept,\nFor she would not be idle till she slept.\nAnd when she homeward came, why she would bring\nRoots and green herbs, full many times and oft,\nThe which she'd shred and boil for her living,\nAnd made her bed a hard one and not soft;\nHer father kept she in their humble croft\nWith what obedience and diligence\nA child may do for father's reverence.\nUpon Griselda, humble daughter pure,\nThe marquis oft had looked in passing by,\nAs he a-hunting rode at adventure;\nAnd when it chanced that her he did espy,\nNot with the glances of a wanton eye\nHe gazed at her, but all in sober guise,\nAnd pondered on her deeply in this wise:\nCommending to his heart her womanhood,\nAnd virtue passing that of any wight,\nOf so young age in face and habitude.\nFor though the people have no deep insight\nIn virtue, he considered all aright\nHer goodness, and decided that he would\nWed only her, if ever wed he should.\nThe day of wedding came, but no one can\nTell who the woman is that bride shall be;\nAt which strange thing they wondered, many a man,\nAnd they said, marvelling, in privacy:\nWill not our lord yet leave his vanity?\nWill he not wed? Alas, alas, the while!\nWhy will he thus himself and us beguile?\nNevertheless, this marquis has bade make,\nOf jewels set in gold and in rich azure,\nBrooches and rings, all for Griselda's sake,\nAnd for her garments took he then the measure\nBy a young maiden of her form and stature,\nAnd found all other ornaments as well\nThat for such wedding would be meet to tell.\nThe time of mid-morn of that very day\nApproached when this lord's marriage was to be;\nAnd all the palace was bedecked and gay,\nBoth hall and chambers, each in its degree;\nWith kitchens stuffed with food in great plenty,\nThere might one see the last and least dainty\nThat could be found in all of Italy.\nThis regal marquis, splendidly arrayed,\nWith lords and ladies in his company\n(Who to attend the feasting had been prayed)\nAnd of his retinue the bachelory,\nWith many a sound of sundry melody,\nUnto the village whereof I have told,\nIn this array the nearest way did hold.\nGriselda who, God knows, was innocent\nThat for her sake was all this fine array,\nTo fetch some water, to a fountain went,\nYet she returned soon, did this lovely may,\nFor she had heard it said that on this day\nThe marquis was to wed, and if she might,\nShe was full fain to see the glorious sight.\nShe thought: With other maidens I will stand\n(Who are my friends) within our door, and see\nThe marchioness, and therefore I'll turn hand\nTo do at home, as soon as it may be,\nThe household work that's waiting there for me;\nAnd then I'll be at leisure to behold\nHer, if they this way to the castle hold.\nAnd as across her threshold she'd have gone,\nThe marquis came, and for her did he call;\nAnd she set down her water jar anon\nBeside the threshold, in an ox's stall,\nAnd down upon her two knees did she fall\nAnd, kneeling, with grave countenance, was still\nTill she had heard what was his lordship's will.\nThis thoughtful marquis spoke unto this maid\nFull soberly, and said in this manner:\nGriselda, where's your father? so he said.\nAnd she, with reverence and with humble cheer,\nAnswered: My lord, he is but inside here.\nAnd in she went without more tarrying\nAnd to the marquis did her father bring.\nHe by the hand then took this ancient man\nAnd said, when he had led him well aside:\nJanicula, I neither will nor can\nConceal my love, nor my heart's longing hide.\nIf you but acquiesce, whate'er betide,\nYour daughter will I take, before I wend,\nTo be my wife until her life's dear end.\nYou love me, and I know it well today,\nAnd are my faithful liege, and were of yore;\nAnd all that pleases me, I dare well say,\nPleases you too; especially therefore\nAssure me on the point I made before-\nCan we together in this compact draw,\nAnd will you take me as your son-in-law?\nThis sudden word the man astonished so\nThat red he grew, abashed, and all quaking\nHe stood; nor could he answer further, no,\nThan but to say: O Lord, I am willing\nTo do your will; but against your liking\nI'll do no thing; you are my lord so dear\nThat what you wish governs this matter here.\nThen I will, said this marquis, quietly,\nThat in your chamber you and I and she\nHave consultation, and do you know why?\nBecause I'd ask her if her will it be\nTo be my wife and so be ruled by me;\nAnd all this shall be done in your presence,\nI will not speak without your audience.\nAnd while in chamber they three were about\nTheir business, whereof you'll hereafter hear,\nThe people crowded through the house without\nAnd wondered by what honest method there\nSo carefully she'd kept her father dear.\nBut more Griselda wondered, as she might,\nFor never before that saw she such a sight.\nNo wonder, though, astonishment she felt\nAt seeing so great a guest within that place;\nWith people of his sort she'd never dealt,\nWherefore she looked on with a pallid face.\nBut briefly through the matter now to race,\nThese are the very words the marquis said\nTo this most modest, truly constant maid.\nGriselda, said he, You shall understand\nIt's pleasing to your father and to me\nThat I wed you, and even it may stand,\nAs I suppose, that you would have it be.\nBut these demands must I first make, said he,\nAnd since it shall be done in hasty wise,\nWill you consent, or will you more advise?\nI say this: Are you ready with good heart\nTo grant my wish, and that I freely may,\nAs I shall think best, make you laugh or smart,\nAnd you to grumble never, night or day?\nAnd too, when I say 'yea' you say not 'nay'\nBy word or frown to what I have designed.\nSwear this, and here I will our contract bind.\nWondering upon this word, quaking for fear,\nShe said: My lord, unsuited, unworthy\nAm I to take the honour you give me here;\nBut what you'd have, that very thing would I.\nAnd here I swear that never willingly,\nIn deed or thought, will I you disobey,\nTo save my life, and I love life, I say.\nThis is enough, Griselda mine, cried he.\nAnd forth he went then with full sober cheer\nOut at the door, and after him came she,\nAnd to the people who were waiting near,\nThis is my wife, he said, who's standing here.\nHonour her, all, and love her, all, I pray,\nWho love me; and there is no more to say.\n\nAnd so that nothing of her former gear\nShe should take with her to his house, he bade\nThat women strip her naked then and there;\nWhereat these ladies were not over-glad\nTo handle clothes wherein she had been clad.\nNevertheless, this maiden bright of hue\nFrom head to foot they clothed her all anew.\nHer hair they combed and brushed, which fell untressed\nAll artlessly, and placed a coronal\nWith their small fingers on her head, and dressed\nHer robes with many jewels great and small;\nOf her array how shall I tell withal?\nScarcely the people knew her for fairness,\nSo transformed was she in her splendid dress.\nThis marquis her has married with a ring\nBrought for the purpose there; and then has set\nUpon a horse, snow-white and well ambling,\nAnd to his palace, without longer let,\nWith happy following folk and more they met,\nConvoyed her home, and thus the day they spent\nIn revelry until the sun's descent.\nAnd briefly forth throughout this tale to chase,\nI say that unto this new marchioness\nGod has such favour sent her, of His grace,\nIt seemed in no way true, by likeliness,\nThat she was born and bred in humbleness,\nAs in a hovel or an ox's stall,\nBut rather nurtured in an emperor's hall.\nTo everyone she soon became so dear\nAnd worshipful, that folk where she had dwelt\nAnd from her birth had known her, year by year,\nAlthough they could have sworn it, scarcely felt\nThat to Janicula, with whom I've dealt,\nShe really was a daughter, for she seemed\nAnother creature now, or so they deemed.\nFor though she ever had been virtuous,\nShe was augmented by such excellence\nOf manners based on noble goodness thus,\nAnd so discreet and wise of eloquence,\nSo gentle and so worthy reverence,\nAnd she could so the people's hearts embrace,\nThat each her loved that looked upon her face.\nNot only in Saluzzo, in the town,\nWas published wide the goodness of her name,\nBut throughout many a land where she'd renown\nIf one said well, another said the same;\nSo widespread of her goodness was the fame\nThat men and women came; the young and old\nWent to Saluzzo, her but to behold.\nThus Walter lowly, nay, but royally,\nWedded, by Fortune's grace, right honourably,\nIn the good peace of God lived easily\nAt home, and outward grace enough had he;\nAnd since he saw that under low degree\nIs virtue often hid, the people fairly\nHeld him a prudent man, and that's done rarely.\nNot only this Griselda through her wit\nKnew how with wifely arts her home to bless,\nBut also, when there was a need for it,\nThe people's wrongs she knew how to redress.\nThere was no discord, rancour, heaviness\nIn all that land that she could not appease,\nAnd wisely bring them all to rest and ease.\nAlthough her husband from the court were gone,\nIf gentlemen, or less, of her country\nWere angered, she would bring them all at one;\nSo wise and so mature of speech was she,\nAnd judgments gave of so great equity,\nMen felt that God from Heaven her did send\nPeople to save and every wrong to amend.\nNot long Griselda had, it seems, been wed\nBefore a daughter to her lord she bore,\nThough of a son she'd rather have gone to bed.\nGlad were the marquis and the folk therefor;\nFor though a girl-child came thus all before,\nShe might well to a boy-child yet attain,\nSince barren she was not, it now was plain.\nExplicit secunda pars.\nIncipit tercia pars.\nIt happened, as it has sometimes before,\nThat when this child had sucked a month or so,\nThis marquis in his heart such longing bore\nTo test his wife, her patience thus to know,\nHe could not in his heart the chance forgo\nThis marvelous desire his wife to try;\n'Twas needless, God knows, thus to peek and pry\nHe had sufficiently tried her before\nAnd found her ever good; what needed it\nThat he should test her ever more and more?\nThough some men praise it for a subtle wit,\nYet I say that to him 'twas no credit\nTo try his wife when there was never need,\nPutting her heart to anguish and to dread.\nIn doing which the marquis took this turn:\nHe came alone by night to where she lay\nAnd with a troubled look and features stern\nHe said to her: Griselda mine, that day\nWhen I removed you from your poor array\nAnd placed you in a state of nobleness-\nYou have not all forgotten that, I guess.\nI say, Griselda, this your dignity\nWherein I have so placed you, as I trow,\nHas not made you forgetful now to be\nThat I raised you from poor estate and low\nFor any good you might then have or know.\nTake heed of every word that now I say,\nThere's no one else shall hear it, by my fay.\nYou know and well enough how you came here\nInto this house, it is not long ago,\nAnd though to me you are both lief and dear,\nUnto my nobles you are not; and so\nThey say that unto them 'tis shame and woe\nTo be your subjects and compelled to serve\nYou who are village-born and naught deserve.\nAnd specially, since that girl-child you bore,\nThese things they've said- of this there is no doubt;\nBut I desire, as I have done before,\nTo live at peace with all the folk about;\nI cannot in this matter leave them out.\nI must do with your daughter what is best,\nNot as I would, but under men's behest.\nAnd yet, God knows, the act is hard for me;\nAnd only with your knowledge would I bring\nThe deed to pass, but this I would, said he,\nThat you assent with me to this one thing.\nShow now that patience in your life's dealing\nYou told me of and swore to in your village\nThe day that marked the making of our marriage.\nWhen she had heard all this, this she received\nWith never a word or change of countenance;\nFor, as it seemed, she was in no way grieved.\nShe said: Lord, all lies at your own pleasance;\nMy child and I, with hearty obeisance,\nAre all yours, and you may save us or kill\nThat which is yours; do you what thing you will.\nThere is no thing, and so God my soul save,\nThat you may like displeasing unto me;\nI do not wish a single thing to have,\nNor dread a thing to lose, save only ye;\nThis will is in my heart and aye shall be,\nNor length of time nor death may this deface,\nNor turn my passion to another place.\nGlad was this marquis of her answering,\nAnd yet he feigned as if he were not so;\nAll dreary were his face and his bearing\nWhen it came time from chamber he should go.\nSoon after this, a quarter-hour or so,\nHe privily told all of his intent\nUnto a man, whom to his wife he sent.\nA kind of sergeant was this serving man,\nWho had proved often faithful, as he'd found,\nIn matters great, and such men often can\nDo evil faithfully, as can a hound.\nThe lord knew this man loved him and was bound;\nAnd when this sergeant learned his lordship's will\nHe stalked into the chamber, grim and still.\nMadam, said he, you must forgive it me,\nThough I do that to which I am constrained;\nYou are so wise you know well, it may be,\nThat a lord's orders may not well be feigned;\nThey may be much lamented or complained,\nBut men must needs their every wish obey,\nAnd thus will I; there is no more to say.\nThis child I am commanded now to take-\nAnd spoke no more, but seized that innocent\nPitilessly, and did a gesture make\nAs if he would have slain it ere he went,\nGriselda, she must suffer and consent;\nAnd so, meek as a lamb, she sat there, still,\nAnd let this cruel sergeant do his will.\nSuspicious of repute was this same man,\nSuspect his face, suspect his word also,\nSuspect the time when this thing he began,\nAlas! Her daughter that she had loved so,\nShe thought he'd slay it right there, whether or no.\nNevertheless, she neither wept nor sighed,\nDoing the marquis' liking though she died.\nAt last she found her voice and thus began\nAnd meekly to the sergeant then she prayed\nThat, as he was a worthy, gentle man,\nShe might kiss her child once before his blade;\nAnd on her breast this little child she laid,\nWith sad face, and so kissed it and did press\nAnd lulled it and at last began to bless.\nAnd thus she said in her benignant voice:\nFarewell, my child that I no more shall see;\nBut now I've crossed you thus, I will rejoice\nThat of the Father blessed may you be,\nWho died for us upon the bitter tree.\nYour soul, my little child, to Him I give;\nThis night you die for my sake- though I live.\nI think that to a nurse in such a case\nIt had been hard this pitiful thing to see;\nWell might a mother then have cried Alas!\nBut so steadfastly serious was she\nThat she endured all her adversity,\nAnd to the sergeant she but meekly said:\nI give you now again your little maid.\nGo now, said she, and do my lord's behest,\nBut one thing will I pray you, of your grace,\nThat, save my lord forbade you, at the least\nBury this little body in some place\nWhere beasts nor birds will tear its limbs and face.\nBut no word to that purpose would he say,\nBut took the child and went upon his way.\nThis sergeant went unto his lord again\nAnd of Griselda's words and of her cheer\nHe told him point by point, all short and plain,\nAnd so presented him his daughter dear.\nA little pity felt the marquis here;\nNevertheless, he held his purpose still,\nAs great lords do when they will have their will;\nAnd bade the sergeant that he privily\nShould softly swaddle the young child and wrap\nWith all the necessaries, tenderly,\nAnd in a coffer or some garment lap;\nBut upon pain his head should meet mishap\nNo man should know the least of his intent,\nNor whence he came, nor whither that he went;\nBut to Bologna, to his sister dear\nWho then was of Panago the countess,\nHe should take it, and tell of matters here,\nAsking of her she do her busyness\nThis child to foster in all nobleness;\nAnd whose the child was, that he bade her hide\nFrom everyone, for aught that might betide.\nThe sergeant goes and has fulfilled this thing;\nBut to this marquis now return must we;\nFor soon he went to see her, wondering\nIf by his wife's demeanour he might see,\nOr by her conversation learn that she\nWere changed in aught; but her he could not find\nOther than ever serious and kind.\nAs glad, as humble, as busy in service,\nAnd even in love, as she was wont to be,\nWas she to him at all times in each wise;\nAnd of her daughter not a word spoke she.\nNo strange nor odd look of adversity\nWas seen in her, and her dear daughter's name\nShe never named in earnest nor in game.\nExplicit tercia pars.\nSequitur pars quarta.\nIn this way over them there passed four years\nEre she with child was; but as High God would,\nA boy-child then she bore, as it appears,\nBy Walter, fair and pleasing to behold.\nAnd when folk this word to the father told,\nNot only he but all the people raised\nTheir joyous hymns to God and His grace praised.\nWhen he was two years old and from the breast\nWeaned by his nurse, it chanced upon a day\nThis marquis had another wish to test\nAnd try his wife yet further, so they say.\nOh, needless her temptation in this way!\nBut wedded men no measure can observe\nWhen they've a wife who's patient and will serve.\nWife, said this marquis, you have heard before,\nMy people bear our marriage with ill-will;\nParticularly since my son you bore\nNow it is worse than ever, all this ill.\nTheir murmurs all my heart and courage kill,\nFor to my ears come words so aimed to smart\nThat they have well-nigh broken all my heart.\nNow they say this: 'When Walter's dead and gone.\nThen shall Janicula's base blood succeed\nAnd be our lord, for other have we none!'\nSuch words my people say, 'tis true, indeed!\nWell ought I of such murmurs to take heed;\nFor truly do I fear the populace,\nThough they say nothing plainly to my face.\nI would exist in peace, if that I might;\nWherefore I am determined utterly\nThat as his sister served I, and by night,\nJust so will I serve him full secretly;\nAnd thus I warn you, that not suddenly\nOut of yourself for woe you start or stray;\nBe patient in this sorrow, so I pray.\nI have, said she, I said thus, and ever shall:\nI'll have no thing, or not have, that's certain,\nSave as you wish; nothing grieves me at all,\nEven though my daughter and my son are slain\nAt your command, and that, I think, is plain.\nI have had no part in my children twain\nBut sickness first, and after, woe and pain.\nYou are our master; do with your own thing\nJust as you like; no counsel ask of me.\nFor, as I left at home all my clothing\nWhen first I came to you, just so, said she,\nLeft will and all my liberty,\nAnd took your clothing; wherefore do I pray\nYou'll do your pleasure, I'll your wish obey.\nFor certainly, if I had prescience\nYour will to know ere you your wish had told,\nI would perform it without negligence;\nBut now I know the wish that you unfold,\nTo do your pleasure firmly will I hold;\nFor knew I that my death would give you ease,\nRight gladly would I die, lord, you to please.\nFor death can offer no loss that is known\nCompared to your love's loss. And when, I say,\nHe saw his wife's great constancy, then down\nHe cast his eyes, and wondered at the way\nShe would in patience all his will obey;\nAnd forth he went with dreary countenance,\nBut in his heart he knew a great pleasance.\nThis ugly sergeant in the very wise\nThat he her daughter took away, so he\n(Or worse, if worse than this men could devise)\nHas taken her son, the child of such beauty.\nAnd always yet so all-patient was she\nThat she no sign gave forth of heaviness,\nBut kissed her son and so began to bless;\nSave this: She prayed him that, and if he might,\nHer son he'd bury in an earthen grave,\nHis tender limbs, so delicate to sight,\nFrom ravenous birds and from all beasts to save.\nBut she no answer out of him could have.\nHe went his way as if he cared nor thought,\nBut to Bologna tenderly 'twas brought.\nThis marquis wondered ever more and more\nUpon her patience; and indeed if he\nHad not known truly in her years before\nThat she had loved her children perfectly,\nHe would have thought that out of subtlety\nAnd malice, or from some urge more savage\nShe suffered this with calm face and courage.\nBut well he knew that, next himself, 'twas plain\nShe loved her children best in every wise.\nBut now to ask of women I am fain,\nWhether these trials should not the man suffice?\nWhat could an obdurate husband more devise\nTo prove her wifehood and her faithfulness,\nAnd he continuing in his stubbornness?\nBut there are folk to such condition grown\nThat, when they do a certain purpose take,\nThey cannot quit the intent they thus own,\nBut just as they were bound unto a stake\nThey will not from that first hard purpose shake.\nJust so this marquis fully was purposed\nTo test his wife, as he was first disposed.\nHe watched her, if by word or countenance\nShe show a change toward him, or in courage;\nBut never could he find a variance.\nShe was aye one in heart and in visage;\nAnd aye the farther that she went in age,\nThe more true, if such thing were possible,\nShe was in love, and painstaking, as well.\n\nFrom which it seemed that, as between those two,\nThere was but one will, for, to Walter's quest,\nThe same thing was her sole desire also,\nAnd- God be thanked!- all fell out for the best.\nShe showed well that, in all this world's unrest,\nA wife, of her volition, nothing should\nWill to be done, save as her husband would.\nThe scandal of this Walter widely spread,\nThat, of his cruel heart, he'd wickedly\n(Because a humble woman he had wed)\nMurdered his two young children secretly.\nSuch murmurs went among them commonly.\nNo wonder, either, for to people's ear\nThere came no word but they'd been murdered there.\nFor which, whereas the people theretofore\nHad loved him, now the scandal of such shame\nCaused them to hate where they had loved before;\nTo be a murderer brings a hateful name.\nNevertheless, in earnest nor in game\nWould he from this his cruel plan be bent;\nTo test his wife was all his fixed intent.\nNow when his daughter was twelve years of age,\nHe to the court of Rome (in subtle wise\nInformed of his design) sent his message,\nCommanding them such bulls they should devise\nAs for his cruel purpose would suffice,\nHow that the pope, for Walter's people's rest,\nBade him to wed another, and the best.\nI say, he ordered they should counterfeit\nA papal bull and set it forth therein\nThat he had leave his first wife now to quit,\nBy papal dispensation, with no sin,\nTo stop all such dissension as did win\nBetween his folk and him; thus said the bull,\nThe which thing they did publish to the full.\nThe ignorant people, as no wonder is,\nSupposed of course that things were even so;\nBut when Griselda's ears caught word of this,\nI judge that then her heart was filled with woe.\nBut she, for ever steadfast, still did show\nHerself disposed, this humble meek creature,\nThe adversity of Fortune to endure.\nAbiding ever his wish and pleasure still,\nTo whom she had been given, heart and all;\nHe was her worldly hope, for good or ill;\nBut to tell all this briefly, if I shall,\nThis marquis wrote, in letter personal,\nThe devious working of his whole intent\nAnd secretly 'twas to Bologna sent.\nUnto Panago's count, who had, we know,\nWedded his sister, prayed he specially\nTo bring him home again his children two,\nIn honourable estate, all openly.\nBut one more thing he prayed him, utterly,\nThat he to no one, whoso should inquire,\nWould tell who was their mother or their sire,\nBut say: The maiden married was to be\nUnto Saluzzo's marquis, and anon.\nAnd as this count was asked, so then did he;\nFor on day set he on his way was gone\nToward Saluzzo, with lords many a one,\nIn rich array, this maiden there to guide,\nWith her young brother riding at her side.\nSo toward her marriage went this fresh young maid\nClad richly and bedecked with jewels clear;\nHer brother with her, boyishly arrayed,\nAnd all anew, was now in his eighth year.\nAnd thus in great pomp and with merry cheer\nToward Saluzzo went they on their way,\nAnd rode along together day by day.\nExplicit quarta pars.\nSequitur pars quinta.\nMeanwhile, according to his wicked way,\nThis marquis, still to test his wife once more,\nEven to the final proof of her, I say,\nFully to have experience to the core\nIf she were yet as steadfast as before,\nHe on a day in open audience\nLoudly said unto her this rude sentence:\nTruly, Griselda, I'd much joy, perchance,\nWhen you I took for wife, for your goodness\nAnd for your truth and your obedience,\nNot for your lineage nor your wealth, I guess;\nBut now I know, in utter certainness,\nThat in great lordship, if I well advise,\nThere is great servitude in sundry wise.\nI may not act as every plowman may;\nMy people have constrained me that I take\n'Another wife, and this they ask each day;\nAnd now the pope, hot rancour thus to slake,\nConsents, I dare the thing to undertake;\nAnd truly now this much to you I'll say,\nMy new wife journeys hither on her way.\nBe strong of heart and leave at once her place,\nAnd that same dower that you brought to me,\nTake it again, I grant it of my grace;\nReturn you to your father's house, said he;\nNo man may always have prosperity;\nWith a calm heart I urge you to endure\nThe stroke of Fortune or of adventure.\nAnd she replied again, of her patience:\nMy lord, said she, I know, and knew alway,\nHow that between your own magnificence\nAnd my poor state, no person can or may\nMake a comparison in an equal way.\nI never held me worthy or of grade\nTo be your wife, no, nor your chambermaid.\nAnd in this house, where lady you made me\n(The High God do I take now to witness,\nAnd as He truly may my soul's joy be),\nI never held me lady nor mistress,\nBut only servant to your worthiness;\nAnd ever shall, while my life may endure,\nBeyond all worldly beings, that is sure.\nThat you so long, of your benignity,\nHave held me here in honour in this way,\nWhere I was never worthy, once, to be,\nFor that, thank God and you- to God I pray\nHe will reward you. There's no more to say.\nUnto my father gladly will I wend\nAnd dwell with him until my life shall end.\nWhere I was fostered when an infant small,\nThere will I lead my life till I be dead,\nA widow, clean in body, heart, and all.\nFor, since I gave to you my maidenhead,\nAnd am your true and lawful wife, wedded,\nMay God forbid such a lord's wife to take\nAnother man for husband or love's sake.\nAnd of your new wife, may God of His grace\nGrant you but joy and all prosperity:\nFor I will gladly yield to her my place,\nWherein so happy I was wont to be,\nFor since it pleases you, my lord, said she,\nWho have been all my heart's ease and its rest,\nThat I shall go, I'll go when you request.\nBut whereas now you proffer me such dower\nAs first I brought to you, it's in my mind\nThat 'twas my wretched clothes and nothing fair.\nThe which to me were hard now for to find.\nO my good God! How noble and how kind\nYou seemed then, in your speech and in your face.\nThe day we married in that humble place.\nBut truth is said- at least I find it true\nFor actually its proof is seen in me-\nOld love is not the same as when it's new.\nBut truly, lord, for no adversity,\nThough I should die of all this, shall it be\nThat ever in word or deed I shall repent\nThat I gave you my heart in whole intent.\nMy lord, you know that, in my father's place,\nYou stripped from me my poor and humble weed\nAnd clothed me richly, of your noble grace.\nI brought you nothing else at all indeed,\nThan faith and nakedness and maidenhead.\nAnd here again my clothing I restore,\nAnd, too, my wedding-ring, for evermore.\nThe rest of all your jewels, they will be\nWithin your chamber, as I dare maintain;\nNaked out of my father's house, said she,\nI came, and naked I return again.\nTo follow aye your pleasure I am fain,\nBut yet I hope it is not your intent\nThat smockless from your palace I be sent.\nYou could not do so base and shameful thing\nThat the same womb in which your children lay\nShould, before all the folk, in my walking,\nBe seen all bare; and therefore do I pray\nLet me not like a worm go on my way.\nRemember that, my own lord, always dear,\nI was your wife, though I unworthy were.\nWherefore, as guerdon for my maidenhead,\nThe which I brought, but shall not with me bear,\nLet them but give me, for my only meed,\nSuch a poor smock as I was wont to wear,\nThat I therewith may hide the womb of her\nWho was your wife; and here I take my leave\nOf you, my own dear lord, lest you should grieve.\nThe smock, said he, that you have on your back,\nLet it stay there and wear it forth, said he.\nBut firmness in so saying the man did lack;\nBut went his way for ruth and for pity.\nBefore the folk her body then stripped she\nAnd in her smock, with head and feet all bare,\nToward her father's hovel did she fare.\nThe folk they followed, weeping and with cries,\nAnd Fortune did they curse as they passed on;\nBut she with weeping did not wet her eyes,\nAnd all this while of words she said not one.\nHer father, who had heard this news anon,\nCursed then the day and hour when from the earth,\nA living creature, nature gave him birth.\nFor, beyond any doubt, this poor old man\nHad always feared the marquis soon would tire,\nAnd doubted since the marriage first began,\nIf when the lord had satisfied desire,\nHe would not think a wife of station higher,\nFor one of his degree, had been more right,\nAnd send her thence as soon as ever he might.\nTo meet his daughter hastily went he,\nFor he, by noise of folk, knew her coming;\nAnd with her old coat, such as it might be,\nHe covered her, full sorrowfully weeping;\nBut the coat over her he could not bring,\nFor poor the cloth, and many days had passed\nSince on her marriage day she wore it last.\nThus with her father, for a certain space,\nDid dwell this flower of wifely meek patience,\nWho neither by her words nor in her face,\nBefore the people nor in their absence,\nShowed that she thought to her was done offense;\nNor of her high estate a remembrance\nHad she, to judge by her calm countenance.\nNo wonder, though, for while in high estate,\nHer soul kept ever full humility;\nNo mouth complaining, no heart delicate,\nNo pomp, no look of haughty royalty,\nBut full of patience and benignity,\nDiscreet and prideless, always honourable,\nAnd to her husband meek and firm as well.\nMen speak of Job and of his humbleness,\nAs clerks, when they so please, right well can write\nConcerning men, but truth is, nevertheless,\nThough clerks' praise of all women is but slight,\nNo man acquits himself in meekness quite\nAs women can, nor can be half so true\nAs women are, save this be something new.\nExplicit quinta pars. / Sequitur pars sexta.\nNow from Bologna is Panago come,\nWhereof the word spread unto great and less,\nAnd in the ears of people, all and some,\nIt was told, too, that a new marchioness\nCame with him, in such pomp and such richness\nThat never had been seen with human eye\nSo noble array in all West Lombardy.\nThe marquis, who had planned and knew all this,\nBefore this count was come, a message sent\nTo poor Griselda, who had lost her bliss;\nWith humble heart and features glad she went\nAnd on her knees before her lord she bent.\nNo pride of thought did her devotion dim;\nShe wisely and with reverence greeted him.\nHe said, Griselda, hear what I shall say:\nThis maiden, who'll be wedded unto me,\nShall be received with splendour of array\nAs royally as in my house may be,\nAnd, too, that everyone in his degree\nHave his due rank in seating and service,\nAnd high pleasance, as I can best devise.\nI have not serving women adequate\nTo set the rooms in order as I would.\nAnd so I wish you here to regulate\nAll matters of the sort as mistress should.\nYou know of old the ways I think are good,\nAnd though you're clothed in such a slattern's way,\nGo do at least your duty as you may.\nNot only am I glad, my lord, said she,\nTo do your wish, but I desire also\nTo serve you and to please in my degree;\nThis without wearying I'll always do.\nAnd ever, lord, in happiness or woe,\nThe soul within my heart shall not forgo\nTo love you best with true intent, I know.\n\nThen she began to put the house aright,\nTo set the tables and the beds to make;\nAnd was at pains to do all that she might,\nPraying the chambermaids, for good God's sake,\nTo make all haste and sweep hard and to shake;\nAnd she, who was most serviceable of all,\nDid every room array, and his wide hall.\nAbout mid-morning did this count alight,\nWho brought with him these noble children twain,\nWhereat the people ran to see the sight\nOf their array, so rich was all the train;\nAnd for the first time did they not complain,\nBut said that Walter was no fool, at least,\nTo change his wife, for it was for the best.\nFor she was fairer far, so thought they all,\nThan was Griselda, and of younger age,\nAnd fairer fruit betwixt the two should fall,\nAnd pleasing more, for her high lineage;\nHer brother, too, so fair was of visage,\nThat, seeing them, the people all were glad,\nCommending now the sense the marquis had.\nO storm-torn people! Unstable and untrue!\nAye indiscreet, and changing as a vane,\nDelighting ever in rumour that is new,\nFor like the moon aye do you wax and wane;\nFull of all chatter, dear at even a jane;\nYour judgment's false, your constancy deceives,\nA full great fool is he that you believes!\nThus said the sober folk of that city,\nSeeing the people staring up and down,\nFor they were glad, just for the novelty,\nTo have a young new lady of their town.\nNo more of this I'll mention or make known;\nBut to Griselda I'll myself address\nTo tell her constancy and busyness.\nFull busy Griselda was in everything\nThat to the marquis' feast was pertinent;\nNothing was she confused by her clothing,\nThough rude it was and somewhat badly rent\nBut with a glad face to the gate she went,\nWith other folk, to greet the marchioness,\nAnd afterward she did her busyness.\nWith so glad face his guests she did receive,\nAnd with such tact, each one in his degree,\nThat no fault in it could a man perceive;\nBut all they wondered much who she might be\nThat in so poor array, as they could see,\nYet knew so much of rank and reverence;\nAnd worthily they praised her high prudence.\nIn all this while she never once did cease\nThe maiden and her brother to commend\nWith kindness of a heart that was at peace,\nSo well that no man could her praise amend.\nBut at the last, when all these lords did wend\nTo seat themselves to dine, then did he call\nGriselda, who was busy in his hall.\nGriselda, said he, as it were in play,\nHow like you my new wife and her beauty?\nRight well, said she, my lord, for by my fay\nA fairer saw I never than is she.\nI pray that God give her prosperity;\nAnd so I hope that to you both He'll send\nGreat happiness until your lives shall end.\nOne thing I beg, my lord, and warn also,\nThat you prick not, with any tormenting,\nThis tender maid, as you've hurt others so;\nFor she's been nurtured in her up-bringing\nMore tenderly, and, to my own thinking,\nShe could not such adversity endure\nAs could one reared in circumstances poor.\nAnd when this Walter thought of her patience,\nHer glad face, with no malice there at all,\nAnd how so oft he'd done to her offence,\nAnd she aye firm and constant as a wall,\nRemaining ever blameless through it all,\nThis cruel marquis did his heart address\nTo pity for her wifely steadfastness.\nThis is enough, Griselda mine! cried he,\nBe now no more ill pleased nor more afraid;\nI have your faith and your benignity,\nAs straitly as ever woman's was, assayed\nIn high place and in poverty arrayed.\nNow know I well, dear wife, your steadfastness.\nAnd he began to kiss her and to press.\nAnd she, for wonder, took of this no keep;\nShe heard not what the thing was he had cried;\nShe fared as if she'd started out of sleep,\nTill from bewilderment she roused her pride.\nGriselda, said he, by our God Who died,\nYou are my wife, no other one I have,\nNor ever had, as God my soul may save!\nThis is your daughter, whom you have supposed\nShould be my wife; the other child truly\nShall be my heir, as I have aye purposed;\nYou bore him in your body faithfully.\nI've kept them at Bologna secretly;\nTake them again, for now you cannot say\nThat you have lost your children twain for aye.\nAnd folk that otherwise have said of me,\nI warn them well that I have done this deed\nNeither for malice nor for cruelty,\nBut to make trial in you of virtue hid,\nAnd not to slay my children, God forbid!\nBut just to keep them privily and still\nTill I your purpose knew and all your will.\nWhen she heard this, she swooned and down did fall\nFor pitiful joy, and after her swooning\nBoth her young children to her did she call,\nAnd in her arms, full piteously weeping,\nEmbraced them, and ail tenderly kissing,\nAs any mother would, with many a tear\nShe bathed their faces and their sunny hair.\nOh, what a pitiful thing it was to see\nHer swooning, and her humble voice to hear!\nThanks, lord, that I may thank you now, said she,\nThat you have saved to me my children dear!\nNow I am ready for death right here;\nSince I stand in your love and in your grace,\nDeath matters not, nor what my soul may face!\nO young, O dear, O tender children mine,\nYour woeful mother thought for long, truly,\nThat cruel hounds, or birds, or foul vermin\nHad eaten you; but God, of His mercy,\nAnd your good father, all so tenderly,\nHave kept you safely. And in swoon profound\nSuddenly there she fell upon the ground.\nAnd in her swoon so forcefully held she\nHer children two, whom she'd had in embrace,\nThat it was hard from her to set them free,\nHer arms about them gently to unlace.\nOh, many a tear on many a pitying face\nRan down, of those were standing there beside;\nScarcely, for sympathy, could they abide.\nBut Walter cheered her till her sorrow fled;\nAnd she rose up, abashed, out of her trance;\nAll praised her now, and joyous words they said,\nTill she regained her wonted countenance.\nWalter so honoured her by word and glance\nThat it was pleasing to observe the cheer\nBetween them, now again together here.\nThese ladies, when they found a tactful way,\nWithdrew her and to her own room were gone,\nAnd stripped her out of her so rude array,\nAnd in a cloth of gold that brightly shone,\nCrowned with a crown of many a precious stone\nUpon her head, once more to hall they brought\nHer, where they honoured her as all they ought.\nThus had this heavy day a happy end,\nFor everyone did everything he might\nThe day in mirth and revelry to spend\nTill in the heavens shone the stars' fair light.\nFor far more grand in every person's sight\nThis feast was, and of greater cost, 'twas said,\nThan were the revels when they two were wed.\nFull many a year in high prosperity\nThey lived, these two, in harmony and rest,\nAnd splendidly his daughter married he\nUnto a lord, one of the worthiest\nIn Italy; and then in peace, as best\nHis wife's old father at his court he kept\nUntil the soul out of his body crept.\nHis son succeeded to his heritage\nIn rest and peace, after the marquis' day,\nAnd wedded happily at proper age,\nAlbeit he tried his wife not, so they say.\nThis world is not so harsh, deny who may,\nAs in old times that now are long since gone,\nAnd hearken what this author says thereon.\nThis story's told here, not that all wives should\nFollow Griselda in humility,\nFor this would be unbearable, though they would,\nBut just that everyone, in his degree,\nShould be as constant in adversity\nAs was Griselda; for that Petrarch wrote\nThis tale, and in a high style, as you'll note.\nFor since a woman once was so patient\nBefore a mortal man, well more we ought\nReceive in good part that which God has sent;\nFor cause he has to prove what He has wrought.\nBut He tempts no man that His blood has bought,\nAs James says, if you his epistle read;\nYet does He prove folk at all times, indeed,\nAnd suffers us, for our good exercise,\nWith the sharp scourges of adversity\nTo be well beaten oft, in sundry wise;\nNot just to learn our will; for truly He,\nEre we were born, did all our frailty see;\nBut for our good is all that He doth give.\nSo then in virtuous patience let us live.\nBut one word, masters, hearken ere I go:\nOne hardly can discover nowadays,\nIn all a town, Griseldas three or two;\nFor, if they should be put to such assays,\nTheir gold's so badly alloyed, in such ways,\nWith brass, that though the coin delight the eye,\n'Twill rather break in two than bend, say I.\nBut now, for love of the good wife of Bath,\nWhose life and all whose sex may God maintain\nIn mastery high, or else it were but scathe,\nI will with joyous spirit fresh and green\nSing you a song to gladden you, I ween;\nFrom all such serious matters let's be gone;\nHearken my song, which runs in this way on:"},{"index":5,"markdown":"\n**ENVOY OF CHAUCER**\n\nGriselda's dead, and dead is her patience,\nIn Italy both lie buried, says the tale;\nFor which I cry in open audience,\nThat no man be so hardy as to assail\nHis own wife's patience, in a hope to find\nGriselda, for 'tis certain he shall fail!\nO noble wives, full of a high prudence,\nLet not humility your free tongue nail,\nNor let some clerk have cause for diligence\nTo write of you, so marvelous detail\nAs of Griselda, patient and so kind;\nLest Chichevache swallow you in her entrail!\nNay, follow Echo, that holds no silence,\nBut answers always like a countervail;\nBe not befooled, for all your innocence,\nBut take the upper hand and you'll prevail.\nAnd well impress this lesson on your mind,\nFor common profit, since it may avail.\nStrong-minded women, stand at your defence,\nSince you are strong as camel and don't ail,\nSuffer no man to do to you offence;\nAnd slender women in a contest frail,\nBe savage as a tiger there in Ind;\nClatter like mill, say I, to beat the male.\nNay, fear them not, nor do them reverence;\nFor though your husband be all armed in mail,\nThe arrows of your shrewish eloquence\nShall pierce his breast and pierce his aventail.\nIn jealousy I counsel that you bind,\nAnd you shall make him cower as does a quail.\nIf you are fair to see, in folks' presence,\nShow them your face and with your clothes regale;\nIf you are foul, be lavish of expense,\nTo gain friends never cease to do travail;\nBe lightsome as a linden leaf in wind,\nAnd let him worry, weep and wring and wail!\n\n\n### The Merchant's Prologue\n\nOf weeping and wailing, care and other sorrow\nI know enough, at eventide and morrow,\nThe merchant said, and so do many more\nOf married folk, I think, who this deplore,\nFor well I know that it is so with me.\nI have a wife, the worst one that can be;\nFor though the foul Fiend to her wedded were,\nShe'd overmatch him, this I dare to swear.\nHow could I tell you anything special\nOf her great malice? She is shrew in all.\nThere is a long and a large difference\nBetween Griselda's good and great patience\nAnd my wife's more than common cruelty.\nWere I unbound, as may I prosperous be!\nI'd never another time fall in the snare.\nWe wedded men in sorrow live, and care;\nTry it who will, and he shall truly find\nI tell the truth, by Saint Thomas of Ind,\nAs for the greater part, I say not all.\nNay, God forbid that it should so befall!\nAh, good sir host! I have been married, lad,\nThese past two months, and no day more, by gad;\nAnd yet I think that he whose days alive\nHave been all wifeless, although men should rive\nHim to the heart, he could in no wise clear\nTell you so much of sorrow as I here\nCould tell you of my spouse's cursedness.\nNow, said our host, merchant, so God you bless,\nSince you're so very learned in that art,\nFull heartily, I pray you, tell us part.\nGladly, said he, but of my own fresh sore,\nFor grief of heart I may not tell you more.\n\n\n### The Merchant's Tale\n\nOnce on a time there dwelt in Lombardy\nOne born in Pavia, a knight worthy,\nAnd there he lived in great prosperity;\nAnd sixty years a wifeless man was he,\nAnd followed ever his bodily delight\nIn women, whereof was his appetite,\nAs these fool laymen will, so it appears.\nAnd when he had so passed his sixty years,\nWere it for piety or for dotage\nI cannot say, but such a rapturous rage\nHad this knight to become a wedded man\nThat day and night he did his best to scan\nAnd spy a place where he might wedded be;\nPraying Our Lord to grant to him that he\nMight once know something of that blissful life\nThat is between a husband and his wife;\nAnd so to live within that holy band\nWherein God first made man and woman stand.\nNo other life, said he, is worth a bean;\nFor wedlock is so easy and so clean\nThat in this world it is a paradise.\nThus said this ancient knight, who was so wise.\nAnd certainly, as sure as God is King,\nTo take a wife, it is a glorious thing,\nEspecially when a man is old and hoary;\nThen is a wife the fruit of wealth and glory.\nThen should he take a young wife and a fair,\nOn whom he may beget himself an heir,\nAnd lead his life in joy and in solace,\nWhereas these bachelors do but sing Alas!'\nWhen they fall into some adversity\nIn love, which is but childish vanity.\nAnd truly, it is well that it is so\nThat bachelors have often pain and woe;\nOn shifting ground they build, and shiftiness\nThey find when they suppose they've certainness.\nThey live but as a bird does, or a beast,\nIn liberty and under no arrest,\nWhereas a wedded man in his high state\nLives a life blissful, ordered, moderate,\nUnder the yoke of happy marriage bound;\nWell may his heart in joy and bliss abound.\nFor who can be so docile as a wife?\nWho is so true as she whose aim in life\nIs comfort for him, sick or well, to make?\nFor weal or woe she will not him forsake.\nShe's ne'er too tired to love and serve, say I,\nThough he may lie bedridden till he die.\nAnd yet some writers say it is not so,\nAnd Theophrastus is one such, I know.\nWhat odds though Theophrastus chose to lie?\nTake not a wife, said he, for husbandry,\nIf you would spare in household your expense;\nA faithful servant does more diligence\nTo keep your goods than your own wedded wife.\nFor she will claim a half part all her life;\nAnd if you should be sick, so God me save,\nYour true friends or an honest serving knave\nWill keep you better than she that waits, I say,\nAfter your wealth, and has done, many a day.\nAnd if you take a wife to have and hold,\nRight easily may you become cuckold.\nThis judgment and a hundred such things worse\nDid this man write, may God his dead bones curse!\nBut take no heed of all such vanity.\nDefy old Theophrastus and hear me.\nA wife is God's own gift, aye verily;\nAll other kinds of gifts, most certainly,\nAs lands, rents, pasture, rights in common land,\nOr moveables, in gift of Fortune stand,\nAnd pass away like shadows on the wall.\nBut, without doubt, if plainly speak I shall,\nA wife will last, and in your house endure\nLonger than you would like, peradventure.\nBut marriage is a solemn sacrament;\nWho has no wife I hold on ruin bent;\nHe lives in helplessness, all desolate,\nI speak of folk in secular estate.\nAnd hearken why, I say not this for naught:\nIt's because woman was for man's help wrought.\nThe High God, when He'd Adam made, all rude,\nAnd saw him so alone and belly-nude,\nGod of His goodness thus to speak began:\nLet us now make a help meet for this man,\nLike to himself. And then he made him Eve.\nHere may you see, and here prove, I believe,\nA wife is a man's help and his comfort,\nHis earthly paradise and means of sport;\nSo docile and so virtuous is she\nThat they must needs live in all harmony.\nOne flesh they are, and one flesh, as I guess,\nHas but one heart in weal and in distress.\nA wife! Ah, Holy Mary, ben'cite!\nHow may a man have any adversity\nWho has a wife? Truly, I cannot say.\nThe bliss that is between such two, for aye,\nNo tongue can tell, nor any heart can think.\nIf he be poor, why, she helps him to swink;\nShe keeps his money and never wastes a deal;\nAll that her husband wishes she likes well;\nShe never once says nay when he says yea.\nDo this, says he; All ready, sir, she'll say.\nO blissful state of wedlock, prized and dear,\nSo pleasant and so full of virtue clear,\nSo much approved and praised as fortune's peak,\nThat every man who holds him worth a leek\nUpon his bare knees ought, through all his life,\nTo give God thanks, Who's sent to him a wife;\nOr else he should pray God that He will send\nA wife to him, to last till his life's end.\nFor then his life is set in certainness;\nHe cannot be deceived, as I may guess,\nSo that he act according as she's said;\nThen may he boldly carry high his head,\nThey are so true and therewithal so wise;\nWherefore, if you will do as do the wise,\nThen aye as women counsel be your deed.\nLo, how young Jacob, as these clerics read,\nAbout his hairless neck a kid's skin bound,\nA trick that Dame Rebecca for him found,\nBy which his father's benison he won.\nLo, Judith, as the ancient stories run,\nBy her wise counsel she God's people kept,\nAnd Holofernes slew, while yet he slept.\nLo, Abigail, by good advice how she\nDid save her husband, Nabal, when that he\nShould have been slain; and lo, Esther also\nBy good advice delivered out of woe\nThe people of God and got him, Mordecai,\nBy King Ahasuerus lifted high.\nThere is no pleasure so superlative\n(Says Seneca) as a humble wife can give.\nSuffer your wife's tongue, Cato bids, as fit;\nShe shall command, and you shall suffer it;\nAnd yet she will obey, of courtesy.\nA wife is keeper of your husbandry;\nWell may the sick man wail and even weep\nWho has no wife the house to clean and keep.\nI warn you now, if wisely you would work,\nLove well your wife, as Jesus loves His Kirk.\nFor if you love yourself, you love your wife;\nNo man hates his own flesh, but through his life\nHe fosters it, and so I bid you strive\nTo cherish her, or you shall never thrive.\nHusband and wife, despite men's jape or play,\nOf all the world's folk hold the safest way;\nThey are so knit there may no harm betide,\nEspecially upon the good wife's side.\nFor which this January, of whom I told,\nDid well consider in his days grown old,\nThe pleasant life, the virtuous rest complete\nThat are in marriage, always honey-sweet;\nAnd for his friends upon a day he sent\nTo tell them the effect of his intent.\nWith sober face his tale to them he's told;\nHe said to them: My friends, I'm hoar and old,\nAnd almost, God knows, come to my grave's brink;\nAbout my soul, now, somewhat must I think.\nI have my body foolishly expended;\nBlessed be God, that thing be amended!\nFor I will be, truly, a wedded man,\nAnd that anon, in all the haste I can,\nUnto some maiden young in age and fair.\nI pray you for my marriage all prepare,\nAnd do so now, for I will not abide;\nAnd I will try to find one, on my side,\nTo whom I may be wedded speedily.\nBut for as much as you are more than I,\nIt's better that you have the thing in mind\nAnd try a proper mate for me to find.\nBut of one thing I warn you, my friends dear,\nI will not have an old wife coming here.\nShe shan't have more than twenty years, that's plain;\nOf old fish and young flesh I am full fain.\nBetter, said he, a pike than pickerel;\nAnd better than old beef is tender veal.\nI'll have no woman thirty years of age,\nIt is but bean-straw and such rough forage.\nAnd these old widows, God knows that, afloat,\nThey know so much of spells when on Wade's boat,\nAnd do such petty harm, when they think best,\nThat with one should I never live at rest.\nFor several schools can make men clever clerks;\nWoman in many schools learns clever works.\nBut certainly a young thing men may guide,\nJust as warm wax may with one's hands be plied.\nWherefore I tell you plainly, in a clause,\nI will not have an old wife, for that cause.\nFor if it chanced I made that sad mistake\nAnd never in her could my pleasure take,\nMy life I'd lead then in adultery\nAnd go straight to the devil when I die.\nNo children should I then on her beget;\nYet would I rather hounds my flesh should fret\nThan that my heritage descend and fall\nInto strange hands, and this I tell you all.\nI dote not, and I know the reason why\nA man should marry, and furthermore know I\nThere speaks full many a man of all marriage\nWho knows no more of it than knows my page,\nNor for what reasons man should take a wife.\nIf one may not live chastely all his life,\nLet him take wife whose quality he's known\nFor lawful procreation of his own\nBlood children, to the honour of God above,\nAnd not alone for passion or for love;\nAnd because lechery they should eschew\nAnd do their family duty when it's due;\nOr because each of them should help the other\nIn trouble, as a sister shall a brother;\nAnd live in chastity full decently.\nBut, sirs, and by your leave, that is not I.\nFor, God be thanked, I dare to make a vaunt,\nI feel my limbs are strong and fit to jaunt\nIn doing all man's are expected to;\nI know myself and know what I can do.\nThough I am hoar, I fare as does a tree\nThat blossoms ere the fruit be grown; you see\nA blooming tree is neither dry nor dead.\nAnd I feel nowhere hoary but on head;\nMy heart and all my limbs are still as green\nAs laurel through the year is to be seen.\nAnd now that you have heard all my intent,\nI pray that to my wish you will assent.\nThen divers men to him diversely told,\nOf marriage, many an instance known of old.\nSome blamed it and some praised it, that's certain,\nBut at the last, and briefly to make plain,\nSince altercation follows soon or late\nWhen friends begin such matters to debate,\nThere fell a strife between his brothers two,\nWhereof the name of one was Placebo\nAnd verily Justinus was that other.\nPlacebo said: O January, brother,\nFull little need had you, my lord so dear,\nCounsel to ask of anyone that's here;\nSave that you are so full of sapience\nThat you like not, what of your high prudence,\nTo vary from the word of Solomon.\nThis word said he to each and every one:\n'Do everything by counsel,' thus said he,\n'And then thou hast no cause to repent thee.'\nBut although Solomon spoke such a word,\nMy own dear brother and my proper lord,\nSo truly may God bring my soul to rest\nAs I hold your own counsel is the best.\nFor, brother mine, of me take this one word,\nI've been a courtier all my days, my lord.\nAnd God knows well, though I unworthy be\nI have stood well, and in full great degree,\nWith many lords of very high estate;\nYet ne'er with one of them had I debate.\nI never contradicted, certainly;\nI know well that my lord knows more than I.\nWhate'er he says, I hold it firm and stable;\nI say the same, or nearly as I'm able.\nA full great fool is any Councillor\nThat serves a lord of any high honour\nAnd dares presume to say, or else think it,\nHis counsel can surpass his lordship's wit.\nNay, lords are never fools, nay, by my fay;\nYou have yourself, sir, showed, and here today,\nWith such good sense and piety withal\nThat I assent to and confirm it all,\nThe words and the opinions you have shown.\nBy God, there is no man in all this town,\nOr Italy, it better could have phrased;\nAnd Christ Himself your counsel would have praised\nAnd truthfully, it argues high courage\nIn any man that is advanced in age\nTo take a young wife; by my father's kin,\nA merry heart you've got beneath your skin?\nDo in this matter at your own behest,\nFor, finally, I hold that for the best.\nJustinus, who sat still and calm, and heard,\nRight in this wise Placebo he answered:\nNow, brother mine, be patient, so I pray;\nSince you have spoken, hear what I shall say.\nFor Seneca, among his words so wise,\nSays that a man ought well himself advise\nTo whom he'll give his chattels or his land.\nAnd since I ought to know just where I stand\nBefore I give my wealth away from me,\nHow much more well advised I ought to be\nTo whom I give my body; for alway\nI warn you well, that it is not child's play\nTo take a wife without much advisement.\nMen must inquire, and this is my intent,\nWhether she's wise, or sober, or drunkard,\nOr proud, or else in other things froward,\nOr shrewish, or a waster of what's had,\nOr rich, or poor, or whether she's man-mad.\nAnd be it true that no man finds, or shall,\nOne in this world that perfect is in all,\nOf man or beast, such as men could devise;\nNevertheless, it ought enough suffice\nWith any wife, if so were that she had\nMore traits of virtue that her vices bad;\nAnd all this leisure asks to see and hear.\nFor God knows I have wept full many a tear\nIn privity, since I have had a wife.\nPraise whoso will a wedded man's good life,\nTruly I find in it, but cost and care\nAnd many duties, of all blisses bare.\nAnd yet, God knows, my neighbours round about,\nEspecially the women, many a rout,\nSay that I've married the most steadfast wife,\nAye, and the meekest one there is in life.\nBut I know best where pinches me my shoe.\nYou may, for me, do as you please to do;\nBut take good heed, since you're a man of age,\nHow you shall enter into a marriage,\nEspecially with a young wife and a fair.\nBy Him Who made the water, earth, and air,\nThe youngest man there is in all this rout\nIs busy enough to bring the thing about\nThat he alone shall have his wife, trust me.\nYou'll not be able to please her through years three,\nThat is to say, to give all she desires.\nA wife attention all the while requires.\nI pray you that you be not offended.\nWell? asked this January, And have you said?\nA straw for Seneca and your proverbs!\nI value not a basketful of herbs\nYour schoolmen's terms; for wiser men than you,\nAs you have heard, assent and bid me do\nMy purpose now. Placebo, what say ye?\nI say it is a wicked man, said he,\nThat hinders matrimony, certainly.\nAnd with that word they rose up, suddenly,\nHaving assented fully that he should\nBe wedded when he pleased and where he would.\n\nImagination and his eagerness\nDid in the soul of January press\nAs he considered marriage for a space.\nMany fair shapes and many a lovely face\nPassed through his amorous fancy, night by night.\nAs who might take mirror polished bright\nAnd set it in the common market-place\nAnd then should see full many a figure pace\nWithin the mirror; just in that same wise\nDid January within his thought surmise\nOf maidens whom he dwelt in town beside.\nHe knew not where his fancy might abide.\nFor if the one have beauty of her face,\nAnother stands so in the people's grace\nFor soberness and for benignity,\nThat all the people's choice she seems to be;\nAnd some were rich and had an evil name.\nNevertheless, half earnest, half in game,\nHe fixed at last upon a certain one\nAnd let all others from his heart be gone,\nAnd chose her on his own authority;\nFor love is always blind and cannot see.\nAnd when in bed at night, why then he wrought\nTo portray, in his heart and in his thought,\nHer beauty fresh and her young age, so tender,\nHer middle small, her two arms long and slender,\nHer management full wise, her gentleness,\nHer womanly bearing, and her seriousness.\nAnd when to her at last his choice descended,\nHe thought that choice might never be amended.\nFor when he had concluded thus, egad,\nHe thought that other men had wits so bad\nIt were impossible to make reply\nAgainst his choice, this was his fantasy.\nHis friends he sent to, at his own instance,\nAnd prayed them give him, in this wise, pleasance,\nThat speedily they would set forth and come:\nHe would abridge their labour, all and some.\nHe need not more to walk about or ride,\nFor he'd determined where he would abide.\nPlacebo came, and all his friends came soon,\nAnd first of all he asked of them the boon\nThat none of them an argument should make\nAgainst the course he fully meant to take;\nWhich purpose pleasing is to God, said he,\nAnd the true ground of my felicity.\nHe said there was a maiden in the town\nWho had for beauty come to great renown,\nDespite the fact she was of small degree;\nSufficed him well her youth and her beauty.\nWhich maid, he said, he wanted for his wife,\nTo lead in ease and decency his life.\nAnd he thanked God that he might have her, all,\nThat none partook of his bliss now, nor shall.\nAnd prayed them all to labour in this need\nAnd so arrange that he'd fail not, indeed;\nFor then, he said, his soul should be at case.\nAnd then, said he, there's naught can me displease,\nSave one lone thing that sticks in my conscience,\nThe which I will recite in your presence.\nI have, said he, heard said, and long ago,\nThere may no man have perfect blisses two,\nThat is to say, on earth and then in Heaven.\nFor though he keep from sins the deadly seven,\nAnd, too, from every branch of that same tree,\nYet is there so complete felicity\nAnd such great pleasure in the married state\nThat I am fearful, since it comes so late,\nThat I shall lead so merry and fine a life,\nAnd so delicious, without woe and strife,\nThat I shall have my heaven on earth here.\nFor since that other Heaven is bought so dear,\nWith tribulation and with great penance,\nHow should I then, who live in such pleasance,\nAs all these wedded men do with their wives,\nCome to the bliss where Christ Eternal lives?\nThis is my fear, and you, my brothers, pray\nResolve for me this problem now, I say.\nJustinus, who so hated this folly,\nAnswered anon in jesting wise and free;\nAnd since he would his longish tale abridge,\nHe would no old authority allege,\nBut said: Sir, so there is no obstacle\nOther than this, God, of high miracle\nAnd of His mercy, may so for you work\nThat, ere you have your right of Holy Kirk,\nYou'll change your mind on wedded husband's life,\nWherein you say there is no woe or strife.\nAnd otherwise, God grant that there be sent\nTo wedded man the fair grace to repent\nOften, and sooner than a single man!\nAnd therefore, sir, this is the best I can:\nDespair not, but retain in memory,\nPerhaps she may your purgatory be!\nShe may be God's tool, she may be God's whip;\nThen shall your spirit up to Heaven skip\nSwifter than does an arrow from the bow!\nI hope to God, hereafter you shall know\nThat there is none so great felicity\nIn marriage, no nor ever shall there be,\nTo keep you from salvation that's your own,\nSo that you use, with reason that's well known,\nThe charms of your wife's body temperately,\nAnd that you please her not too amorously,\nAnd that you keep as well from other sin.\nMy tale is done now, for my wit is thin.\nBe not deterred hereby, my brother dear-\n(But let us pass quite over what's said here.\nThe wife of Bath, if you have understood,\nHas treated marriage, in its likelihood,\nAnd spoken well of it in little space)-\nFare you well now, God have you in His grace.\nAnd with that word this Justin and his brother\nDid take their leave, and each of them from other.\nFor when they all saw that it must needs be,\nThey so arranged, by sly and wise treaty,\nThat she, this maiden, who was Maia hight,\nAs speedily indeed as ever she might,\nShould wedded be unto this January.\nI think it were too long a time to tarry\nTo tell of deed and bond between them, and\nThe way she was enfeoffed of all his land;\nOr to hear tell of all her rich array.\nBut finally was come the happy day\nWhen to the church together they two went,\nThere to receive the holy sacrament.\nForth came the priest with stole about his neck,\nSaying of Rebecca and Sarah she should reck\nFor wisdom and for truth in her marriage;\nAnd said his orisons, as is usage,\nAnd crossed them, praying God that He should bless,\nAnd made all tight enough with holiness.\nThus are they wedded with solemnity,\nAnd at the feast are sitting, he and she,\nWith other worthy folk upon the dais.\nAll full of joy and bliss the palace gay is,\nAnd full of instruments and viandry,\nThe daintiest in all of Italy.\nBefore them played such instruments anon\nThat Orpheus or Theban Amphion\nNever in life made such a melody.\nWith every course there rose loud minstrelsy,\nAnd never Joab sounded trump, to hear,\nNor did Theodomas, one half so clear\nAt Thebes, while yet the city hung in doubt.\nBacchus the wine poured out for all about,\nAnd Venus gaily laughed for every wight.\nFor January had become her knight,\nAnd would make trial of his amorous power\nIn liberty and in the bridal bower;\nAnd with her firebrand in her hand, about\nDanced she before the bride and all the rout.\nAnd certainly I dare right well say this,\nThat Hymenaeus, god of wedded bliss,\nNe'er saw in life so merry a married man.\nHold thou thy peace, thou poet Marcian\nWho tellest how Philology was wed\nAnd how with Mercury she went to bed,\nAnd of the sweet songs by the Muses sung.\nToo slight are both thy pen and thy thin tongue.\nTo show aright this wedding on thy page.\nWhen tender youth has wedded stooping age,\nThere is such mirth that no one may it show;\nTry it yourself, and then you well will know\nWhether I lie or not in matters here.\nMaia, she sat there with so gentle cheer,\nTo look at her it seemed like faery;\nQueen Esther never looked with such an eye\nUpon Ahasuerus, so meek was she.\nI can't describe to you all her beauty;\nBut thus much of her beauty I can say,\nThat she was like the brightening morn of May,\nFulfilled of beauty and of all pleasance.\nJanuary was rapt into a trance\nWith each time that he looked upon her face;\nAnd in his heart her beauty he'd embrace,\nAnd threatened in his arms to hold her tight,\nHarder than Paris Helen did, that night.\nBut nonetheless great pity, too, had he\nBecause that night she must deflowered be;\nAnd thought: Alas! O tender young creature!\nNow would God you may easily endure\nAll my desire, it is so sharp and keen.\nI fear you can't sustain it long, my queen.\nBut God forbid that I do all I might!\nAnd now would God that it were come to night,\nAnd that the night would last for ever- oh,\nI wish these people would arise and go.\nAnd at the last he laboured all in all,\nAs best he might for Manners there in hall,\nTo haste them from the feast in subtle wise.\nTime came when it was right that they should rise;\nAnd after that men danced and drank right fast,\nAnd spices all about the house they cast;\nAnd full of bliss and joy was every man,\nAll but a squire, a youth called Damian,\nWho'd carved before the knight full many a day.\nHe was so ravished by his Lady May\nThat for the very pain, as madman would,\nAlmost he fell down fainting where he stood.\nSo sore had Venus hurt him with her brand,\nWhen she went dancing, bearing it in hand.\nAnd to his bed he took him speedily;\nNo more of him just at this time say I.\nI'll let him weep his fill, with woe complain,\nUntil fresh May have ruth upon his pain.\nO parlous fire that in the bedstraw breeds!\nO foe familiar that his service speeds!\nO treacherous servant, false domestic who\nIs most like adder in bosom, sly, untrue,\nGod shield us all from knowing aught of you!\nO January, drunk of pleasure's brew\nIn marriage, see how now your Damian,\nYour own trained personal squire, born your man,\nWishes and means to do you villainy.\nGod grant that on this household foe you'll spy!\nFor in this world no pestilence is worse\nThan foe domestic, constantly a curse.\nWhen traversed has the sun his are of day,\nNo longer may the body of him stay\nOn the horizon, in that latitude.\nNight with his mantle, which is dark and rude,\nDid overspread the hemisphere about;\nAnd so departed had this joyous rout\nFrom January, with thanks on every side.\nHome to their houses happily they ride,\nWhereat they do what things may please them best,\nAnd when they see the time come, go to rest.\nSoon after that this hasty January\nWould go to bed, he would no longer tarry.\nHe drank of claret, hippocras, vernage,\nAll spiced and hot to heighten his love's rage;\nAnd many an aphrodisiac, full and fine,\nSuch as the wicked monk, Dan Constantine,\nHas written in his book De Coitu\nNot one of all of them he did eschew.\nAnd to his friends most intimate, said he:\nFor God's love, and as soon as it may be,\nLet all now leave this house in courteous wise.\nAnd all they rose, just as he bade them rise.\nThey drank good-night, and curtains drew anon;\nThe bride was brought to bed, as still as stone;\nAnd when the bed had been by priest well blessed,\nOut of the chamber everyone progressed.\nAnd January lay down close beside\nHis fresh young May, his paradise, his bride.\nHe soothed her, and he kissed her much and oft,\nWith the thick bristles of his beard, not soft,\nBut sharp as briars, like a dogfish skin,\nFor he'd been badly shaved ere he came in.\nHe stroked and rubbed her on her tender face,\nAnd said: Alas! I fear I'll do trespass\nAgainst you here, my spouse, and much offend\nBefore the time when I will down descend.\nBut nonetheless, consider this, said he,\nThere is no workman, whosoe'er he be,\nThat may work well, if he works hastily;\nThis will be done at leisure, perfectly.\nIt makes no difference how long we two play;\nFor in true wedlock were we tied today;\nAnd blessed be the yoke that we are in,\nFor in our acts, now, we can do no sin.\nA man can do no sin with his own wife,\nNor can he hurt himself with his own knife;\nFor we have leave most lawfully to play.\nThus laboured he till came the dawn of day;\nAnd then he took in wine a sop of bread,\nAnd upright sat within the marriage bed,\nAnd after that he sang full loud and clear\nAnd kissed his wife and made much wanton cheer.\nHe was all coltish, full of venery,\nAnd full of chatter as a speckled pie.\nThe slackened skin about his neck did shake\nThe while he sang and chanted like a crake.\nBut God knows what thing May thought in her heart\nWhen up she saw him sitting in his shirt,\nIn his nightcap, and with his neck so lean;\nShe valued not his playing worth a bean.\nThen said he thus: My rest now will I take;\nNow day is come, I can no longer wake.\nAnd down he laid his head and slept till prime.\nAnd afterward, when saw he it was time,\nUp rose this January; but fresh May,\nShe kept her chamber until the fourth day,\nAs custom is of wives, and for the best.\nFor every worker sometime must have rest,\nOr else for long he'll certainly not thrive,\nThat is to say, no creature that's alive,\nBe it of fish, or bird, or beast, or man.\nNow will I speak of woeful Damian,\nWho languished for his love, as you shall hear;\nI thus address him in this fashion here.\nI say: O hapless Damian, alas!\nAnswer to my demand in this your case,\nHow shall you to your lady, lovely May,\nTell all your woe? She would of course say 'Nay.'\nAnd if you speak, she will your state betray;\nGod be your help! I can no better say.\nThis lovesick Damian in Venus' fire\nSo burned, he almost perished for desire;\nWhich put his life in danger, I am sure;\nLonger in this wise could he not endure;\nBut privily a pen-case did he borrow\nAnd in a letter wrote he all his sorrow,\nIn form of a complaint or of a lay,\nUnto his fair and blooming Lady May.\nAnd in a purse of silk hung in his shirt,\nHe put the poem and laid it next his heart.\nThe moon, which was at noon of that same day\nWhereon this January wedded May\nHalf way through Taurus, had to Cancer glided,\nSo long had Maia in her chamber bided.\nAs is the custom among nobles all.\nA bride shall not eat in the common hall\nUntil four days, or three days at the least,\nHave fully passed; then let her go to feast.\nOn the fourth day, complete from noon to noon,\nAfter the high Mass had been said and done,\nIn hall did January sit with May\nAs fresh as is the fair bright summer day.\nAnd so befell it there that this good man\nRecalled to mind his squire, this Damian,\nAnd said: Why holy Mary! How can it be\nThat Damian attends not here on me?\nIs he sick always? How may this betide?\nHis other squires, who waited there beside,\nMade the excuse that he indeed was ill,\nWhich kept him from his proper duties still;\nThere was no other cause could make him tarry.\nThat is a pity, said this January,\nHe is a gentle squire, aye, by my truth!\nIf he should die, it were great harm and ruth;\nAs wise and secret, and discreet is he\nAs any man I know of his degree;\nTherewith he's manly and he's serviceable,\nAnd to become a useful man right able.\nBut after meat, as soon as ever I may,\nI will myself go visit him, with May,\nTo give him all the comfort that I can.\nAnd for that word they blessed him, every man,\nBecause, for goodness and his gentleness,\nHe would so go to comfort, in sickness,\nHis suffering squire, for 'twas a gentle deed.\n\nDame, said this January, take good heed\nThat after meat, you, with your women all,\nWhen you have gone to chamber from this hall,\nThat all you go to see this Damian;\nCheer him a bit, for he's a gentleman;\nAnd tell him that I'll come to visit him\nAfter I've rested- a short interim;\nAnd get this over quickly, for I'll bide\nAwake until you sleep there at my side.\nAnd with that word he raised his voice to call\nA squire, who served as marshal of his hall,\nAnd certain things he wished arranged were told.\nThis lovely May then did her straight way hold,\nWith all her women, unto Damian.\nDown by his bed she sat, and so began\nTo comfort him with kindly word and glance.\nThis Damian, when once he'd found his chance,\nIn secret wise his purse and letter, too,\nWherein he'd said what he aspired to,\nHe put into her hand, with nothing more,\nSave that he heaved a sigh both deep and sore,\nAnd softly to her in this wise said he:\nOh, mercy! Don't, I beg you, tell on me;\nFor I'm but dead if this thing be made known.\nThis purse she hid in bosom of her gown\nAnd went her way; you get no more of me.\nBut unto January then came she,\nWho on his bedside sat in mood full soft.\nHe took her in his arms and kissed her oft,\nAnd laid him down to sleep, and that anon.\nAnd she pretended that she must be gone\nWhere you know well that everyone has need.\nAnd when she of this note had taken heed,\nShe tore it all to fragments at the last\nAnd down the privy quietly it cast.\nWho's in brown study now but fair fresh May?\nDown by old January's side she lay,\nWho slept, until the cough awakened him;\nHe prayed her strip all naked for his whim;\nHe would have pleasure of her, so he said,\nAnd clothes were an incumbrance when in bed,\nAnd she obeyed him, whether lief or loath.\nBut lest these precious folk be with me wroth,\nHow there he worked, I dare not to you tell;\nNor whether she thought it paradise or hell;\nBut there I leave them working in their wise\nTill vespers rang and they must needs arise.\nWere it by destiny or merely chance,\nBy nature or some other circumstance,\nOr constellation's sign, that in such state\nThe heavens stood, the time was fortunate\nTo make request concerning Venus' works\n(For there's a time for all things, say these clerks)\nTo any woman, to procure her love,\nI cannot say; but the great God above,\nWho knows there's no effect without a cause,\nHe may judge all, for here my voice withdraws.\nBut true it is that this fair blooming May\nWas so affected and impressed that day\nFor pity of this lovesick Damian,\nThat from her heart she could not drive or ban\nRemembrance of her wish to give him ease.\nCertainly, thought she, whom this may displease\nI do not care, for I'd assure him now\nHim with my love I'd willingly endow,\nThough he'd no more of riches than his shirt.\nLo, pity soon wells up in gentle heart.\nHere may you see what generosity\nIn women is when they advise closely.\nPerhaps some tyrant (for there's many a one)\nWho has a heart as hard as any stone,\nWould well have let him die within that place\nMuch rather than have granted him her grace;\nAnd such would have rejoiced in cruel pride,\nNor cared that she were thus a homicide.\nThis gentle May, fulfilled of all pity,\nWith her own hand a letter then wrote she\nIn which she granted him her utmost grace;\nThere was naught lacking now, save time and place\nWherein she might suffice to ease his lust:\nFor all should be as he would have it, just;\nAnd when she'd opportunity on a day,\nTo visit Damian went this lovely May,\nAnd cleverly this letter she thrust close\nUnder his pillow, read it if he chose.\nShe took him by the hand and hard did press,\nSo secretly that no one else could guess,\nAnd bade him gain his health, and forth she went\nTo January, when for her he sent.\nUp rose this Damian upon the morrow,\nFor gone was all his sickness and his sorrow.\nHe combed himself and preened his feathers smooth,\nHe did all that his lady liked, in sooth;\nAnd then to January went as low\nAs ever did a hound trained to the bow.\nHe was so pleasant unto every man\n(For craft is everything for those who can),\nThat everyone was fain to speak his good;\nAnd fully in his lady's grace he stood.\nThus Damian I leave about his need\nAnd forward in my tale I will proceed.\nSome writers hold that all felicity\nStands in delight, and therefor, certainly,\nThis noble January, with all his might,\nHonourably, as does befit a knight,\nArranged affairs to live deliciously.\nHis housing, his array, as splendidly\nBefitted his condition as a king's.\nAmong the rest of his luxurious things\nHe built a garden walled about with stone;\nSo fair a garden do I know of none.\nFor, without doubt, I verily suppose\nThat he who wrote The Romance of the Rose\nCould not its beauty say in singing wise;\nNor could Priapus' power quite suffice,\nThough he is god of gardens all, to tell\nThe beauty of that garden, and the well\nWhich was beneath the laurel always green.\nFor oftentimes God Pluto and his queen,\nFair Proserpine and all her faery\nDisported there and made sweet melody\nAbout that well, and danced there, as men told.\nThis noble knight, this January old,\nSuch pleasure had therein to walk and play,\nThat none he'd suffer bear the key, they say.\nSave he himself; for of the little wicket\nHe carried always the small silver clicket\nWith which, as pleased him, he'd unlock the gate.\nAnd when he chose to pay court to his mate\nIn summer season, thither would he go\nWith May, his wife, and no one but they two;\nAnd divers things that were not done abed,\nWithin that garden there were done, 'tis said.\nAnd in this manner many a merry day\nLived this old January and young May.\nBut worldly pleasure cannot always stay,\nAnd January's joy must pass away.\nO sudden chance, O Fortune, thou unstable,\nLike to the scorpion so deceptive, able\nTo flatter with thy mouth when thou wilt sting;\nThy tail is death, through thine envenoming.\nO fragile joy! O poison sweetly taint!\nO monster that so cleverly canst paint\nThy gifts in all the hues of steadfastness\nThat thou deceivest both the great and less!\nWhy hast thou January thus deceived,\nThat had'st him for thine own full friend received?\nAnd now thou hast bereft him of his eyes,\nFor sorrow of which in love he daily dies.\nAlas! This noble January free,\nIn all his pleasure and prosperity,\nIs fallen blind, and that all suddenly.\nHe wept and he lamented, pitifully;\nAnd therewithal the fire of jealousy\nLest that his wife should fall to some folly,\nSo burned within his heart that he would fain\nBoth him and her some man had swiftly slain.\nFor neither after death nor in his life\nWould he that she were other's love or wife,\nBut dress in black and live in widow's state,\nLone as the turtle-dove that's lost her mate.\nBut finally, after a month or twain,\nHis grief somewhat abated, to speak plain;\nFor when he knew it might not elsewise be,\nHe took in patience his adversity,\nSave, doubtless, he could not renounce, as done,\nHis jealousy, from which he never won.\nFor this his passion was so outrageous\nThat neither in his hall nor other house\nNor any other place, not ever, no,\nHe suffered her to ride or walking go,\nUnless he had his hand on her alway;\nFor which did often weep this fresh young May,\nWho loved her Damian so tenderly\nThat she must either swiftly die or she\nMust have him as she willed, her thirst to slake;\nBiding her time, she thought her heart would break.\nAnd on the other side this Damian\nWas now become the most disconsolate man\nThat ever was; for neither night nor day\nMight he so much as speak a word to May\nOf his desire, as I am telling here,\nSave it were said to January's ear,\nWho never took his blind hand off her, no.\nNevertheless, by writing to and fro\nAnd secret signals, he knew what she meant;\nAnd she too knew the aim of his intent.\nO January, what might it now avail\nCould your eyes see as far as ships can sail?\nFor it's as pleasant, blind, deceived to be\nAs be deceived while yet a man may see.\nLo, Argus, who was called the hundred-eyed,\nNo matter how he peered and watched and pried,\nHe was deceived; and God knows others to\nWho think, and firmly, that it is not so.\nOblivion is peace; I say no more.\nThis lovely May, of whom I spoke before,\nIn warm wax made impression of the key\nHer husband carried, to the gate where he\nIn entering his garden often went.\nAnd Damian, who knew all her intent,\nThe key did counterfeit, and privately;\nThere is no more to say, but speedily\nSome mischief of this latch-key shall betide,\nWhich you shall hear, if you but time will bide.\nO noble Ovid, truth you say, God wot!\nWhat art is there, though it be long and hot,\nBut Love will find it somehow suits his turn?\nBy Pyramus and Thisbe may men learn;\nThough they were strictly kept apart in all,\nThey soon accorded, whispering through a wall,\nWhere none could have suspected any gate.\nBut now to purpose: ere had passed: days eight,\nAnd ere the first day of July, befell\nThat January was under such a spell,\nThrough egging of his wife, to go and play\nWithin his garden, and no one but they,\nThat on a morning to this May said he:\nRise up, my wife, my love, my lady free;\nThe turtle's voice is heard, my dove so sweet;\nThe winter's past, the rain's gone, and the sleet;\nCome forth now with your two eyes columbine!\nHow sweeter are your breasts than is sweet wine!\nThe garden is enclosed and walled about;\nCome forth, my white spouse, for beyond all doubt\nYou have me ravished in my heart, O wife!\nNo fault have I found in you in my life.\nCome forth, come forth, and let us take our sport;\nI chose you for my wife and my comfort.\nSuch were the lewd old words that then used he;\nTo Damian a secret sign made she\nThat he should go before them with his clicket;\nThis Damian then opened up the wicket,\nAnd in he slipped, and that in manner such\nThat none could see nor hear; and he did crouch\nAnd still he sat beneath a bush anon.\nThis January, blind as is a stone,\nWith Maia's hand in his, and none else there,\nInto his garden went, so fresh and fair,\nAnd then clapped to the wicket suddenly.\nNow, wife, said he, here's none but you and I,\nAnd you're the one of all that I best love.\nFor by that Lord Who sits in Heaven above,\nFar rather would I die upon a knife\nThan do offence to you, my true, dear wife!\nFor God's sake how I did choose you out,\nAnd for no love of money, beyond doubt,\nBut only for the love you roused in me.\nAnd though I am grown old and cannot see,\nBe true to me, and I will tell you why.\nThree things, it's certain, shall you gain thereby;\nFirst, Christ's dear love, and honour of your own,\nAnd all my heritage of tower and town;\nI give it you, draw deeds to please you, pet;\nThis shall be done tomorrow ere sunset.\nSo truly may God bring my soul to bliss,\nI pray you first, in covenant, that we kiss.\nAnd though I'm jealous, yet reproach me not.\nYou are so deeply printed in my thought\nThat, when I do consider your beauty\nAnd therewith all the unlovely age of me,\nI cannot, truly, nay, though I should die,'\nAbstain from being in your company,\nFor utter love; of this there is no doubt.\nNow kiss me, wife, and let us walk about.\n\nThis blooming May, when these words she had heard,\nGraciously January she answered,\nBut first and foremost she began to weep.\nI have also, said she, a soul to keep,\nAs well as you, and also honour mine,\nAnd of my wifehood that sweet flower divine\nWhich I assured you of, both safe and sound,\nWhen unto you that priest my body bound;\nWherefore I'll answer you in this manner,\nIf I may by your leave, my lord so dear.\nI pray to God that never dawns the day\nThat I'll not die, foully as woman may,\nIf ever I do unto my kin such shame,\nAnd likewise damage so my own fair name,\nAs to be false; and if I grow so slack,\nStrip me and put me naked in a sack\nAnd in the nearest river let me drown.\nI am a lady, not a wench of town.\nWhy speak you thus? Men ever are untrue,\nAnd woman have reproaches always new.\nNo reason or excuse have you, I think,\nAnd so you harp on women who hoodwink.\nAnd with that word she saw where Damian\nSat under bush; to cough then she began,\nAnd with her slender finger signs made she\nThat Damian should climb into a tree\nThat burdened was with fruit, and up he went;\nFor verily he knew her full intent,\nAnd understood each sign that she could make,\nBetter than January, her old rake.\nFor in a letter she had told him all\nOf how he should proceed when time should fall.\nAnd thus I leave him in the pear-tree still\nWhile May and January roam at will.\nBright was the day and blue the firmament,\nPhoebus his golden streamers down has sent\nTo gladden every flower with his warmness.\nHe was that time in Gemini, I guess,\nAnd but a little from his declination\nOf Cancer, which is great Jove's exaltation.\nAnd so befell, in that bright morning-tide,\nThat in this garden, on the farther side,\nPluto, who is the king of Faery,\nWith many a lady in his company,\nFollowing his wife, the fair Queen Proserpine,\nEach after other, straight as any line\n(While she was gathering flowers on a mead,\nIn Claudian you may the story read\nHow in his grim car he had stolen her)-\nThis king of Faery sat down yonder\nUpon a turfen bank all fresh and green,\nAnd right anon thus said he to his queen.\nMy wife, said he, there may no one say nay;\nExperience proves fully every day\nThe treason that these women do to man.\nTen hundred thousand stories tell I can\nTo show your fickleness and lies. Of which,\nO Solomon wise, and richest of the rich,\nFulfilled of sapience and worldly glory,\nWell worth remembrance are thy words and story\nBy everyone who's wit, and reason can.\nThus goodness he expounds with praise of man:\n'Among a thousand men yet found I one,\nBut of all women living found I none.'\nThus spoke the king that knew your wickedness;\nAnd Jesus son of Sirach, as I guess,\nSpoke of you seldom with much reverence.\nA wild-fire and a rotten pestilence\nFall on your bodies all before tonight!\nDo you not see this honourable knight,\nBecause, alas! he is both blind and old,\nHis own sworn man shall make him a cuckold;\nLo, there he sits, the lecher, in that tree.\nNow will I grant, of my high majesty,\nUnto this old and blind and worthy knight,\nThat he shall have again his two eyes' sight,\nJust when his wife shall do him villainy;\nThen shall he know of all her harlotry,\nBoth in reproach to her and others too.\nYou shall, said Proserpine, if will you so;\nNow by my mother's father's soul, I swear\nThat I will give her adequate answer,\nAnd all such women after, for her sake;\nThat, though in any guilt caught, they'll not quake,\nBut with a bold face they'll themselves excuse,\nAnd bear him down who would them thus accuse.\nFor lack of answer none of them shall die.\nNay, though a man see things with either eye,\nYet shall we women brazen shamelessly\nAnd weep and swear and wrangle cleverly,\nSo that you men shall stupid be as geese.\nWhat do I care for your authorities?\nI know well that this Jew, this Solomon\nFound fools among us women, many a one,\nBut though he never found a good woman,\nYet has there found full many another man\nWomen right true, right good, and virtuous\nWitness all those that dwell in Jesus' house;\nWith martyrdom they proved their constancy.\nThe Gesta Romanorum speak kindly\nOf many wives both good and true also.\nBut be not angry, sir, though it be so\nThat he said he had found no good woman,\nI pray you take the meaning of the man;\nHe meant that sovereign goodness cannot be.\nExcept in God, Who is the Trinity.\nAh, since of very God there is but one,\nWhy do you make so much of Solomon?\nWhat though he built a temple for God's house?\nWhat though he were both rich and glorious?\nSo built he, too, a temple to false gods,\nHow could he with the Law be more at odds?\nBy gad, clean as his name you whitewash, sir,\nHe was a lecher and idolater;\nAnd in old age the True God he forsook.\nAnd if that God had not, as says the Book,\nSpared him for father David's sake, he should\nHave lost his kingdom sooner than he would.\nI value not, of all the villainy\nThat you of women write, a butterfly.\nI am a woman, and needs must I speak,\nOr else swell up until my heart shall break.\nFor since he said we gossip, rail, and scold,\nAs ever may I my fair tresses hold,\nI will not spare, for any courtesy,\nTo speak him ill who'd wish us villainy.\nDame, said this Pluto, be no longer wroth;\nI give it up; but since I swore my oath\nThat I would give to him his sight again,\nMy word shall stand, I warn you that's certain.\nI am a king, it suits me not to lie.\nAnd I, said she, am queen of Faery.\nHer answer shall she have, I undertake;\nNo further talk hereof let us two make.\nForsooth, I will not longer be contrary.\nNow let us turn again to January,\nWho in the garden with his lovely May\nSang, and that merrier than the popinjay,\nI love you best, and ever shall, I know.\nAnd so about the alleys did he go\nTill he had come at last to that pear-tree\nWherein this Damian sat right merrily\nOn high, among the young leaves fresh and green.\nThis blooming May, who was so bright of sheen,\nBegan to sigh, and said: Alas, my side!\nNow, sir, said she, no matter what betide,\nI must have some of these pears that I see,\nOr I may die, so much I long, said she,\nTo eat some of those little pears so green.\nHelp, for Her love Who is of Heaven Queen!\nI tell you well, a woman in my plight\nMay have for fruit so great an appetite\nThat she may die if none of it she have.\nAlas! said he, that I had here a knave\nThat could climb up, alas, alas! said he,\nThat I am blind. Yea, sir, no odds, said she,\nIf you'd but grant me, and for God's dear sake,\nThat this pear-tree within your arms you'd take\n(For well I know that you do not trust me),\nThen I could climb up well enough, said she,\nSo I my foot might set upon your back.\nSurely, said he, thereof should be no lack,\nMight I so help you with my own heart's blood.\nSo he stooped down, and on his back she stood,\nAnd gave herself a twist and up went she.\nLadies, I pray you be not wroth with me;\nI cannot gloze, I'm an uncultured man.\nFor of a sudden this said Damian\nPulled up her smock and thrust both deep and long.\nAnd when King Pluto saw this awful wrong,\nTo January he gave again his sight,\nAnd made him see as well as ever he might.\nAnd when he thus had got his sight again,\nNever was man of anything so fain.\nBut since his wife he thought of first and last,\nUp to the tree his eyes he quickly cast,\nAnd saw how Damian his wife had dressed\nIn such a way as cannot be expressed,\nSave I should rudely speak and vulgarly:\nAnd such a bellowing clamour then raised he\nAs does a mother when her child must die:\nOut! Help! Alas! Oh, help me! he did cry,\nOutlandish, brazen woman, what do you do?\nAnd she replied: Why, sir, and what ails you?\nHave patience, and do reason in your mind\nThat I have helped you for your two eyes blind.\nOn peril of my soul, I tell no lies,\nBut I was taught that to recover eyes\nWas nothing better, so to make you see,\nThan struggle with a man up in a tree.\nGod knows I did it with a good intent.\nStruggle! cried he, but damme, in it went!\nGod give you both a shameful death to die!\nHe banged you, for I saw it with my eye,\nOr may they hang me by the neck up, else!\nThen is, said she, my medicine all false;\nFor certainly, if you could really see,\nYou would not say these cruel words to me;\nYou catch but glimpses and no perfect sight.\nI see, said he, as well as ever I might-\nThanks be to God!- and with my two eyes, too,\nAnd truth, I thought he did that thing to you.\nYou are bewildered still, good sir, said she,\nSuch thanks I have for causing you to see;\nAlas! she cried, that ever I was so kind!\nNow, dame, said he, put all this out of mind.\nCome down, my dear, and if I have missaid,\nGod help me if I'm not put out indeed.\nBut by my father's soul, I thought to have seen\nHow Damian right over you did lean\nAnd that your smock was pulled up to his breast.\nYes, sir, said she, you may think as seems best;\nBut, sir, a man that wakens out of sleep,\nHe cannot suddenly take note and keep\nOf any thing, or see it perfectly,\nUntil he has recovered verily;\nJust so a man that blinded long has been,\nHe cannot say that suddenly he's seen\nSo well, at first, when sight is new to him,\nAs later, when his sight's no longer dim.\nUntil your sight be settled for a while,\nThere may full many a thing your mind beguile.\nBeware, I pray you, for, by Heaven's King,\nFull many a man thinks that he sees a thing,\nAnd it is other quite than what it seems.\nAnd he that misconstrues, why, he misdeems.\nAnd with that word she leaped down from the tree.\nThis January, who is glad but he?\nHe kissed her and he hugged her much and oft,\nAnd on her belly stroked and rubbed her soft,\nAnd home to palace led her, let me add.\nAnd now, good men, I pray you to be glad.\nFor here I end my tale of January;\nGod bless us, and His Mother, Holy Mary!\n\n"},{"index":6,"markdown":"## The Merchant's Epilogue\n\nEh! By God's mercy! cried our host. Said he:\nNow such a wife I pray God keep from me!\nBehold what tricks, and lo, what subtleties\nIn women are. For always busy as bees\nAre they, us simple men thus to deceive,\nAnd from the truth they turn aside and leave;\nBy this same merchant's tale it's proved, I feel,\nBut, beyond doubt, as true as any steel\nI have a wife, though poor enough she be;\nBut of her tongue a babbling shrew is she,\nAnd she's a lot of other vices too.\nNo matter, though, with this we've naught to do.\nBut know you what? In secret, be it said,\nI am sore sorry that to her I'm wed.\nFor if I should up-reckon every vice\nThe woman has, I'd be a fool too nice,\nAnd why? Because it should reported be\nAnd told her by some of this company;\nWho'd be the ones, I need not now declare,\nSince women know the traffic in such ware;\nBesides, my wit suffices not thereto\nTo tell it all; wherefore my tale is through.\n\n\n### The Squire's Prologue\n\nSquire, come nearer, if your will it be,\nAnd speak to us of love; for certainly\nYou know thereof as much as any man.\nNay, sir, said he, but I'll do what I can\nWith hearty will; for I will not rebel\nAgainst your wishes, but a tale will tell.\nHold me excused if I say aught amiss,\nMy aim is good, and lo, my tale is this.\n\n\n### The Squire's Tale\n\nAt Sarai, in the land of Tartary,\nThere dwelt a king who warred on Russia, he,\nWhereby there died full many a doughty man.\nThis noble king was known as Cambinskan,\nWho in his time was of so great renown\nThat there was nowhere in the wide world known\nSo excellent a lord in everything;\nHe lacked in naught belonging to a king.\nAs for the faith to which he had been born,\nHe kept its law to which he had been sworn;\nAnd therewith he was hardy, rich, and wise,\nAnd merciful and just in all men's eyes,\nTrue to his word, benign and honourable,\nAnd in his heart like any center stable;\nYoung, fresh, and strong, in warfare ambitious\nAs any bachelor knight of all his house.\nOf handsome person, he was fortunate,\nAnd kept always so well his royal state\nThat there was nowhere such another man.\nThis noble king, this Tartar Cambinskan\nHad got two sons on Elpheta, his wife,\nOf whom the elder's name was Algarsyf,\nAnd that same second son was Cambalo.\nA daughter had this worthy king, also,\nWho was the youngest, and called Canace.\nBut to describe to you all her beauty,\nIt lies not in my tongue nor my knowing;\nI dare not undertake so high a thing.\nMy English is quite insufficient for\nWhat must require a finished orator\nWho knew the colours needful to that art\nIf he were to describe her every part.\nI am none such, I must speak as I can.\nAnd so befell that, when this Cambinskan\nHad twenty winters worn his diadem,\nAs he was wont from year to year, I deem,\nHe let the feast of his nativity\nBe cried throughout all Sarai, his city,\nThe last Idus of March, as 'twas that year.\nPhoebus the sun right festive was, and clear;\nFor he was near his exaltation grown\nIn face of Mars, and in his mansion known\nIn Aries, the choleric hot sign.\nRight pleasant was the weather, and benign,\nFor which the wild birds in the sun's gold sheen,\nWhat of the season and the springing green,\nFull loudly sang their love and their affection;\nIt seemed that they had got themselves protection\nAgainst the sword of winter keen and cold.\nThis Cambinskan, of whom I have you told,\nHigh in the palace, mounted on his throne\nWith crown and royal vestments sat alone,\nAnd held his feast, so splendid and so rich\nThat in this world its like was not, of which,\nIf I should tell you all of the array,\nThen would it occupy a summer's day.\nBesides, it needs not here that I apprise\nOf every course the order of service.\nI will not tell you of their each strange sauce,\nNor of their swans, nor of their heronshaws.\nMoreover, in that land, as tell knights old,\nThere are some foods which they for dainties hold.\nOf which in this land the esteem is small;\nThere is no man that can report them all.\nI will not so delay you, for it's prime,\nAnd all the fruit of this were loss of time;\nUnto my first theme I will have recourse.\nAnd so befell that, after the third course,\nWhile this great king sat in his state that day,\nHearing his minstrels on their instruments play\nBefore him at the board, deliciously,\nIn at the hall door, and all suddenly,\nThere came a knight upon a steed of brass,\nHolding in hand a mirror broad of glass.\nUpon his thumb he had a golden ring,\nAnd by his side a naked sword hanging;\nAnd up he rode right to the highest board.\nIn all the hall there was not spoken word\nFor marvel of this knight; him to behold,\nThey stared and stretched and craned, both young and old.\nThis stranger knight, who came thus suddenly,\nArmed at all points, except his head, richly,\nSaluted king and queen and those lords all,\nIn order of rank, as they sat there in hall,\nShowing such humble courtesy to each\nIn manner of behaviour and in speech,\nThat Gawain, with his old-time courtesy,\nThough he were come again from Faery,\nCould not have bettered him in any word.\nAnd after this, before the king's high board,\nHe with a manly voice said his message,\nAfter the form in use in his language,\nWithout mistake in syllable or letter;\nAnd, that his tale should seem to all the better,\nAccording to his language was his cheer,\nAs men teach art of speech both there and here;\nAlbeit that I cannot ape his style,\nNor can I climb across so high a stile,\nYet sky I this, as to his broad intent,\nTo this amounts the whole of what he meant,\nIf so be that I have it yet in mind.\nHe said: The king of Araby and Ind,\nMy liege-lord, on this great and festive day\nSalutes you as he now best can and may,\nAnd sends to you, in honour of your feast,\nBy me, that am prepared for your behest,\nThis steed of brass, that easily and well\nCan, in one natural day ('tis truth I tell),\nThat is to say, in four and twenty hours,\nWhere'er you please, in drought or else in showers,\nBear you in body unto every place\nTo which your heart wills that you go apace,\nWithout least hurt to you, through foul or fair;\nOr, if you please to fly as high in air\nAs does an eagle when he wills to soar,\nThis self-same steed will bear you evermore\nWithout least harm, till you have gained your quest,\nAlthough you sleep upon his back, or rest;\nAnd he'll return, by twisting of a pin.\nHe that made this could make full many a gin;\nHe waited, watching many a constellation\nBefore he did contrive this operation;\nAnd he knew many a magic seal and band.\nThis mirror, too, which I have in my hand,\nHas power such that in it men may see\nWhen there shall happen any adversity\nUnto your realm, and to yourself also;\nAnd openly who is your friend or foe.\nMore than all this, if any lady bright\nHas set her heart on any kind of wight,\nIf he be false she shall his treason see,\nHis newer love and all his subtlety\nSo openly that nothing can he hide.\nWherefore, upon this pleasant summertide,\nThis mirror and this ring, which you may see,\nHe has sent to my Lady Canace,\nYour most surpassing daughter, who is here.\nThe virtue of the ring, if you will hear,\nIs this: that if she pleases it to wear\nUpon her thumb, or in her purse to bear,\nThere is no bird that flies beneath the heaven\nBut she shall understand his language, even\nTo know his meaning openly and plain,\nAnd answer him in his own words again.\nAnd every herb that grows upon a root\nShe shall know, too, and whom 'twill heal, to boot,\nAlthough his wounds be never so deep and wide.\nThis naked sword that's hanging by my side\nSuch virtue has that any man you smite,\nRight through his armour will it carve and bite,\nWere it as thick as is a branching oak;\nAnd that man who is wounded by its stroke\nShall never be whole until you please, of grace,\nTo strike him with the flat in that same place\nWhere he is hurt; which is to say, 'tis plain,\nThat you may with the flat sword blade again\nStrike him upon the wound and it will close;\nThis is the truth, I seek not to impose,\nFor it shall fail not while it's in your hold.\nAnd when this knight had thus his message told,\nHe rode out of the hall and did alight.\nHis steed, which shone as sun does, and as bright,\nStood in the courtyard, still as any stone.\nThis knight was to a chamber led anon,\nAnd was unarmed, and there at meat sat down.\nThe gifts were brought and royally were shown.\nThat is to say, the sword and glass of power,\nAnd borne anon into the donjon tower\nBy certain officers detailed thereto;\nThe ring to Canace was borne also\nWith ceremony, where she sat at table.\nBut certainly, it is no lie or fable,\nThe horse of brass could no way be removed;\nIt stood as it were glued to ground. 'Twas proved\nThere was no man could lead it out or drive\nWith any windlass that he might contrive.\nAnd why? Because they hadn't craft to heave it.\nAnd therefore in that place they had to leave it\nUntil the knight had taught them the manner\nOf moving it, as you'll hereafter hear.\nGreat was the press of people to and fro\nSwarming to see this horse that stood there so;\nFor it so high was, and so broad and long,\nSo well proportioned as to be most strong,\nJust as it were a steed of Lombardy;\nTherewith as horselike and as quick of eye\nAs if a gentle Apulian courser 'twere.\nFor truly, from his tail unto his ear\nNature nor art could better nor amend\nIn any wise, as people did contend.\nBut evermore their greatest wonder was,\nHow it could go, being made all of brass;\nIt was of Faery, as to people seemed.\nAnd divers folk diversely of it deemed;\nSo many heads, so many wits, one sees.\nThey buzzed and murmured like a swarm of bees,\nAnd played about it with their fantasy,\nRecalling what they'd learned from poetry;\nLike Pegasus it was that mounted high,\nThat horse which had great wings and so could fly;\nOr else it was the horse of Greek Sinon\nWho brought Troy to destruction, years agone.\nAs men in these old histories may read.\nMy heart, said one, is evermore in dread;\nI think some men-at-arms are hid therein\nWho have in mind this capital to win.\nIt were right well that of such things we know.\nAnother whispered to his fellow, low,\nAnd said: He lies, for it is rather like\nSome conjured up appearance of magic,\nWhich jugglers practise at these banquets great.\nOf sundry doubts like these they all did treat,\nAs vulgar people chatter commonly\nOf all things that are made more cunningly\nThan they San in their ignorance comprehend;\nThey gladly judge they're made for some base end.\nAnd some much wondered on the mirror's power,\nThat had been borne up to the donjon tower,\nAnd how men in it such strange things could see.\nAnother answered, saying it might be\nQuite natural, by angles oddly spaced\nAnd sly reflections thus within it placed,\nAnd said, at Rome was such a one, men know.\nThey spoke of Alhazen and Vitello\nAnd Aristotle, who wrote, in their lives,\nOn mirrors strange and on perspectives,\nAs all they know who've read their published word.\nAnd other folk did wonder on the sword\nThat had the power to pierce through anything;\nAnd so they spoke of Telephus the king,\nAnd of Achilles with his magic spear,\nWherewith he healed and hurt too, 'twould appear,\nEven as a man might do with this new sword\nOf which, but now, I've told and you have heard.\nThey spoke of tempering metal sundry wise,\nAnd medicines therewith, which men devise,\nAnd. how and when such steel should hardened be;\nWhich, nevertheless, is all unknown to me.\nThen spoke they of fair Canace's gold ring,\nAnd all men said that such a wondrous thing\nThey'd ne'er heard of as being in ring-craft done,\nExcept that Moses and King Solomon\nHad each a name for cunning in such art.\nThus spoke the people and then drew apart,\nBut notwithstanding, some said that it was\nWondrous to make fern-ashes into glass,\nSince glass is nothing like the ash of fern;\nBut since long since of this thing men did learn,\nTherefore they ceased their gabble and their wonder,\nAs sorely wonder some on cause of thunder,\nOf ebb, of flood, of gossamer, of mist,\nAnd each thing, till they know what cause exist.\nThus did they chatter and judge and thus surmise\nUntil the king did from the board arise.\nPhoebus had left the angle meridional,\nAnd yet ascending was that beast royal,\nThe noble Lion, with his Aldiran,\nWhen that this Tartar king, this Cambinskan\nRose from his board where he had sat full high.\nBefore him went the sounding minstrelsy,\nInto a room hung with rich ornaments,\nWherein they sounded divers instruments\nTill it was like a heavenly thing to hear.\nAnd now danced merry Venus' children dear,\nFor in the Fish their lady sat on high\nAnd looked upon them with a friendly eye.\nThis noble king sat high upon his throne.\nAnd this strange knight was brought to him anon,\nAnd then to dance he went with Canace.\nHere was such revel and such jollity\nAs no dull man is able to surmise;\nHe must have known and served love's high emprise,\nAnd be a festive man as fresh as May\nWho could for you describe such an array.\nWho could tell you the figures of the dances,\nSo odd and strange and the blithe countenances,\nThe subtle glances and dissimulation\nFor fear of jealous persons' observation?\nNo man but Launcelot, and he is dead!\nI therefore pass the joyous life they led\nAnd saw no more, but in this jolliness\nI leave them till to supper all did press.\nThe steward bade them serve the spices, aye,\nAnd the rich wine through all this melody.\nThe ushers and the squires got them gone;\nThe spices and the wine were come anon.\nThey ate and drank, and when this had an end,\nUnto the temple, as was right, did wend.\nThe service done, they supped while yet 'twas day.\nWhat needs it that I tell all their array?\nEach man knows well that at a kingly feast\nThere's plenty for the greatest and the least,\nAnd dainties more than are in my knowing.\nThen, after supper, went this noble king\nTo see the horse of brass, with all the rout\nOf lords and ladies thronging him about.\nSuch wondering was there on this horse of brass\nThat, since the siege of Troy did overpass,\nWhen once a horse seemed marvellous to men.\nWas there such wondering as happened then.\nBut finally the king asked of this knight\nThe virtue of this courser, and the might,\nAnd prayed him tell the means of governance.\nThis horse anon began to trip and dance\nWhen this strange knight laid hand upon the rein\nAnd said: Sire, there's no more I need explain\nThan, when you wish to journey anywhere,\nYou must but twirl a peg within his ear,\nWhich I will show you when alone with you.\n\nYou must direct him to what place also,\nOr to what country you may please to ride.\nAnd when you come to where you would abide,\nBid him descend, and twirl another pin,\nFor therein lies the secret of the gin,\nAnd he will then descend and do your will;\nAnd there he'll stand, obedient and still.\nThough all the world the contrary had sworn,\nHe shall not thence be drawn nor thence be borne.\nOr, if you wish to bid him thence be gone,\nTwirl but this pin and he'll depart anon\nAnd vanish utterly from all men's sight,\nAnd then return to you, by day or night,\nWhen you shall please to call him back again\nIn such a fashion as I will explain\nWhen we two are alone, and that full soon.\nRide when you choose, there's no more to be done.\nInstructed when the king was by that knight,\nAnd when he'd stablished in his mind aright\nThe method and the form of all this thing,\nThen glad and blithe this noble doughty king\nRepaired unto his revels as before.\nThe bridle to the donjon tower they bore,\nAnd placed among his jewels rich and dear.\nHow I know not, the horse did disappear\nOut of their sight; you get no more of me.\nBut thus I leave, in joy and jollity,\nThis Cambinskan with all his lords feasting\nWell nigh until the day began to spring.\nExplicit prima pars.\nSequitur pars secunda.\nThe nurse of good digestion, natural sleep,\nCaused them to nod, and bade them they take keep\nThat labour and much drinking must have rest;\nAnd with a gaping mouth all these he pressed,\nAnd said that it was time they laid them down,\nFor blood was in the ascendant, as was shown,\nAnd nature's friend, the blood, must honoured be.\nThey thanked him, gaping all, by two, by three,\nAnd every one began to go to rest,\nAs sleep them bade; they took it for the best.\nBut here their dreams shall not by me be said;\nThe fumes of wine had filled each person's head,\nWhich cause senseless dreams at any time.\nThey slept next morning till the hour of prime,\nThat is, the others, but not Canace;\nShe was right temperate, as women be.\nFor of her father had she taken leave,\nTo go to rest, soon after it was eve;\nFor neither pale nor languid would she be,\nNor wear a weary look for men to see;\nBut slept her first deep sleep and then awoke.\nFor so much joy upon her heart there broke\nWhen she looked on the mirror and the ring\nThat twenty times she flushed, and sleep did bring-\nSo strong an impress had the mirror made-\nA vision of it to the slumbering maid.\nWherefore, ere up the sun began to glide,\nShe called her mistress, sleeping there beside,\nAnd said to her that she was pleased to rise.\nOld women like this governess are wise,\nOr often so, and she replied anon,\nAnd said: My lady, where will you be gone\nThus early? For the folk are all at rest.\nI will, said she, arise, for I've no zest\nFor longer sleep, and I will walk about.\nHer mistress called of women a great rout,\nAnd they rose up, a dozen more or less,\nAnd up rose lovely Canace to dress,\nAs ruddy and bright as is the warm young sun\nThat in the Ram now four degrees has run;\nHe was no higher when she all ready was;\nAnd forth she sauntered at an easy pace,\nArrayed according to the season sweet,\nLightly, to play and walk on maiden feet;\nWith five or six girls of her company\nAll down an alley, through the park, went she.\nThe morning mists that rose from the damp earth\nReddened the sun and broadened it in girth;\nNevertheless it was so fair a sight\nThat it made all their hearts dance for delight,\nWhat of the season and the fair morning,\nAnd all the myriad birds that she heard sing;\nFor when she heard, she knew well what they meant,\nJust by their songs, and learned all their intent.\nThe point of every story, why it's told,\nIf it's delayed till interest grow cold\nIn those who have, perchance, heard it before,\nThe savour passes from it more and more,\nFor fulsomeness of its prolixity.\nAnd for this reason, as it seems to me,\nI should to my tale's major point descend\nAnd make of these girls' walking a swift end.\nAmidst a dry, dead tree, as white as chalk,\nAs Canace was playing in her walk,\nThere sat a falcon overhead full high,\nThat in a pitiful voice began to cry,\nrill all the wood resounded mournfully.\nFor she had beaten herself so pitiably\nWith both her wings that the red glistening blood\nRan down the tree trunk whereupon she stood.\nAnd ever in one same way she cried and shrieked,\nAnd with her beak her body she so pricked\nThat there's no tiger, nor a cruel beast\nThat dwells in open wood or deep forest,\nWould not have wept, if ever weep he could,\nFor pity of her, she shrieked alway so loud.\nFor never yet has been a man alive-\nIf but description I could well contrive-\nThat heard of such a falcon for fairness,\nAs well of plumage as of nobleness\nOf shape, and all that reckoned up might be.\nA falcon peregrine she was, and she\nSeemed from a foreign land; and as she stood\nShe fainted now and then for loss of blood,\nTill almost she had fallen from the tree.\nThis king's fair daughter, Princess Canace,\nWho on her finger bore the magic ring\nWhereby she understood well everything\nThat any bird might in his language say,\nAnd in such language could reply straightway,\nShe understood well what this falcon said,\nAnd of her pity well-nigh was she dead.\nSo to the tree she went right hastily,\nAnd on this falcon looked she pitifully,\nAnd held her lap up wide, for she knew now\nThe falcon must come falling from the bough\nWhen next it swooned away from loss of blood.\nA long while waiting there the princess stood,\nTill at the last she spoke, in her voice clear,\nUnto the hawk, as you'll hereafter hear.\nWhat is the cause, if it be one to tell,\nThat you are in this furious pain of hell?\nSaid Canace unto this hawk above.\nIs this for sorrow of death or loss of love?\nFor, as I think, these are the causes two\nThat torture gentle heart with greatest woe;\nOf other ills there is no need to speak,\nBecause such harm upon yourself you wreak;\nWhich proves right well that either love or dread\nMust be the reason for your cruel deed,\nSince I can see no one that gives you chase.\nFor love of God, come, do yourself some grace,\nOr say what thing may help; for west nor east\nHave I before now seen a bird or beast\nThat ever treated self so wretchedly.\nYou slay me with your sorrow, verily,\nSuch great compassion in my heart has grown.\nFor God's dear love, come from the dry tree down;\nAnd, as I am a monarch's daughter true,\nIf I but verily the real cause knew\nOf your distress, if it lay in my might,\nI would make you amends before the night,\nAs truly help me God of human kind!\nAnd even now will I look out and find\nSome herbs to heal your hurts with, speedily.\nThen shrieked this falcon the more piteously\nThan ever, and to ground fell down anon,\nAnd lay there, swooning, deathlike as a stone,\nTill Canace within her lap did take\nAnd hold the bird till she began to wake.\nAnd when from out her fainting fit she made,\nAll in her own hawk's language thus she said:\nThat pity wells up soon in gentle heart,\nFeeling its likeness in all pains that smart,\nIs proved, and day by day, as men may see,\nAs well by deeds as by authority;\nFor gentle heart can spy out gentleness.\nI see well that you have on my distress\nCompassion, my fair Princess Canace,\nOf truly womanly benignity\nThat nature in your character has set.\nNot that I hope much good therefrom to get,\nBut to obey the word of your heart free,\nAnd so that others may be warned by me,\nAs by the whelp instructed is the lion,\nJust for that cause and reason shall I fly on,\nWhile yet I have the leisure and the space,\nThe story of my wrongs to you I'll trace.\nAnd ever, while the one her sorrow said,\nThe other wept, as she to water'd fled,\nUntil the falcon bade her to be still;\nAnd with a sigh, right thus she said her will.\nWhere I was born (alas, that cruel day!)\nAnd fostered on a rock of marble grey\nSo tenderly that nothing troubled me,\nI knew not what it was, adversity,\nTill I could soar on high under the sky.\nThere dwelt a handsome tercelet there, hard by,\nWho seemed the dwell of every nobleness;\nThough he was full of treason and falseness,\nIt was so hidden under humble bearing,\nAnd under hues of truth which he was wearing,\nAnd under kindness, never used in vain,\nThat no one could have dreamed that he could feign,\nSo deeply ingrained were his colours dyed.\nBut just as serpent under flower will hide\nUntil he sees the time has come to bite,\nJust so this god of love, this hypocrite\nWith false humility for ever served\nAnd seemed a wooer who the rites observed\nThat so become the gentleness of love.\nAs of a tomb the fairness is above,\nWhile under is the corpse, such as you know,\nSo was this hypocrite, cold and hot also;\nAnd in this wise he served his foul intent\nThat (save the Fiend) no one knew what he meant,\nTill he so long had wept and had complained,\nAnd many a year his service to me feigned,\nThat my poor heart, a pitiful sacrifice,\nAll ignorant of his supreme malice,\nFearing he'd die, as it then seemed to me,\nBecause of his great oaths and surety,\nGranted him love, on this condition known,\nThat evermore my honour and renown\nWere saved, both private fame and fame overt;\nThat is to say, that, after his desert\nI gave him all my heart and all my thought-\nGod knows, and he, that more I gave him naught-\nAnd took his heart in change for mine, for aye.\nBut true it is, and has been many a day,\nA true man and a thief think not at one.\nAnd when he saw the thing so far was gone\nThat I had fully granted him my love,\nIn such a way as I've explained above,\nAnd given him my faithful heart, as free\nAs he swore he had given his to me,\nAnon this tiger, full of doubleness,\nFell on his knees, devout in humbleness,\nWith so high reverence, and, by his face,\nSo like a lover in his gentle grace,\nSo ravished, as it seemed, for very joy,\nThat never Jason nor Paris of Troy-\nJason? Nay, truly, nor another man\nSince Lamech lived, who was the first began\nTo love two women (those that write have sworn),\nNot ever, since the primal man was born,\nCould any man, by twenty-thousandth part,\nEnact the tricks of this deceiver's art;\nNor were he worthy to unlace his shoe,\nWhere double-dealing or deceit were due,\nNor could so thank a person as he me!\nHis manner was most heavenly to see,\nFor any woman, were she ever so wise;\nSo painted he, and combed, at point-device,\nHis manner, all in all, and every word.\nAnd so much by his bearing was I stirred\nAnd for the truth I thought was in his heart,\nThat, if aught troubled him and made him smart,\nThough ever so little bit, and I knew this,\nIt seemed to me I felt death's cruel kiss.\nAnd briefly, so far all these matters went,\nMy will became his own will's instrument;\nThat is to say, my will obeyed his will\nIn everything in reason, good or ill,\nKeeping within the bounds of honour ever.\nNever had I a thing so dear- ah, never!-\nAs him, God knows! nor ever shall anew.\nThis lasted longer than a year or two\nWhile I supposed of him no thing but good.\nBut finally, thus at the last it stood,\nThat Fortune did decree that he must win\nOut of that place, that home, that I was in.\nWhether I felt woe, there's no question, none;\nI can't describe my feelings, no, not one;\nBut one thing dare I tell, and that boldly,\nI came to know the pain of death thereby;\nSuch grief I felt for him, none might believe.\nSo on a day of me he took his leave,\nSo sorrowfully, too, I thought truly\nThat he felt even as deep a woe as I,\nWhen I had heard him speak and saw his hue.\nNevertheless, I thought he was so true,\nAnd that to me he would come back again\nWithin a little while, let me explain;\nAnd 'twas quite reasonable that he must go\nFor honour's sake, for oft it happens so,\nThat I made virtue of necessity,\nAnd took it well, because it had to be.\nA look of cheer I felt not I put on,\nAnd took his hand, I swear it by Saint John.\nAnd said to him: 'Behold, I'm yours in all;\nBe you to me as I have been, and shall.'\nWhat he replied it needs not I rehearse,\nWho can say better than he, who can do worse?\nWhen he had well said, all his good was done.\n'It well behooves him take a lengthy spoon\nWho eats with devils,' so I've heard folk say.\nSo at the last he must be on his way,\nAnd forth he flew to where it pleased him best\nWhen it became his purpose he should rest,\nI think he must have had this text in mind,\nThat 'Everything, returning to its kind,\nGladdens itself'; thus men say, as I guess;\nMen love, and naturally, newfangledness,\nAs do these birds that men in cages feed.\nFor though you night and day take of them heed,\nAnd fairly strew their cage as soft as silk,\nAnd give them sugar, honey, bread, and milk,\nYet on the instant when the door is up,\nThey with their feet will spurn their feeding cup,\nAnd to the wood will fly and worms will eat;\nSo are they all newfangled of their meat,\nAnd love all novelties of their own kind;\nNor nobleness of blood may ever bind.\nSo fared this tercelet, oh, alas the day!\nThough he was gently born, and fresh and gay,\nAnd handsome, and well-mannered, aye and free,\nHe saw a kite fly, and it proved a she,\nAnd suddenly he loved this she-kite so\nThat all his love for me did quickly go,\nAnd all his truth turned falsehood in this wise;\nThus has this kite my love in her service,\nAnd I am love-lorn without remedy.\nAnd with that word the hawk began to cry,\nAnd after, swooned on Canace's fair arm.\nGreat was the sorrow for the falcon's harm\nThat Canace and all her women made;\nThey knew not how they might this falcon aid.\nBut Canace home bore her in her lap,\nAnd softly her in poultices did wrap\nWhere she with her own beak had hurt herself.\nNow Canace dug herbs more rich than pelf\nOut of the ground, and made up ointments new\nOf precious herbs, all beautiful of hue,\nWherewith to heal this hawk; from day to night\nShe nursed her carefully with all her might.\nAnd by her bed's head she contrived a mew\nAnd lined the cage with velvets all of blue,\nSymbol of truth that is in women seen.\nAnd all without, the mew was painted green,\nAnd there were painted all these treacherous fowls\nAs are these titmice, tercelets, and these owls,\nWhile for despite were painted there beside\nMagpies, that they might cry at them and chide.\nThus leave I Canace her hawk keeping,\nI will no more, just now, speak of her ring,\nTill I come back with purpose to explain\nHow this poor falcon got her love again\nRepentant, as the story tells to us,\nBy mediation of that Cambalus,\nThe king's son, of whom I've already told.\nBut henceforth I a straightened course will hold\nGreat battles and adventures to relate,\nWhereof were never heard such marvels great.\nFirst will I tell you of King Cambinskan\nWho won so many a town and many a man;\nAnd after will I speak of Algarsyf,\nHow he won Theodora for his wife,\nFor whom full oft in peril great he was,\nHad he been helped not by the steed of brass;\nAnd after that I'll speak of Cambalo,\nWho in the lists fought with the brothers two\nFor Canace, before he could her win.\nAnd where I left off, I'll again begin.\nExplicit secunda pars.\nIncipit pars tercia.\nApollo in his chariot whirled so high\nThat in the God Mercurius' house, the sly--\n\n\n### The Words of Franklin and the Host\n\nIn faith, sir squire, you have done well with it,\nAnd openly I praise you for your wit,\nThe franklin said, Considering your youth,\nSo feelingly you speak, sir, in good truth!\nIn my opinion, there is none that's here\nIn eloquence shall ever be your peer,\nIf you but live; may God give you good chance\nAnd in all virtue send continuance!\nFor, sir, your speech was great delight to me.\nI have a son, and by the Trinity\nI'd rather have, than twenty pounds in land,\nThough it were right now fallen to my hand,\nHe were a man of such discretion shown\nAs you, sir; fie on what a man may own,\nUnless the man have virtue therewithal.\nI've checked my son, and yet again I shall,\nFor he toward virtue chooses not to wend;\nBut just to play at dice, and gold to spend,\nAnd lose all that he has, is his usage.\nAnd he would rather talk with any page\nThan to commune with any gentle wight\nFrom whom he might, learn courtesy aright.\nA straw for courtesy! exclaimed our host;\nWhat, franklin? Gad, sir, well you know, I trust,\nThat each of you must tell us, at the least,\nA tale or two, or break his sworn behest.\nI know it, said the franklin; I am fain,\nAnd pray you all, you do not me disdain,\nThough to this man I speak a word or two.\nCome, tell your tale, sir, without more ado.\nGladly, sir host, said he, I will obey\nYour will, good host; now hearken what I say.\nFor I'll not be contrary in any wise,\nAt least so far as my wit shall suffice;\nI pray to God that it may please you; rough\nThough it may be, I'll know 'tis good enough.\n\n\n### The Franklin's Prologue\n\nThese ancient gentle Bretons, in their days,\nOf divers high adventures made great lays\nAnd rhymed them in their primal Breton tongue,\nThe which lays to their instruments they sung,\nOr else recited them where joy might be;\nAnd one of them have I in memory,\nWhich I shall gladly tell you, as I can.\nBut, sirs, because I am an ignorant man,\nAt my beginning must I first beseech\nYou will excuse me for my vulgar speech;\nI never studied rhetoric, that's certain;\nThat which I say, it must be bare and plain.\nI never slept on Mount Parnassus, no,\nNor studied Marcus Tullius Cicero.\nColours I know not, there's no doubt indeed,\nSave colours such as grow within the mead,\nOr such as men achieve with dye or paint.\nColours of rhetoric I find but quaint;\nMy spirit doesn't feel the beauty there.\nBut if you wish, my story you shall hear.\n\n\n### The Franklin's Tale\n\nIn old Armorica, now Brittany,\nThere was a knight that loved and strove, did he\nTo serve a lady in the highest wise;\nAnd many a labour, many a great emprise\nHe wrought for her, or ever she was won.\nFor she was of the fairest under sun,\nAnd therewithal come of so high kindred\nThat scarcely could this noble knight, for dread,\nTell her his woe, his pain, and his distress.\nBut at the last she, for his worthiness,\nAnd specially for his meek obedience,\nHad so much pity that, in consequence,\nShe secretly was come to his accord\nTo take him for her husband and her lord,\nOf such lordship as men have over wives;\nAnd that they might be happier in their lives,\nOf his free will he swore to her, as knight,\nThat never in his life, by day or night,\nWould he assume a right of mastery\nAgainst her will, nor show her jealousy,\nBut would obey and do her will in all\nAs any lover of his lady shall;\nSave the name and show of sovereignty,\nThose would he have, lest he shame his degree\nShe thanked him, and with a great humbleness\nShe said: Since, sir, of your own nobleness\nYou proffer me to have so loose a rein\nWould God there never come between us twain,\nFor any guilt of mine, a war or strife.\nSir, I will be your humble, faithful wife,\nTake this as truth till heart break in my breast.\nThus were they both in quiet and in rest.\nFor one thing, sirs, I safely dare to say,\nThat friends each one the other must obey\nIf they'd be friends and long keep company.\nLove will not be constrained by mastery;\nWhen mastery 'comes, the god of love anon\nBeats his fair wings, and farewell! He is gone!\nLove is a thing as any spirit free;\nWomen by nature love their liberty,\nAnd not to be constrained like any thrall,\nAnd so do men, if say the truth I shall.\nObserve who is most patient in his love,\nHe is advantaged others all above.\nPatience is virtue high, and that's certain;\nFor it does vanquish, as these clerks make plain,\nThings that oppression never could attain.\nOne must not chide for trifles nor complain.\nLearn to endure, or else, so may I go,\nYou'll have to learn it, whether you will or no.\nFor in this world, it's certain, no one is\nWho never does or says sometimes amiss.\nSickness, or woe, or what the stars have sent,\nAnger, or wine, or change of temperament\nCauses one oft to do amiss or speak.\nFor every wrong one may not vengeance wreak;\nConditions must determine temperance\nIn all who understand good governance.\nAnd therefore did this wise and worthy knight,\nTo live in quiet, patience to her plight,\nAnd unto him full truly did she swear\nThat never should he find great fault in her.\nHere may men see an humble wise accord;\nThus did she take her servant and her lord,\nServant in love and lord in their marriage;\nSo was he both in lordship and bondage;\nIn bondage? Nay, but in lordship above,\nSince he had both his lady and his love;\nHis lady truly, and his wife also,\nTo which the law of love accords, we know.\nAnd when he was in this prosperity,\nHome with his wife he went to his country,\nNot far from Penmarch, where his dwelling was.\nAnd there he lived in bliss and all solace.\nWho could relate, save those that wedded be,\nThe joy, the ease, and the prosperity\nThat are between a husband and a wife?\nA year and more endured this blissful life,\nUntil the knight, of whom I've spoken thus,\nWho at Kayrrud I was called Arviragus,\nArranged to go and dwell a year or twain\nIn England, which was then known as Britain,\nTo seek in arms renown and great honour;\nFor his desire was fixed in such labour;\nAnd there he lived two years (the book says thus).\nNow will I hold from this Arviragus,\nAnd I will speak of Dorigen his wife,\nWho loved her husband as her heart's own life.\nFor all his absence wept she and she sighed,\nAs noble wives do at a lone fireside.\nShe mourned, watched, wailed, she fasted and complained;\nDesire for him so bound her and constrained,\nThat all this wide world did she set at naught.\nHer friends, who knew her grief and heavy thought,\nComforted her as they might do or say;\nThey preached to her, they told her night and day\nThat for no cause she killed herself, alas!\nAnd every comfort possible in this pass\nThey gave to her, in all their busyness,\nTo make her thus put by her heaviness.\nWith passing time, as you know, every one,\nMen may so long with tools engrave a stone\nThat thereon will some figure printed be.\nAnd so long did they comfort her that she\nReceived at last, by hope and reason grown,\nImprinted consolations as her own,\nWhereby her sorrow did somewhat assuage;\nShe could not always live in such a rage.\nAnd, then, Arviragus, through all her care,\nHad sent her letters home, of his welfare.\nAnd that he would come speedily again;\nOtherwise had this sorrow her heart slain.\nHer friends saw that her grief began to slake,\nAnd prayed her on their knees, for dear God's sake,\nTo come and wander in their company\nAnd drive away her gloomy fantasy.\nAnd finally she granted that request;\nFor well she saw that it was for the best.\nNow stood her castle very near the sea,\nAnd often with her good friends wandered she\nFor pleasure on the cliffs that reared so high,\nWhence she saw many a ship and barge go by,\nSailing their courses where they wished to go;\nBut that was part and parcel of her woe.\nFor to herself full oft, Alas! said she,\nIs there no ship, of many that I see,\nWill bring me home my lord? Then were my heart\nRecovered of its bitter pains that smart.\nAt other times there would she sit and think,\nAnd cast her two eyes downward from the brink.\nBut when she saw the grisly rocks all black,\nFor very fear her heart would start aback\nAnd quake so that her feet would not sustain\nHer weight. Then on the grass she'd sit again\nAnd piteously upon the sea she'd stare,\nAnd say, with dull sighs on the empty air:\nEternal God, Who by Thy providence\nLeadest the world with a true governance,\nIdly, as men say, dost Thou nothing make;\nBut, Lord, these grisly, fiendish rocks, so black,\nThat seem but rather foul confusion thrown\nAwry than any fair world of Thine own,\nAye of a perfect wise God and stable,\nWhy hast Thou wrought this insane work, pray tell?\nFor by this work, north, south, and west and east,\nThere is none nurtured, man, nor bird, nor beast;\nIt does no good, to my mind, but annoys.\nSee'st Thou not, Lord, how mankind it destroys?\nA hundred thousand bodies of mankind\nHave died on rocks, whose names are not in mind,\nAnd man's a creature made by Thee most fair,\nAfter Thine image, as Thou didst declare.\nThen seemed it that Thou had'st great charity\nToward mankind; but how then may it be\nThat Thou hast wrought such means man to destroy,\nWhich means do never good, but ever annoy?\nI know well, clerics gladly do attest,\nBy arguments, that all is for the best,\nThough I can never the real causes know.'\nBut O Thou God Who made'st the wind to blow,\nKeep Thou my lord! This is my argument;\nTo clerks I leave disputing on what's meant.\nBut O would God that all these rocks so black\nWere sunken down to Hell for my lord's sake!\nThese rocks, they slay my very heart with fear.\nThus would she say, with many a piteous tear.\nHer friends saw that to her it was no sport\nTo wander by the sea, but discomfort;\nAnd so arranged to revel somewhere else.\nThey led her along rivers and to wells,\nAnd such delightful places; and told fables,\nAnd danced, and played at chess, and played at tables.\nSo on a day, all in the morningtide,\nUnto a garden which was there beside,\nWherein they'd given command that there should be\nFood and whatever else was necessary,\nThey went for pleasure all the livelong day.\nAnd this was on the morning sixth of May,\nAnd May had painted with his soft warm showers\nThis garden full of foliage and of flowers;\nAnd work of man's hand had so curiously\nArrayed this lovely garden, truthfully,\nThat never was another of such price,\nUnless it were the very Paradise.\nThe scent of flowers and the fair fresh sight\nWould have made any heart dance for delight\nThat e'er was born, unless too great sickness\nOr too great sorrow held it in distress;\nSo full it was of beauty and pleasance.\nAfter their dinner all began to dance,\nAnd sing, also, save Dorigen alone,\nWho made alway her same complaint and moan.\nFor him she saw not through the dancing go,\nWho was her husband and her love also.\nNevertheless, she must a time abide,\nAnd with good hope held, let her sorrow slide.\nAmid these mazes, with the other men,\nThere danced a squire before this Dorigen,\nThat was more blithe, and prettier of array,\nIn my opinion, than the month of May.\nHe sang and danced better than any man\nThat is, or was, since first the world began.\nTherewith he was, description to contrive,\nOne of best conditioned men alive;\nYoung, strong, right virtuous, and rich, and wise,\nAnd well beloved, and one to idealize.\nAnd briefly, if I tell the truth withal,\nUnknown to Dorigen- nay, least of all-\nThis pleasant squire, servant to Queen Venus,\nThe name of whom was this, Aurelius,\nHad loved her best of anyone alive\nTwo years and more (since she did first arrive),\nBut never dared he tell her of his state;\nWithout a cup he drank his draught of fate.\nHe had despaired, for nothing dared he say,\nSave that in songs he would somewhat betray\nHis woe, as of a general complaint;\nHe loved, but none loved him, though he went faint.\nOf such a subject made he many lays,\nSongs and complaints, rondels and virelays,\nHow that he dared not his deep sorrow tell,\nBut languished, as a fury does in Hell;\nAnd die he must, he said, as did Echo\nFor her Narcissus, daring not tell her woe.\nIn other manner than you hear me say\nDared he not unto her his woe betray;\nSave that, perchance, there would be times at dances,\nWhere young folk honoured all that makes romances,\nIt may well be he looked upon her face\nIn such wise as a man who sued for grace;\nBut nothing knew she of his love's intent.\nNevertheless it chanced, ere thence they went,\nBecause it happened he was her neighbour,\nAnd was a man of worship and honour,\nAnd she had known him in the time of yore,\nThey fell to talking; and so, more and more,\nUnto his purpose drew Aurelius,\nAnd when he saw his time addressed her thus:\nMadam, said he, by God Who this world made,\nSo that I knew it might your sad heart aid,\nI would, that day when your Arviragus\nWent overseas, that I, Aurelius,\nHad gone whence never I should come again;\nFor well I know. service is in vain.\nMy guerdon is the breaking of my heart;\nMadam, have pity on my pains that smart;\nFor with a word you may slay me or save,\nHere at your feet would God I found my grave!\nTime to say more, at present naught have I;\nHave mercy, sweet, or you will make me die!\nSo then she looked upon Aurelius:\nIs this your will? asked she, And say you thus?\nNever before have I known what you meant.\nBut since, Aurelius, I know your intent,\nBy that same God Who gave me soul and life,\nNever shall I become an untrue wife\nIn word or deed, so far as I have wit:\nI will remain his own to whom I'm knit;\nTake this for final answer as from me.\nBut after that she said thus, sportively:\nAurelius, said she, by God above,\nYet would I well consent to be your love,\nSince I hear you complain so piteously,\nOn that day when, from coasts of Brittany,\nYou've taken all the black rocks, stone by stone,\nSo that they hinder ship nor boat- I own,\nI say, when you have made the coast so clean\nOf rocks that there is no stone to be seen,\nThen will I love you best of any man;\nTake here my promise- all that ever I can.\nIs there no other grace in you? asked he.\nNo, by that Lord, said she, Who has made me!\nFor well I know that it shall ne'er betide.\nLet suchlike follies out of your heart slide.\nWhat pleasure can a man have in his life\nWho would go love another man's own wife,\nThat has her body when he wishes it?\nDeep sighs Aurelius did then emit;\nWoe was Aurelius when this he heard,\nAnd with a sorrowful heart he thus answered:\nMadam, said he, this were impossible!\nThen must I die a sudden death and fell.\nAnd with that word he turned away anon.\nThen came her other friends, and many a one,\nAnd in the alleys wandered up and down,\nAnd nothing knew of this decision shown,\nBut suddenly began to dance anew\nUntil the bright sun lost his golden hue;\nFor the horizon had cut off his light;\nThis is as much as saying, it was night.\nAnd home they went in joy and with solace,\nExcept the wretch Aurelius, alas!\nHe to his house went with a woeful heart;\nHe saw he could not from his near death part.\nIt seemed to him he felt his heart grow cold;\nUp toward Heaven his two hands did he hold,\nAnd on his bare knees did he kneel him down\nAnd in his raving said his orison.\nFor very woe out of his wits he fled.\nHe knew not what he spoke, but thus he said;\nWith mournful heart his plaint had he begun\nUnto the gods, and first unto the sun.\nHe said: Apollo, governor and god\nOf every plant, herb, tree, and flower in sod,\nThat givest, according to thy declination,\nTo each of them its time of foliation,\nAll as thy habitation's low or high,\nLord Phoebus, cast thy merciful bright eye\nOn wretched Aurelius, who is lost and lorn.\nLo, Lord! My lady has my swift death sworn,\nWithout my guilt, save thy benignity\nUpon my dying heart have some pity!\nFor well I know, Lord Phoebus, if you lest,\nYou can thus aid me, save my lady, best.\nNow vouchsafe that I may for you devise\nA plan to help me, telling in what wise.\nYour blessed sister, Lucina, serene,\nThat of the sea is goddess chief and queen\n(Though Neptune is the deity in the sea,\nYet empress set above him there is she).\nYou know well, Lord, that just as her desire\nIs to be quickened and lighted by your fire,\nFor which she follows you right busily,\nJust so the sea desires, and naturally,\nTo follow her, she being high goddess\nBoth of the sea and rivers, great and less.\nWherefore, Lord Phoebus, this request I make-\nWithout this miracle, my heart will break-\nThat at the time of your next opposition,\nWhich will be in the Lion, make petition\nTo her that she so great a flood will bring\nThat full five fathoms shall it over-spring\nThe highest rock in Armoric Brittany;\nAnd let this flood endure two years for me;\nThen truly to my lady may I say:\n'Now keep your word, the rocks are gone away.'\n\nLord Phoebus, do this miracle for me;\nPray her she run no faster course, being free-\nI say, Lord, pray your sister that she go\nNo faster course than you these next years two.\nThen shall she be even at the full alway,\nAnd spring-flood shall endure both night and day.\nAnd save she vouchsafe, Lord, in such manner\nTo grant to me my sovereign lady dear,\nPray her to sink, then, every rock far down\nInto that region dark and cold, her own,\nUnder the earth, the place Pluto dwells in,\nOr nevermore shall I my lady win.\nThy temple in Delphi will I, barefoot, seek;\nLord Phoebus, see the tears upon my cheek,\nAnd on my pain be some compassion shown.\nAnd with that word in swoon he tumbled down,\nAnd for a long time lay there in a trance.\nHis brother, who knew all his suppliance,\nFound him, and took him, and to bed him brought.\nDespairing in the torment of his thought,\nLet I this woeful fellow-creature lie,\nTo choose, for all of me, to live or die.\nArviragus, with health, in honour's hour,\nAs he that was of chivalry the flower,\nCame home again, with other gentlemen.\nO happy are you now, my Dorigen,\nWho have your pleasant husband in your arms,\nThe vigorous knight, the worthy man-at-arms,\nThat loves you as he loves his own heart's life.\nNothing he chose to question of his wife\nIf any man had said, while he was out,\nSome words of love; of her he had no doubt.\nHe tended not that way, it would appear,\nBut danced and jousted, made for her good cheer;\nAnd thus in joy and bliss I let them dwell\nAnd of love-sick Aurelius will I tell.\nIn weakness and in torment furious\nTwo years and more lay wretched Aurelius\nEre foot on earth he went- aye, even one;\nFor comfort in this long time had he none,\nSave from his brother, who was a good clerk;\nHe knew of all this woe and all this work.\nFor to no other human, 'tis certain,\nDared he his cause of illness to explain.\nIn breast he kept more secret his idea\nThan did Pamphilius for Galatea.\nHis breast was whole, with no wound to be seen,\nBut in his heart there was the arrow keen.\nAnd well you know that of a sursanure\nIn surgery is difficult the cure,\nUnless they find the dart or take it out.\nHis brother wept, and long he sought about\nTill at the last he called to remembrance\nThat while he was at Orleans in France-\nFor many young clerks are all ravenous\nTo read of arts that are most curious,\nAnd into every nook and cranny turn\nParticular strange sciences to learn-\nHe thus recalled that once upon a day,\nAt Orleans, while studying there, I say,\nA book of natural magic there he saw\nIn a friend's room, a bachelor of law\n(Though he was there to learn another craft),\nWhich book he'd privately on his desk left;\nAnd which book said much of the operations\nTouching the eight and twenty variations\nThat designate the moon, and such folly\nAs is, in our days, valued not a fly;\nFor Holy Church provides us with a creed\nThat suffers no illusion to mislead.\nAnd when this book came to his remembrance,\nAt once, for joy, his heart began to dance,\nAnd to himself he said in privacy:\nMy brother shall be healed, and speedily;\nFor I am sure that there are sciences\nWhereby men make divers appearances,\nSuch as these prestidigitators play.\nFor oft at feasts, have I well heard men say\nThat jugglers, in a hall both bright and large,\nHave made come in there, water and a barge,\nAnd in the hall the barge rowed up and down.\nSometimes there seemed to come a grim lion;\nAnd sometimes flowers sprang as in a mead;\nOr vines with grapes both red and white indeed;\nSometimes a castle built of lime and stone;\nAnd when they wished it disappeared anon.\nThus seemed these things to be in each man's sight.\nNow, then, conclude I thus, that if I might\nAt Orleans some old school-fellow find,\nWho has these mansions of the moon in mind,\nOr other natural magic from above,\nHe could well make my brother have his love.\nFor with a mere appearance clerks may make\nIt seem in man's sight that all rocks that break\nThe seas of Brittany were banished, so\nThat right above them ships might come and go,\nAnd in such wise endure a week or two;\nThen were my brother cured of all his woe.\nFor she must keep the word she gave at feast.\nOr he'll have right to shame her, at the least.\nWhy should I longer speak of this event?\nHe to the bedside of his brother went,\nAnd urged him eagerly to get him gone\nTo Orleans; he started up anon\nAnd forward on his way at once did fare\nIn hope to be relieved of all his care.\nWhen they were come almost to that city,\nPerhaps two furlongs short of it, or three,\nA young clerk walking by himself they met,\nWho, in good Latin, heartily did greet,\nAnd after that he said a wondrous thing.\nI know, said he, the cause of your coming.\nAnd ere a farther foot the brothers went,\nHe told them all the soul of their intent.\nThis Breton clerk asked after school-fellows\nWhom he had known through former suns and snows;\nAnd he replied to this that dead they were,\nWhereat he wept, for sorrow, many a tear.\nDown from his horse Aurelius leaped anon,\nAnd onward with this wizard he was gone\nHome to his house, where he was put at case.\nTo him there lacked no victuals that might please;\nSo well appointed house as was that one\nAurelius in life before saw none.\nHe showed him, ere he went to supper here,\nForests and parks full of the dim wild deer;\nThere saw he harts of ten with their horns high,\nThe greatest ever seen by human eye.\nHe saw of them a hundred slain by hounds,\nAnd some with arrows bled, with bitter wounds.\nHe saw, when vanished all were these wild deer,\nSome falconers by river flowing clear,\nWho with their hawks had many herons slain.\nAnd then he saw knights jousting on a plain;\nAnd after this he did him such pleasance\nThat he showed him his lady in a dance\nWherein he also joined, or so he thought.\nAnd when this master who this magic wrought\nSaw it was time, he clapped his two hands, lo!\nFarewell to all! the revels out did go.\nAnd yet they'd never moved out of the house\nWhile they saw all these sights so marvelous,\nBut in his study, where his books would be,\nThey had sat still, and no one but they three.\nThen unto him this master called his squire,\nAnd asked him thus: Is supper ready, sir?\nAlmost an hour it is, I'll undertake,\nSince I bade you our evening meal to make,\nWhen these two gentlemen came in with me\nInto my study, wherein my books be.\nSir, said this squire then, when it pleases you\nIt is all ready, though you will right now.\nThen let us sup, said he, for that is best;\nThese amorous folk must sometime have some rest.\nAfter the supper they discussed, they three,\nWhat sum should this said master's guerdon be\nFor moving all rocks Breton coasts contain\nFrom the Gironde unto the mouth of Seine.\nHe played for time, and swore, so God him save,\nLess than a thousand he would not have,\nNor eagerly for that would take it on.\nAurelius, with blissful heart, anon\nAnswered him thus: Fig for a thousand pound!\nThis great wide world, the which, men say, is round,\nI'd give it all, if I were lord of it.\nThe bargain is concluded and we're knit.\nYou shall be truly paid, sir, by my troth!\nBut look you, for no negligence or sloth,\nDelay no longer than tomorrow morn.\nNay, said this clerk! upon my faith I'm sworn.\nTo bed went this Aurelius and undressed,\nAnd well-nigh all that night he had his rest;\nWhat of his labour and his hope of bliss\nThe pain had left that woeful heart of his.\nUpon the morrow, when it was full day,\nTo Brittany took they the nearest way,\nAurelius, with this wizard at his side,\nAnd thus they came to where they would abide;\nAnd that was, as the books say, I remember,\nThe cold and frosty season of December.\nPhoebus was old and coloured like pale brass,\nThat in hot declination coloured was\nAnd shone like burnished gold with streamers bright;\nBut now in Capricorn did he alight,\nWherein he palely shone, I dare explain.\nThe bitter frosts, with all the sleet and rain,\nHad killed the green of every garden-yard.\nJanus sat by the fire, with double beard,\nAnd drained from out his bugle horn the wine.\nBefore him stood the brawn of tusked swine,\nAnd Noel! cried then every lusty man.\nAurelius, in all that he could plan,\nDid to this master cheerful reverence,\nAnd prayed of him he'd use all diligence\nTo bring him from his pains that so did smart,\nOr else with sword that he would slit his heart.\nThis subtle clerk such ruth had for this man,\nThat night and day he sped about his plan,\nTo wait the proper time for his conclusion;\nThat is to say, the time to make illusion,\nBy such devices of his jugglery\n(I understand not this astrology)\nThat she and everyone should think and say\nThat all the Breton rocks were gone away,\nOr else that they were sunken underground.\nSo at the last the proper time he found\nTo do his tricks and all his wretchedness\nOf such a superstitious wickedness.\nFor his Toletan Tables forth he brought,\nAll well corrected, and he lacked in naught,\nThe years collected nor the separate years,\nNor his known roots, nor any other gears,\nAs, say, his centres and his argument,\nAnd his proportionals convenient\nIn estimating truly his equations.\nThe eighth sphere showed him in his calculations\nHow far removed was Alnath, passing by,\nFrom head of that fixed Aries on high,\nThat in the ninth great sphere considered is;\nRight cleverly he calculated this.\nWhen he the moon's first mansion thus had found,\nThe rest proportionally he could expound;\nAnd knew the moon's arising-time right well,\nAnd in what face and term, and all could tell;\nThis gave him then the mansion of the moon-\nHe worked it out accordingly right soon,\nAnd did the other necessary rites\nTo cause illusions and such evil sights\nAs heathen peoples practised in those days.\nTherefore no longer suffered he delays,\nBut all the rocks by magic and his lore\nAppeared to vanish for a week or more.\nAurelius, who yet was torn by this,\nWhether he'd gain his love or fare amiss,\nAwaited night and day this miracle;\nAnd when he knew there was no obstacle,\nThat vanished were these black rocks, every one,\nDown at the master's feet he fell anon\nAnd said: I, woeful wretch, Aurelius,\nThank you, my lord, and Lady mine Venus,\nThat have so saved me from my dreadful care.\nAnd to the temple straightway did he fare,\nWhereat he knew he should his lady see.\nAnd when he saw his opportunity,\nWith fluttering heart and with an humble cheer\nHe greeted thus his sovereign lady dear.\nMy own dear lady, said this woeful man,\nWhom I most fear and love best, as I can,\nAnd whom, of all this world, I'd not displease,\nWere it not that for you I've such unease\nThat I must die here at your feet anon,\nI would not tell how I am woebegone;\nBut I must either die or else complain;\nYou slay me, for no crime, with utter pain.\nBut on my death, although you have no ruth,\nTake heed now, ere you break your promised troth\nRepent you, for die sake of God above,\nEre me you slay, because it's you I love.\nFor well you know your promise apposite;\nNot that I challenge aught, of my own right,\nIn you, my sovereign lady, save your grace;\nBut in a garden, in a certain place,\nYou know right well what you did promise me;\nAnd in my hand you plighted troth, said he,\nTo love me best, God knows you promised so,\nHowe'er I may unworthy be thereto.\nMadam, I say it for your honour's vow\nMore than to save my heart's dear life right now;\nI have done all that you commanded me;\nAnd if you will, you may well go and see.\n\nDo as you please, but hold your word in mind,\nFor quick or dead, as you do, me you'll find;\nIn you lies all, to make me live or die,\nBut well I know the rocks are vanished, aye!\nHe took his leave, and she astounded stood,\nIn all her face there was no drop of blood;\nShe never thought to have come in such a trap.\nAlas! said she, that ever this should hap!\nFor thought I never, by possibility,\nThat such prodigious marvel e'er might be!\nIt is against the way of all nature.\nAnd home she went, a sorrowful creature.\nFor utter terror hardly could she go,\nShe wept, she wailed throughout a day or so,\nAnd swooned so much 'twas pitiful, to see;\nBut why this was to not a soul told she;\nFor out of town was gone Arviragus.\nBut to her own heart spoke she, and said thus,\nWith her face pale and with a heavy cheer,\nAll her complaint, as you'll hereafter hear:\nOf thee, she cried, O Fortune, I complain,\nThat, unaware, I'm bound within thy chain;\nFrom which to go, I know of no succour\nSave only death, or else my dishonour;\nOne of these two I am compelled to choose.\nNevertheless, I would far rather lose\nMy life than of my body come to shame,\nOr know myself untrue, or lose my name;\nBy death I know it well, I may be freed;\nHas there not many a noble wife, indeed,\nAnd many a maiden slain herself- alas!-\nRather than with her body do trespass?\nYes, truly, lo, these stories bear witness;\nWhen Thirty Tyrants, full of wickedness,\nHad Phido slain in Athens, at a feast,\nThey gave command his daughters to arrest,\nAnd had them brought before them, for despite,\nAll naked, to fulfill their foul delight,\nAnd in their father's blood they made them dance\nUpon the pavement- God give them mischance!\nFor which these woeful maidens, full of dread,\nRather than they should lose their maidenhead,\nUnseen they all leaped down into a well\nAnd drowned themselves therein, as old books tell.\nThey of Messina did require and seek\nFrom Lacedaemon fifty maids to take,\nOn whom they would have done their lechery;\nBut there was none of all that company\nWho was not slain, and who with good intent\nPreferred not death rather than give consent\nTo be thus ravished of her maidenhead.\nWhy should I then hold dying in such dread?\nLo, too, the tyrant Aristoclides,\nWho loved a maiden called Stimphalides.\nWhenas her father had been slain by night,\nUnto Diana's temple she took flight\nAnd grasped the image in her two hands so\nThat from this image would she not let go.\nNo one could tear her hands from that embrace\nTill she was slaughtered in that self-same place.\nNow since these maidens showed such scorn outright\nOf being defiled to make man's foul delight,\nWell ought a wife rather herself to slay\nThan be defiled, I think, and so I say.\nWhat shall I say of Hasdrubal's fair wife,\nWho in Carthage bereft herself of life?\nFor when she saw that Romans won the town,\nShe took her children all and leaped right down\nInto the fire, choosing thus to die\nBefore a Roman did her villainy.\nDid not Lucretia slay herself- alas!-\nAt Rome, when she so violated was\nBy Tarquin? For she thought it was a shame\nMerely to live when she had lost her name.\nThe seven maidens of Miletus, too,\nDid slay themselves, for very dread and woe,\nRather than men of Gaul should on them press.\nMore than a thousand stories, as I guess,\nCould I repeat now of this matter here.\nWith Abradates slain, his wife so dear\nHerself slew, and she let her red blood glide\nIn Abradates' wounds so deep and wide,\nAnd said: 'My body, at the least, I say,\nNo man shall now defile,' and passed away.\nWhy should I of more instances, be fain?\nSince that so many have their bodies slain\nRather than that they should dishonoured be?\nI will conclude it better is for me\nTo slay myself than be dishonoured thus.\nI will be true unto Arviragus,\nOr else I'll slay myself in some manner,\nAs did Demotion's virgin daughter dear\nBecause she would not violated be.\nO Cedasus, it rouses great pity\nTo read of how your daughters died, alas!\nThat slew themselves in such another case.\nAs great a pity was it, aye and more,\nThat a fair Theban maid, for Nicanor,\nDid slay herself in such a kind of woe.\nAnother Theban maiden did also;\nFor one of Macedonia her had pressed,\nAnd she, by death, her maidenhead redressed.\nWhat shall I say of Nicerates' wife,\nWho, for like cause, bereft herself of life?\nHow true, too, was to Alcibiades\nHis love, who chose to drain death to the lees\nAnd would not let his corpse unburied be!\nLo, what a wife was Alcestis, said she.\nWhat says Homer of good Penelope?\nThe whole of Hellas knew her chastity.\nPardieu, of Laodamia they wrote thus,\nThat when at Troy was slain Protesilaus,\nNo longer would she live after his day.\nThe same of noble Portia may I say;\nWithout her Brutus could she no wise live,\nTo whom in youth her whole heart she did give.\nThe perfect wifehood of Artemisia\nWas honoured throughout all old Caria.\nO Teuta, queen! Your wifely chastity,\nTo all wives may a very mirror be.\nThe same thing may I say of Bilia,\nOf Rhodogune and of Valeria.\nThus Dorigen went on a day or so,\nPurposing ever that to death she'd go.\nBut notwithstanding, upon the third night\nHome came Arviragus, this worthy knight,\nAnd asked her why it was she wept so sore.\nAnd thereat she began to weep the more.\nAlas! cried she, that ever I was born!\nThus have I said, quoth she, thus have I sworn-\nAnd told him all, as you have heard before;\nIt needs not to re-tell it to you more.\nThis husband, with glad cheer, in friendly wise,\nAnswered and said as I shall you apprise:\nIs there naught else, my Dorigen, than this?\nNay, nay, said she, God help me, as it is\nThis is too much, though it were God's own will.\nYea, wife, said he, let sleep what's lying still;\nIt may be well with us, perchance, today.\nBut you your word shall hold to, by my fay!\nAs God may truly mercy have on me,\nWounded to death right now I'd rather be,\nFor sake of this great love of you I have,\nThan you should not your true word keep and save.\nTruth is the highest thing that man may keep.\nBut with that word began he then to weep,\nAnd said: I you forbid, on pain of death,\nThat ever, while to you last life and breath,\nTo anyone you tell this adventure.\nAs I best may, I will my woe endure,\nNor show a countenance of heaviness,\nThat folk no harm may think of you, or guess.\nAnd then he called a squire and a maid:\nGo forth anon with Dorigen, he said,\nAnd bring her to a certain place anon.\nThey took their leave and on their way were gone.\nBut nothing knew of why she thither went\nNor would he to a soul tell his intent.\nPerhaps a lot of you will certainly\nHold him a wicked man that wilfully\nPut his wife's honour thus in jeopardy;\nHearken the tale, ere you upon her cry.\nShe may have better luck than you suppose;\nAnd when you've heard all, let your judgment close.\nThis squire I've told you of, Aurelius,\nOf Dorigen he being so amorous,\nChanced, as it seems, his lady fair to meet\nIn middle town, right in the busiest street,\nAs she was going forth, as you have heard,\nToward the garden where she'd pledged her word.\nAnd he was going gardenward also;\nFor he was always watching when she'd go\nOut of her house to any kind of place.\nBut thus they met, by chance perhaps or grace;\nAnd he saluted her with good intent,\nAnd asked her, now, whither it was she went.\nAnd she replied, as if she were half mad:\nUnto the garden, as my husband bade,\nMy promise there to keep, alas, alast\nAurelius then pondered on this case,\nAnd in his heart he had compassion great\nOn her and her lamenting and her state,\nAnd on Arviragus, the noble knight,\nWho'd bidden her keep promise, as she might,\nBeing so loath his wife should break with truth;\nAnd in his heart he gained, from this, great ruth,\nConsidering the best on every side,\nThat from possession rather he'd abide\nThan do so great a churlish grievousness\nAgainst free hearts and all high nobleness;\nFor which, and in few words, he told her thus:\nMadam, say to your lord Arviragus\nThat since I see his noble gentleness\nTo you, and since I see well your distress,\nThat he'd have rather shame (and that were ruth)\nThan you to me should break your word of truth,\nI would myself far rather suffer woe\nThan break apart the love between you two.\nSo I release, madam, into your hand,\nAnd do return, discharged, each surety and\nEach bond that you have given and have sworn,\nEven from the very time that you were born.\nMy word I pledge, I'll ne'er seek to retrieve\nA single promise, and I take my leave\nAs of the truest and of the best wife\nThat ever yet I've known in all my life.\nLet every wife of promises take care,\nRemember Dorigen, and so beware!\nThus can a squire perform a gentle deed\nAs well as can a knight, of that take heed.\nUpon her bare knees did she thank him there,\nAnd home unto her husband did she fare,\nAnd told him all, as you have heard it said;\nAnd be assured, he was so pleased and glad\nThat 'twere impossible of it to write.\nWhat should I further of this case indite?\nArviragus and Dorigen his wife\nIn sovereign happiness led forth their life.\nNever did any anger come between;\nHe cherished her as if she were a queen;\nAnd she to him was true for evermore.\nOf these two folk you get from me no more.\nAurelius, whose wealth was now forlorn,\nHe cursed the time that ever he was born;\nAlas! cried he, Alas! that I did state\nI'd pay fine gold a thousand pounds by weight\nTo this philosopher! What shall I do?\nI see no better than I'm ruined too.\nAll of my heritage I needs must sell\nAnd be a beggar; here I cannot dwell\nAnd shame all of my kindred in this place,\nUnless I gain of him some better grace.\nAnd so I'll go to him and try, today,\nOn certain dates, from year to year, to pay,\nAnd thank him for his princely courtesy;\nFor I will keep my word, and I'll not lie.\nWith sore heart he went then to his coffer,\nAnd took gold unto this philosopher,\nThe value of five hundred pounds, I guess,\nAnd so besought him, of his nobleness,\nTo grant him dates for payment of the rest,\nAnd said: Dear master, I may well protest\nI've never failed to keep my word, as yet;\nFor certainly I'll pay my entire debt\nTo you, however after I may fare,\nEven to begging, save for kirtle, bare.\nBut if you'd grant, on good security,\nTwo years or three of respite unto me,\nThen all were well; otherwise must I sell\nMy heritage; there is no more to tell.\nThen this philosopher soberly answered\nAnd spoke in. this wise, when these words he'd heard:\nHave I not fairly earned my promised fee?\nYes, truly, you have done so, sir, said he.\nHave you not bad the lady at your will?\nNo, no, said he, and sighed, and then was still.\nWhat was the reason? Tell me if you can.\nAurelius his tale anon began,\nAnd told him all, as you have heard before;\nIt needs not I repeat it to you more.\nHe said: Arviragus, of nobleness,\nHad rather die in sorrow and distress\nThan that his wife were to her promise false.\nHe told of Dorigen's grief, too, and how else\nShe had been loath to live a wicked wife\nAnd rather would that day have lost her life,\nAnd that her troth she swore through ignorance:\nShe'd ne'er before heard of such simulance;\nWhich made me have for her such great pity.\nAnd just as freely as he sent her me,\nAs freely sent I her to him again.\nThis is the sum, there's no more to explain.\nThen answered this philosopher: Dear brother,\nEach one of you has nobly dealt with other.\nYou are a squire, true, and he is a knight,\nBut God forbid, what of His blessed might,\nA clerk should never do a gentle deed\nAs well as any of you. Of this take heed!\nSir, I release to you your thousand pound,\nAs if, right now, you'd crept out of the ground\nAnd never, before now, had known of me.\nFor, sir, I'll take of you not one penny\nFor all my art and all my long travail.\nYou have paid well for all my meat and ale;\nIt is enough, so farewell, have good day!\nAnd took his horse and went forth on his way.\nMasters, this question would I ask you now:\nWhich was most generous, do you think, and how.\nPray tell me this before you farther wend.\nI can no more, my tale is at an end.\n\n"},{"index":7,"markdown":"### The Physician's Tale\n\nThere was, as tells us Titus Livius,\nA knight whose name was called Virginius,\nFulfilled of honour and of worthiness,\nWho many friends and much wealth did possess.\nThis knight had had a daughter by his wife,\nNor children more had he in all his life.\nFair was this maid, in excellent beauty\nAbove all others that a man may see;\nFor Nature had, with sovereign diligence,\nMoulded her to so great an excellence\nShe seemed to say: Behold now, I, Nature,\nThus can I form and paint a creature pure\nWhen I desire. Who can it counterfeit?\nPygmalion? Nay, not though he forge and beat,\nOr curve, or paint; and I dare say again,\nApelles, Zeuxis too, should work in vain,\nEither to carve or paint, or forge or beat,\nIf they presumed my work to counterfeit.\nFor He Who is Creator Principal\nHas made of me His Vicar General\nTo form and colour earthly creatures all,\nJust as I like, for they're mine, great and small\nUnder the moon, the which may wax and wane;\nAnd for my work I ask no payment vain;\nMy Lord and I are of one sole accord;\nI made her in the worship of my Lord.\nSo do I other fair or foul creatures,\nWhat colours though they have, or what figures.\nIt seems to me that Nature thus would say.\nThis maid was fourteen years of age, this may\nIn whom Dame Nature had so great delight.\nFor just as she can paint a lily white\nOr redden rose, even with such a stroke\nShe did this creature by her art evoke\nEre she was born, painting her sweet limbs free\nIn such true colours as they'd come to be;\nAnd Phoebus dyed her long hair with such gold\nAs have his burning streamers manifold.\nBut if right excellent was her beauty,\nA thousand-fold more virtuous was she.\nIn her there lacked not one condition known\nThat's praiseworthy when by discretion shown.\nAs well in soul as body chaste was she;\nFor which she flowered in virginity\nWith all humility and abstinence,\nAnd with all temperance and with patience,\nAnd with a modest bearing and array.\nDiscreet in her replies she was alway;\nThough she was wise as Pallas, and not vain,\nHer speech was always womanly and plain,\nNo highfalutin pretty words had she\nTo ape deep knowledge; after her degree\nShe spoke, and all her words, greater and less,\nTended to virtue and to gentleness.\nModest she was, with maiden bashfulness,\nConstant of heart, and full of busyness\nTo keep her from all idle sluggardry.\nBacchus had of her mouth no mastery;\nFor wine and youth help Venus to increase,\nAs when on fire is scattered oil or grease.\nAnd of her virtue, free and unconstrained,\nShe had ofttimes some little illness feigned\nIn order to avoid a company\nWhich likely was to do some great folly,\nAs people do at revels and at dances,\nWhich are occasions when young folk take chances.\nSuch things but make young men and maidens be\nToo ripe and bold, as everyone may see,\nWhich is right dangerous, as 'twas of yore.\nFor all too soon a virgin learns the lore\nOf wantonness when she becomes a wife.\nYou governesses, who in older life\nHave great lords' daughters in your governance,\nTake from my words no foolish petulance;\nRemember you've been set to governings\nOf lords' daughters for but one of two things:\nEither that you have kept your honesty,\nOr else that you've succumbed to your frailty,\nAnd having learned the measures of love's dance,\nHave now forsaken such ways of mischance\nFor evermore; therefore, for Jesus' sake,\nSee that you teach them virtue, nor mistake.\nA poacher of the deer, who has reformed,\nLeft wicked ways and been by goodness warmed,\nCan guard a forest best of any man.\nSo guard them well, for if you will you can;\nLook that to no vice do you give assent,\nLest you be damned for your so vile intent;\nFor who does thus is traitor, that's certain.\nAnd take good care that I speak not in vain;\nOf treacheries all, the sovereign pestilence\nIs when adults betray young innocence.\nYou fathers and you mothers fond, also,\nIf you have children, be it one or two,\nYours is the burden of their wise guidance\nThe while they are within your governance.\nBeware that not from your own lax living,\nOr by your negligence in chastening\nThey fall and perish; for I dare well say,\nIf that should chance you'll dearly have to pay.\nUnder a shepherd soft and negligent\nFull many a sheep and lamb by wolf is rent.\nSuffice one instance, as I give it here,\nFor I must in my story persevere.\nThis maid, of whom I do this praise express,\nGuarded herself, nor needed governess;\nFor in her daily life all maids might read,\nAs in a book, every good word or deed\nThat might become a maiden virtuous;\nShe was so prudent and so bounteous.\nFrom all this grew the fame on every side\nOf both her beauty and her goodness wide;\nThroughout that land they praised her, every one\nThat virtue loved; and Envy stood alone,\nThat sorry is when others live in weal\nAnd for their woe will ever gladness feel.\n(Doctor Augustine's are these words, I own).\nThis maid, upon a day, went into town\nUnto a temple, with her mother dear,\nAs the wont is of young maids everywhere.\nNow there was then a justice in that town\nWas governor of all the region known.\nAnd so befell, this judge his two eyes cast\nUpon this maid, noting her beauty fast,\nAs she went by the place wherein he stood.\nSwiftly his heart was altered, and his mood,\nHe was so caught by beauty of the maid,\nAnd to his own dark secret heart he said:\nShe shall be mine in spite of any man!\nAnon the Fiend into his bosom ran\nAnd taught him swiftly how, by treachery,\nThe maiden to his purpose might win he.\nFor truly not to bribery or force\nWould it avail, he thought, to have recourse,\nSince she had many friends, and was so good,\nSo strong in virtue, that he never could\nBy any subtle means her favour win\nAnd make her give her body unto sin.\nTherefore, and with great scheming up and down,\nHe sent to find a fellow of the town,\nWhich man, he knew, was cunning and was bold.\nAnd unto this man, when the judge had told\nHis secret, then he made himself right sure\nThat it should come to ears of no creature,\nFor if it did the fellow'd lose his head.\nAnd when assent to this crime had been said,\nGlad was the judge, and then he made great cheer\nAnd gave the fellow precious gifts and dear.\nWhen plotted out was their conspiracy,\nFrom point to point, how all his lechery\nShould have its will, performing craftily,\nAs you shall hear it now told openly,\nHome went the churl, whose name was Claudius.\nThis false judge, who was known as Appius\n(Such was his name, for this is no fable,\nBut an historical event I tell,\nAt least the gist is true, beyond a doubt)-\nThis false judge goes now busily about\nTo hasten his delight in all he may.\nAnd so befell soon after, on a day,\nThis false judge, as recounts the ancient story,\nAs he was wont, sat in his auditory\nAnd gave his judgment upon every case.\nForthwith the wicked churl advanced a pace,\nAnd said: Your honour, if it be your will,\nThen give me justice prayed for in this bill,\nOf my complaint against Virginius.\nAnd if he claim the matter stands not thus,\nI will so prove, by many a good witness,\nThat truth is what my bill does here express.\nThe judge replied: On this, in his absence,\nI may not give definitive sentence.\nLet him be called and I will gladly hear;\nYou shall have all your right, and no wrong, here.\nVirginius came to learn the judge's will,\nAnd then was read to him this wicked bill,\nThe substance of it being as you shall hear.\nTo you, Judge Appius, may it so appear\nThat comes and says your servant Claudius,\nHow that a knight, by name Virginius,\nAgainst the law, against all equity,\nHolds, expressly against the will of me,\nMy servant who is slave to me by right,\nWho from my house was stolen, on a night,\nWhile yet she was but young; this will I prove,\nMy lord, by witness competent thereof.\nShe's not his child, whatever he may say;\nWherefore to you, my lord the judge, I pray,\nYield me my slave, if that it be your will.\nLo, this was all the substance of his bill.\nVirginius' eyes the churl's began to hold,\nBut hastily, before his tale he'd told,\nReady to prove it, as befits a knight,\nAnd by the evidence of many a wight,\nThat false was this charge of his adversary.\nThe wicked judge, he would no moment tarry,\nNor hear a word more from Virginius,\nBut gave his judgment then and there, as thus:\nI do decree in favour of the churl:\nNo longer shall you hold this servant girl.\nGo bring her here and leave her as my ward.\nThis man shall have his slave, as my award.\nAnd when this noble knight Virginius,\nBy judgment of this Justice Appius,\nMust now, perforce, his darling daughter give\nUnto the judge, in lechery to live,\nHe did go home and sat down in his hall,\nAnd gave command his daughter there to call;\nAnd, with a face dead white and ashen cold,\nHer modest mien his eyes did then behold,\nWith father's pity striking through his heart,\nThough from his purpose he would not depart.\nDaughter, said he, Virginia by your name,\nThere are two ways, for either death or shame\nYou now must suffer. Ah, that I was born!\nFor you have not deserved to be thus lorn,\nTo die by means of sword or any knife.\nO my dear daughter, ender of my life,\nWhom I have bred up with so deep pleasance\nThat you were never from my remembrance!\nO daughter who are now my final woe,\nAye, and in life my final joy also,\nO gem of chastity, in brave patience\nReceive your death, for that is my sentence.\nFor love and not for hate you must be dead;\nMy pitying hand must strike your innocent head.\nAlas! That ever Appius saw you! Nay,\nThus has he falsely judged of you today.-\nAnd told her all the case, as you before\nHave heard; there is no need to tell it more.\nO mercy, my dear father, said this maid,\nAnd with that word both of her arms she laid\nAbout his neck, as she was wont to do;\nThen broke the bitter tears from her eyes two.\nShe said: O my good father, must I die?\nIs there no grace? Is there no remedy?\nNo, truly, darling daughter mine, said he.\nThen give me leisure, father mine, quoth she,\nBut to lament my death a little space;\nFor even Jephtha gave his daughter grace\nTo weep a little ere he slew, alas!\nAnd God knows that in naught did she trespass,\nSave that she ran to be the first to see\nAnd welcome him with greetings, merrily.\nAnd with that word she fell into a swoon,\nAnd after, when the faint was past and gone,\nShe rose up and unto her father said:\nPraise be to God that I shall die a maid.\nGive me my death before I come to shame;\nDo with your child your will, and in God's name!\nAnd then she prayed him, as he was expert,\nHe'd strike her swiftly, lest the blow should hurt,\nWhereon again a-swooning down she fell.\nHer father, with a heavy heart and will,\nStruck off her head, and bore it by the hair\nStraight to the judge and did present it there\nWhile yet he sat on bench in auditory.\nAnd when the judge saw this, so says the story,\nHe bade them take him out and swiftly hang.\nBut then a thousand people rose and sprang\nTo save the knight, for ruth and for pity,\nFor known was now the false iniquity.\nThe people had suspected some such thing,\nBy the churl's manner in his challenging,\nThat it was done to please this Appius;\nThey knew right well that he was lecherous.\nWherefore they ran this Appius upon\nAnd cast him into prison cell anon,\nWherein he slew himself; and Claudius,\nWho had been creature of this Appius,\nWas sentenced to be hanged upon a tree;\nBut then Virginius, of his great pity,\nSo pleaded for him that he was exiled,\nFor, after all, the judge had him beguiled.\nThe rest were hanged, the greater and the less,\nWho had been parties to this wickedness.\nHere may men see how sin has its desert!\nBeware, for no man knows whom God will hurt,\nNor how profoundly, no, nor in what wise\nThe hidden worm of conscience terrifies\nThe wicked soul, though secret its deeds be\nAnd no one knows thereof but God and he.\nFor be he ignorant or learned, yet\nHe cannot know when fear will make him sweat\nTherefore I counsel you, this counsel take:\nForsake your sin ere sin shall you forsake.\n\n\n### The Words of the Host\n\nOur host began to swear as madman would:\nHalloo! he cried, now by the Nails and Blood!\nThis was a false churl and a false justice!\nAs shameful death as thinking may devise\nCome to such judge who such a helper has!\nAnd so this luckless maid is slain, alas!\nAlas, too dearly paid she for beauty!\nWherefore I always say, as men may see,\nThat Fortune's gifts, or those of Dame Nature,\nAre cause of death to many a good creature.\nHer beauty was her death, I say again;\nAlas, so pitiably she there was slain!\nFrom both the kinds of gift I speak of now\nMen often take more harm than help, I vow.\nBut truly, my own master lief and dear,\nThis is a very pitiful tale to hear,\nYet let us pass it by as of no force.\nI pray to God to save your gentle corse,\nYour urinals and all your chamberpots,\nYour hippocras and medicines and tots\nAnd every boxful of electuary;\nGod bless them, and Our Lady, holy Mary!\nSo may I prosper, you're a proper man,\nAnd like a prelate too, by Saint Ronan!\nSaid I not well? I can't speak in set terms;\nBut well I know my heart with grief so warms\nThat almost I have caught a cardiac pain.\nBody and Bones! Save I some remedy gain,\nOr else a draught of fresh-drawn, malty ale,\nOr save I hear, anon, a merry tale,\nMy heart is lost for pity of this maid.\nYou, bon ami, you pardoner, he said,\nTell us some pleasant tale or jest, anon.\nIt shall be done, said he, by Saint Ronan!\nBut first, he said, just here, at this ale-stake,\nI will both drink and eat a bite of cake.\nBut then these gentle folk began to cry:\nNay, let him tell us naught of ribaldry;\nTell us some moral thing, that we may hear\nWisdom, and then we gladly will give ear.\nI grant it, aye, said he, but I must think\nUpon some seemly tale the while I drink.\n\n\n### The Pardoner's Prologue\n\nMasters, quoth he, in churches, when I preach,\nI am at pains that all shall hear my speech,\nAnd ring it out as roundly as a bell,\nFor I know all by heart the thing I tell.\nMy theme is always one, and ever was:\n'Radix malorum est cupiditas.'\nFirst I announce the place whence I have come,\nAnd then I show my pardons, all and some.\nOur liege-lord's seal on my patent perfect,\nI show that first, my safety to protect,\nAnd then no man's so bold, no priest nor clerk,\nAs to disturb me in Christ's holy work;\nAnd after that my tales I marshal all.\nIndulgences of pope and cardinal,\nOf patriarch and bishop, these I do\nShow, and in Latin speak some words, a few,\nTo spice therewith a bit my sermoning\nAnd stir men to devotion, marvelling.\nThen show I forth my hollow crystal-stones,\nWhich are crammed full of rags, aye, and of bones;\nRelics are these, as they think, every one.\nThen I've in latten box a shoulder bone\nWhich came out of a holy Hebrew's sheep.\n'Good men,' say I, 'my words in memory keep;\nIf this bone shall be washed in any well,\nThen if a cow, calf, sheep, or ox should swell\nThat's eaten snake, or been by serpent stung,\nTake water of that well and wash its tongue,\nAnd 'twill be well anon; and furthermore,\nOf pox and scab and every other sore\nShall every sheep be healed that of this well\nDrinks but one draught; take heed of what I tell.\nAnd if the man that owns the beasts, I trow,\nShall every week, and that before cock-crow,\nAnd before breakfast, drink thereof a draught,\nAs that Jew taught of yore in his priestcraft,\nHis beasts and all his store shall multiply.\nAnd, good sirs, it's a cure for jealousy;\nFor though a man be fallen in jealous rage,\nLet one make of this water his pottage\nAnd nevermore shall he his wife mistrust,\nThough he may know the truth of all her lust,\nEven though she'd taken two priests, aye, or three.\n'Here is a mitten, too, that you may see.\nWho puts his hand therein, I say again,\nHe shall have increased harvest of his grain,\nAfter he's sown, be it of wheat or oats,\nJust so he offers pence or offers groats.\n'Good men and women, one thing I warn you.\nIf any man be here in church right now\nThat's done a sin so horrible that he\nDare not, for shame, of that sin shriven be,\nOr any woman, be she young or old,\nThat's made her husband into a cuckold,\nSuch folk shall have no power and no grace\nTo offer to my relics in this place.\nBut whoso finds himself without such blame,\nHe will come up and offer, in God's name,\nAnd I'll absolve him by authority\nThat has, by bull, been granted unto me.'\nBy this fraud have I won me, year by year,\nA hundred marks, since I've been pardoner.\nI stand up like a scholar in pulpit,\nAnd when the ignorant people all do sit,\nI preach, as you have heard me say before,\nAnd tell a hundred false japes, less or more.\nI am at pains, then, to stretch forth my neck,\nAnd east and west upon the folk I beck,\nAs does a dove that's sitting on a barn.\nWith hands and swift tongue, then, do I so yarn\nThat it's a joy to see my busyness.\nOf avarice and of all such wickedness\nIs all my preaching, thus to make them free\nWith offered pence, the which pence come to me.\nFor my intent is only pence to win,\nAnd not at all for punishment of sin.\nWhen they are dead, for all I think thereon\nTheir souls may well black-berrying have gone!\nFor, certainly, there's many a sermon grows\nOfttimes from evil purpose, as one knows;\nSome for folks' pleasure and for flattery,\nTo be advanced by all hypocrisy,\nAnd some for vainglory, and some for hate.\nFor, when I dare not otherwise debate,\nThen do I sharpen well my tongue and sting\nThe man in sermons, and upon him fling\nMy lying defamations, if but he\nHas wronged my brethren or- much worse- wronged me.\nFor though I mention not his proper name,\nMen know whom I refer to, all the same,\nBy signs I make and other circumstances.\nThus I pay those who do us displeasances.\nThus spit I out my venom under hue\nOf holiness, to seem both good and true.\nBut briefly my intention I'll express;\nI preach no sermon, save for covetousness.\nFor at my theme is yet, and ever was,\n'Radix malorum est cupiditas.'\nThus can I preach against that self-same vice\nWhich I indulge, and that is avarice.\nBut though myself be guilty of that sin,\nYet can I cause these other folk to win\nFrom avarice and really to repent.\nBut that is not my principal intent.\nI preach no sermon, save for covetousness;\nThis should suffice of that, though, as I guess.\nThen do I cite examples, many a one,\nOut of old stories and of time long gone,\nFor vulgar people all love stories old;\nSuch things they can re-tell well and can hold.\nWhat? Think you that because I'm good at preaching\nAnd win me gold and silver by my teaching\nI'll live of my free will in poverty?\nNo, no, that's never been my policy!\nFor I will preach and beg in sundry lands;\nI will not work and labour with my hands,\nNor baskets weave and try to live thereby,\nBecause I will not beg in vain, say I.\nI will none of the apostles counterfeit;\nI will have money, wool, and cheese, and wheat,\nThough it be given by the poorest page,\nOr by the poorest widow in village,\nAnd though her children perish of famine.\nNay! I will drink good liquor of the vine\nAnd have a pretty wench in every town.\nBut hearken, masters, to conclusion shown:\nYour wish is that I tell you all a tale.\nNow that I've drunk a draught of musty ale,\nBy God, I hope that I can tell something\nThat shall, in reason, be to your liking.\nFor though I am myself a vicious man,\nYet I would tell a moral tale, and can,\nThe which I'm wont to preach more gold to win.\nNow hold your peace! my tale I will begin.\n\n\n### The Pardoner's Tale\n\nIn Flanders, once, there was a company\nOf young companions given to folly,\nRiot and gambling, brothels and taverns;\nAnd, to the music of harps, lutes, gitterns,\nThey danced and played at dice both day and night.\nAnd ate also and drank beyond their might,\nWhereby they made the devil's sacrifice\nWithin that devil's temple, wicked wise,\nBy superfluity both vile and vain.\nSo damnable their oaths and so profane\nThat it was terrible to hear them swear;\nOur Blessed Saviour's Body did they tear;\nThey thought the Jews had rent Him not enough;\nAnd each of them at others' sins would laugh.\nThen entered dancing-girls of ill repute,\nGraceful and slim, and girls who peddled fruit,\nHarpers and bawds and women selling cake,\nWho do their office for the Devil's sake,\nTo kindle and blow the fire of lechery,\nWhich is so closely joined with gluttony;\nI call on holy writ, now, to witness\nThat lust is in all wine and drunkenness.\nLo, how the drunken Lot unnaturally\nLay with his daughters two, unwittingly;\nSo drunk he was he knew not what he wrought.\nHerod, as in his story's clearly taught,\nWhen full of wine and merry at a feast,\nSitting at table idly gave behest\nTo slay John Baptist, who was all guiltless.\nSeneca says a good word too, doubtless;\nHe says there is no difference he can find\nBetween a man that's quite out of his mind\nAnd one that's drunken, save perhaps in this\nThat when a wretch in madness fallen is,\nThe state lasts longer than does drunkenness.\nO gluttony; full of all wickedness,\nO first cause of confusion to us all,\nBeginning of damnation and our fall,\nTill Christ redeemed us with His blood again!\nBehold how dearly, to be brief and plain,\nWas purchased this accursed villainy;\nCorrupt was all this world with gluttony!\nAdam our father, and his wife also,\nFrom Paradise to labour and to woe\nWere driven for that vice, no doubt; indeed\nThe while that Adam fasted, as I read,\nHe was in Paradise; but then when he\nAte of the fruit forbidden of the tree,\nAnon he was cast out to woe and pain.\nO gluttony, of you we may complain!\nOh, knew a man how many maladies\nFollow on excess and on gluttonies,\nSurely he would be then more moderate\nIn diet, and at table more sedate.\nAlas! The throat so short, the tender mouth,\nCausing that east and west and north and south,\nIn earth, in air, in water men shall swink\nTo get a glutton dainty meat and drink!\nOf this same matter Paul does wisely treat:\nMeat for the belly and belly for the meat:\nAnd both shall God destroy, as Paul does say.\nAlas! A foul thing is it, by my fay,\nTo speak this word, and fouler is the deed,\nWhen man so guzzles of the white and red\nThat of his own throat makes he his privy,\nBecause of this cursed superfluity.\nThe apostle, weeping, says most piteously:\nFor many walk, of whom I've told you, aye,\nWeeping I tell you once again they're dross,\nFor they are foes of Christ and of the Cross,\nWhose end is death, whose belly is their god.\nO gut! O belly! O you stinking cod,\nFilled full of dung, with all corruption found!\nAt either end of you foul is the sound.\nWith how great cost and labour do they find\nYour food! These cooks, they pound and strain and grind;\nSubstance to accident they turn with fire,\nAll to fulfill your gluttonous desire!\nOut of the hard and riven bones knock they\nThe marrow, for they throw nothing away\nThat may go through the gullet soft and sweet;\nWith spicery, with leaf, bark, root, replete\nShall be the sauces made for your delight,\nTo furnish you a sharper appetite.\nBut truly, he that such delights entice\nIs dead while yet he wallows in this vice.\nA lecherous thing is wine, and drunkenness\nIs full of striving and of wretchedness.\nO drunken man, disfigured is your face,\nSour is your breath, foul are you to embrace,\nAnd through your drunken nose there comes a sound\nAs if you snored out Samson, Samson round;\nAnd yet God knows that Samson drank no wine.\nYou fall down just as if you were stuck swine;\nYour tongue is loose, your honest care obscure;\nFor drunkenness is very sepulture\nOf any mind a man may chance to own.\nIn whom strong drink has domination shown\nHe can no counsel keep for any dread.\nNow keep you from the white and from the red,\nAnd specially from the white wine grown at Lepe\nThat is for sale in Fish Street or in Cheap.\nThis wine of Spain, it mixes craftily\nWith other wines that chance to be near by,\nFrom which there rise such fumes, as well may be,\nThat when a man has drunk two draughts, or three,\nAnd thinks himself to be at home in Cheap,\nHe finds that he's in Spain, and right at Lepe,-\nNot at Rochelle nor yet at Bordeaux town,\nAnd then will he snore out Samson, Samson.\nBut hearken, masters, one word more I pray:\nThe greatest deeds of all, I'm bold to say,\nOf victories in the old testament,\nThrough the True God, Who is omnipotent,\nWere gained by abstinence and after prayer:\nLook in the Bible, you may learn this there.\nLo, Attila, the mighty conqueror,\nDied in his sleep, in shame and dishonour,\nAnd bleeding at the nose for drunkenness;\nA great captain should live in soberness.\nAbove all this, advise yourself right well\nWhat was commanded unto Lemuel-\nNot Samuel, but Lemuel, say I-\nThe Bible's words you cannot well deny:\nDrinking by magistrates is called a vice.\nNo more of this, for it may well suffice.\nAnd now that I have told of gluttony,\nI'll take up gambling, showing you thereby\nThe curse of chance, and all its evils treat;\nFrom it proceeds false swearing and deceit,\nBlaspheming, murder, and- what's more- the waste\nOf time and money; add to which, debased\nAnd shamed and lost to honour quite is he,\nWho once a common gambler's known to be.\nAnd ever the higher one is of estate,\nThe more he's held disgraced and desolate.\nAnd if a prince plays similar hazardry\nIn all his government and policy,\nHe loses in the estimate of men\nHis good repute, and finds it not again.\nChilon, who was a wise ambassador,\nWas sent to Corinth, all in great honour,\nFrom Lacedaemon, to make alliance.\nAnd when he came, he noticed there, by chance,\nAll of the greatest people of the land\nPlaying at hazard there on every hand.\nWherefore, and all as soon as it might be,\nHe stole off home again to his country,\nAnd said: I will not thus debase my name;\nNor will I take upon me so great shame\nYou to ally with common hazarders.\nSend, if you will, other ambassadors;\nFor, my truth, I say I'd rather die\nThan you with gamblers like to them ally.\nFor you that are so glorious in honours\nShall never ally yourselves with hazarders\nBy my consent, or treaty I have made.\nThis wise philosopher, 'twas thus he said.\nLet us look, then, at King Demetrius.\nThe king of Parthia, as the book tells us,\nSent him a pair of golden dice, in scorn,\nBecause the name of gambler he had borne;\nWherefore he marked his reputation down\nAs valueless despite his wide renown.\nGreat lords may find sufficient other play\nSeemly enough to while the time away.\nNow will I speak of oaths both false and great\nA word or two, whereof the old books treat.\nGreat swearing is a thing abominable,\nAnd vain oaths yet more reprehensible.\nThe High God did forbid swearing at all,\nAs witness Matthew; but in especial\nOf swearing says the holy Jeremiah,\nThou shalt not swear in vain, to be a liar,\nBut swear in judgment and in righteousness;\nBut idle swearing is a wickedness.\nBehold, in the first table of the Law,\nThat should be honoured as High God's, sans flaw,\nThis second one of His commandments plain:\nThou shalt not take the Lord God's name in vain.\nNay, sooner He forbids us such swearing\nThan homicide or many a wicked thing;\nI say that, as to order, thus it stands;\n'Tis known by him who His will understands\nThat the great second law of God is that.\nMoreover, I will tell you full and flat,\nThat retribution will not quit his house\nWho in his swearing is too outrageous.\nBy God's own precious heart, and by His nails,\nAnd by the blood of Christ that's now at Hales,\nSeven is my chance, and yours is five and trey!\nBy God's good arms, if you do falsely play,\nThis dagger through your heart I'll stick for you!\nSuch is the whelping of the bitched bones two:\nPerjury, anger, cheating, homicide.\n\nNow for the love of Christ, Who for us died,\nForgo this swearing oaths, both great and small;\nBut, sirs, now will I tell to you my tale.\nNow these three roisterers, whereof I tell,\nLong before prime was rung by any bell,\nWere sitting in a tavern for to drink;\nAnd as they sat they heard a small bell clink\nBefore a corpse being carried to his grave;\nWhereat one of them called unto his knave:\nGo run, said he, and ask them civilly\nWhat corpse it is that's just now passing by,\nAnd see that you report the man's name well.\nSir, said the boy, it needs not that they tell.\nI learned it, ere you came here, full two hours;\nHe was, by gad, an old comrade of yours;\nAnd he was slain, all suddenly, last night,\nWhen drunk, as he sat on his bench upright;\nAn unseen thief, called Death, came stalking by,\nWho hereabouts makes all the people die,\nAnd with his spear he clove his heart in two\nAnd went his way and made no more ado.\nHe's slain a thousand with this pestilence;\nAnd, master, ere you come in his presence,\nIt seems to me to be right necessary\nTo be forewarned of such an adversary:\nBe ready to meet him for evermore.\nMy mother taught me this, I say no more.\nBy holy Mary, said the innkeeper,\nThe boy speaks truth, for Death has slain, this year,\nA mile or more hence, in a large village,\nBoth man and woman, child and hind and page.\nI think his habitation must be there;\nTo be advised of him great wisdom 'twere,\nBefore he did a man some dishonour.\nYea, by God's arms! exclaimed this roisterer,\nIs it such peril, then, this Death to meet?\nI'll seek him in the road and in the street,\nAs I now vow to God's own noble bones!\nHear, comrades, we're of one mind, as each owns;\nLet each of us hold up his hand to other\nAnd each of us become the other's brother,\nAnd we three will go slay this traitor Death;\nHe shall be slain who's stopped so many a breath,\nBy God's great dignity, ere it be night.\nTogether did these three their pledges plight\nTo live and die, each of them for the other,\nAs if he were his very own blood brother.\nAnd up they started, drunken, in this rage,\nAnd forth they went, and towards that village\nWhereof the innkeeper had told before.\nAnd so, with many a grisly oath, they swore\nAnd Jesus' blessed body once more rent-\nDeath shall be dead if we find where he went.\nWhen they had gone not fully half a mile,\nJust as they would have trodden over a stile,\nAn old man, and a poor, with them did meet.\nThis ancient man full meekly them did greet,\nAnd said thus: Now, lords, God keep you and see!'\nThe one that was most insolent of these three\nReplied to him: What? Churl of evil grace,\nWhy are you all wrapped up, except your face?\nWhy do you live so long in so great age?\nThis ancient man looked upon his visage\nAnd thus replied: Because I cannot find\nA man, nay, though I walked from here to Ind,\nEither in town or country who'll engage\nTo give his youth in barter for my age;\nAnd therefore must I keep my old age still,\nAs long a time as it shall be God's will.\nNot even Death, alas! my life will take;\nThus restless I my wretched way must make,\nAnd on the ground, which is my mother's gate,\nI knock with my staff early, aye, and late,\nAnd cry: 'O my dear mother, let me in!\nLo, how I'm wasted, flesh and blood and skin!\nAlas! When shall my bones come to their rest?\nMother, with you fain would I change my chest,\nThat in my chamber so long time has been,\nAye! For a haircloth rag to wrap me in!'\nBut yet to me she will not show that grace,\nAnd thus all pale and withered is my face.\nBut, sirs, in you it is no courtesy\nTo speak to an old man despitefully,\nUnless in word he trespass or in deed.\nIn holy writ you may, yourselves, well read\n'Before an old man, hoar upon the head,\nYou should arise.' Which I advise you read,\nNor to an old man any injury do\nMore than you would that men should do to you\nIn age, if you so long time shall abide;\nAnd God be with you, whether you walk or ride.\nI must pass on now where I have to go.\nNay, ancient churl, by God it sha'n't be so,\nCried out this other hazarder, anon;\nYou sha'n't depart so easily, by Saint John!\nYou spoke just now of that same traitor Death,\nWho in this country stops our good friends' breath.\nHear my true word, since you are his own spy,\nTell where he is or you shall rue it, aye\nBy God and by the holy Sacrament!\nIndeed you must be, with this Death, intent\nTo slay all us young people, you false thief.\nNow, sirs, said he, if you're so keen, in brief,\nTo find out Death, turn up this crooked way,\nFor in that grove I left him, by my fay,\nUnder a tree, and there he will abide;\nNor for your boasts will he a moment hide.\nSee you that oak? Right there you shall him find.\nGod save you, Who redeemed all humankind,\nAnd mend your ways!- thus said this ancient man.\nAnd every one of these three roisterers ran\nTill he came to that tree; and there they found,\nOf florins of fine gold, new-minted, round,\nWell-nigh eight bushels full, or so they thought.\nNo longer, then, after this Death they sought,\nBut each of them so glad was of that sight,\nBecause the florins were so fair and bright,\nThat down they all sat by this precious hoard.\nThe worst of them was first to speak a word.\nBrothers, said he, take heed to what I say;\nMy wits are keen, although I mock and play.\nThis treasure here Fortune to us has given\nThat mirth and jollity our lives may liven,\nAnd easily as it's come, so will we spend.\nEh! By God's precious dignity! Who'd pretend,\nToday, that we should have so fair a grace?\nBut might this gold be carried from this place\nHome to my house, or if you will, to yours-\nFor well we know that all this gold is ours-\nThen were we all in high felicity.\nBut certainly by day this may not be;\nFor men would say that we were robbers strong,\nAnd we'd, for our own treasure, hang ere long.\nThis treasure must be carried home by night\nAll prudently and slyly, out of sight.\nSo I propose that cuts among us all\nBe drawn, and let's see where the cut will fall;\nAnd he that gets the short cut, blithe of heart\nShall run to town at once, and to the mart,\nAnd fetch us bread and wine here, privately.\nAnd two of us shall guard, right cunningly,\nThis treasure well; and if he does not tarry,\nWhen it is night we'll all the treasure carry\nWhere, by agreement, we may think it best.\nThat one of them the cuts brought in his fist\nAnd bade them draw to see where it might fall;\nAnd it fell on the youngest of them all;\nAnd so, forth toward the town he went anon.\nAnd just as soon as he had turned and gone,\nThat one of them spoke thus unto the other:\nYou know well that you are my own sworn brother,\nSo to your profit I will speak anon.\nYou know well how our comrade is just gone;\nAnd here is gold, and that in great plenty,\nThat's to be parted here among us three.\nNevertheless, if I can shape it so\nThat it be parted only by us two,\nShall I not do a turn that is friendly?\nThe other said: Well, now, how can that be?\nHe knows well that the gold is with us two.\nWhat shall we say to him? What shall we do?\nShall it be secret? asked the first rogue, then,\nAnd I will tell you in eight words, or ten,\nWhat we must do, and how bring it about.\nAgreed, replied the other, Never doubt,\nThat, on my word, I nothing will betray.\nNow, said the first, we're two, and I dare say\nThe two of us are stronger than is one.\nWatch when he sits, and soon as that is done\nArise and make as if with him to play;\nAnd I will thrust him through the two sides, yea,\nThe while you romp with him as in a game,\nAnd with your dagger see you do the same;\nAnd then shall all this gold divided be,\nMy right dear friend, just between you and me;\nThen may we both our every wish fulfill\nAnd play at dice all at our own sweet will.\nAnd thus agreed were these two rogues, that day,\nTo slay the third, as you have heard me say.\nThis youngest rogue who'd gone into the town,\nOften in fancy rolled he up and down\nThe beauty of those florins new and bright.\nO Lord, thought he, if so be that I might\nHave all this treasure to myself alone,\nThere is no man who lives beneath the throne\nOf God that should be then so merry as I.\nAnd at the last the Fiend, our enemy,\nPut in his thought that he should poison buy\nWith which he might kill both his fellows; aye,\nThe Devil found him in such wicked state,\nHe had full leave his grief to consummate;\nFor it was utterly the man's intent\nTo kill them both and never to repent.\nAnd on he strode, no longer would he tarry,\nInto the town, to an apothecary,\nAnd prayed of him that he'd prepare and sell\nSome poison for his rats, and some as well\nFor a polecat that in his yard had lain,\nThe which, he said, his capons there had slain,\nAnd fain he was to rid him, if he might,\nOf vermin that thus damaged him by night.\nThe apothecary said: And you shall have\nA thing of which, so God my spirit save,\nIn all this world there is no live creature\nThat's eaten or has drunk of this mixture\nAs much as equals but a grain of wheat,\nThat shall not sudden death thereafter meet;\nYea, die he shall, and in a shorter while\nThan you require to walk but one short mile;\nThis poison is so violent and strong.\nThis wicked man the poison took along\nWith him boxed up, and then he straightway ran\nInto the street adjoining, to a man,\nAnd of him borrowed generous bottles three;\nAnd into two his poison then poured he;\nThe third one he kept clean for his own drink.\nFor all that night he was resolved to swink\nIn carrying the florins from that place.\nAnd when this roisterer, with evil grace,\nHad filled with wine his mighty bottles three,\nThen to his comrades forth again went he.\nWhat is the need to tell about it more?\nFor just as they had planned his death before,\nJust so they murdered him, and that anon.\nAnd when the thing was done, then spoke the one:\nNow let us sit and drink and so be merry,\nAnd afterward we will his body bury.\nAnd as he spoke, one bottle of the three\nHe took wherein the poison chanced to be\nAnd drank and gave his comrade drink also,\nFor which, and that anon, lay dead these two.\nI feel quite sure that Doctor Avicena\nWithin the sections of his Canon never\nSet down more certain signs of poisoning\nThan showed these wretches two at their ending.\nThus ended these two homicides in woe;\nDied thus the treacherous poisoner also.\nO cursed sin, full of abominableness!\nO treacherous homicide! O wickedness!\nO gluttony, lechery, and hazardry!\nO blasphemer of Christ with villainy,\nAnd with great oaths, habitual for pride!\nAlas! Mankind, how may this thing betide\nThat to thy dear Creator, Who thee wrought,\nAnd with His precious blood salvation bought,\nThou art so false and so unkind, alas!\nNow, good men, God forgive you each trespass,\nAnd keep you from the sin of avarice.\nMy holy pardon cures and will suffice,\nSo that it brings me gold, or silver brings,\nOr else, I care not- brooches, spoons or rings.\nBow down your heads before this holy bull!\nCome up, you wives, and offer of your wool!\nYour names I'll enter on my roll, anon,\nAnd into Heaven's bliss you'll go, each one.\nFor I'll absolve you, by my special power,\nYou that make offering, as clean this hour\nAs you were born. And lo, sirs, thus I preach.\nAnd Jesus Christ, who is our souls' great leech,\nSo grant you each his pardon to receive;\nFor that is best; I will not you deceive.\nBut, sirs, one word forgot I in my tale;\nI've relics in my pouch that cannot fail,\nAs good as England ever saw, I hope,\nThe which I got by kindness of the pope.\nIf gifts your change of heart and mind reveal,\nYou'll get my absolution while you kneel.\nCome forth, and kneel down here before, anon,\nAnd humbly you'll receive my full pardon;\nOr else receive a pardon as you wend,\nAll new and fresh as every mile shall end,\nSo that you offer me each time, anew,\nMore gold and silver, all good coins and true.\nIt is an honour to each one that's here\nThat you may have a competent pardoner\nTo give you absolution as you ride,\nFor all adventures that may still betide.\nPerchance from horse may fall down one or two,\nBreaking his neck, and it might well be you.\nSee what insurance, then, it is for all\nThat I within your fellowship did fall,\nWho may absolve you, both the great and less,\nWhen soul from body passes, as I guess.\nI think our host might just as well begin,\nFor he is most-enveloped in all sin.\nCome forth, sir host, and offer first anon,\nAnd you shall kiss the relics, every one,\nAye, for a groat! Unbuckle now your purse.\nNay, nay, said he, then may I have Christ's curse!\nIt sha'n't be, said he, as I've hope for riches,\nWhy, you would have me kissing your old breeches,\nAnd swear they were the relics of a saint,\nThough with your excrement 'twere dabbed like paint.\nBy cross Saint Helen found in Holy Land,\nI would I had your ballocks in my hand\nInstead of relics in a reliquary;\nLet's cut them off, and them I'll help you carry;\nThey shall be shrined within a hog's fat turd.\nThis pardoner, he answered not a word;\nSo wrathy was he no word would he say.\nNow, said our host, I will no longer play\nWith you, nor any other angry man.\nBut at this point the worthy knight began,\nWhen that he saw how all the folk did laugh:\nNo more of this, for it's gone far enough;\nSir pardoner, be glad and merry here;\nAnd you, sir host, who are to me so dear,\nI pray you that you kiss the pardoner.\nAnd, pardoner, I pray you to draw near,\nAnd as we did before, let's laugh and play.\nAnd then they kissed and rode forth on their way.\n\n\n### The Shipman's Prologue\n\nOur host upon his stirrups stood, anon,\nAnd said: Good men, now hearken, every one;\nThis was useful story, for the nonce!\nSir parish priest, quoth he, for God His bones.\nTell us a tale, as you agreed before.\nI see well that you learned men of lore\nHave learned much good, by God's great dignity!\nThe parson answered: Benedicite!\nWhat ails the man, so sinfully to swear?\nOur host replied: Ho, Jenkin, are you there?\nI smell a Lollard in the wind, quoth he.\nHo, good men! said our host, now hearken me;\nWait but a bit, for God's high passion do,\nFor we shall have a sermon ere we're through;\nThis Lollard here will preach to us somewhat.\nNay, by my father's soul, that shall he not!\nReplied the sailor; Here he shall not preach,\nNor comment on the gospels here, nor teach.\nWe all believe in the great God, said he,\nBut he would sow among us difficulty,\nOr sprinkle cockles in our good clean corn;\nAnd therefore, host, beforehand now, I warn\nMy jolly body shall a story tell\nAnd I will clink for you so merry a bell\nThat it shall waken all this company;\nBut it shall not be of philosophy,\nNor yet of physics, nor quaint terms of law;\nThere is but little latin in my maw.\n\n\n### The Shipman's Tale\n\nA merchant, dwelling, once, at Saint Denis,\nWas rich, for which men held him wise, and he\nHad got a wife of excellent beauty,\nAnd very sociable and gay was she,\nWhich is a thing that causes more expense\nThan all the good cheer and the deference\nThat men observe at festivals and dances;\nSuch salutations and masked countenances\nPass by as does a shadow on the wall;\nBut woe to him that must pay for it all.\nThe foolish husband, always he must pay;\nHe must buy clothes and other fine array,\nAnd all for his own worship, wealthily,\nIn which, indeed, women dance jollily.\nAnd if he cannot thus, peradventure,\nOr cares not such expenses to endure,\nBut thinks his money wasted or quite lost,\nWhy then another man must pay the cost,\nOr else lend gold, and that is dangerous.\nThis noble merchant had a worthy house,\nTo which, each day, so many did repair,\nSince he was generous and his wife was fair,\n'Twas to be wondered at; but hear my tale.\nAmong his many guests of great and small\nThere was a monk, a handsome man and bold,\nI think that he was thirty winters old,\nWho was for ever coming to that place.\nThis youthful monk, who was so fair of face,\nWas so far intimate with the worthy man,\nAnd had been since their friendship first began.\nThat in the house familiar was he\nAs it is possible for friend to be.\nAnd in as much as this same goodly man\nAnd too, this monk of whom I first began,\nWere both born in the village they'd lived in,\nThe monk claimed him for cousin, or such kin;\nAnd he again, he never said him nay,\nBut was as glad thereof as bird of day;\nFor to his heart it was a great pleasance.\nThus they were knit by endless alliance,\nAnd each of them did other one assure\nOf brotherhood the while their lives endure.\nFree was Dan John with money and expense\nWhen in that house; and full of diligence\nTo please all there, whatever be his age.\nHe ne'er forgot to tip the humblest page\nIn all that house; according to degree\nHe gave the master, then the company,\nWhene'er he came, some kind of honest thing;\nFor which they were as glad of his coming\nAs bird is glad when the new sun up-rises.\nNo more of all this now, for it suffices.\nIt so befell, this merchant, on a day,\nPrepared to make all ready his array,\nSince to the town of Bruges he was to fare\nTo purchase there a quantity of ware;\nTo which end he'd to Paris sent someone\nWith messages, and he had prayed Dan John\nThat he should come to Saint-Denis to pay\nHim and his wife a visit for a day,\nSaid 'twas a thing he certainly must do.\nThis noble monk, whereof I'm telling you.\nHad from his abbot, when he wished, license,\nBecause he was a man of great prudence,\nAn officer, indeed, who out did ride\nTo see to barns and granges, far and wide;\nAnd now to Saint-Denis he came anon.\nWho was so welcome as my lord Dan John,\nOur cousin dear, so full of courtesy?\nWith him he brought a jug of rare malmsey,\nAnd still another full of fine vernage,\nAnd wild fowls, too, as was his long usage.\nAnd so I let them eat and drink and play,\nThis monk and merchant, for a night and day.\nUpon the third day this good trader rises,\nAnd on his needs discreetly he advises;\nAnd up into his counting-house goes he\nTo reckon up his books, as well may be,\nFor the past year, to learn how matters stood\nAnd what he'd spent, and whether it were good,\nAnd whether he were wealthier than before.\nHis books and bags, all that he had in store,\nHe put before him on his counting-board;\nHe was right rich in goods and rich in hoard,\nFor the which cause he bolted fast his door;\nHe'd have no one disturb him while before\nHim stood his books and monies at that time;\nAnd thus he sat till it was well past prime.\nDan John had risen with the dawn, also,\nAnd in the garden wandered to and fro,\nHaving said all his prayers full reverently.\nThen came this goodwife, walking secretly\nInto the garden, walking slow and soft.\nAnd kissed him in salute, as she'd done oft.\nA little girl came walking at her side,\nWas in her charge to govern and to guide,\nFor yet beneath the rod was this small maid.\nO my dear cousin, O Dan John, she said,\nWhat ails you that so early you arise?\nDear niece, said he, surely it should suffice\nTo sleep for five full hours of any night,\nUnless 'twere for some old and languid wight,\nAs are these married men, who doze and dare\nAbout as in the form the weary hare,\nWorn all distraught by hounds both great and small.\nBut, my dear niece, just why are you so pale?\nI must suppose of course that our good man\nHas you belaboured since the night began,\nAnd you were forced to sleep but scantily.\nAnd with that word he laughed right merrily,\nAnd, what of his own thoughts, he blushed all red.\nThis pretty wife began to shake her head,\nAnd answered thus: Aye, God knows all! said she:\nNay, cousin mine, it stands not so with me.\nFor by that God Who gave me soul and life,\nIn all the realm of France there is no wife\nWho has less lust for that same sorry play.\nFor I may sing 'Alas!' and 'Welaway\nThat I was born!' but to no man, said she,\nDare I to tell how this thing stands with me.\nWherefore I'm thinking from this land to wend,\nOr else of my own life to make an end,\nI am so fearful and so full of care.\nThis monk began, then, at the wife to stare,\nAnd said: Alas, my niece, may God forbid\nThat you, for any care or fear morbid,\nDestroy yourself! But tell me of your grief;\nPerhaps I may, whatever the mischief,\nCounsel or help, and therefore do tell me\nAll the annoyance, for 'twill secret be;\nFor on my breviary I make oath\nThat never in my life, though lief or loath,\nShall I your secret whisper or betray.\nThe same to you again, said she, I say;\nBy God and by this breviary, I swear,\nThough men this body of mine a-pieces tear,\nNo I will never, though I go to Hell,\nBetray a single word that you may tell,\nAnd this, not for our kinship and alliance,\nBut verily for love and true reliance.\nThus are they sworn, and thereupon they kissed,\nAnd each told other such things as they list.\nCousin, said she, if I had time and space,\nAs I have not, and specially in this place,\nThen would I tell a legend of my life,\nWhat I have suffered since I've been a wife,\nFrom my husband, though he is your cousin.\nNay, quoth the monk, by God and Saint Martin,\nHe is no more a cousin unto me\nThan is this leaf a-hanging on the tree!\nI call him so, by Saint-Denis of France,\nTo have but better reason to advance\nWith you, whom I have loved especially\nAbove all other women, and truly;\nI swear this to you on the faith I own.\nTell me your grief before your man comes down,\nCome, hasten now, and go your way anon.\nMy dearest love, said she, O my Dan John,\nRight glad I were this counsel for to hide,\nBut it must out, I can't it more abide.\nTo me my husband is the poorest man\nThat ever was, since first the world began.\nBut since I am a wife, becomes not me\nTo tell a living soul our privity,\nEither abed or in some other place;\nGod guard that I should tell it, of His grace!\nFor wife must never talk of her husband,\nSave to his honour, as I understand.\nBut now to you thus much I can and shall:\nSo help me God, he is not worth, at all,\nIn any wise, the value of a fly.\nBut yet this grieves me most- he's niggardly;\nAnd well you know that women naturally\nDesire six things, and even so do I.\nFor women all would have their husbands be\nHardy, and wise, and rich, and therewith free,\nObedient to the wife, and fresh in bed.\nBut by that very Lord Who for us bled,\nThough in his honour, myself to array\nOn Sunday next, I must yet go and pay\nA hundred francs, or else be but forlorn.\nYet would I rather never have been born\nThan have a scandal or disgrace, say I.\nAnd if my husband such a thing should spy,\nI were but lost, and therefore do I pray,\nLend me this sum, or else I perish, yea!\nDan John, I say, lend me these hundred francs;\nBy gad, I will not fail to give you thanks,\nIf only you will do the thing I pray.\nFor on a certain day I will repay,\nAnd give to you what pleasure and service\nI can give, aye, just as you may devise.\nAnd if I don't, God take on me vengeance\nAs foul as once on Ganelon of France!\nThis gentle monk replied as you shall hear.\nNow truthfully, my own sweet lady dear,\nI have, said he, on you so great a ruth\nThat I do swear and promise you, in truth,\nThat when your husband goes to Flanders there,\nI will deliver you from all this care;\nFor I will bring to you a hundred francs.\nAnd with that word he caught her by the flanks\nAnd hugged her to him hard and kissed her oft.\nGo now your way, he said, all still and soft,\nAnd let us dine as soon as ever we may,\nFor by my dial it's the prime of day.\nGo now, and be as true as I shall be.\nNow all else God forbid, sir, then said she.\nAnd in she went as jolly as a pie,\nAnd bade the cooks that they to kitchen hie,\nSo that her men might dine, and that anon.\nUp to her husband is this wife then gone,\nAnd knocked upon his counting-room boldly.\nQui est la? asked he. Peter! It is I,\nSaid she; What, sir, and how long will you fast?\nHow long time will you reckon up and cast\nYour sums and books and other tiresome things?\nThe devil take away such reckonings!\nYou have enough, by gad, of God's mercy;\nCome down today, and let your gold-bags be.\nWhy, are you not ashamed that our Dan John\nHas fasted miserably all morning gone?\nWhat! Let us hear a Mass and then go dine.\nWife, said this man, little can you divine\nThe curious businesses that merchants have.\nAs for us traders, as may God me save,\nAnd by that lord that all we call Saint Yve,\nAmong twelve merchants scarcely two shall thrive\nContinually, and lasting into age.\nWe must keep open house and blithe visage,\nWhile goes the world as it may chance to be,\nAnd hold all our affairs in secrecy\nTill we are dead; or else we must go play\nAt pilgrimage, or else go clean away.\nAnd therefore have I great necessity\nThat on this curious world advised I be;\nFor evermore we merchants stand in dread\nOf chance and mishap as our ways we tread.\nTo Flanders go I at the break of day,\nAnd I'll come back as soon as ever I may.\nFor which, my dearest wife, your aid I seek\nTo be, to all, both courteous and meek,\nAnd to maintain our wealth be studious,\nAnd govern honourably and well our house.\nYou have enough in every sort of wise\nThat, to a thrifty, household, should suffice.\nYou've clothes and food, I've seen to each detail,\nAnd silver in your purse shall never fail.\nAnd with that word his counting-door he shut\nAnd down he went, no longer tarrying, but\nRight hastily a Mass for them was said,\nAnd speedily the tables there were spread,\nAnd to the dinner swiftly all they sped;\nAnd richly then the monk this merchant fed\nAfter the dinner Dan John soberly\nThis merchant took aside, and privately\nHe said to him, Cousin, it stands just so,\nFor I see well that you to Bruges will go.\nGod and good Saint Augustine speed and guide!\nI pray you, cousin, that you'll wisely ride;\nGuard your health well, and govern your diet\nTemperately, especially in this heat.\nNeither of us requires outlandish fare;\nFarewell, dear cousin; God shield you from care.\nIf anything there be, by day or night,\nIf it lie in my power and my might,\nThat you would have me do, in any wise,\nIt shall be done, just as you may devise.\nOne thing, before you go, if it may be,\nI pray you do, and that is, to lend me\nA hundred francs, for but a week or two,\nFor certain cattle I must buy, to do\nThe stocking of a little place of ours.\nSo help me God, I would that it were yours!\nI will not fail you, come next settling day,\nNot for a thousand francs, a mile away.\nBut let this thing be secret, pray, for I,\nEven tonight, must go these beasts to buy;\nAnd farewell now, my own good cousin dear.\nAnd many thanks for entertainment here.\nThis noble merchant, civilly, anon,\nAnswered and said: O cousin mine, Dan John,\nNow surely this is but a small request;\nMy gold is yours and aye at your behest.\nAnd not gold only, no but all my ware;\nTake what you like, God shield that you should spare.\nThere's but one thing, which you know well enow\nOf traders, for their money is their plow.\nWe may on credit trade, while we've a name,\nBut to be goldless is to lose the game.\nPay it again when you are at your ease;\nIn all I can, full fain am I to please.\nThese hundred francs he went and got anon,\nAnd privately he gave them to Dan John.\nNo one in all the world knew of this loan,\nSaving this merchant and Dan John alone.\nThey drink, and talk, and walk awhile, and play,\nUntil Dan John sets out for his abbey.\nThe morrow came and forth this merchant rides\nToward Flanders; and his apprentice guides\nUntil he came to Bruges all happily.\nNow went this merchant fast and busily\nAbout his trade, and bought, and borrowed gold;\nHe neither played at dice nor danced, I'm told,\nBut like a merchant, briefly here to tell,\nHe led his life, and there I let him dwell.\nOn the first Sunday after he was gone,\nTo Saint-Denis is come again Dan John,\nWith face and tonsure shining from a shave.\nIn all the house was not so small a knave,\nNor any other, but was right glad, then,\nBecause my lord Dan John was come again.\nAnd coming briefly to point, anon\nThis lovely wife agreed with her Dan John\nThat for these hundred francs he should, all night,\nHave her within his arms and bolt upright;\nAnd this agreement was performed in bed.\nIn mirth all night a busy life they led\nTill it was dawn, when Dan John went his way,\nBidding the household Farewell! and Good-day!\nFor none of them, nor any in the town,\nHad of Dan John the least suspicion shown.\nSo forth he rode, home to his own abbey,\nOr where he wished; no more of him I say.\nThis merchant, when all ended was the fair,\nTo Saint-Denis made ready to repair;\nAnd with his wife he feasted and made cheer,\nAnd told her that, since goods were very dear,\nHe needs must get more cash at his command,\nFor he was bound by his own note of hand\nTo pay some twenty thousand crowns anon.\nFor which this merchant is to Paris gone\nTo borrow there, from certain friends he had,\nSome certain francs unto his own to add.\nAnd when he'd come at length into the town,\nOut of great friendship never yet outgrown,\nUnto Dan John he went first, there to play,\nNot to talk business, nor ask money, nay,\nBut to inquire and see to his welfare,\nAnd, too, to tell about his Flemish ware,\nAs friends are wont when come from far or near.\nDan John made him a feast and merry cheer;\nAnd he told him again, and specially,\nHow he had purchased well and luckily-\nThanks be to God!- all of his merchandise.\nSave that he must, nor fail in any wise,\nObtain a loan, at least it would be best,\nAnd then he'd have some time for joy and rest.\nDan John replied: No gladness do I feign\nThat sound in health you are come home again.\nAnd if I were but rich, as I have bliss,\nThese twenty thousand crowns you should not miss,\nSince you so kindly, but the other day,\nLent me some gold; and as I can and may,\nI thank you, by the Lord and by Saint James!\nNevertheless, to no hand but our dame's,\nYour wife at home, I gave the gold again\nUpon your counter; she'll remember when\nBy certain tokens that I gave to her.\nNow, by your leave, I must get up and stir,\nOur abbot will be leaving town anon;\nAnd in his company I must be gone.\nGreet well our dame, your wife and my niece sweet,\nAnd farewell, cousin dear, until we meet.\nThis merchant, being a man full wary-wise,\nHas got his loan and paid there in Paris,\nTo certain Lombards, ready in their hand,\nThe sum of gold, and got his note back, and\nNow home he goes as merry as a jay.\nFor well he knew he stood in such array\nThat now he needs must make, with nothing lost,\nA thousand francs above his total cost.\nHis wife, all ready, met him at the gate,\nAs she was wont, though he came soon or late,\nAnd all that night with pleasure did they pet,\nFor he was rich and cleanly out of debt.\nWhen it was day, this merchant did embrace\nHis wife anew, and kissed her on her face,\nAnd up he goes and makes it rather tough.\nNo more, cried she, by God, you've had enough!\nAnd wantonly again with him she played,\nTill, at the last, this merchant sighed and said:\nBy God, said he, I am a little wroth\nWith you, my wife, though to be so I'm loath.\nAnd know you why? By God, and as I guess,\nYou've been the causing of some small strangeness\nBetween me and my cousin, dear Dan John.\nYou should have warned me, really, ere I'd gone,\nThat he to you a hundred francs had paid\nIn cash; he was put out, I am afraid,\nBecause I spoke to him of loans, by chance,\nAt least I judged so by his countenance.\nNevertheless, by God our Heavenly King,\nI never thought to ask him such a thing.\nI pray you, wife, never again do so;\nBut always tell me, ere away I go,\nIf any debtor has, in my absence,\nRepaid to you, lest through your negligence\nI might demand a sum already paid.\nThis wife was not astounded nor afraid,\nBut boldly she spoke up and that anon:\nMarry, I challenge that false monk, Dan John!\nI kept, of all his coins, not one to tell.\nHe brought me certain gold- that know I well\nWhat! Ill success upon his friar's snout!\nFor God knows that I thought, with never a doubt.\nThat he had given it me because of you,\nTo advance thus my honour, and yours too,\nIn cousinhood, and for the merry cheer\nThat he has found so many a time right here.\nBut since I see our peace is thus disjoint,\nI'll answer you but briefly, to the point.\nYou have far slacker debtors than am I!\nFor I will pay you well and readily\nFrom day to day; and if it be I fail\nI am your wife, tally it on my tail,\nAnd I will pay as soon as ever I may.\nFor by my truth I have, on new array,\nAnd not on rubbish, spent it, every sou.\nAnd since so well I've spent it, all for you,\nAll for your honour, for God's sake, I say,\nDo not be angry, but let's laugh and play.\nMy jolly body's yours in pledge, she said,\nBy God, I will not pay you, save in bed!\nForgive me, then, my own sweet husband dear;\nLet us be happy now- turn over here!\nThis merchant saw there was no remedy,\nAnd, thought he, chiding were but great folly,\nSince that the thing might not amended be.\nNow wife, he said, I do forgive, you see;\nBut on your life, don't run so far at large;\nConserve our wealth hereafter, so I charge.\nThus ends my tale, and may the good God send\nTales fair enough until our lives shall end! Amen.\n\n"},{"index":8,"markdown":"### The Words of the Host to the Prioress\n\nWell said, by corpus dominus, said our host,\nNow long time may you sail along the coast,\nSir gentle master, gentle mariner!\nGod give this monk a thousand years bitter!\nAha, comrades, beware of such a jape!\nThe monk put into that man's hood an ape,\nAnd in the wife's too, by Saint Augustine!\nInvite no more monks to your house or inn.\nBut let that pass, and let us look about\nTo see who shall be next, of all this rout,\nTo tell a tale. And after that he said,\nAs courteously as it had been a maid:\nMy lady prioress, and by your leave,\nSo that I knew I should in no way grieve,\nI would opine that tell a tale you should,\nThe one that follows next if you but would.\nNow will you please vouchsafe it, lady dear?\nGladly, said she, and spoke as you shall hear.\n\n\n### The Prioress's Prologue\n\nO Lord, Our Lord, Thy name how marvelous\nIs spread through all this mighty world, said she;\nFor not alone Thy praise so glorious\nIs given by men of worth and dignity,\nBut from the mouths of children Thy bounty\nIs hymned, yea, even sucklings at the breast\nDo sometimes Thy laudation manifest.\nWherefore in praise, as best I can or may,\nOf Thee and of that pure white Lily-flower\nWho bore Thee, and is yet a maid alway,\nI tell a tale as best is in my power,\nNot that I may increase Her heavenly dower,\nFor She Herself is honour and the one\nFrom Whom spring wealth and goodness, next Her Son.\nO Mother-Maid! O Maiden-Mother free!\nO bush unburnt, burning in Moses' sight,\nWho ravished so the Soul of Deity,\nWith Thy meekness, the Spirit of the Light,\nThat His virtue, which was Thy soul's delight,\nConceived in Thee the Father's wise Essence,\nHelp me to speak now with all reverence!\nLady, Thy goodness and Thy generous grace.\nThy virtue and Thy great humility-\nNo tongue may say, no pen may fully trace;\nFor sometimes, Lady, ere men pray to Thee.\nThou goest before, of Thy benignity,\nAnd givest us the true light, by Thy prayer,\nTo guide us all unto Thy Son so dear.\nI cannot bear the burden, blessed Queen,\nOf fitly praising all Thy worthiness,\nMy wisdom and my knowledge are too mean;\nBut as a child of twelve months old, or less,\nThat scarcely any word can well express,\nSo fare I now, and therefore do I pray,\nGuide Thou that song of Thee which I shall say!'\n\n\n### The Prioress's Tale\n\nIn Asia, in a city rich and great\nThere was a Jewry set amidst the town,\nEstablished by a rich lord of the state\nFor usury and gain of ill renown,\nHateful to Christ and those who are His own;\nAnd through that street a man might ride or wend,\nFor it was free and open at each end.\nA little school for Christian folk there stood,\nDown at the farther end, in which there were\nA many children born of Christian blood,\nWho learned in that same school, year after year,\nSuch teachings as with men were current there,\nWhich is to say, to sing well and to read,\nAs children do of whatsoever creed.\nAmong these children was a widow's son,\nA little choir boy, seven years of age,\nWho went to school as days passed one by one,\nAnd who, whenever saw he the image\nOf Jesus' Mother, it was his usage,\nAs he'd been taught, to kneel down there and say\nAve Maria, ere he went his way.\nThus had this widow her small son well taught\nOur Blessed Lady, Jesus' Mother dear,\nTo worship always, and he ne'er forgot,\nFor simple child learns easily and clear;\nBut ever, when I muse on matters here,\nSaint Nicholas stands aye in my presence,\nFor he, when young, did do Christ reverence.\nThis little child, his little lesson learning,\nSat at his primer in the school, and there,\nWhile boys were taught the antiphons, kept turning,\nAnd heard the Alma redemptoris fair,\nAnd drew as near as ever he did dare,\nMarking the words, remembering every note,\nUntil the first verse he could sing by rote.\nHe knew not what this Latin meant to say,\nBeing so young and of such tender age,\nBut once a young school-comrade did he pray\nTo expound to him the song in his language,\nOr tell him why the song was in usage;\nAsking the boy the meaning of the song,\nOn his bare knees he begged him well and long.\nHis fellow was an older lad than he,\nAnd answered thus: This song, as I've heard say,\nWas made to praise Our Blessed Lady free,\nHer to salute and ever Her to pray\nTo be our help when comes our dying day.\nI can expound to you only so far;\nI've learned the song; I know but small grammar.\nAnd is this song made in all reverence\nOf Jesus' Mother? asked this innocent;\nNow truly I will work with diligence\nTo learn it all ere Christmas sacrament,\nThough for my primer I take punishment\nAnd though I'm beaten thrice within the hour,\nYet will I learn it by Our Lady's power!\nHis fellow taught him on their homeward way\nUntil he learned the antiphon by rote.\nThen clear and bold he sang it day by day,\nEach word according with its proper note;\nAnd twice each day it welled from out his throat,\nAs schoolward went he and as homeward went;\nOn Jesus' Mother was his fixed intent.\nAs I have said, as through the Jewry went\nThis little school-boy, out the song would ring,\nAnd joyously the notes he upward sent;\nO Alma redemptoris would he sing;\nTo his heart's core it did the sweetness bring\nOf Christ's dear Mother, and, to Her to pray,\nHe could not keep from singing on his way.\nOur primal foe, the serpent Sathanas,\nWho has in Jewish heart his hornets' nest,\nSwelled arrogantly: O Jewish folk, alas!\nIs it to you a good thing, and the best,\nThat such a boy walks here, without protest,\nIn your despite and doing such offense\nAgainst the teachings that you reverence?\nFrom that time forth the Jewish folk conspired\nOut of the world this innocent to chase;\nA murderer they found, and thereto hired,\nWho in an alley had a hiding-place;\nAnd as the child went by at sober pace,\nThis cursed Jew did seize and hold him fast,\nAnd cut his throat, and in a pit him cast.\nI say, that in a cesspool him they threw,\nWherein these Jews did empty their entrails.\nO cursed folk of Herod, born anew,\nHow can you think your ill intent avails?\nMurder will out, 'tis sure, nor ever fails,\nAnd chiefly when God's honour vengeance needs.\nThe blood cries out upon your cursed deeds.\nO martyr firm in thy virginity,\nNow mayest thou sing, and ever follow on\nThe pure white Lamb Celestial- quoth she-\nWhereof the great evangelist, Saint John,\nIn Patmos wrote, saying that they are gone\nBefore the Lamb, singing a song that's new,\nAnd virgins all, who never woman knew.\nThis widow poor awaited all that night\nHer child's return to her, but be came not;\nFor which, so soon as it was full daylight,\nWith pale face full of dread, and busy thought,\nAt school she sought and everywhere she sought,\nUntil, at last, from all her questioning she\nLearned that he last was seen in the Jewry.\nWith mother's pity in her breast enclosed\nShe ran, as she were half out of her mind,\nTo every place where it might be supposed,\nIn likelihood, that she her son should find;\nAnd ever on Christ's Mother meek and kind\nShe called until, at last, Our Lady wrought\nThat amongst the cursed Jews the widow sought.\nShe asked and she implored, all piteously,\nOf every Jew who dwelt in that foul place,\nTo tell her where her little child could be.\nThey answered Nay. But Jesus, of His grace,\nPut in her mind, within a little space,\nThat after him in that same spot she cried\nWhere he'd been cast in it, or near beside.\nO Thou great God, Who innocents hast called\nTo give Thee praise, now shown is Thy great might!\nThis gem of chastity, this emerald,\nOf martyrdom the ruby clear and bright,\nBegan, though slain and hidden there from sight,\nThe Alma redemptoris loud to sing,\nSo clear that all the neighbourhood did ring.\nThe Christian folk that through the ghetto went\nCame running for the wonder of this thing,\nAnd hastily they for the provost sent;\nHe also came without long tarrying,\nAnd gave Christ thanks, Who is of Heaven King,\nAnd, too, His Mother, honour of mankind;\nAnd after that the Jews there did he bind.\nThis child, with piteous lamentation, then\nWas taken up, singing his song alway;\nAnd, honoured by a great concourse of men,\nCarried within an abbey near, that day.\nSwooning, his mother by the black bier lay,\nNor easily could people who were there\nThis second Rachel carry from the bier.\nWith torture and with shameful death, each one,\nThe provost did these cursed Hebrews serve\nWho of the murder knew, and that anon;\nFrom justice to the villains he'd not swerve.\nEvil shall have what evil does deserve.\nAnd therefore, with wild horses, did he draw,\nAnd after hang, their bodies, all by law.\nUpon the bier lay this poor innocent\nBefore the altar, while the mass did last,\nAnd after that the abbot and monks went\nAbout the coffin for to close it fast;\nBut when the holy water they did cast,\nThen spoke the child, at touch of holy water,\nAnd sang, O Alma redemptoris mater!\nThis abbot, who was a right holy man,\nAs all monks are, or as they ought to be,\nThe dead young boy to conjure then began,\nSaying: O dear child, I do beg of thee,\nBy virtue of the Holy Trinity,\nTell me how it can be that thou dost sing\nAfter thy throat is cut, to all seeming?\nMy throat is cut unto the spinal bone,\nReplied the child. By nature of my kind\nI should have died, aye, many hours agone,\nBut Jesus Christ, as you in books shall find,\nWills that His glory last in human mind;\nThus for the honour of His Mother dear,\nStill may I sing 'O Alma' loud and clear.\nThis well of mercy, Jesus' Mother sweet,\nI always loved, after poor knowing;\nAnd when came time that I my death must meet,\nShe came to me and bade me only sing\nThis anthem in the pain of my dying,\nAs you have heard, and after I had sung,\nShe laid a precious pearl upon my tongue.\nWherefore I sing, and sing I must, 'tis plain,\nIn honour of that blessed Maiden free,\nTill from my tongue is taken away the grain;\nAnd afterward she said thus unto me:\n'My little child, soon will I come for thee,\nWhen from thy tongue the little bead they take;\nBe not afraid, thee I will not forsake.'\nThe holy monk, this abbot, so say I,\nThe tongue caught out and took away the grain,\nAnd he gave up the ghost, then, easily,\nAnd when the abbot saw this wonder plain,\nThe salt tears trickled down his cheeks like rain,\nAnd humbly be fell prone upon the ground,\nLying there still as if he had been bound.\nAnd all the monks lay there on the pavement,\nWeeping and praising Jesus' Mother dear,\nAnd after that they rose and forth they went,\nTaking away this martyr from his bier,\nAnd in a tomb of marble, carved and clear,\nDid they enclose his little body sweet;\nWhere he is now- grant us him to meet!\nO you young Hugh of Lincoln, slain also\nBy cursed Jews, as is well known to all,\nSince it was but a little while ago,\nPray you for us, sinful and weak, who call,\nThat, of His mercy, God will still let fall\nSomething of grace, and mercy multiply,\nFor reverence of His Mother dear on high. Amen.\n\n\n### Sir Topas's Prologue\n\nWhen told was all this miracle, every man\nSo sober fell 'twas wonderful to see,\nUntil our host in jesting wise began,\nAnd for the first time did he glance at me,\nSaying, What man are you?- 'twas thus quoth he-\nYou look as if you tried to find a hare,\nFor always on the ground I see you stare.\nCome near me then, and look up merrily.\nNow make way, sirs, and let this man have place;\nHe in the waist is shaped as well as I;\nThis were a puppet in an arm's embrace\nFor any woman, small and fair of face.\nWhy, he seems absent, by his countenance,\nAnd gossips with no one for dalliance.\nSince other folk have spoken, it's your turn;\nTell us a mirthful tale, and that anon.\nMine host, said I, don't be, I beg, too stern,\nFor of good tales, indeed, sir, have I none,\nSave a long rhyme I learned in years agone.\nWell, that is good, said he; now shall we hear\nIt seems to me, a thing to bring us cheer.\n\n\n### Sir Topas's Tale\n\nListen, lords, with good intent,\nI truly will a tale present\nOf mirth and of solace;\nAll of a knight was fair and gent\nIn battle and in tournament.\nHis name was Sir Thopas.\nBorn he was in a far country,\nIn Flanders, all beyond the sea,\nAnd Poperinghe the place;\nHis father was a man full free,\nAnd lord he was of that countree,\nAs chanced to be God's grace.\nSir Thopas was a doughty swain,\nWhite was his brow as paindemaine,\nHis lips red as a rose;\nHis cheeks were like poppies in grain,\nAnd I tell you, and will maintain,\nHe had a comely nose.\nHis hair and beard were like saffron\nAnd to his girdle reached adown,\nHis shoes were of cordwain;\nFrom Bruges were come his long hose brown,\nHis rich robe was of ciclatoun-\nAnd cost full many a jane.\nWell could he hunt the dim wild deer\nAnd ride a-hawking by river,\nWith grey goshawk on hand;\nTherewith he was a good archer,\nAt wrestling was there none his peer\nWhere any ram did stand.\nFull many a maiden, bright in bower,\nDid long for him for paramour\nWhen they were best asleep;\nBut chaste he was, no lecher sure,\nAnd sweet as is the bramble-flower\nThat bears a rich red hepe.\nAnd so befell, upon a day,\nIn truth, as I can tell or may,\nSir Thopas out would ride;\nHe mounted on his stallion grey,\nAnd held in hand a lance, I say,\nWith longsword by his side.\nHe spurred throughout a fair forest\nWherein was many a dim wild beast,\nAye, both the buck and hare;\nAnd as he spurred on, north and east,\nI tell you now he had, in breast,\nA melancholy care.\nThere herbs were springing, great and small,\nThe licorice blue and white setwall,\nAnd many a gillyflower,\nAnd nutmeg for to put in ale,\nAll whether it be fresh or stale,\nOr lay in chest in bower.\nThe birds they sang, upon that day,\nThe sparrow-hawk and popinjay,\nTill it was joy to hear;\nThe missel thrush he made his lay,\nThe tender stockdove on the spray,\nShe sang full loud and clear.\nSir Thopas fell to love-longing\nAll when he heard the throstle sing,\nAnd spurred as madman would:\nHis stallion fair, for this spurring,\nDid sweat till men his coat might wring,\nHis two flanks were all blood.\nSir Thopas grown so weary was\nWith spurring on the yielding grass,\nSo fierce had been his speed,\nThat down he laid him in that place\nTo give the stallion some solace\nAnd let him find his feed.\nO holy Mary, ben'cite!\nWhat ails my heart that love in me\nShould bind me now so sore?\nFor dreamed I all last night, pardie,\nAn elf-queen shall my darling be,\nAnd sleep beneath my gore.\nAn elf-queen will I love, ywis,\nFor in this world no woman is\nWorthy to be my make\nIn town;\nAll other women I forsake,\nAnd to an elf-queen I'll betake\nMyself, by dale and down!\nInto his saddle he climbed anon\nAnd spurred then over stile and stone.\nAn elf-queen for to see,\nTill he so far had ridden on\nHe found a secret place and won\nThe land of Faery\nSo wild;\nFor in that country was there none\nThat unto him dared come, not one,\nNot either wife or child.\nUntil there came a great giant,\nWhose name it was Sir Oliphant,\nA dangerous man indeed;\nHe said: O Childe, by Termagant,\nSave thou dost spur from out my haunt,\nAnon I'll slay thy steed\nWith mace.\nFor here the queen of Faery,\nWith harp and pipe and harmony,\nIs dwelling in this place.\nThe Childe said: As I hope to thrive,\nWe'll fight the morn, as I'm alive,\nWhen I have my armour;\nFor well I hope, and par ma fay,\nThat thou shalt by this lance well pay,\nAnd suffer strokes full sore;\nThy maw\nShall I pierce through, and if I may,\nEre it be fully prime of day,\nThou'lt die of wounds most raw.\nSir Thopas drew aback full fast;\nThis giant at him stones did cast\nOut of a fell staff-sling;\nBut soon escaped was Childe Thopas,\nAnd all it was by God's own grace,\nAnd by his brave bearing.\nAnd listen yet, lords, to my tale,\nMerrier than the nightingale,\nWhispered to all and some,\nHow Sir Thopas, with pride grown pale,\nHard spurring over hill and dale,\nCame back to his own home.\nHis merry men commanded he\nTo make for him both game and glee,\nFor needs now must he fight\nWith a great giant of heads three,\nFor love in the society\nOf one who shone full bright.\nDo come, he said, my minstrels all,\nAnd jesters, tell me tales in hall\nAnon in mine arming;\nOf old romances right royal,\nOf pope and king and cardinal,\nAnd e'en of love-liking.\nThey brought him, first, the sweet, sweet wine,\nAnd mead within a maselyn,\nAnd royal spicery\nOf gingerbread that was full fine,\nCumin and licorice, I opine,\nAnd sugar so dainty.\nHe drew on, next his white skin clear,\nOf finest linen, clean and sheer,\nHis breeches and a shirt;\nAnd next the shirt a stuffed acton,\nAnd over that a habergeon\n'Gainst piercing of his heart.\nAnd over that a fine hauberk\nThat was wrought all of Jewish work\nAnd reinforced with plate;\nAnd over that his coat-of-arms,\nAs white as lily-flower that charms,\nWherein he will debate.\nHis shield was all of gold so red,\nAnd thereon was a wild boar's head\nA carbuncle beside;\nAnd now he swore, by ale and bread,\nThat soon this giant shall be dead,\nBetide what may betide!\nHis jambeaux were of cuir-bouilli,\nHis sword sheath was of ivory,\nHis helm of latten bright,\nHis saddle was of rewel bone,\nAnd as the sun his bridle shone,\nOr as the full moonlight.\nHis spear was of fine cypress wood,\nThat boded war, not brotherhood,\nThe head full sharply ground;\nHis steed was all a dapple grey\nWhose gait was ambling, on the way,\nFull easily and round\nIn land.\nBehold, my lords, here is a fit!\nIf you'll have any more of it,\nYou have but to command.\nNow hold your peace, par charitee,\nBoth knight and lady fair and free,\nAnd hearken to my spell;\nOf battle and of chivalry\nAnd all of ladies' love-drury\nAnon I will you tell.\nRomances men recount of price,\nOf King Horn and of Hypotis,\nOf Bevis and Sir Guy,\nOf Sir Libeaux and Plain-d'Amour;\nBut Sir Thopas is flower sure\nOf regal chivalry.\nHis good horse all he then bestrode,\nAnd forth upon his way he rode\nLike spark out of a brand;\nUpon his crest he bore a tower\nWherein was thrust a lily-flower;\nGod grant he may withstand!\nHe was a knight adventurous,\nWherefore he'd sleep within no house,\nBut lay down in his hood;\nHis pillow was his helmet bright,\nAnd by him browsed his steed all night\nOn forage fine and good.\nHimself drank water of the well,\nAs did the knight Sir Percival,\nSo worthy in his weeds,\nTill on a day...\n\n\n### Melibeus's Prologue\n\nNo more of this, for God's high dignity!\nExclaimed our host, For you, sir, do make me\nSo weary with your vulgar foolishness\nThat, as may God so truly my soul bless,\nMy two ears ache from all your worthless speech;\nNow may such rhymes the devil have, and each!\nThis sort of thing is doggerel, said he.\nWhy so? I asked, Why will you hinder me\nIn telling tales more than another man,\nSince I have told the best rhyme that I can?\nBy God! cried he, now plainly, in a word,\nYour dirty rhyming is not worth a turd;\nYou do naught else but waste and fritter time.\nSir, in one word, you shall no longer rhyme.\nLet's see if you can use the country verse,\nOr tell a tale in prose- you might do worse-\nWherein there's mirth or doctrine good and plain.'\nGladly, said I, by God's sweet tears and pain,\nI will relate a little thing in prose\nThat ought to please you, or so I suppose,\nFor surely, else, you're contumelious.\nIt is a moral tale, right virtuous,\nThough it is told, sometimes, in different wise\nBy different folk, as I shall you apprise.\nAs thus: You know that each evangelist\nWho tells the passion of Lord Jesus Christ\nSays not in all things as his fellows do,\nBut, nonetheless, each gospel is all true.\nAnd all of them accord in their essence,\nHowbeit there's in telling difference.\nFor some of them say more and some say less\nWhen they His piteous passion would express;\nI mean now Mark and Matthew, Luke and John;\nYet, without doubt, their meaning is all one.\nAnd therefore, masters all, I do beseech,\nIf you should think I vary in my speech,\nAs thus: That I do quote you somewhat more\nOf proverbs than you've ever heard before,\nIncluded in this little treatise here,\nTo point the morals out, as they appear,\nAnd though I do not quite the same words say\nThat you have heard before, yet now, I pray,\nYou'll blame me not; for in the basic sense\nYou will not find a deal of difference\nFrom the true meaning of that tale polite\nAfter the which this happy tale I write.\nAnd therefore hearken now to what I say,\nAnd let me tell you all my tale, I pray.\n\n\n### The Tale of Melibeus\n\nA young man called Melibee, mighty and rich, had with his wife, who was called Prudence, a daughter, who was called Sophie.\n\nOne day it happened that he for his pastime went into the fields to enjoy himself. He had left his wife and his daughter within his house, the doors of which were shut fast.\n\nThree of his longtime foes had seen this, set ladders to the walls of his house, and entered by windows. They beat his wife and wounded his daughter, leaving her with five mortal wounds in five different places, that is to say, in her feet, in her hands, in her ears, in her nose, and in her mouth. And they left her for dead and went away.\n\nWhen Melibee returned to his house and saw all this mischief, he, like a madman, tearing his clothes, began to weep and cry. Prudence, his wife, as far as she dared, entreated him to stop his weeping. Despite that he went on to cry and weep ever longer.\n\nThis noble wife Prudence recalled the teaching of Ovid, in his book called The Remedies of Love, in which he says \"One is a fool who disturbs a mother in her weeping for the death of her child until she has wept her fill for a certain time; at this time one would do his duty to comfort her with amiable words, and pray her to stop her weeping.\"\n\nFor this reason this noble wife Prudence allowed her husband to weep and cry for a certain time; and when she found the right time, she spoke to him in this way: \"Alas, my lord,\" she said, \"why do you permit yourself to act like such a fool? For truly it is not fitting to a wise man to make such sorrow. Your daughter, with the grace of God, will recover and escape death. And, even if it were so that she were dead right now, you should not destroy yourself on account of her death. Seneca says, 'The wise man shall not take too great a discomfort for the death of his children; instead, he should suffer it in patience, in the same way that he awaits the death of his own proper self.'\"\n\nThis Melibee answered right away and said, \"What man,\" he said, \"who has so great a cause to weep could stop weeping? Jesus Christ, our Lord, himself wept for the death of his friend Lazarus.\"\n\nPrudence answered, \"Surely, I know well that moderate weeping is not prohibited to him who is sorrowful among people in sorrow, but it is granted him to weep. The Apostle Paul writes to the Romans, 'Man shall rejoice with those who make joy, and weep with those who weep.'\n\n\"But though moderate weeping may be granted, excessive weeping surely is forbidden. Moderation in weeping should be understood with the wisdom that Seneca teaches us. 'When your friend is dead,' he said, 'do not let your eyes be too moist with tears, nor too dry; although the tears come to your eyes, let them not fall. When you have lost your friend, work diligently to get another friend. This is greater wisdom than to weep for your friend that you have lost, for in this is no benefit.'\n\n\"Therefore, if you govern yourself by wisdom, put away sorrow from your heart. Remember what Jesus Sirach says: 'A man that is joyous and glad in heart may flourish in his age; but a truly sorrowful heart makes his bones dry.' He also says that a sorrowful heart slays many.\n\n\"Solomon says that 'Just as moths in the sheep's fleece do injury to the clothes, and the small worms to the tree, so too sorrow does injury to the heart. Therefore, in both the death of our children and in the loss of our temporal goods, we should have patience.\n\n\"Remember the patient Job. He lost his children and his temporal goods and had received and endured many grievous tribulations on his body, yet he said, 'Our Lord has given to me; our Lord has taken away; just as our Lord has willed, so it is done. Blessed be the name of our Lord!'\"\n\nTo these things Melibee answered his wife Prudence: \"All your words,\" he said, \"are true, and in that way profitable. But truly my heart is troubled with this sorrow so grievously that I know not what to do.\"\n\n\"Call,\" said Prudence, \"all your true friends, and those of your lineage who are wise. Set forth your case, and listen to what they say in counseling, and govern yourself according to their wisdom. Solomon says, 'Act always by counsel, and you shall never repent.'\"\n\nThen, by the counsel of his wife Prudence, this Melibee called together a great congregation of people, including surgeons, physicians, old people and young, and some of his old enemies reconciled as by her pretended to his love and into his grace; and therewithal there came some of his neighbors that paid him reverence more for fear than for love, as it often happens. There came also many subtle flatterers, and wise advocates learned in the law.\n\nAnd when these people were assembled together, this Melibee in sorrowful fashion explained to them his case. And by the manner of his speech it seemed that in heart he bore a cruel anger, ready to do vengeance upon his foes, and suddenly desired that the war should begin; but he nonetheless asked for her counsel on this matter.\n\nA surgeon, by license and assent of others who were as wise, rose up, and said to Melibee as you may hear: \"Sire,\" he said, \"as to us surgeons pertains that we do to every creature the best that we know, where we are engaged by one, and to our patients that we do no damage; as such, it happens many times and often that when two men have wounded each other, the same surgeon heals them both; therefore in our art it is not pertinent to nourish war nor to support parties in it. But surely, as to the cure of your daughter, albeit that she may be perilously wounded, we should do such devoted business from day to night that with the grace of God she shall be whole and sound as soon as is possible.\"\n\nAlmost in the same way the physicians answered, except that they said a few words more: that just as maladies are cured by their contraries, so too should men cure war by vengeance.\n\nHis neighbors full of envy, his feigned friends that seemed reconciled, and his flatterers made the semblance of weeping, made things worse and aggravated much of this matter in praising greatly Melibee of might, of power, of wealth, and of friends, despising the power of his adversaries, and said utterly that he should wreak himself on his foes immediately and begin war.\n\nUp rose then an advocate that was wise, by leave and by counsel of others who were wise, and said: \"Lords, the need for which we have been assembled in this place is a very heavy thing and an important matter, because of the wrong and of the wickedness that has been done, and by reason also of the great damages that in the time coming are possible to occur for this same cause, and by reason as well of the great wealth and power of both of the parties; for these reasons it would be a great peril to err in this matter.\n\n\"Therefore, Melibee, this is our advice: we counsel you above all things that right away you work diligently in protecting your proper person in such a fashion that you are not without a spy or watchman to keep you safe. And after that, we counsel that in your house you establish a sufficient garrison, so that they may defend your body as well as your house. But surely, to begin war, and to do so suddenly for the sake of vengeance, we may not judge in a short time that it would profitable.\n\n\"Therefore we ask the opportunity and time to have deliberation in this case to judge. For the common proverb says thus: one who judges hastily soon shall repent. And people also say, that judge is wise that soon understands a matter and judges at leisure; for albeit that all tarrying may be annoying, it is, nevertheless, not to be disdained in giving of judgment nor in taking vengeance, when it is sufficient and reasonable.\n\n\"And Lord Jesus Christ showed that by example; for when the woman that was taken in adultery was brought into his presence to know what should be done with her person, albeit so that he knew well himself what he would answer, yet he would not answer suddenly, but he wished to have deliberation, and he wrote twice on the ground. And these causes increase deliberation, and we shall then, by the grace of God, counsel you in such a way that will be profitable.\n\nUp jumped then the young people at once, and the most part of that company had scorned this old wise man and began to make noise, and said that just as while the iron is hot, men should strike, so too men should avenge their wrongs while they are fresh and new; and with loud voice they cried \"War! War!\"\n\nUp rose then one of these old wise men, and with his hand made a sign that the people should hold themselves still and give him audience. \"Lords,\" he said, \"there are many men who cry 'War! War!' who know very little what war amounts to. War at its beginning has so great an entry and so large that every creature may enter when it pleases him, and lightly find war; but surely what end that shall come of it, it is not easy to know. For truly, once that war has begun, there are many children unborn of his mother that shall die young because of this war, or else live in sorrow and die in wretchedness. And therefore, before any war might begin, people must have great counsel and great deliberation.\"\n\nAnd when this old man began to enforce his tale by reasons, nearly all at once began to rise to break his tale, and bid him to abridge his words. For truly, he who preaches to those who wish not to hear his words annoys them with his sermon. For Jesus Sirach says that music in mourning is a troublesome thing; this is to say: it is as much use as speaking before people who are troubled by one's speech, as it is to sing before one who mourns.\n\nAnd when this wise man saw that he lacked an audience, he sat down again filled with shame. For Solomon says: 'Where you can not find an audience, do not insist that you are to speak.'\n\n\"I see well,\" said this wise man, \"that the common proverb is true, that 'Good counsel is lacking when it is needed most.'\"\n\nYet this Melibee had in his counsel many people who counseled him a certain thing privately in his ear, and counseled him the opposite in general audience. When Melibee had heard that the greatest part of his counselors were in agreement that he should make war, at once he consented to their counsel and fully affirmed their wisdom.\n\nThen Lady Prudence, when she saw how her husband prepared to avenge himself on his foes and to begin war, she in very humble fashion, when she saw her time, said these words to him: \"My lord,\" she said, \"I beseech you as heartily as I dare and know how to, do not make haste too quickly, and for all my service to you, please listen to me. For Petrus Alphonsus says, 'No matter who does to you either good or harm, hasten you not to requite it; for in this fashion your friend will abide, and your enemy shall for a longer time live in dread.' The proverb says, \"One hastens well who can abide wisely,\" and 'In wicked haste is no profit.'\"\n\nThis Melibee answered unto his wife Prudence: \"I purpose not,\" he said, \"to work by your counsel, for many causes and reasons. For surely, every creature would hold me then a fool; this is to say, if I, on account of your counsel, would change things that are ordained and affirmed by so many wise people. Secondly, I say that all women are wicked, and of all of them none are good. For 'Of a thousand men,' says Solomon, 'I found one good man, but surely, of all women, I never found one good woman.' And also, surely, if I governed myself by your counsel, it should seem that I had given to you the mastery over me; and God forbid that it were so! For Jesus Sirach says that 'If the wife has mastery, she is contrary to her husband.' And Solomon says: 'Never in your life to your wife, nor to your child, nor to your friend, give any power over your self; for it would be better if your children were to ask of your person things that they need, than that you see yourself in the hands of your children.' And also if I would work by your counseling, surely, my counsel must sometime be secret, until the time that it must be known, and this may not be. [For it is written, the jangling of women canonly hide those things that they do not know. Furthermore, the Philosopher says, in bad counsel the women vanquish the men; and for these reasons I ought not to use your advice.]\"\n\nWhen Lady Prudence, very debonairly and with great patience, had heard all that her husband liked to say, then she asked of him permission to speak, and said in this way: \"My lord,\" she said, \"as to your first reason, surely it may be easily answered. For I say that it is no folly to change counsel when the thing is changed, or else when the thing seems otherwise than it was before. And moreover, I say that, though you have sworn and promised to perform your undertaking, and nonetheless you neglect to perform that same undertaking by just cause, men should not say therefore that you were a liar or a perjurer. For the Bible says that 'The wise man makes no lies when he changes his mind.' And albeit so that your undertaking be established and ordained by the great multitude of people, yet there is no need for you to carry out this ordinance, unless you like. For the truth of things and the profit are found rather in the few people who are wise and full of reason, than by great multitude of people of which every man cries and clatters whatever he pleases. Truthfully such a multitude is not worthy of respect.\n\n\"And as to the second reason, by which you say that all women are wicked; with all due respect, surely you despise all women in this way, and 'He who despises all, all displeases,' as says the Bible. And Seneca says that, 'He who will have wisdom shall dispraise no man, but he shall gladly teach the knowledge that he has without presumption or pride, and such things as he can not know, he shall not be ashamed to learn them, and learn from lesser people than himself.\" And, sir, it may be easily proven that there have been many good women. For surely, sir, our Lord Jesus Christ would never have descended to be born of a woman, if all women had been wicked. And after that, for the great goodness that is in women, our Lord Jesus Christ, when he had risen from death to life, appeared rather to a woman than to his apostles. And though Solomon says that he never found a good woman, it follows not therefore that all women are wicked. For though he never found a good woman, surely, many other men have found many very good and true women. Or else, perhaps, the intent of Solomon was this: that he found no woman in supreme goodness; this is to say that there is no creature that has supreme goodness except God alone, as he himself records in his Gospel. For there is no creature so good that he is not lacking in some of the perfection of God, who is his maker.\n\n\"Your third reason is this: you say that if you govern yourself by my counsel, it should seem that you had given me the mastery and the lordship over your person. Sir, except in your case, it is not so. For if it were so that no man should be counseled but only those that have lordship and mastery of his person, men would not be counseled so often. For truly that man that asks advice for a certain purpose still has free choice in whether he will work by that advice or not.\n\n\"And as to your fourth reason, there you say that the babbling of women can hide things that they do not know, which is the same as those who say that a woman can not hide what she knows. sir, these words are understood of women who are babblers and wicked; of such women men say that three things drive a man out of his house -- that is to say, smoke, the falling of rain, and wicked wives, and of such women Solomon says that 'It would be better to dwell in the desert than with a woman that is wanton.' And sir, by your leave, that I am not; for you have very often tested my great silence and my great patience, and also how well that I can hide and conceal things that men ought to hide secretly.\"\n\n\"And truly, as to your fifth reason, in which you say that in wicked counsel women vanquish men, God knows, that reason stands here on no ground. For understand now, you ask advice to do wickedness; and if you wish to do wickedness, and your wife restrains that wicked purpose, and overcomes you by reason and by good counsel, surely your wife ought rather to be praised than blamed. Thus should you understand the philosopher who says, 'In wicked counsel women vanquish their husbands.' And whereas you blame all women and their reasons, I shall show you by many examples that many women have been very good, and still are, and their counsels wholly healthful and profitable. Some men have also said that the counsel of women is either too costly, or else of too little value. But although many women are bad, and their counsel vile and worth nothing, yet have men found very many good women, and very discrete and wise in giving counsel. Lo, Jacob, by Good counsel of his mother Rebecca, won the blessing of Isaac his father, and the lordship over all his brothers. Judith, by her good counsel, delivered the city of Bethulie, in which she dwelled, out of the hands of Holofernes, who had besieged it and would have all destroyed it. Abigail delivered Nabal her husband from David the king, who would have slain him, and appeased the anger of the king by her wit and by her good counsel. Hester, by her good counsel, enhanced greatly the people of God in the reign of Assuerus the king. And one may tell of the same goodness in good counsel of many good women. And moreover, when our Lord had created Adam, our first father, he said in this way: 'It is not good to be a man alone; let us make for him a helper similar to himself.' Here may you see that if that women were not good, and their counsels good and profitable, our Lord God of heaven would never have created them, nor called them helper of man, but rather the ruin of man. And once a clerk said in two verses, 'What is better than gold? Jasper. What is better than jasper? Wisdom. And what is better than wisdom? Woman. And what is better than a good woman? Nothing.' And, sir, by many of other reasons may you see that many women are good, and her counsels good and profitable. And therefore, sir, if you will trust in my counsel, I shall restore you your daughter whole and sound. And I will also do for you so much that you should have honor in this matter.\"\n\nWhen Melibee had heard the words of his wife Prudence, he said thus: \"I see well that the word of Solomon is truth. He says that 'Words that are spoken discreetly in order are honeycombs, for they give sweetness to the soul and healthfulness to the body.' And, wife, because of your sweet words, and also because I have tried and tested your great wisdom and your great truth, I will govern myself by your counsel in all things.\"\n\n\"Now, sir,\" said Lady Prudence, \"since you promise to been governed by my counsel, I will inform you how you should govern yourself in the choosing of your counselors. You should first in all your works meekly beseech to the high God that He will be your counselor; and prepare yourself to such an intention, so that he may give you counsel and comfort, as taught Tobias his son: 'At all times you shall bless God, and pray to him to direct your ways, and see that all your counsels are in him forevermore.' Saint James also says: 'If any of you have need of wisdom, ask it of God.' And afterward then should you taken counsel in yourself, and examine well your thoughts of such a thing as you think that is best for your profit. And then you should drive from your heart three things that are contrary to good counsel; that is to say, anger, covetousness, and rashness.\n\n\"First, he who asks counsel of himself must surely be without anger, for many causes. The first is this: he that has great anger and wrath in himself thinks always that he may do a thing that he may not do. And secondly, he that is angry and wrathful may not judge well; and he who may not judge well, may not counsel well. The third is this, that he that is angry and wrathful, as says Seneca, may not speak but blameful things, and with his vicious words he stirs other people to wrath and to anger. And, sir, you also must drive covetousness out of your heart. For the Apostle says that covetousness is root of all harms. And trust well that a covetous man can not judge nor think, but only to fulfill the end of his covetousness; and surely, that may never been accomplished; for ever the more abundance that he has of wealth, the more he desires. And, sir, you must also drive out of your heart rashness; for surely, you may not judge for the best by a sudden thought that falls into your heart, but you must counsel yourself on it very often. For, as you heard before, the commune proverb is this: 'He who soon judges, soon repents.' sir, you are not always in the same disposition; for surely, something that at one time seems to you good to do, another time seems to you the contrary.\n\n\"When you have taken counsel in yourself, and have deemed by good deliberation such thing as you seems bus, then I advise you that you keep it secret. Reveal your counsel to no person, unless it is so that you believe firmly that through your revelation your condition shall be more profitable to you. For Jesus Sirach says, 'Neither to your foe, nor to your friend, reveal your secret nor your folly; for they will give you audience and attention and support in your presence, and scorn you in your absence.' Another scholar says that 'Scarcely shall you find any person that may keep counsel secretly.' The Bible says, 'While you keep your counsel in your heart, you keep it in your prison; and when you reveal your counsel to any creature, he holds you in his snare.' And therefore you are better to hide your counsel in your heart than pray to one whom you have revealed your counsel that he will keep it close and silent. For Seneca says: 'If it is so that you may not hide your own counsel, how dare you to ask any other creature your counsel to keep your counsel secretly?' But nonetheless, if you believe firmly that the revealing of your counsel to a person will allow you to stand in a better condition, then you shall tell him your counsel in this way. First, you shall make no appearance whether you would prefer peace or war, or this or that, nor show him not your will and your intent. For trust well that commonly these counselors are flatterers, namely the counselors of great lords; for they try always rather to speak pleasant words, inclining to the lord's desire, than words that are true or profitable. And therefore men say that the rich man seldom has good counsel, unless he has it from himself.\n\n\"And after that you shall consider your friends and your enemies. And as concerning your friends, you shall consider which of them are most faithful, most wise, eldest, and most approved in giving counsel; and of them shall you ask your counsel, as the case requires. I say that first you should call to your counsel your friends that are true. For Solomon says that 'Just as the heart of a man delights in savor that is sweet, so too the counsel of true friends gives sweetness to the soul.' He says also, 'Nothing may be likened to the true friend; for surely neither gold nor silver are not worth as much as the good will of a true friend.' And he also says that 'A true friend is a strong defense; whoever finds that surely finds a great treasure.' Then you should also consider if your true friends are discreet and wise. For the Bible says, 'Ask always your counsel from those who are wise.' And by this same reason should you call to your counsel of your friends that are of age, such as have advised and been expert in many things and been approved in advising matters. For the Bible says that 'In old men is the wisdom, and in long time the prudence.' And Tullius says that 'Great things are never accomplished by strength, nor by dexterity of body, but by good counsel, by authority of persons, and by knowledge, all three of which do not become feeble by age, but surely grow stronger and increase day by day.' And then you should keep this for a general rule: first you should call to your counsel a few of your friends that are very close to you; for Solomon says, 'You have many friends, but among a thousand chose one to be your counselor.' For although you first tell your counsel to only a few, you may afterward tell it to more people if it is necessary. But look always that your counselors have these three qualities that I have said before, that is to say, that they would be true, wise, and of old experience. And act not always in every situation by one counselor alone; for sometimes it is necessary to be counseled by many. For Solomon says, 'There is safety where there are many counselors.'\n\n\"Now, since I have told you by which people you should be counseled, now I will teach you whose counsel you ought to avoid. First, you should eschew the counseling of fools; for Solomon says, 'Take no counsel of a fool, for he can know no counsel but after his own lust and his affection.' The Bible says that 'The property of a fool is this: he believes lightly harm of every creature, and lightly believes all bounty in himself.' You shall also eschew the counseling of all flatterers, such as enforce them rather to praise your person by flattery than to tell you the true condition of things. Therefore Cicero says, 'Among all the pestilences that there are in friendship the greatest is flattery.' And therefore it is more necessary that you avoid and fear flatterers than any other people. The Bible says, 'You shall rather dread and flee from the sweet words of flattering praisers than from the eager words of your friend who tells you the truth.' Solomon says that 'The words of a flatterer are a snare to catch innocent ones.' He says also that 'One who speaks to his friend words of sweetness and of pleasure, sets a net before his feet to catch him.' And therefore Cicero says, 'Incline not your ears to flatterers, nor take no counsel in the words of flattery.' And Cato says, 'Advise you well, and avoid the words of sweetness and of pleasure.' And eek you shall avoid the counseling of your old enemies who have been reconciled. The Bible says that 'No creature returns safely into the grace of his old enemy.' And Aesop says, 'Neither trust in those to whom you have had some time at war or enmity, nor tell them your counsel.' And Seneca tells the cause why: 'It may not be' he says, 'that where great fire has endured for a long time, that there does not dwell some warm vapor.' And therefore Solomon says, 'Never trust in your old foe.' For surely, though your enemy may be reconciled, and makes a show of humility to you, and bows to you with his head, never trust him. For surely he makes that feigned humility more for his profit than for any love of your person, because he intends to have victory over your person through such a feigned countenance, the which victory he might not have by strife or war. And Petrus Alphonsus says, 'Make no fellowship with your old enemies; for if you do them good, they will pervert it into wickedness.'\n\n\"And you must also avoid the counsel of those who are your servants and bear you great reverence, for perhaps they would say it more for fear than for love. And therefore says a philosopher in this way: 'There is no creature perfectly true to him that he fears too greatly.' And Cicero says, 'There is no might so great of any emperor that may endure long, unless he has more love of the people than fear.' You shall also avoid the counsel of people who are addicted to drink, for they can hide no counsel. For Solomon says, 'There is no privacy where drunkenness reigns.' You should also hold in suspicion the counsel of such people as counsel you one thing privately, and counsel you the contrary openly. For Cassiodorus says that 'It is a sleight of hand to hinder you, when he shows to do one thing openly and does the contrary privately.' You shall also hold in suspicion the counsel of wicked people, for the Bible says, 'The counsel of wicked people is always full of fraud.' And David says, 'Blissful is that man that has not followed the counsel of scoundrels.' You shall also avoid the counsel of young people, for their advice is not ripe.\n\n\"Now, sir, since I have showed you of which people you should take your counsel, and of which people you should follow the counsel, now will I teach you how you shall examine your counsel, according to the teachings of Cicero. In the examining then of your counselor you should consider many things. First of all, you shall consider that in that thing that you set as your purpose, and upon that thing you wish to have counsel, that absolute truth be said and observed; this is to say, tell truly your tale. For he that speaks falsely may not well be counseled in the case of which he lies. And after this you shall consider if the things the things that you propose to do through the advice of your counselors are reasonable; and if your power may also attain it; and if the larger part and the better part of your counselors are in agreement with it, or not. Then shall you consider what thing shall follow from that advice, such as hate, peace, war, grace, profit, or damage, and many other things. And in all these things you shall choose the best and reject all other things. Then you shall consider from what root the matter is engendered from the advice given to you, and what fruit it may conceive and produce. You shall also consider all these causes, from whence they have sprung. And when you have examined your counsel, as I have said, and which part is better and more profitable, and have approved it by many wise and old people, then you shall consider if you may carry it out it and make a good end of it. For certainly, reason will not allow that any man should begin a thing, unless he might carry it out as he should; and no creature should take upon him so heavy a burden that he might not bear it. For the proverb says, 'He that embraces too much, grasps little.' And Cato says, 'Attempt to do such things as you have the power to do, lest the burden should oppress you so sorely that it is necessary for you to abandon the thing that you have begun.' And if it is so that you are in doubt whether you may carry out a thing or not, choose rather to wait than begin. And Piers Alphonce says, 'If you have the might to do a thing for which you must repent, it is better to say \"nay\" than \"ye.\"' This is to say that you are better to hold your tongue still than to speak.\n\n\"Then may you understand by stronger reasons that if you have the power to carry out a work of which you shall repent, then is it better that you wait than begin. Well say they that forbid every creature to attempt a thing of which he is in doubt whether he may carry it out or not. And after, when you have examined your purpose, as I have said before, and know well that you may carry out your undertaking, resolve to do it then firmly until it is brought to an end.\n\n\"Now is it reason and time that I show you when and for what reason that you may change your counselors without reproaching yourself. Truly, a man may change his purpose and his intention if the cause ceases, or when a new situation arises. For the law says that 'Upon things that newly arise new counsel is needed.' And Seneca says, 'If your counsel has come to the ears of your enemy, change your counsel.' You may also change your counsel if it is so that you find that by error, or by another cause, harm or damage may arise. Also if your intention is dishonest, or else comes from a dishonest cause, change your intention. For the laws say that 'All promises that are dishonest are of no value;' and if it is so also that it is impossible, or may not be carried out or kept satisfactorily.\n\n\"And take this for a general rule, that every intention that is affirmed so strongly that it may not be changed for any condition that may arise, I say that this counsel is wicked.\"\n\nThis Melibee, when he had heard the teaching of his wife Lady Prudence, answered in this fashion: \"Lady,\" he said, \"until this time you have well and properly taught me in general how I shall govern myself in the choosing and in the withholding of my counselors. But now would I would be glad if you would condescend especially and tell me how you like, or what you think of, our counselors that we have chosen in our present need.\"\n\n\"My lord,\" she said, \"I beseech you in all humility that you will not willfully object against my reasons, nor be disturbed in your heart, though I may say something that displeases you. For God knows that, as in my intention, I speak it for your best, for your honor, and for your profit as well. And truly, I hope that your kindness will take it in patience. Trust me well,\" she said, \"that your counsel in this case should not, to speak properly, be called a counseling, but a motion or a gesture of folly, by which counsel you have erred in many and various ways.\"\n\n\"First and foremost, you have erred in the assembling of your counselors. For you should first have called a few people to your counsel, and afterward you might have shown it to more people, if it had been necessary. But surely, you have suddenly called to your counsel a great multitude of people, burdensome and tedious to hear. Also you have erred, for whereas you should only have called to your counsel your true friends old and wise, you have called strangers, young people, false flatterers, reconciled enemies, and people who do reverence to you without love. And you have also erred, for you have brought with you to your counsel anger, covetousness, and rashness, which three things are contrary to every honest and profitable counsel; which three things you have not annihilated or destroyed, neither in yourself, nor in your counselors, as you ought. You have erred also, for you have showed to your counselors your inclination and your desire to make war immediately, and to do vengeance. They have seen by your words to what things you are inclined; and therefore they have counseled you rather to your inclination than to your profit. You have erred also, for it seems that you are satisfied to have been advised by these counselors only, and with little advice, whereas in so great and so high a need more counselors and more deliberation were necessary to carry out your undertaking. You have erred also, for you have not examined your counsel in the foresaid manner, and not in due course, as the case requires. You have erred also, for you have made no distinction between your counselors; this is to say, between your true friends and your pretended counselors; you have also not known the will of your true friends old and wise; but you have cast all their words into an hotchpotch, and inclined your heart to the larger part and to the greater number, and there you have condescended. And since you know well that one shall always find a greater number of fools than of wise men, and for that reason in the counsels that are offered at gatherings and multitudes of people, where men give more regard to the number than to the wisdom of persons, you can see well that in such counsel fools have the mastery.\n\nMelibee answered again, and said, \"I grant openly that I have erred; but since you have told me before that one is not to blame who changes counselors in certain case and for certain just causes, I am entirely ready to change my counselors just as you would suggest. The proverb says that 'To do sin is human, but surely to persevere for a long time in sin is the work of the devil.\"\n\nTo this opinion Lady Prudence answered then, and said: \"Examine,\" she said, \"your counsel, and let us see which of them have spoken most reasonably and taught you the best counsel. And since this examination is necessary, let us begin at the surgeons and at the physicians, who first speak in this matter. I tell you that the surgeons and physicians have spoken to you in your counsel discreetly, as they should; and in their speech said very wisely that their duty is to do honor and profit to every creature, and to trouble no creature; and to do great diligence according to their skill for the cure of those who they have in their governance. And, sir, just as they have answered wisely and discreetly, so too I advise that they are highly and supremely rewarded for their noble speech; and for the fact that they should do the more attentive care in the curing of your dear daughter. For although they are your friends, you shall not allow that they serve you for nothing; you ought rather to reward them and show them your generosity. And regarding the proposition that the physicians advanced in this case, that is to say, that in maladies one contrary is cured by another contrary, I would gladly know how you understand this text, and what your opinion is.\"\n\n\"Surely,\" Melibee said, \"I understand it in this fashion: that just as they have done me a contrary, so too should I do them another. For just as they have avenged themselves on me and done me wrong, so too shall I avenge myself upon them and do them wrong; and then have I cured one contrary by another.\"\n\n\"Lo, lo,\" said Lady Prudence, \"how readily every man is inclined to his own desire and to his own pleasure! Surely,\" she said, \"the words of the physicians should not have been understood in this manner. For surely, wickedness is not contrary to wickedness, nor is vengeance to vengeance, nor is wrong to wrong, but they are similar. And therefore one vengeance is not cured by another vengeance, nor one wrong by another wrong, but every one of them increases and aggravates the other. But for certain, the words of the physicians should be understood in this way: good and wickedness are two contraries, and peace and war, vengeance and long-suffering, discord and accord, and many other things. But certainly, wickedness shall be cured by goodness, discord by accord, war by peace, and so forth for other things. And Saint Paul the Apostle agrees with this in many places. He says: 'Give not harm for harm, nor wicked speech for wicked speech; but do well to one who does you harm, and bless him that speaks to you harm. And in many other places he recommends peace and accord.\n\n\"But now will I speak to you of the counsel that was given to you by the men of law and the wise people, that said all in agreement, as you have heard before, that over all things you shall do your diligence to protect your person and to fortify your house; and said also that in this case you ought to work under much advisement and with great deliberation. And, sir, as to the first point, that pertains to the protection of your person, you should understand that he that has war shall evermore meekly and devoutly pray, before all things, that Jesus Christ of his mercy will keep him in his protection and be his highest help in his need. For surely, there is no creature in this world that may be counseled nor protected sufficiently without the protection of Our Lord Jesus Christ. With this opinion agrees the prophet David, who says, 'If God protects not the city, he that guards it watches in vain.'\n\n\"Now, sir, then you should commit the protection of your person to your true friends, who are approved and recognized, and you should ask help of them to protect your person. For Cato says: 'If you have need of help, ask it of your friends; for there is no physician as good as your true friend.' And after this then should you protect yourself from all strangers, and from liars, and always suspect their fellowship. For Petrus Alphonsus says, 'Take no fellowship along the way of a stranger, but only if you have known him for a longer time. And if he should fall into your fellowship by chance, without your assent, inquire then as skillfully as you can of his behavior, and of his life before, and invent a story about your travels; say that you wish to go where you do not wish to go; and if he bears a spear, keep yourself on the right side, and if he bears a sword, keep yourself on the left side.' And in this way then you should protect yourself wisely from all such people as I have noted before, and avoid them and their counsel. And after this then should you protect yourself in such a manner that, through any presumption of your strength, you neither despise nor underestimate the might of your adversary, to the extent that you neglect the protection of your person on account of your presumption; for every wise man fears his enemy. And Solomon says: 'Happy is he who has fear of all; for surely, he who, through the hardiness of his heart, and through the hardiness of himself, has too much presumption, evil shall come upon him.' Then you should evermore watch out for ambushes and espionage. For Seneca says that 'The wise man that fears harms, avoids harms, and he that avoids perils does not fall into perils.' And although it seems that you are in secure place, yet shall you always do your duty in protecting your person; this is to say, be not negligent in protecting your person, not only from your greatest enemies, but from your least enemy. Seneca says: 'A man that is well advised dreads his least enemy.' Ovid says that 'The little weasel will slay the great bull and the wild stag.' And the Bible says, 'A little thorn may prick a king sorely, and a hound will capture the wild boor.' But nonetheless, I am not saying that you should be such a coward that you fear where there is nothing to fear. The Bible says that 'Some people have great desire to deceive, but yet they fear to be deceived themselves.' Yet shall you fear to been empoisoned, and keep yourself from the company of scorners. For the Bible says, 'With scorners make no company, but flee their words as venom.'\n\n\"Now, as to the second point, whereas your wise counselors advised you to fortify your house with great diligence, I would gladly know how you understand these words and what your opinion is.\"\n\nMelibee answered and said, \"surely, I understand it in this way: that I shall fortify my house with towers, such as castles and other types of edifices have, and armor, and artilleries, by which I may maintain and defend my person and my house so that my enemies should approach my house in fear.\"\n\nTo this opinion Prudence then answered: \"Fortifying,\" she said, \"by high towers and great edifices is sometimes related to pride. And men also make high towers, and great edifices at great costs and with great travail; and when they have been accomplished, they are still not worth a straw unless they are defended by true friends that are old and wise. And understand well that the greatest and strongest garrison that a riche man may have, to protect both his person and his goods, is that he be loved by his subjects and by his neighbors. For thus says Cicero, that 'There is a type of garrison that no man may vanquish nor overthrow, and that is a lord to be loved by his citizens and by his people.'\n\n\"Now, sir, as to the third point, whereas your old and wise counselors said that you ought not suddenly nor hastily proceed in this need, but that you ought to provide and prepare yourself in this case with great diligence and great deliberation; truly, I believe that they spoke very wisely and very truly. For Cicero says: 'In every need, before you begin it, prepare yourself with great diligence.' Then I say that in vengeance-taking, in war, in battle, and in fortifying, before you begin, I advise that you prepare yourself for it, and do it with great deliberation. For Cicero says that 'Lengthy preparation before the battle makes swift victory.' And Cassiodorus says, 'The garrison is stronger, when it is long time considered.'\n\n\"But now let us speak of the counsel that was agreed upon by your neighbors, such as give you reverence without love, your old enemies reconciled, your flatterers, who counseled you certain things privately and openly counseled you the contrary; the young people also who counseled you to avenge yourself and make war immediately. And surely, sir, as I have said before, you have greatly erred to have called to your counsel such a manner of people who are sufficiently reproved by the reasons aforesaid. But nonetheless, let us now descend to the specifics. You shall first proceed according to the doctrine of Cicero. Certainly, the truth of this matter, or of this counsel, needs not be diligently investigated; for it is well known who they are who have done this crime and shameful deed to you, how many trespassers there were, and in what manner they have done all this wrong and all this shame to you. And after this, should you then examine the second condition that the same Cicero adds in this matter. For Cicero sets forth a term that he calls 'Consenting'; this is to say, who they are, which they are and how many, that consent to your counsel in your stubborn resolve to do hasty vengeance.\n\n\"And let us consider also who they are, how many they are, and what sort of people they are, that agreed with your adversaries. And surely, as to the first point, it is well known which people are they that consented to your rash stubbornness; for truly, all those who counseled you to make sudden war were not, and are not, your friends. Let us now consider who they are that you take as your personal friends. For although you may be mighty and rich, surely you are as good as alone, for surely you nor have no child but a daughter, and you have no brothers, nor first cousins, nor any other close family, on whose account your enemies for fear would desist from reasoning with you or destroying your person. You know also that your wealth might be divided into diverse parts, and when every creature has his share, they will find little reward in avenging your death. But you have three enemies, and they have many children, brothers, cousins, and other close family. And even if you were to slay two or tree of them, there would still remain enough of them to avenge their death and to slay your person. And even if your family are more sure and steadfast than the family of your adversary, your family, nonetheless, is only a distant family; they are only slightly related to you, and the families of your enemies are closely related to them. And certainly, in this way, their condition is better than yours. Then let us consider also if the advice of those who counseled you to take sudden vengeance is in accord with reason. And surely, you know well it is \"nay.\" For, as by right and reason, no person may take vengeance on no creature except the judge that has the jurisdiction of it, when it is granted him to take such vengeance swiftly or temperately, as the law requires. And yet moreover of the term that Cicero calls \"Consenting\" you should consider if your might and your power may consent to and suffice for your stubbornness and your counselors. And surely you may well say \"nay\" to that. For surely, to speak properly, we may do nothing, except such thing as we may do rightfully. And surely you may take no vengeance rightfully on your own authority. Then might you see that your power neither consents nor accords with your stubbornness.\n\n\"Let us now examine the third term, which Cicero calls 'Consequent.' You shall understand that the vengeance that you intend to take is the consequent; and from it follows further vengeance, peril, war, and other damages without number, of which we are not aware at this time.\n\nAnd concerning the fourth point, that Cicero calls 'Engendering,' you shall consider that this wrong that is done to you is engendered of the hate of your enemies, and of the vengeance-taking that would engender further vengeance, and much sorrow and wasting of wealth, as I said.\n\n\"Now, sir, as to the point that Cicero calls 'Causes,' which is the last point, you shall understand that the wrong that you have received has certain causes, which clerks call oriens and efficiens, and causa longinqua and causa propinqua, which is to say, the remote cause and the immediate cause. The remote cause is Almighty God, that is cause of all things. The immediate cause is your three enemies. The accidental cause was hate. The material cause would be the five wounds of your daughter. The formal cause is the manner of their working that brought ladders and climbed in at your windows. The final cause was to slay your daughter. They delayed in this no more than they could help. But to speak of the remote cause, to what end they should come, or what shall finally happen to them in this case, I can not judge except by conjecturing and by supposing. For we should suppose that they should come to a wicked end, because the Book of Decrees says, 'Seldom, or with great pain, are causes brought to a good end when they are badly begun.'\n\n\"Now, sir, if men would ask me why God allowed men to commit this crime against you, surely, I could not well answer, as I do not know the truth. For the Apostle says that 'The knowledge and the judgments of our Lord God Almighty are very deep; no person may comprehend or penetrate them sufficiently.' Nonetheless, by certain presumptions and conjectures, I hold and believe that God, who is full of justice and of righteousness, has allowed this to happen for a just and reasonable cause.\n\n\"Your name is Melibee, which is to say, 'a man that drinks honey.' You have drunk so much honey of sweet worldly riches, and delights and honors of this world, that you are drunk and have forgotten Jesus Christ your creator. You have not given to him such honor and reverence as you ought, nor have you heeded well the words of Ovid, who says, 'Beneath the honey of the goods of the body is hidden the venom that slays the soul.' And Solomon says, 'If you have found honey, eat of it so that it suffices; for if you eat of it immoderately, you shall vomit,' and be needy and poor. And perhaps Christ holds you in contempt and has turned away from you his face and his ears of mercy; and he has also allowed that you have been punished in the same manner that you have trespassed. You hast committed sin against our Lord Christ; for surely, the three enemies of mankind, that is to say, the flesh, the devil, and the world, you have allowed them to enter in to your heart willfully by the windows of your body, and have not defended yourself sufficiently against their assaults and their temptations, so that they have wounded your soul in five places; this is to say, the Deadly Sins that have entered into your heart through your five senses. And in the same manner our Lord Christ has willed and allowed that your three enemies have entered into your house by the windows, and have wounded your daughter in the aforesaid manner.\"\n\n\"Surely,\" Melibee said, \"I see well that you support yourself much by words to overcome me in such a manner that I shall not avenge myself of my enemies, showing me the perils and the evils that might come from this vengeance. But whoever would consider in all vengeances the perils and evils that might follow from vengeance-taking would never take vengeance, and that would be a pity; for by the vengeance-taking are the wicked men separated from the good men, and those who have the will to do wickedness restrain their wicked purpose when they see the punishing and chastising of the trespassers.\"\n\n[And to this Lady Prudence responds, \"Certainly,\"she said, \"I grant you that from vengeance comes much evil and good; but vengeance does not appertain to each person but only to the judges and to those who have the jurisdiction over the malefactors.] And yet I say furthermore that just as a singular person sins in taking vengeance on another man, so too the judge sins if he should do no vengeance to those who have deserved it. For Seneca says thus: 'That master,' he says, 'is good who puts scoundrels to the test.' And as Cassiodorus says, 'A man fears doing outrages when he understands and knows that it displeases the judges and the sovereigns.' And another says, 'The judge that fears to do right makes men scoundrels.' And Saint Paul the Apostle says in his Epistle, when he writes to the Romans, that 'The judges bear not the spear without cause, but they bear it to punish the scoundrels and mis-doers, and to defend the good men.' If you wish then to take vengeance on your enemies, you should return or take your recourse in the judge who has the jurisdiction upon them, and he shall punish them as the law asks and requires.\"\n\n\"A!\" Melibee said, \"This vengeance does not please me at all. I recollect now and take heed how Fortune has nourished me from my childhood and has helped me to pass through many difficult situations. Now will I test her, believing, with God's help, that she shall help me to avenge my shame.\"\n\n\"Surely,\" said Prudence, \"if you will work by counsel, you should not test Fortune in any way, nor should you lean or bow to her, according to the word of Seneca; for 'Things that are foolishly done, and that are in hope of Fortune, should never come to a good end.' And, as the same Seneca says, \"The more bright and the more shining that Fortune is, the more brittle and the sooner broken she is.' Trust not in her, for she is not steadfast nor stable; for when you believe to be most sure or certain of her help, she will fail you and deceive you. And whereas you say that Fortune has nourished you from your childhood, I say that by the same token you should trust less in her and in her wisdom. For Seneca says, 'The one who is nourished by Fortune, she makes a great fool.' Now then, since you desire and ask vengeance, and the vengeance that is done according to the law and before the judge does not please you, and the vengeance that is done in hope of Fortune is perilous and uncertain, then you have no other remedy but to have your recourse in the Sovereign Judge that avenges all crimes and wrongs. And he shall avenge you as He Himself testifies, as he says, 'Leave the vengeance to me, and I shall do it.'\"\n\nMelibee answered, \"If I do not avenge myself for the crimes that men have done to me, I summon or announce to those who have done that wrong to me, and to all others, to do another wrong to me. For it is written, 'If you take no vengeance on an old wrong, you summon your adversaries to do you a new wrong.' And also for my long-suffering men would do me so much wrong that I might neither bear nor endure it, and so I would be esteemed too lowly. For men say, 'In much patient endurance many things might happen to you, which you will not be able to endure.'\"\n\n\"Surely,\" said Prudence, \"I grant you that too much patient endurance is not good. But it does not follow from this that every person to whom men do injury take vengeance for it; for all of that pertains and belongs only to the judges, for they should avenge the villainies and injuries. And therefore those two authorities that you have quoted above are referring only to the judges. For when they allow too much the wrongs and the crimes to be carried out without punishment, they not only summon a man to do new wrongs, but they also command it. Also a wise man says that 'the judge that does not correct the sinner commands and bids him to sin.' And the judges and sovereigns might in their land endure so much of the scoundrels and mis-doers that the wicked ones should, by such long-suffering, in process of time grow to such power and might that they should remove the judges and the sovereigns from their places, and at last make them lose their authority.\n\n\"But let us now suppose that you have permission to avenge yourself. I say you are not at present of might and power to avenge yourself; for if you will compare your might to that of your adversaries, you should find in many things that I have showed you before this that their condition is better than yours. And therefore I say that it is good for now that you endure and be patient.\n\n\"Furthermore, you know well that according to the common saying, 'It is madness for a man to strive against a stronger or a more mighty man than he is himself; and to strive against a man of equal strength, that is to say, with a man as strong as him is a peril; and to strive with a weaker man is folly.' And therefore a man should flee from strife as much as he can. For Solomon says, 'It is a great honor to a man to keep himself from disturbance and strife.' And if it should take place or happen that a man of greater might and strength than you does wrong to you, study and busy yourself rather to resolve the same wrong than to avenge yourself. For Seneca says that 'He puts himself in great peril who strives against a greater man than he is himself.' And Cato says, 'If a man of higher estate or degree, or more mighty than you, does injury or wrong to you, allow him; for he that once has wronged you, may another time relieve and help you.'\n\n\"Yet I put forth in the case that you have both might and permission to avenge yourself, I say that there are very many things that ought to restrain you from vengeance-taking, to make you to incline to endure, and to have patience in the wrongs that have been done to you. First and foremost, if you will consider the faults that are in your own person, for which faults God has allowed you to have this tribulation, as I have said you earlier. For the poet says that 'We ought to take the tribulations that come to us patiently, when we think and consider that we have deserved to have them.' And Saint Gregory says that 'When a man considers well the number of his faults and of his sins, the pains and the tribulations that he suffers seem less to him; and inasmuch as it seems to him his sins are more heavy and grievous, his pain seem lighter and easier to him.' Also you ought to incline and bow your heart to take the patience of Our Lord Jesus Christ,' as Saint Peter in his Epistles says. 'Jesus Christ,' he says, 'has suffered for us and given an example to every person to follow and imitate; for he never committed sin, nor never did an evil word come from his mouth. When men cursed him, he cursed them not; and when men beat him, he threatened them not.' Also the great patience that the saints who are in paradise have had in tribulations that they have endured, undeservedly and innocently, ought to encourage you greatly to patience. Furthermore you should try to have patience, considering that the tribulations of this world endure for only a short time and are soon passed and gone, and the joy that a man seeks to have by patience in tribulations is eternal, in accordance with what the Apostle says in his Epistle. 'The joy of God,' he says, 'is eternal, which is to say, everlasting.'\n\n\"Also consider and believe steadfastly that one is not well nourished, nor well taught, who can not have patience or will not receive patience. For Solomon says that 'The doctrine and the wit of a man are known by patience.' And in another place he says that 'He who is patient governs himself by great prudence.' And the same Solomon says, 'The angry and wrathful man makes noises, and the patient man moderates them and keeps silence.' He says also, 'It is more worthy to be patient than to be strong; and he that may have the authority over his own heart is more praiseworthy than he who by his force or strength conquers great cities.' And therefore Saint James says in his epistle that 'Patience is a great virtue of perfection.'\"\n\n\"For certain,\" Melibee said, \"I grant you, Lady Prudence, that patience is a great virtue of perfection; but every man may not have the perfection that you seek; I am not among the number of perfect men, for my heart may never be in peace until the time it is avenged. And although it was a great peril to my enemies to do me a wrong in taking vengeance upon me, they took no heed of the peril, but fulfilled their wicked will and their desire. And therefore I think others ought not to reprove me, even if I put myself in a little peril to avenge myself, and even if I perform a great sin, that is to say, that I avenge one outrage by another.\"\n\n\"Ah,\" said Lady Prudence, \"you speak your mind and as you please, but in no circumstance in this world should a man commit an outrage or sin to avenge him. For Cassiodorus says that 'He who avenges himself by outrage acts as evilly as he who does the outrage.' And therefore you should avenge yourself according to righteousness, that is to say, by the law, and not by sin nor by outrage. And if you also wish to avenge yourself for the outrage of your adversaries in a manner other than what righteousness commands, you sin. And therefore Seneca says that 'A man shall never avenge evil by evil.'\n\n\"And if you say that righteousness asks a man to defend violence by violence, and fighting by fighting, surely you speak truly, when the defense is done immediately without interval or without tarrying or delay, to defend himself and not to avenge himself. And it is necessary that a man defend himself with such temperance that others have no cause or reason to reproach him who defends himself from excess and outrage, for otherwise it would be against reason. By God, you know well that you make no defense for now to defend yourself, but to avenge yourself; and so it follows that you have no will to do your deed temperately. And therefore I think that patience is good; for Solomon says that 'He who is not patient shall have great harm.'\"\n\n\"Surely,\" Melibee said, \"I grant you that when a man is impatient and angry about what does not affect or pertain to him, though it may harm him, it is no wonder. For the law says that 'He who interferes or meddles with such things as do not pertain to him is guilty.' And Solomon says that 'One who interferes in the disturbance or strife of another is like another who takes a hound by the ears.' For just as he who takes a unfamiliar dog by the ears is sometimes bitten by the dog, in the same way is it logical that he will have harm who by his impatience meddles in the disturbance of another man, though it pertains not to him. But you know well that this deed, that is to say, my grief and my disease, touches me close to home. And therefore, though I may be angry and impatient, it is no marvel. And, except in your case, I can not see that it might greatly harm me if I took vengeance. For I am richer and more mighty than my enemies are; and you know well that by money and by having great possessions are all the things of this world governed. And Solomon says that 'All things obey money.'\n\nWhen Prudence had heard her husband boast of his wealth and of his money, disparaging the power of his adversaries, she spoke, and said this: \"For certain, dear sir, I grant you that you are rich and mighty, and that the riches are good to those who have gotten them well and can use them well. For just as the body of a man may not live without the soul, so too it may not live more without worldly goods. And by riches may a man get himself great friends. And therefore Pamphilius says: 'If a cowherd's daughter,' he says, 'is rich, she may choose from a thousand men one whom she will take as a husband; for, of a thousand men, one will not forsake her nor refuse her. And this Pamphilius also says: 'If you are happy--that is to say, if you are rich--you shall find a great number of fellows and friends. And if your fortune changes so that you grow poor, farewell friendship and fellowship; for you shall be alone without any company, unless it should be the company of poor people.' And yet this Pamphilius says moreover that 'Those who have been serfs by birth should be made worthy and noble by the riches.'\n\n\"And just as by riches many goods come, so also by poverty many harms and evils come. For great poverty compels a man to do many evils. And therefore Cassiodorus calls poverty the mother of ruin, that is, the mother of destruction or falling down. And therefore Petrus Alphonsus says: 'One of the greatest adversities of this world is when a free man by nature or by birth is compelled by poverty to eat the alms of his enemy' And the same says Innocent in one of his books. He says that 'Sorrowful and unhappy is the condition of a poor beggar; for if he asks not for his food, he dies for hunger; and if he asks, he dies for shame; and in all ways necessity compels him to ask.' And Solomon says that 'It is better to die than to have such poverty.' And as the same Solomon says, 'It is better to die of bitter death than to live in such a fashion.' By these reasons that I have related to you, and by many other reasons that I could say, I grant you that riches are good to those who gain them well, and to those who use those riches well. And therefore I will show you how you should behave yourself and how you should conduct yourself in gathering riches, and in what manner you should use them.\n\n\"First, you should get them without great desire, in a leisurely way, gradually and not too hastily. For a man who is too desirous to get riches abandons himself first to theft, and to all other evils; and therefore Solomon says, 'He who makes haste too eagerly to grow rich shall not be innocent.' He says also that 'The riches that quickly come to a person, quickly and easily depart and pass away from a person; but that wealth that comes little by little, grows always and multiplies.'\n\n\"And, sir, you shall gain riches by your intelligence and by your travail for your profit, and do so without doing wrong or harm to any other person. For the law says that 'No man makes himself rich, if he does harm to another person.' This is to say that nature prohibits and forbids by right that no man make himself rich to the harm of another person. And Cicero says that 'No sorrow, nor no fear of death, nor no thing that may happen to a man, is so much against nature as a man to increase his own profit to the harm of another man. And though the great man and the mighty men get riches more easily than you, yet you shall not be idle or slow to work for your own profit, for you shall in all ways flee idleness.' For Solomon says that 'Idleness teaches a man to do many evils.' And the same Solomon says that 'He who travails and busies himself to till his land, shall eat bread; but he who is idle and casts himself to no business nor occupation, shall fall into poverty, and die for hunger.' And he that is idle and slow can never find a suitable time to work for his profit. For there is a versifier who says that 'The idle man excuses himself in winter because of the great cold, and in summer by reason of the great heat.' For these causes Cato says, 'Wake and incline not yourself too much to sleep, for too much rest nourishes and causes many vices.' And therefore Saint Jerome says, 'Do some good deeds so that the devil, who is our enemy, will not find you unoccupied.' For the devil does not take easily into his work those whom he finds occupied in good works.\n\n\"Then thus, in getting riches, you must flee idleness. And afterward, you should use the riches that you have gained by your intelligence and by your travail, in such a manner that men think you not too parsimonious, nor too sparing, nor too foolishly generous, that is to say, too great a spender. For just as men blame an avaricious man on account of his miserliness and stinginess, in the same way is he to blame who spends too freely. And therefore Cato says: 'Use,' he says, 'your riches that you have gained in such a manner that others have no matter nor cause to call you neither wretch nor miser; for it is a great shame to a man to have a poor heart and a rich purse.' He says also: 'Use the goods that you have gained in moderation,' which is to say, spend them moderately; for those who foolishly waste and spend the goods that they have, when they have no more property of their own, they scheme to take the goods of another.\n\n\"I say then that you should flee from avarice; using your riches in such a manner that others will not say that your riches are buried, but that you have them in your might and in your control. For a wise man reproves the avaricious man, and says this in two verses: why and for what reason does a man bury his goods by his great avarice, and knows well that he must die? For death is the end of every man in this present life. And for what cause or reason does he join himself or knit himself so fast to his goods that all his wits might not separate him or part him from his goods, and know well, or ought to know, that when he is dead he shall bear nothing with him out of this world? And therefore Saint Augustine says that 'The avaricious man is likened to hell, in that the more it swallows, the more desire it has to swallow and devour.' And just as you would avoid being called an avaricious man or miser, so too you should maintain and govern yourself in such a way that others will not call you foolishly generous. Therefore Cicero says: 'The goods,' he says, 'of your house should not be hidden nor kept so secret, that they might not be freed by pity and gentleness;' which is to say, to give part to those who have great need; 'nor shall your goods be so free as to be every person's goods.'\"\n\n\"Afterward, in the getting of your riches and in using them, you should always have three things in your heart, that is to say, our Lord God, conscience, and good name. First, you should have God in your heart, and for no wealth should you do no anything that may in any manner displease God, who is your creator and maker. For according to the word of Solomon, 'It is better to have a few goods with the love of God than to have many goods and treasure and lose the love of the Lord God. And the prophet says that 'Better it is to be a good man and have little good and treasure than to be held as a scoundrel and have great riches.' And yet I say furthermore that you should always take pains to get yourself riches, so that you get them with good conscience. And the Apostle says that 'There is nothing in this world of which we should have so great joy as when our conscience bears us good witness.' And the wise man says, 'The substance of a man is good when sin is not in man's conscience.'"},{"index":9,"markdown":"\n\"Afterward, in getting your riches and in using them, you must exert yourself busily and diligently so that your good name may be always kept and preserved. For Solomon says that 'It is better and profits a man more to have a good name than to have great riches.' And therefore he says in another place, 'Do exert yourself diligently,' says Solomon, 'in keeping of your friend and of your good name; for it shall remain with you longer than any treasure, matter how precious.'\n\n\"And surely he should not be called a gentleman that after God and good conscience, all other things left aside, does not work busily and diligently to keep his good name. And Cassiodorus says that 'It is the sign of a gentle heart, when a man loves and desires to have a good name.' And therefore Saint Augustine says that 'There are two things that are necessary and needful, and they are good conscience and good reputation; that is to say, good conscience about your own inward person, and good reputation of your outward neighbor. And he who trusts so much in his good conscience that he displeases, and does not value his good name or reputation, and cares not at all that he keeps not his good name, is nothing but a cruel fellow.\n\n\"Sire, now have I showed you how you should act in getting riches and how you should use them, and I see well that for the trust that you have in your riches you will begin war and battle. I counsel you that you begin no war in trust of your riches, for they will not suffice to maintain wars. And therefore a philosopher says, \"That man who desires and wills at any price to have war shall never have sufficiency; for the richer that he is, the greater expenditure must he make, if he will have honor and victory.' And Solomon says that 'The greater riches that a man has, the more spenders he has.'\n\n\"And, dear sir, although for your riches you might have many people, yet it is not necessary, nor it is good, to begin war, seeing that you might in another manner have peace unto your honor and profit. For the victory by battles that are in this world lie not in great number or multitude of the people, nor in the virtue of man, but it lies in the will and in the hand of our Lord God Almighty. And therefore Judas Maccabeus, who was God's knight, when he was to fight against his adversary that had a greater number and a greater multitude of people and was stronger than the people of Maccabee, he nonetheless encouraged his little company, and said in this very way: 'As easily,' he said, 'may our Lord God Almighty give victory to a few people as to many people; for the victory of a battle comes not by the great number of people, but from our Lord God of Heaven.' And, dear sir, because there is no man certain if he may be worthy that God will give him victory, [any more than he is certain if he is worthy of the love of God], or nothing, just as Solomon says, therefore, every man should greatly fear to begin wars. And because in battles many perils occur, and it happens sometimes that the great man is slain as soon as the little man; and as it is written in the Second Book of Kings, 'The deeds of battles are filled with risk and nothing is certain, for one is hurt with a spear as easily as another;' and because there is great peril in war; therefore one should flee from and avoid war, to the extent that he properly can. For Solomon says, 'He who loves peril shall fall in peril.'\n\nAfter Lady Prudence had spoken in this manner, Melibee answered and said: \"I see well, Lady Prudence, that by your fair words and by your reasons that you have showed me, that war does not please you at all; but I have not yet heard your advice, how I shall act in this crisis.\"\n\n\"Certainly,\" she said, \"I counsel you that you reconcile with your adversaries and that you have peace with them. For Saint James says in his Epistle that 'By concord and peace small riches grow great, and by strife and discord the great riches are depleted.' And you know well that [two] of the greatest and most supreme things that are in this world is unity and peace. And therefore Our Lord Jesus Christ said to his Apostles in this way: 'Very happy and blessed are those who love and promote peace, for they are called children of God.'\"\n\n\"A,\" Melibee said, \"now I see well that you love not my honor or my worship. You know well that my adversaries have begun this strife and contention by their outrage, and you see well that they neither beg nor ask me for peace, nor do they ask to be reconciled. Do you wish then that I should go and humble myself and be obedient to them, and cry to them for mercy? For truly, that would not be to my credit. For just as men say that 'Over-great familiarity engenders contempt,' so it also goes by too great humility or meekness.\n\nThen Lady Prudence began to make the appearance of wrath, and said: \"Surely, sir, with all due respect, I love your honor and your profit as I do my own, and ever have done so; not you, nor no other, may ever say the contrary. And yet if I had said that you should have obtained the peace and the reconciliation, I had not been much mistaken, nor said amiss. For the wise man says, 'The dissention begins with another, and the reconciliation begins with yourself.' And the Prophet says, 'Flee evil and do goodness; seek peace and follow it, as much as there is in you.' Yet I do not say that you should sooner appeal to your adversaries for peace than they should to you. For I know well that you are so hard-hearted that you will do nothing for me. And Solomon says, 'He whose heart it too hard shall at last meet with misfortune and come to grief.'\n\nWhen Melibee had heard Lady Prudence make the appearance of wrath, he said in this fashion: Lady, I pray you that you will not be not displeased with things that I say, for you know well that I am angry and wrathful, and that is no wonder; and those who are wrathful do not know well what they are doing or what they are saying. Therefore the prophet says that 'Troubled eyes have no clear sight.' But peak to me and advise me as it pleases you, for I am ready to do just as you will desire; and if you reprove me for my folly, I am more bound to love you and to praise you. For Solomon says that he who reproves another who does folly shall find greater grace than he who deceives another by sweet words.\n\nThen Lady Prudence said, \"I make no appearance of wrath or anger, except for your great profit. For Solomon says, 'He is more worthy who reproves or chides a fool for his folly, showing him the appearance of wrath, than he who supports him and praises him in his misdoing, and laughs at his folly.' And this same Solomon says afterward that 'By the sorrowful face of a man,' which is to say by the sorry and heavy countenance of a man, 'the fool corrects and amends himself.'\"\n\nThen Melibee said, \"I shall not be able to answer to so many fair reasons as you set forth and show to me. Tell me your will and your advice in brief, and I am prepared to fulfill it and carry it out.\"\n\nThen Lady Prudence made all her will known to him, and said, \"I advise you,\" she said, \"above all things, that you make peace between God and yourself; and be reconciled to him and to his grace. For, as I have told you earlier, God has permitted you to have this tribulation and misery because of your sins. And if you do as I say you, God will send your adversaries to you, and make them fall at your feet, ready to do your will and your commandments. For Solomon says, 'When the condition of man is pleasant and liking to God, he changes the hearts of the man's adversaries and compels them to beseech him for peace and grace.' And I pray you to let me speak with your adversaries in a private place; for they should not know that it is of your will or of your intention. And then, when I know their will and their intention, I may counsel you more with more certainty.\"\n\n\"Lady,\" Melibee said, \"do your will and your liking; for I put myself wholly at your disposal and in your guidance.\n\nThen Lady Prudence, when she saw the good will of her husband, deliberated with herself, thinking how she might bring this crisis to a good conclusion and to a good conclusion. And when she saw her time, she sent for these adversaries to come to her to a secret place, and showed to them in a wise fashion the great goods that come from peace, and the great harms and perils that are in war; and said to them in a kindly manner how they should greatly repent the injury and wrong that they had done to Melibee her lord, to her, and to their daughter.\n\nAnd when they heard the kindly words of Lady Prudence, they were so surprised and enraptured, and had such great joy from her that it is a wonder to relate it. \"Ah, lady,\" they said, \"you have shown to us the blessing of sweetness, according to the words of David the Prophet; for the reconciliation which we are not worthy to have in any manner, but which we ought to beg with great contrition and humility, you from your great goodness have presented to us. Now we see well that the knowledge and the wisdom of Solomon is very true. For he says that 'Sweet words multiply and increase friends, and make the wicked to be gentle and meek.'\"\n\n\"Surely,\" they said, \"we put our action and all our matter and cause entirely in your good will and are ready to obey the speech and commandment of my lord Melibee. And therefore, dear and benign lady, we pray you and beseech you as meekly as we possibly can, that it should please your great goodness to fulfill in deed your kindly words. For we consider and acknowledge that we have offended and grieved my lord Melibee to great excess, so far that we are not able to make amends with him. And therefore we oblige and bind ourselves and our friends to do all his will and his commandments. But perhaps he has such resentment and such wrath toward us, because of our offense, that he will lay such a penalty on us as we will not be able to bear or sustain. And therefore, noble lady, we beseech your womanly pity to take counsel in this extreme circumstance that neither we nor our friends be not disinherited nor destroyed through our folly.\"\n\n\"Certainly,\" said Prudence, \"it is a hard and very perilous thing that a man put himself utterly at the discretion, judgment, and the might and power of his enemies. For Solomon says, 'Believe me, and give credence to what I shall say: I say,' he said, 'you people and governors of holy church, never give to your son, to your wife, your friend, or your brother the mastery of your body as long as you live.' Now since he refutes that a man should give to his brother or his friend the might of his body, by a stronger reason he refutes and forbids a man to given himself to his enemy. And nonetheless I advise you that you do not mistrust my lord, for I know well and know truly that he is gentle and meek, generous, courteous, and not all desirous or covetous of goods or riches. For there is nothing in this world that he desires, except worship and honor alone. Furthermore, I know well and am very sure that he shall do nothing in this extreme situation without my counsel; and I shall so work in this cause that, by the grace of our Lord God, you should be reconciled with us.\n\nThen they said with one voice, \"Worshipful lady, we put us and our goods entirly at your will and disposition, and been redy to comen, what day that it like unto your nobility to lymyte us or assigne us, for to make our obligacioun and boond as strong as it liketh unto your goodness, that we might fulfille the wille of you and of my lord Melibee.\"\n\nWhen Lady Prudence had heard the answers of these men, she bade them go again secretly. And she returned to her lord Melibee and told him how she found his adversaries entirely repentant, acknowledging very humbly their sins and trespasses, and how they were ready to suffer all pain, begging and praying him for mercy and pity.\n\nThen Melibee said, \"He who does not excuse his own sin, but acknowledges, repents it, and asks indulgence, is well worthy to have pardon and forgiveness of his sin. For Seneca says, 'There is the remission and forgiveness, where there is confession'; for confession is the neighbor to innocence. And he says in another place that 'He who has shame for his sin and acknowledges it is worthy of remission.' And therefore I consent, and I confirm myself to have peace. But it is good that we do it not without the consent and will of our friends.\n\nThen Prudence was very glad and joyful, and said, \"Surely, sir,\" she said, \"you have answered well and kindly. For just as by the counsel, consent, and help of your friends you have been moved to avenge yourself and make war, so too without their counsel you have reconciled yourself to have peace with your adversaries. For the law says: 'There is nothing so good by way of nature as a thing to be undone by the one who did it.'\n\nAnd then Lady Prudence, without delay or tarrying, sent her messages immediately for her family, and for her old friends that were true and wise, and told them by order in the presence of Melibee all this matter as it is expressed and declared above, and prayed them that they would give her advice and counsel what would be best to do in this time of need. And when Melibee's friends had consulted and deliberated on the foresaid matter, and had examined it with great energy and diligence, they gave unanimous advice to have peace and rest, and that Melibee should receive with good heart his adversaries with forgiveness and mercy.\n\nAnd when Lady Prudence had heard the assent of her lord Melibee, and the counsel of his friends in agreement with her will and her intention, she was glad in her heart, and said, \"There is an old proverb,\" she said, \"which says that 'The goodness that you may do this day, do it, and do not wait or delay until tomorrow.' And therefore I advise that you send your messages, ones that are discreet and wise, to your adversaries, telling them on your behalf that if they will discuss peace and accord, that they prepare themselves without delay or tarrying to come to us.\"\n\nThis thing was performed indeed. And when these offenders and repentants of their follies, that is, the adversaries of Melibee, had heard what these messengers said to them, they were very glad and joyful, and answered meekly and humbly, yielding graces and thanks to her lord Melibee and to all his company; and prepared themselves without delay to go with the messengers, and to obey the commandment of her lord Melibee.\n\nAnd swiftly they made their way to the court of Melibee, and took with them some of their true friends to swear their good faith for them and to stand as their surety. And when they had come into the presence of Melibee, he said these words to them: \"It stands thus,\" Melibee said, \"and true it is, that you, without cause or rationale or reason, have done great injuries and wrongs to me, to my wife Prudence, and to my daughter also. For you have entered into my house by violence and have done such outrage that all men know well that you have deserved death. And therefore I wish to know and understand from you whether you wish to put the punishment, the chastisement, and the vengeance for this outrage in the will of me and of my wife Prudence, or do you wish not?\"\n\nThen the wisest of the three answered for them all and said, \"Sire,\" he said, \"we know well that we are unworthy to enter the court of so great and so worthy a lord as you are. For we have so greatly erred and have offended and sinned in such a way against your high honor, that truly we have deserved death. But yet, for the great goodness and gentility that all the world witnesses of your person, we submit ourselves to the excellence and kindness of your gracious lordship, and are ready to obey all your commandments; beseeching you that by your merciful pity you will consider our great repentance and humble submission, and grant us forgiveness for our outrageous trespass and offense. For well we know that your generous grace and mercy reach farther into goodness than do our outrageous sins and trespasses into wickedness, albeit that we have cursedly and damnably sinned against your high lordship.\"\n\nThen Melibee took them up from the ground gently, and received their obligations and their bonds by their oaths upon their pledges and sureties, and assigned them a certain day to return to his court, to accept and receive the sentence and judgment that Melibee would command to be done to them by the causes aforesaid. These things having been ordained, every man returned to his house.\n\nAnd when Lady Prudence saw her time, she inquired of and asked her lord Melibee what vengeance he thought to take on his adversaries.\n\nTo this Melibee answered, and said: \"Surely,\" he said, \"I think and intend fully to disinherit them of all that they ever should have, and to send them into exile for ever.\"\n\n\"Certainly,\" said Lady Prudence, \"this would be a cruel sentence and much against reason. For you are plenty rich and have no need of other men's goods; and you might easily in this way get yourself a reputation for covetousness, which is a vicious thing and ought to be avoided by every good man. For according to the wisdom of the word of the Apostle, 'Covetousness is the root of all harms.' And therefore it would be better for you to lose as much property of your own, than to take from their property in this manner; for it is better to lose property with honor than it is to gain property with villainy and shame. And every man ought to exert himself diligently and to get himself a good name. And yet shall he not only employ himself in keeping his good name, but he shall also endeavor always to do something by which he may renew his good name. For it is written that 'The old good reputation or good name of a man is soon goon and passed, when it is not renewed or refashioned.'\n\n\"And regarding the fact that you say you will exile your adversaries, this seems to me much against reason and beyond moderation, considering the power that they have given you over themselves. And it is written that 'He who misuses the might and the power that is given him deserves to lose his privilege.' And I propose that you could impose such a penalty by right and by law, which I believe you might not do, I say you might not execute it perhaps, and then it would be likely to return to the war as it was before.\n\n\"And therefore, if you wish that men will give you homage, you must judge more graciously; this is to say, you must give lighter sentences and judgments. For it is written that 'He who most courteously commands, men will obey most.' And therefore I pray you that in this extreme situation you decide to overcome your heart. For Seneca says that 'He who overcomes his heart, overcomes twice.' And Cicero says: 'There is no thing so commendable in a great lord as when he is gentle and meek, and is easily appeased.' And I pray you that you will refrain now from doing vengeance, in such a manner that your good name may be kept and preserved, and that men might have cause and matter to praise you for your pity and mercy, and that you have no cause to repent of things that you have done. For Seneca says, 'He is a bad victor who repents his victory.' For this reason I pray you, let mercy be in your heart, to the effect and intent that God Almighty may have mercy on you in his last judgment. For Saint James says in his epistle: 'Judgment without mercy shall be done to him that has no mercy for another creature.'\"\n\nWhen Melibee had heard the great arguments and reasons of Lady Prudence, and her wise instructions and teachings, his heart began to incline to the will of his wife, considering her true intent, and he soon conformed, agreed fully to work according to her counsel; and thanked God, from whom all virtue and all goodness proceeds, who sent him a wife of such great discretion.\n\nAnd when the day came that his adversaries were to appear in his presence, he spoke to them very kindly, and said in this way: \"Although in your pride, great presumption and folly, and negligence and ignorance, you have misbehaved yourself and trespassed against me, yet because I see and behold your great humility, and that you are sorry for and repentant of your sins, it compels me to offer you grace and mercy. For these reasons I receive you into my grace, and forgive you utterly all the offenses, injuries, and wrongs that you have done against me and mine, to the effect and to the end that God of his endless mercy will at the time of our dying forgive us our sins that we have trespassed against him in this wretched world.\n\n\"For doubtless, if we are sorry and repentant for the sins and crimes through which we have trespassed in the sight of our Lord God, he is so noble and so merciful that he will forgive us our sins and bring us to the bliss that has no end. Amen.\n\n\n### The Monk's Prologue\n\nWhen ended was my tale of Melibee\nAnd of Prudence and her benignity,\nOur host remarked: As I am faithful man,\nAnd by the precious corpus Madrian,\nI'd rather than a barrel of good ale\nThat my wife Goodlief could have heard this tale!\nFor she has no such patience, I'll avow,\nAs had this Melibeus' Prudence, now.\nBy God's own bones! When I do beat my knaves\nShe fetches forth the stoutest gnarly staves\nAnd cries out: 'Slay the damned dogs, every one!\nAnd break their bones, backbone and every bone!'\nAnd if but any neighbour, aye, of mine\nWill not, in church, bow to her and incline,\nOr happens to usurp her cherished place,\nWhy, she comes home and ramps right in my face,\nCrying, 'False coward, go avenge your wife!\nBy corpus bones! Come, let me have your knife,\nAnd you shall take my distaff and go spin!'\nFrom day to day like this will she begin:\n'Alas!' she cries, 'that ever fate should shape\nMy marriage with a milksop coward ape\nThat may be overborne by every wight!\nYou dare not stand up for your own wife's right!'\nThis is my life, unless I choose to fight;\nAnd through the door anon I must take flight,\nOr else I'm lost, unless, indeed, that I\nBe like a young wild lion, foolhardy.\nI know well she will make me kill, one day,\nSome neighbour man and have to run away.\nFor I am dangerous with a knife in hand,\nAlbeit that I dare not her withstand;\nFor she's big of arm, and wickedly inclined,\nAs anyone who crosses her will find.\nBut let us leave that doleful subject here.\nMy lord the monk, said he, be of good cheer\nFor you shall tell a tale, and verily.\nLo, Rochester is standing there hard by!\nRide up, my own liege lord, break not our game,\nBut, by my truth, I do not know your name,\nWhether I ought to call you lord Don John,\nOr Don Thomas, or else Don Albion?\nOf what house are you, by your father's kin?\nI vow to God you have a right fair skin;\nIt is a noble pasture where you're most;\nYou are not like a penitent or ghost.\nUpon my faith, you are some officer,\nSome worthy sexton, or a cellarer,\nFor by my father's soul, I guess, in sum,\nYou are a master when you are at home.\nNo cloisterer or novice can you be:\nA wily governor you seem to me,\nAnd therewithal a man of brawn and bone.\nA person of some consequence you've grown.\nI pray that God confound the silly fool\nThat put you first in a religious school;\nYou would have been a hen-hopper, all right!\nHad you as good a chance as you have might\nTo work your lust in good engendering;\nWhy, you'd beget full many a mighty thing.\nAlas! Why do you wear so wide a cope?\nGod give me sorrow but, if I were pope,\nNot only you, but every mighty man,\nThough he were shorn full high upon the pan,\nShould have a wife. For all the world's forlorn!\nReligion, why it's gathered all the corn\nOf treading, and we laymen are but shrimps!\nFrom feeble trees there come but wretched imps.\nThat's why our heirs are all so very slender\nAnd feeble that they may not well engender.\nThat's why out goodwives always will essay\nReligious folk, for you may better pay\nWith Venus' payments than we others do;\nGod knows, in no light weight of coin pay you!\nBut be not wroth, my lord, because I play;\nFull oft in jest have I heard truth, I say.\nThis worthy monk took all with sober sense,\nAnd said: I will do all my diligence,\nSo far as it accords with decency,\nTo tell to you a tale, or two, or three.\nAnd if you care to hear, come hitherward,\nAnd I'll repeat the life of Saint Edward;\nOr rather, first some tragedies I'll tell,\nWhereof I have a hundred in my cell.\nTragedy is to say a certain story\nFrom ancient books which have preserved the glory\nOf one that stood in great prosperity\nAnd is now fallen out of high degree\nIn misery, where he ends wretchedly.\nSuch tales are versified most commonly\nIn six feet, which men call hexameter.\nIn prose are many written; some prefer\nA quantitative metre, sundry wise.\nLo, this short prologue will enough suffice.\nNow hearken, if you'd like my speech to hear;\nBut first I do beseech, let it be clear\nThat I, in order, tell not all these things,\nBe it of popes, of emperors, or kings,\nEach in his place, as men in writings find,\nBut I put some before and some behind,\nAs they to memory may come by chance;\nHold me excused, pray, of my ignorance.\n\n\n### The Monk's Tale\n\nI will bewail in manner of tragedy\nThe ills of those that stood in high degree\nAnd fell so far there was no remedy\nTo bring them out of their adversity;\nFor certain 'tis, when Fortune wills to flee,\nThere may no man the course of her withhold;\nLet no man trust in blind prosperity;\nBe warned by these examples true and old.\n\n**LUCIFER**\n\nWith Lucifer, though he was angel fair\nAnd not a man, with him will I begin;\nFor though Fortune may not an angel dare,\nFrom high degree yet fell he for his sin\nDown into Hell, and he lies yet therein.\nO Lucifer, brightest of angels all,\nNow art thou Satan, and thou may'st not win\nFrom misery wherein thou far did'st fall!\n\n**ADAM**\n\nLo, Adam, in the garden Damascene,\nBy God Almighty's finger wrought was he,\nAnd not begotten of man's sperm unclean;\nHe ruled all Paradise, except one tree.\nHad never earthly man so high degree\nAs Adam, till he, for misgovernance,\nWas driven from his high prosperity\nTo labour, and to Hell, and to mischance.\n\n**SAMSON**\n\nLo, Samson, whose birth was annunciated\nBy angel, long ere his nativity,\nAnd was to God Almighty consecrated,\nAnd had nobility while he could see.\nWas never such another as was he\nFor body's strength, and therewith hardiness;\nBut to his wives he told his privity,\nWhereby he slew himself for wretchedness.\nSamson, this noble mighty champion,\nWithout a weapon in his hands, I say,\nHe slew and rent in two a young lion,\nWhile to his wedding walking in the way.\nHis false wife could so please him, she did pray\nTill she his secret held, when she, untrue,\nUnto his foes that secret did betray\nAnd him forsook for other loves and new.\nThree hundred foxes Samson took, for ire,\nAnd bound their brushes well together, and\nThen set those foxes' tails alight with fire,\nFor he to every one had fixed a brand;\nAnd they burned all the corn of all that land\nAnd all the olive trees and vines, each one.\nA thousand men he slew with his own hand,\nWith no weapon save an ass's jaw-bone.\nWhen they were slain, he thirsted so that he\nWas well nigh lost, for which he prayed, say I,\nThat God would on his pain have some pity\nAnd send him drink, or must he surely die;\nAnd from that ass's jaw-bone, then but dry,\nOut of a tooth there sprang anon a well,\nWhereof he drank his fill and laid it by.\nThus helped him God, as Judges, fifteen, tell.\nBy very force at Gaza, on a night,\nMaugre Philistines of that said city,\nThe great gates of the town he took with might,\nAnd on his shoulders carried them, did he,\nHigh on a hill where every man might see.\nO noble mighty Samson, lief and dear,\nHad'st thou not woman told thy privity,\nIn all this world had never been thy pear.\nThis Samson never liquor drank, nor wine.\nNor on his head came razor, nor a shear,\nObeying thus the angel's word divine,\nFor all his forces in his long locks were;\nAnd fully twenty winters, year by year,\nHe held of Israel the governance.\nBut all too soon should he weep many a tear,\nFor women should betray him to mischance!\nDelilah being his darling, her he told\nThat in his unshorn locks all his strength lay,\nAnd him to foemen then she falsely sold.\nFor, sleeping in her bosom, on a day,\nShe clipped and sheared all his long hair away,\nThen showed his state unto his enemies,\nAnd when they found him lying in this array\nThey bound him fast and put out both his eyes.\nBefore his hair was sheared and shaven close,\nThere were no bonds wherewith men might him bind;\nBut now he lies in prison cell, morose,\nAnd labours, when at mill they make him grind.\nO noble Samson, strongest of mankind,\nO judge, but late, in glory measureless,\nNow may'st thou shed hot tears from thine eyes blind,\nFor thou from wealth art fallen to wretchedness.\nThis captive's end was as I now shall say;\nHis foes they made a feast upon a day,\nAnd made him as their fool before them play,\nAll in a temple great, of rich array.\nBut at the last he made a stern affray;\nFor he two pillars took and caused them fall,\nAnd down came roof and all, and there it lay,\nKilling himself and enemies, each and all.\nThat is to say, those princes, every one,\nAnd full three thousand others who were slain\nBy falling of that temple built of stone.\nTo Samson now I'll not revert again.\nBe warned by this example old and plain.\nMen should not tell their business to their wives\nIn such things as of secrecy they're fain,\nAnd if it touch their limbs or touch their lives.\n\n**HERCULES**\n\nOf Hercules, the sovereign conquering power,\nSing his deeds' praise and sing his high renown;\nFor in his time of strength he was the flower.\nHe slew, and made a lion's skin his own;\nOf centaurs laid he all the boastings down;\nHe killed the cruel Harpies, those birds fell;\nBrought golden apples from the dragon thrown;\nAnd he stole Cerberus, the hound of Hell.\nHe slew the cruel tyrant Busiris\nAnd made his horses eat him, flesh and bone;\nTo a fiery, venomous worm he wrote finis;\nAchelous had two horns, but he broke one;\nCacus he slew within his cave of stone;\nHe slew the giant Anthaeus the strong;\nHe killed the Erymanthian boar anon;\nAnd bore the heavens upon his shoulders long.\nWas never man, since this old world began,\nThat slew so many monsters as did he.\nThroughout all earth's wide realms his honour ran,\nWhat of his strength and his high chivalry,\nAnd every kingdom went he out to see.\nHe was so strong no man could hinder him;\nAt both ends of the world, as says Trophy,\nIn lieu of limits he set pillars grim.\nA darling had this noble champion,\nDeianira, sweet as is the May;\nAnd as these ancient writers say, each one,\nShe sent to him a new shirt, fresh and gay.\nAlas that shirt, alas and welaway!\nEnvenomed was so cunningly withal\nThat, ere he'd worn the thing but half a day,\nIt made the flesh from off his bones to fall.\nYet are there writers who do her excuse\nBecause of Nessus, who the shirt had made;\nHowe'er it be, I will not her accuse;\nBut all his naked back this poison flayed\nUntil the flesh turned black, and torn, and frayed.\nAnd when he saw no other remedy,\nUpon a pyre of hot brands he was laid,\nFor of no poison would he deign to die.\nThus died this mighty worthy, Hercules.\nLo, who may trust to Fortune any throw?\nAnd he who seeks on earth for fame and case\nEre he's aware, he's often brought down low.\nRight wise is he that can his own heart know.\nBeware, when Fortune may her smile disclose,\nShe lies in wait her man to overthrow,\nAnd in such wise as he would least suppose.\n\n**NEBUCHADNEZZAR**\n\nThe precious treasure and the mighty throne,\nThe glorious sceptre and royal majesty\nThat Nebuchadnezzar counted as his own\nWith tongue or pen not easily told may be.\nTwice of Jerusalem the victor he;\nThe Temple's vessels took he and was glad.\nAnd Babylon was the ancient sovereign see\nWherein his glory and delight he had.\nThe fairest children of the blood royal\nOf Israel, he gelded them anon,\nAnd made each one of them to be his thrall.\nAmong the number Daniel thus was one,\nOf all the youth the nation's wisest son;\nFor he the dreams of the great king expounded\nWhen in Chaldea wise clerk was there none\nWho knew to what end those dreams were propounded.\nThis proud king made a statue of pure gold\nFull sixty cubits long by seven wide,\nUnto which image both the young and old\nCommanded he to bow down, nor deride,\nElse in a furnace full of flames go bide\nAnd burn to ashes, who would not obey.\nBut no assent to that, whate'er betide,\nWould Daniel and his pair of comrades say.\nThis king of kings right proud was and elate,\nAnd thought that God, Who sits in majesty,\nCould not bereave him of his high estate:\nYet suddenly he lost all dignity,\nAnd like a brute beast then he seemed to be,\nAnd ate hay like an ox, and lay without;\nIn rain and storm with all wild beasts walked he,\nUntil a certain time was come about.\nAnd like an eagle's fathers were his hairs,\nHis nails like any bird's claws hooked were;\nTill God released him after certain years\nAnd gave him sense; and then, with many a tear,\nHe gave God thanks; thereafter all in fear\nHe lived of doing ever again trespass,\nAnd till the time they laid him on his bier,\nHe knew that God was full of might and grace.\n\n**BELSHAZZAR**\n\nHis son, called Belshazzar, or Balthasar,\nWho held the realm after his father's day,\nHe for his father's fate would not beware,\nFor proud, he was of heart and of array;\nHe was a worshipper of idols aye.\nHis high estate assured him in his pride.\nBut Fortune cast him down and there he lay,\nAnd suddenly his kingdom did divide.\nA feast he made unto a thousand lords,\nUpon a time, and bade them merry be.\nThen to his officers he said these words:\nGo fetch me forth the vessels all, said he,\nOf which my father, in prosperity,\nThe temple in Jerusalem bereft,\nAnd unto our high gods give thanks that we\nRetain the honour that our elders left.\nHis wife, his lords, and all his concubines,\nThey drank then, while that mighty feast did last,\nOut of those noble vessels sundry wines.\nBut on a wall this king his eyes did cast\nAnd saw an armless hand that wrote full fast,\nFor fear whereof he shook with trouble sore.\nThis hand that held Belshazzar so aghast\nWrote Mene, mene, tekel, and no more.\nIn all that land magician was there none\nWho could explain what thing this writing meant;\nBut when they sent for Daniel it was done,\nWho said: O king, God to your father lent\nGlory and honour, treasure, government,\nAnd he was proud, nor feared God, being mad,\nWherefore Lord God great misery on him sent,\nAnd him bereft of all the realm he had.\nHe was cast out of human company;\nWith asses was his habitation known;\nHe ate hay like a beast, through wet and dry,\nUntil he learned, by grace and reason shown,\nThat Heaven's God has dominion, up and down,\nOver all realms and everything therein;\nAnd then did God to him compassion own\nAnd gave him back his kingdom and his kin.\nNow you, who are his son, are proud also,\nThough you knew all these things, aye verily;\nYou are a rebel and you are God's foe.\nYou drank from out His vessels boastfully;\nYour wife and all your wenches sinfully\nDrank from those sacred vessels sundry wines,\nAnd praised false gods, and hailed them, wickedly;\nWhereof toward you the wrath of God inclines.\nThat hand was sent from God which on the wall\nWrote Mene, mene, tekel. Oh, trust me,\nYour reign is done, you have no worth at all,\nDivided is your realm, and it shall be\nTo Medes and Persians given now, said he.\nAnd that night went the king to fill death's maw,\nAnd so Darius took his high degree,\nThough he thereto had naught of right in law.\nMasters, therefrom a moral may you take,\nThat in dominion is no certainness;\nFor when Fortune will any man forsake,\nShe takes his realm and all he may possess,\nAnd all his friends, too, both the great and less;\nFor when a man has friends that Fortune gave,\nMishap but turns them enemies, as I guess:\nThis word is true for king as well as slave.\n\n**ZENOBIA**\n\nZenobia, of all Palmyra queen\n(As write old Persians of her nobleness),\nSo mighty was in warfare, and so keen,\nThat no man her surpassed in hardiness,\nNor yet in lineage, nor in gentleness.\nOf blood of Persia's kings she was descended;\nI say not she had greatest beauteousness,\nBut of her figure naught could be amended.\nFrom childhood on I find that she had fled\nDuties of women, and to wildwood went;\nAnd many a wild hart's blood therein she shed\nWith arrows broad that she within them sent.\nSo swift she was, she ran them down all spent;\nAnd when she was grown older she would kill\nLions and leopards, and bears too she rent,\nAnd in her arms she broke them at her will.\nShe even dared the wild beasts' dens to seek,\nAnd ran upon the mountains all the night,\nSleeping beneath a bush; and, nothing weak,\nWrestled by very force and very might\nWith any man, however brave in fight;\nFor there was nothing in her arms could stand.\nShe kept her maidenhead from every wight,\nAnd unto no man would she yield her hand.\nBut at the last her friends did make her marry\nOdenathus, a prince of that country,\nAlbeit she long waited and did tarry;\nAnd you must understand that also he\nHeld to the same queer fancies as had she.\nNevertheless, when wedded, 'twould appear\nThey lived in joy and all felicity,\nFor each of them held other lief and dear.\nBut to one thing she never would consent,\nFor any prayers, that he should near her lie\nSave one night only, when 'twas her intent\nTo have a child, since men should multiply;\nYet when she learned she'd got no pregnancy\nFrom that night's work together on her bed,\nThen would she suffer him again to try,\nBut only once indeed, and then with dread.\nAnd when she was with child, all at the last,\nThen no more might he play at that same game\nTill fully forty days were gone and past;\nThen would she once more suffer him the same\nAnd were Odenathus grown wild or tame,\nHe got no more of her; for thus she'd say:\nIn wives it is but lechery and shame\nWhen, oftener, men with their bodies play.\nTwo sons by this Odenathus had she,\nThe which she bred in virtue and learning;\nBut now again unto our tale turn we.\nI say, so worshipful a young being,\nWise, and right generous in everything,\nCareful in war and courteous as well,\nAnd hardy in the field, and full daring,\nWas not in all the world where men do dwell.\nHer rich array may not be rightly told,\nEither of vessels or of fine clothing;\nShe was clad all in jewels and in gold;\nAnd she did never cease, despite hunting,\nTo gain of divers tongues a full knowing,\nWhenever she had time; she did intend\nTo learn from books, which were to her liking,\nHow she in virtue might her whole life spend.\nAnd briefly of this story now to treat,\nSo doughty was her husband, as was she,\nThat they two conquered many kingdoms great\nThroughout the East, with many a fair city\nThat did pertain unto the majesty\nOf Rome; and with strong hands they held them fast;\nNor might a foe escape by trying to flee\nThe while Odenathus' good days did last.\nHer battles all (as whoso wills may read)\nAgainst Sapor the king and others too,\nAnd all her story as it fell, indeed,\nWhy she was victor and had right thereto,\nAnd, after, all her misfortune and woe,\nHow they besieged her and at last did take,\nLet him unto my master Petrarch go,\nWho wrote the whole of this, I undertake.\nNow when Odenathus was dead, then she\nThe kingdom held within her own strong hand;\nAgainst her foes she fought so bitterly\nThere was no king or prince in all that land\nBut was right glad, if mercy make her bland,\nThat she turned not against him her array;\nWith her they made alliance, bond and band,\nTo keep the peace and let her ride and play.\nThe emperor of Rome, on Claudius\n(His predecessor, Galien too, that man),\nHad never courage to oppose her thus;\nNor was Egyptian nor Armenian,\nNor Syrian, nor yet Arabian\nThat dared against her in the field to fight,\nFor fear that at her hands they might be slain,\nOr by her army put to sudden flight.\nIn kingly habit went her sons also,\nAs being heirs to their sire's kingdoms all,\nAthenodorus and Thymalao\nTheir names were (or the Greeks did so them call).\nBut Fortune's honey is aye mixed with gall;\nThis mighty queen could no great while endure.\nAnd Fortune from her high throne made her fall\nTo wretchedness and into ways obscure.\nAurelian, when Roman governance\nCame to his two strong hands, made no delay,\nBut swore that on this queen he'd wreak vengeance,\nAnd so with mighty legions took his way\nAgainst Zenobia; let me briefly say\nHe made her flee; and at the last he sent\nAnd fettered her and her two sons one day,\nAnd won the land, and home to Rome he went.\nAmong the other booty Asian\nHer chariot was, of gold and jewellery,\nAnd this great Roman, this Aurelian,\nHe carried it away for men to see.\nBefore his car in triumph then walked she\nWith golden chains upon her neck hanging;\nCrowned was she, too, to show her high degree,\nAnd full of priceless gems was her clothing.\nAlas, Fortune! She that but lately was\nThe scourge of kings and emperors and powers,\nNow may the rabble gape at her, alas!\nAnd she that, armed, rode where grim battle lowers\nAnd took by force great cities and strong towers,\nMust wear a cap now while her two eyes weep;\nAnd she that bore the sceptre of carved flowers\nMay bear a distaff and thus earn her keep.\n\n**PEDRO, KING OF SPAIN**\n\nO noble Pedro, glory once of Spain,\nWhom Fortune held so high in majesty,\nWell ought men read thy piteous death with pain!\nOut of thy land thy brother made thee flee;\nAnd later, at a siege, by scheme crafty,\nThou wert betrayed, and led into his tent,\nWhere he then, and with his own hand, slew thee,\nSucceeding to thy realm and government.\nThe field of snow, with eagle black therein,\nCaught by the lime-rod, coloured as the gleed,\nHe brewed this wickedness and all this sin.\nThe Wicked Nest was worker of this deed;\nNot that Charles Oliver who aye took heed\nOf truth and honour, but the Armorican\nGanelon Oliver, corrupt for mead,\nBrought low this worthy king by such a plan.\nPETER, KING OF CYPRUS\nO noble Peter, Cyprus' lord and king,\nWhich Alexander won by mastery,\nTo many a heathen ruin did'st thou bring;\nFor this thy lords had so much jealousy,\nThat, for no crime save thy high chivalry,\nAll in thy bed they slew thee on a morrow.\nAnd thus does Fortune's wheel turn treacherously\nAnd out of happiness bring men to sorrow.\n\n**BERNABO OF LOMBARDY**\n\nOf Milan, great Bernabo Visconti,\nGod of delight and scourge of Lombardy,\nWhy should I tell not of thy misery,\nSince in all power thou did'st climb so high?\nThy brother's son, and doubly thine ally,\nFor he thy nephew was and son-in-law,\nWithin his prison shut thee up to die,\nBut I know not how death to thee did draw.\n\n**UGOLINO, COUNT OF PISA**\n\nOf Ugolino, Count of Pisa's woe\nNo tongue can tell the half for hot pity.\nNear Pisa stands a tower, and it was so\nThat to be there imprisoned doomed was he,\nWhile with him were his little children three,\nThe eldest child was scarce five years of age.\nAlas, Fortune! It was great cruelty\nTo lock such birds into such a cage!\nCondemned was he to die in that prison,\nSince Ruggieri, Pisa's bishop, twice\nHad lied, intrigued, and egged old passions on,\nWhereby the people did against him rise,\nAnd thrust him into prison in such wise\nAs you have heard; and meat and drink he had\nSo little that it could not long suffice,\nAnd was, moreover, very poor and bad.\nAnd on a day befell it, at the hour\nWhen commonly to him his food was brought,\nThe gaoler shut the great doors of the tower.\nHe heard it well enough, but he said naught,\nAnd to his heart anon there came the thought\nThat they by hunger would leave him to die.\nAlas, said he, that ever I was wrought!\nAnd thereupon the tears fell from his eye.\nHis youngest son, who three years was of age,\nUnto him said: Father, why do you weep?\nWhen will the gaoler bring us out pottage?\nIs there no crumb of bread that you did keep?\nI am so hungry that I cannot sleep.\nNow would God that I might sleep on for aye!\nThen should not hunger through my belly creep;\nFor nothing more than bread I'd rather pray.\nThus, day by day, this little child did cry,\nTill on his father's breast at length he lay\nAnd said: Farewell, my father, I must die.\nAnd kissed the man and died that very day.\nAnd when the father saw it dead, I say,\nFor grief his arms gnawed he until blood came,\nAnd said: Alas, Fortune and welaway,\nIt is thy treacherous wheel that I must blame!\nHis children thought that it for hunger was\nHe gnawed his arms, and not that 'twas for woe,\nAnd cried: O father, do not thus, alas!\nBut rather eat our young flesh, even so;\nThis flesh you gave us; take it back and go\nAnd eat enough! 'Twas thus those children cried,\nAnd after that, within a day or two,\nThey laid themselves upon his knees and died.\nHimself, despairing, all by hunger starved,\nThus ended this great count of Pisa's cries;\nAll his vast riches Fortune from him carved.\nOf his fate tragic let thus much suffice.\nWhoso would hear it told in longer wise,\nLet him read the great bard of Italy\nWhom men call Dante; seen through Dante's eyes\nNo point is slurred, nor in one word fails he.\n\n**NERO**\n\nThough viciousness had Nero in overplus,\nAs ever fiend that's low in torment thrown.\nYet he, as tells us old Suetonius,\nThis whole wide world held subject; aye, did own,\nEast, west, south, north, wherever Rome was known.\nOf rubies, sapphires, and of great pearls white\nWere all his garments broidered up and down,\nFor he in jewels greatly did delight.\nMore delicate, more pompous of array,\nMore proud was never emperor than he;\nThat toga which he wore on any day,\nAfter that time he nevermore would see.\nNets of gold thread he had in great plenty\nTo fish in Tiber when he pleased to play.\nHis lusts were all the laws in his decree,\nFor Fortune was his friend and would obey.\nHe burned Rome for his delicate profligacy;\nSome senators he slew upon a day\nOnly to learn how men might weep and cry;\nHe killed his brother and with his sister lay.\nHis mother put he into piteous way,\nFor he her belly ripped up just to see\nWhere he had been conceived; alack-a-day,\nThat but so little for her life cared he!\nNo tear out of his two eyes for that sight\nCame, but he said: A woman fair was she.\nGreat wonder is it how he could or might\nPass judgment thus upon her dead beauty.\nWine to be brought him then commanded he\nAnd drank anon; no other sign he made.\nWhen might is wedded unto cruelty,\nAlas, too deep its venom will pervade!\nA master had, in youth, this emperor,\nTo teach him letters and all courtesy,\nFor of morality he was the flower\nIn his own time, unless the old books lie;\nAnd while this master held his mastery,\nSo well he taught him wiles and subtle ways\nThat ere could tempt him vice or tyranny\nWas, it is said, the length of many days.\nThis Seneca, of whom I do apprise,\nBy reason Nero held him in such dread,\nSince he for vices spared not to chastise,\nDiscreetly, though, by word and not by deed-\nSir, would he say, an emperor must need\nBe virtuous and hate all tyranny-\nFor which, in bath, did Nero make him bleed\nFrom both his arms until he had to die.\nThis Nero had, though, out of arrogance,\nBeen wont, in youth, against the rod to rise,\nWhich afterward he thought a great grievance;\nWherefore he made him perish in this wise.\nNevertheless, this Seneca the wise\nChose in a bath to die, as you did hear,\nRather than suffer in some other guise;\nAnd thus did Nero slay his master dear.\nNow it befell that Fortune cared no longer\nTo Nero's high pride to be accomplice;\nFor though he might be strong, yet she was stronger;\nShe thought thus: By God, I am none too nice,\nSetting a man who is but filled with vice\nIn high degree, emperor over all.\nBy God, up from his seat I will him trice;\nWhen he least thinks of it, then shall he fall.\nThe people rose against him, on a night,\nFor all his faults; and when he it espied,\nOut of the doors he went and took to flight\nAlone; and where he thought he was allied\nHe knocked; but always, and the more he cried\nThe faster did they bar the doors, aye all;\nThen learned he well he'd been his own worst guide,\nAnd went his way, nor longer dared to call.\nThe people cried and rumbled up and down,\nAnd, having ears, he heard the thing they said:\nWhere's this false tyrant Nero, where's he flown?\nFor fear almost out of his wits he strayed,\nAnd to his gods, then, piously he prayed\nFor succour, but no help might him betide.\nFor fear of this he wished himself unmade,\nAnd ran into a garden, there to hide.\nAnd in this garden were two fellows, yea,\nWho sat before a great fire and a red,\nAnd to those fellows he began to pray\nThat they would slay him and strike off his head,\nBut of his body, after he was dead,\nThey should do nothing to its further shame.\nHimself he slew, no better counsel sped,\nWhereat Dame Fortune laughed and made a game.\n\n**HOLOFERNES**\n\nWas never captain, no, of any king's\nThat had more kingdoms in subjection thrown,\nNor stronger was, in field; above all things,\nNor in his time a greater of renown,\nNor had more pomp with high presumption shown,\nThan Holofernes, whom Dame Fortune kissed\nRight lecherously, and led him up and down\nUntil his head was off before 'twas missed.\nNot only did this world hold him in awe\nFor taking all its wealth and liberty,\nBut he made every man renounce old law.\nNebuchadnezzar is your god, said he,\nAnd now no other god shall worshipped be.\nAgainst his order no man dared to stand,\nSave in Bethulia, a strong city,\nWhere Eliachim priest was of the land.\nBut from the death of Holofernes learn.\nAmidst his host he lay drunk, on a night,\nWithin his tent, as large as ever barn,\nAnd yet, for all his pomp and all his might,\nJudith, a woman, as he lay upright,\nSleeping, smote off his head and from his tent\nStole secretly away from every wight,\nAnd with the head to her own town she went.\n\n**ANTIOCHUS EPIPHANES**\n\nWhat needs it, as for King Antiochus,\nTo tell his high and royal majesty,\nHis great pride and his deeds so venomous?\nThere never was another such as he.\nGo read what's said of him in Maccabee,\nAnd all the haughty sayings that he said,\nAnd how he fell from high prosperity,\nAnd on a hill how wretchedly lay dead.\nFortune had so enhanced the man's great pride\nThat verily he thought he might attain\nUnto the utter stars on every side,\nAnd in a balance weigh the high mountain,\nAnd all the flood-tides of the sea restrain.\nAnd God's own people held he most in hate.\nThem would he slay with torment and with pain,\nThinking that God his pride would not abate.\nAnd because Nicanor and Timothy\nWere vanquished by the Jews so mightily,\nUnto all Jews so great a hate had he\nThat he bade bring his chariot hastily,\nAnd swore an oath and said, impiteously,\nThat to Jerusalem he'd go ere noon\nTo wreak his ire on it full cruelly;\nBut from his purpose he was turned, and soon.\nGod, for this menace, smote him then full sore\nWith wound invisible, incurable,\nFor in his guts he was so carved, aye more,\nThe pain of it was insupportable.\nAnd certainly the thing was reasonable,\nFor many a man's guts he had caused to pain;\nBut from his purpose, cursed, damnable,\nIn spite of all he would not him restrain.\nHe gave command to marshal his great host,\nAnd suddenly, or ere he was aware,\nGod daunted all his pride and all his boast.\nFor he so heavily fell from his car\nThat from his very bones the flesh did tear,\nSo that he might not either walk or ride,\nBut in a litter men were forced to bear\nHim with them, bruised upon the back and side.\nThe wrath of God smote him so cruelly\nThat through his body loathsome maggots crept;\nAnd therewithal he stank so horribly\nThat none of those that round his person kept,\nWhether he lay awake or whether slept,\nCould, for the very stench of him, endure.\nIn this foul state he wailed and howled and wept;\nThat God was Lord of all he then was sure.\nTo all his host and to himself also\nFull loathsome was his carrion, one great blain;\nThere were no men could bear him to and fro.\nAnd in this stink and in this horrid pain\nHe died full wretchedly on a mountain.\nThus had this robber and this homicide,\nWho made so many men weep and complain,\nSuch guerdon as belongs to too great pride.\n\n**ALEXANDER**\n\nAlexander's tale is so well known a tune\nThat everyone who is not simple grown\nHas heard somewhat, or all, of his fortune\nThis whole wide world, to state conclusion known,\nHe won by strength, or else for his renown\nRight gladly men to sue for peace did send.\nThe pride of man and beast he tumbled down\nWhere'er he went, and that was the world's end.\nComparison might never yet be staked\nUpon a single similar conquering power;\nFor all this world in dread of him has quaked.\nHe was of knighthood and of freedom flower;\nFortune made him her heir to honour's bower;\nSave wine and women, nothing might assuage\nHis high intent in arms; all men must cower,\nSo filled he was of leonine courage.\nWhat praise were it to him, though 'gain were told\nDarius' tale or of others brought low-\nOf kings and dukes and earls and princes bold,\nThe which he conquered and brought down to woe?\nI say, as far as man may ride or go\nThe world was his, to tell it in a trice.\nFor though I wrote or told you always, so,\nOf his knighthood, the time would not suffice.\nTwelve years he reigned, as tells us Maccabee;\nAnd Philip's son of Macedon he was,\nWho first was king of Greece, the whole country.\nO noble Alexander, O alas!\nThat ever you should come to such a pass!\nFor poisoned by your very own you were;\nYour six did Fortune turn into an ace,\nAnd yet for you she never wept a tear!\nWho shall give me the tears now to complain\nFor death of gentle blood and high franchise?\nHe all the world did wield as one domain,\nAnd yet he thought it could not long suffice,\nSo full his heart was of high enterprise.\nAlas! And who shall help me to indict\nFalse Fortune, and all poison to despise?\nFor these I blame for all the woe I write.\n\n**JULIUS CAESAR**\n\nBy wisdom, manhood, and by great labour,\nFrom humble bed to royal majesty\nUp rose he, Julius the conqueror,\nWho won the Occident by land and sea,\nBy force of arms, or else by clear treaty,\nAnd unto Rome made all this tributary;\nAnd then of Rome the emperor was he,\nTill Fortune came to be his adversary.\nO mighty Caesar, who in Thessaly\nAgainst great Pompey, father of yours in law,\nThat of the East had all the chivalry\nFrom farthest places that the sun e'er saw,\nYou, by your knighthood broke them for death's maw,\nSave those few men who thence with Pompey fled,\nWhereby you put the Orient in awe.\nThank Fortune now that you so well have sped.\nBut now a little while I will bewail\nThis Pompey, this so noble governor\nOf Rome, who fled when battle's chance did fail;\nI say, one of his men, a false traitor,\nSmote off his head to win himself favour\nWith Julius, and there the head he brought.\nAlas, Pompey! Of Orient conqueror,\nThat Fortune such an end for thee hath wrought!\nTo Rome again repaired great Julius,\nTo have his triumph, laureate full high;\nBut on a time Brutus and Cassius,\nWho ever had of great estate envy,\nFull secretly did lay conspiracy\nAgainst this Julius, in subtle wise,\nAnd fixed the place at which he soon should die\nBy dagger thrusts, as I shall you apprise.\nThis Julius, to the Capitol he went\nUpon a day, as he'd been wont to go,\nAnd there they seized on him, as well they meant,\nThis treacherous Brutus and each other foe,\nAnd struck him with their daggers, high and low,\nAnd gave him many a wound and let him die;\nBut never groaned he, save at one stroke, no\n(Or two perchance), unless his legend lie.\nSo manly was this Julius in his heart,\nAnd so well loved he stately decency,\nThat, though his deadly wounds did burn and smart,\nHis mantle yet about his hips cast he,\nThat no man there should see his privity.\nAnd as he lay there, dying, in a trance,\nAnd knew that he was dying, verily,\nOf decency yet had he remembrance.\nLucan to tell this story I commend,\nSuetonius too, Valerius also,\nWho of the tale have written to the end\nAnd told how, of these mighty conquerors two,\nFortune was first the friend and then the foe.\nNo man may trust in Fortune's favour long,\nBut as one fearing ambush must he go.\nWitness the end of all these conquerors strong.\n\n**CROESUS**\n\nThe wealthy Croesus, Lydia's sometime king,\nOf which Croesus King Cyrus had such dread,\nYet was he taken, in his pride swelling,\nAnd to be burned upon a pyre was led.\nBut such a rain down from the clouds was shed\nAs quenched the fire and let him there escape;\nBut to be warned, no grace was in him spread\nTill Fortune on the gallows made him gape.\nWhen he'd escaped, not changed was his intent\nTo march at once into new wars again.\nHe thought right well 'twas Fortune that had sent\nSuch chance that he'd escape because of rain,\nAnd that by foes he never should be slain;\nAnd then a vision in the night he met,\nAt which he waxed so proud and grew so fain\nThat upon vengeance all his heart was set.\nUpon a tree he was, or so he thought,\nWhere Jupiter did wash him, back and side,\nAnd Phoebus, then, a fair white towel brought\nTo dry him with and thereby swell his pride;\nAnd to his daughter, who stood there beside,\nAnd well, he knew, in knowledge did abound,\nHe bade interpret what it signified,\nAnd she his dream in this wise did expound.\nThe tree, she said, the gallows is to mean,\nAnd Jupiter betokens snow and rain,\nWhile Phoebus with his towel white and clean,\nThat is the sunbeams beating down amain;\nYou shall be hanged, O father, 'tis certain;\nThe rain shall wash you and the sun shall dry.\nAnd thus she gave him warning flat and plain,\nHis daughter, who was Phania, say I.\nSo hanged was Croesus, that proud Lydian king,\nHis royal throne could nothing then avail.\nTragedy is no other kind of thing;\nNor can the singer cry aught, or bewail,\nBut that Dame Fortune always will assail\nWith unwarned stroke those great ones who are proud;\nFor when men trust her most, then will she fail\nAnd cover her bright face as with a cloud.\n\n"},{"index":10,"markdown":"### The Nun's Priest's Prologue\n\nHold! cried the knight. Good sir, no more of this,\nWhat you have said is right enough, and is\nVery much more; a little heaviness\nIs plenty for the most of us, I guess.\nFor me, I say it's saddening, if you please,\nAs to men who've enjoyed great wealth and ease,\nTo hear about their sudden fall, alas!\nBut the contrary's joy and great solace,\nAs when a man has been in poor estate\nAnd he climbs up and waxes fortunate,\nAnd there abides in all prosperity.\nSuch things are gladsome, as it seems to me,\nAnd of such things it would be good to tell.\nYea, quoth our host, and by Saint Paul's great bell,\nYou say the truth; this monk, his clapper's loud.\nHe spoke how 'Fortune covered with a cloud'\nI know not what, and of a 'tragedy,'\nAs now you heard, and gad! no remedy\nIt is to wail and wonder and complain\nThat certain things have happened, and it's pain.\nAs you have said, to hear of wretchedness.\nSir monk, no more of this, so God you bless!\nYour tale annoys the entire company;\nSuch talking is not worth a butterfly;\nFor in it is no sport nor any game.\nWherefore, sir monk, Don Peter by your name,\nI pray you heartily tell us something else,\nFor truly, but for clinking of the bells\nThat from your bridle hang on either side,\nBy Heaven's king, Who for us all has died,\nI should, ere this, have fallen down for sleep,\nAlthough the mud had never been so deep;\nThen had your story all been told in vain.\nFor certainly, as all these clerks complain,\n'Whenas a man has none for audience,\nIt's little help to speak his evidence.'\nAnd well I know the substance is in me\nTo judge of things that well reported be.\nSir, tell a tale of hunting now, I pray.\nNay, said this monk, I have no wish to play;\nNow let another tell, as I have told.\nThen spoke our host out, in rude speech and bold,\nAnd said he unto the nun's priest anon:\nCome near, you priest, come hither, you Sir John,\nTell us a thing to make our hearts all glad;\nBe blithe, although you ride upon a jade.\nWhat though your horse may be both foul and lean?\nIf he but serves you, why, don't care a bean;\nJust see your heart is always merry. So.\nYes, sir, said he, yes, host, so may I go,\nFor, save I'm merry, I know I'll be blamed.\nAnd right away his story has he framed,\nAnd thus he said unto us, every one,\nThis dainty priest, this goodly man, Sir John.\n\n\n### The Nun's Priest's Tale\n\nA widow poor, somewhat advanced in age,\nLived, on a time, within a small cottage\nBeside a grove and standing down a dale.\nThis widow, now, of whom I tell my tale,\nSince that same day when she'd been last a wife\nHad led, with patience, her strait simple life,\nFor she'd small goods and little income-rent;\nBy husbanding of such as God had sent\nShe kept herself and her young daughters twain.\nThree large sows had she, and no more, 'tis plain,\nThree cows and a lone sheep that she called Moll.\nRight sooty was her bedroom and her hall,\nWherein she'd eaten many a slender meal.\nOf sharp sauce, why she needed no great deal,\nFor dainty morsel never passed her throat;\nHer diet well accorded with her coat.\nRepletion never made this woman sick;\nA temperate diet was her whole physic,\nAnd exercise, and her heart's sustenance.\nThe gout, it hindered her nowise to dance,\nNor apoplexy spun within her head;\nAnd no wine drank she, either white or red;\nHer board was mostly garnished, white and black,\nWith milk and brown bread, whereof she'd no lack,\nBroiled bacon and sometimes an egg or two,\nFor a small dairy business did she do.\nA yard she had, enclosed all roundabout\nWith pales, and there was a dry ditch without,\nAnd in the yard a cock called Chanticleer.\nIn all the land, for crowing, he'd no peer.\nHis voice was merrier than the organ gay\nOn Mass days, which in church begins to play;\nMore regular was his crowing in his lodge\nThan is a clock or abbey horologe.\nBy instinct he'd marked each ascension down\nOf equinoctial value in that town;\nFor when fifteen degrees had been ascended,\nThen crew he so it might not be amended.\nHis comb was redder than a fine coral,\nAnd battlemented like a castle wall.\nHis bill was black and just like jet it shone;\nLike azure were his legs and toes, each one;\nHis spurs were whiter than the lily flower;\nAnd plumage of the burnished gold his dower.\nThis noble cock had in his governance\nSeven hens to give him pride and all pleasance,\nWhich were his sisters and his paramours\nAnd wondrously like him as to colours,\nWhereof the fairest hued upon her throat\nWas called the winsome Mistress Pertelote.\nCourteous she was, discreet and debonnaire,\nCompanionable, and she had been so fair\nSince that same day when she was seven nights old,\nThat truly she had taken the heart to hold\nOf Chanticleer, locked in her every limb;\nHe loved her so that all was well with him.\nBut such a joy it was to hear them sing,\nWhenever the bright sun began to spring,\nIn sweet accord, My love walks through the land.\nFor at that time, and as I understand,\nThe beasts and all the birds could speak and sing.\nSo it befell that, in a bright dawning,\nAs Chanticleer 'midst wives and sisters all\nSat on his perch, the which was in the hall,\nAnd next him sat the winsome Pertelote,\nThis Chanticleer he groaned within his throat\nLike man that in his dreams is troubled sore.\nAnd when fair Pertelote thus heard him roar,\nShe was aghast and said: O sweetheart dear,\nWhat ails you that you groan so? Do you hear?\nYou are a sleepy herald. Fie, for shame!\nAnd he replied to her thus: Ah, madame,\nI pray you that you take it not in grief:\nBy God, I dreamed I'd come to such mischief,\nJust now, my heart yet jumps with sore affright.\nNow God, cried he, my vision read aright\nAnd keep my body out of foul prison!\nI dreamed, that while I wandered up and down\nWithin our yard, I saw there a strange beast\nWas like a dog, and he'd have made a feast\nUpon my body, and have had me dead.\nHis colour yellow was and somewhat red;\nAnd tipped his tail was, as were both his ears,\nWith black, unlike the rest, as it appears;\nHis snout was small and gleaming was each eye.\nRemembering how he looked, almost I die;\nAnd all this caused my groaning, I confess.\nAha, said she, fie on you, spiritless!\nAlas! cried she, for by that God above,\nNow have you lost my heart and all my love;\nI cannot love a coward, by my faith.\nFor truly, whatsoever woman saith,\nWe all desire, if only it may be,\nTo have a husband hardy, wise, and free,\nAnd trustworthy, no niggard, and no fool,\nNor one that is afraid of every tool,\nNor yet a braggart, by that God above!\nHow dare you say, for shame, unto your love\nThat there is anything that you have feared?\nHave you not man's heart, and yet have a beard?\nAlas! And are you frightened by a vision?\nDreams are, God knows, a matter for derision.\nVisions are generated by repletions\nAnd vapours and the body's bad secretions\nOf humours overabundant in a wight.\nSurely this dream, which you have had tonight,\nComes only of the superfluity\nOf your bilious irascibility,\nWhich causes folk to shiver in their dreams\nFor arrows and for flames with long red gleams,\nFor great beasts in the fear that they will bite,\nFor quarrels and for wolf whelps great and slight;\nJust as the humour of melancholy\nCauses full many a man, in sleep, to cry,\nFor fear of black bears or of bulls all black,\nOr lest black devils put them in a sack.\nOf other humours could I tell also,\nThat bring, to many a sleeping man, great woe;\nBut I'll pass on as lightly as I can.\nLo, Cato, and he was a full wise man,\nSaid he not, we should trouble not for dreams?\nNow, sir, said she, when we fly from the beams,\nFor God's love go and take some laxative;\nOn peril of my soul, and as I live,\nI counsel you the best, I will not lie,\nThat both for choler and for melancholy\nYou purge yourself; and since you shouldn't tarry,\nAnd on this farm there's no apothecary,\nI will myself go find some herbs for you\nThat will be good for health and pecker too;\nAnd in our own yard all these herbs I'll find,\nThe which have properties of proper kind\nTo purge you underneath and up above.\nForget this not, now, for God's very love!\nYou are so very choleric of complexion.\nBeware the mounting sun and all dejection,\nNor get yourself with sudden humours hot;\nFor if you do, I dare well lay a groat\nThat you shall have the tertian fever's pain,\nOr some ague that may well be your bane.\nA day or two you shall have digestives\nOf worms before you take your laxatives\nOf laurel, centuary, and fumitory,\nOr else of hellebore purificatory,\nOr caper spurge, or else of dogwood berry,\nOr herb ivy, all in our yard so merry;\nPeck them just as they grow and gulp them in.\nBe merry, husband, for your father's kin!\nDread no more dreams. And I can say no more.\nMadam, said he, gramercy for your lore.\nNevertheless, not running Cato down,\nWho had for wisdom such a high renown,\nAnd though he says to hold no dreams in dread,\nBy God, men have, in many old books, read\nOf many a man more an authority\nThat ever Cato was, pray pardon me,\nWho say just the reverse of his sentence,\nAnd have found out by long experience\nThat dreams, indeed, are good significations,\nAs much of joys as of all tribulations\nThat folk endure here in this life present.\nThere is no need to make an argument;\nThe very proof of this is shown indeed.\nOne of the greatest authors that men read\nSays thus: That on a time two comrades went\nOn pilgrimage, and all in good intent;\nAnd it so chanced they came into a town\nWhere there was such a crowding, up and down,\nOf people, and so little harbourage,\nThat they found not so much as one cottage\nWherein the two of them might sheltered be.\nWherefore they must, as of necessity,\nFor that one night at least, part company;\nAnd each went to a different hostelry\nAnd took such lodgment as to him did fall.\nNow one of them was lodged within a stall,\nFar in a yard, with oxen of the plow;\nThat other man found shelter fair enow,\nAs was his luck, or was his good fortune,\nWhatever 'tis that governs us, each one.\nSo it befell that, long ere it was day,\nThis last man dreamed in bed, as there he lay,\nThat his poor fellow did unto him call,\nSaying: 'Alas! For in an ox's stall\nThis night shall I be murdered where I lie.\nNow help me, brother dear, before I die.\nCome in all haste to me.' 'Twas thus he said.\nThis man woke out of sleep, then, all afraid;\nBut when he'd wakened fully from his sleep,\nHe turned upon his pillow, yawning deep,\nThinking his dream was but a fantasy.\nAnd then again, while sleeping, thus dreamed he.\nAnd then a third time came a voice that said\n(Or so he thought): 'Now, comrade, I am dead;\nBehold my bloody wounds, so wide and deep!\nEarly arise tomorrow from your sleep,\nAnd at the west gate of the town,' said he,\nA wagon full of dung there shall you see,\nWherein is hid my body craftily;\nDo you arrest this wagon right boldly.\nThey killed me for what money they could gain.\nAnd told in every point how he'd been slain,\nWith a most pitiful face and pale of hue.\nAnd trust me well, this dream did all come true;\nFor on the morrow, soon as it was day,\nUnto his comrade's inn he took the way;\nAnd when he'd come into that ox's stall,\nUpon his fellow he began to call.\nThe keeper of the place replied anon,\nAnd said he: 'Sir, your friend is up and gone;\nAs soon as day broke he went out of town.'\nThis man, then, felt suspicion in him grown,\nRemembering the dream that he had had,\nAnd forth he went, no longer tarrying, sad,\nUnto the west gate of the town, and found\nA dung-cart on its way to dumping-ground,\nAnd it was just the same in every wise\nAs you have heard the dead man advertise;\nAnd with a hardy heart he then did cry\nVengeance and justice on this felony:\n'My comrade has been murdered in the night,\nAnd in this very cart lies, face upright.\nI cry to all the officers,' said he\n'That ought to keep the peace in this city.\nAlas, alas, here lies my comrade slain!'\nWhy should I longer with this tale detain?\nThe people rose and turned the cart to ground,\nAnd in the center of the dung they found\nThe dead man, lately murdered in his sleep.\nO Blessed God, Who art so true and deep!\nLo, how Thou dost turn murder out alway!\nMurder will out, we see it every day.\nMurder's so hateful and abominable\nTo God, Who is so just and reasonable,\nThat He'll not suffer that it hidden be;\nThough it may skulk a year, or two, or three,\nMurder will out, and I conclude thereon.\nImmediately the rulers of that town,\nThey took the carter and so sore they racked\nHim and the host, until their bones were cracked,\nThat they confessed their wickedness anon,\nAnd hanged they both were by the neck, and soon.\nHere may men see that dreams are things to dread.\nAnd certainly, in that same book I read,\nRight in the very chapter after this\n(I spoof not, as I may have joy and bliss),\nOf two men who would voyage oversea,\nFor some cause, and unto a far country,\nIf but the winds had not been all contrary,\nCausing them both within a town to tarry,\nWhich town was builded near the haven-side.\nBut then, one day, along toward eventide,\nThe wind did change and blow as suited best.\nJolly and glad they went unto their rest.\nAnd were prepared right early for to sail;\nBut unto one was told a marvelous tale.\nFor one of them, a-sleeping as he lay,\nDid dream a wondrous dream ere it was day.\nHe thought a strange man stood by his bedside\nAnd did command him, he should there abide,\nAnd said to him: 'If you tomorrow wend,\nYou shall be drowned; my tale is at an end.'\nHe woke and told his fellow what he'd met\nAnd prayed him quit the voyage and forget;\nFor just one day he prayed him there to bide.\nHis comrade, who was lying there beside,\nBegan to laugh and scorned him long and fast.\n'No dream,' said he, 'may make my heart aghast,\nSo that I'll quit my business for such things.\nI do not care a straw for your dreamings,\nFor visions are but fantasies and japes.\nMen dream, why, every day, of owls and apes,\nAnd many a wild phantasm therewithal;\nMen dream of what has never been, nor shall.\nBut since I see that you will here abide,\nAnd thus forgo this fair wind and this tide,\nGod knows I'm sorry; nevertheless, good day!'\nAnd thus he took his leave and went his way.\nBut long before the half his course he'd sailed,\nI know not why, nor what it was that failed,\nBut casually the vessel's bottom rent,\nAnd ship and men under the water went,\nIn sight of other ships were there beside,\nThe which had sailed with that same wind and tide\nAnd therefore, pretty Pertelote, my dear,\nBy such old-time examples may you hear\nAnd learn that no man should be too reckless\nOf dreams, for I can tell you, fair mistress,\nThat many a dream is something well to dread\nWhy in the 'Life' of Saint Kenelm I read\n(Who was Kenelphus' son, the noble king\nOf Mercia), how Kenelm dreamed a thing;\nA while ere he was murdered, so they say,\nHis own death in a vision saw, one day.\nHis nurse interpreted, as records tell,\nThat vision, bidding him to guard him well\nFrom treason; but he was but seven years old,\nAnd therefore 'twas but little he'd been told\nOf any dream, so holy was his heart.\nBy God! I'd rather than retain my shirt\nThat you had read this legend, as have I.\n\nDame Pertelote, I tell you verily,\nMacrobius, who wrote of Scipio\nThe African a vision long ago,\nHe holds by dreams, saying that they have been\nWarnings of things that men have later seen.\nAnd furthermore, I pray you to look well\nIn the Old Testament at Daniel,\nWhether he held dreams for mere vanity.\nRead, too, of Joseph, and you there shall see\nWhere dreams have sometimes been (I say not all)\nWarnings of things that, after did befall.\nConsider Egypt's king, Dan Pharaoh,\nHis baker and his butler, these also,\nWhether they knew of no effect from dreams.\nWhoso will read of sundry realms the themes\nMay learn of dreams full many a wondrous thing.\nLo, Croesus, who was once of Lydia king,\nDreamed he not that he sat upon a tree,\nWhich signified that hanged high he should be?\nLo, how Andromache, great Hector's wife,\nOn that same day when Hector lost his life,\nShe dreamed upon the very night before\nThat Hector's life should be lost evermore,\nIf on that day he battled, without fail.\nShe warned him, but no warning could avail;\nHe went to fight, despite all auspices,\nAnd so was shortly slain by Achilles.\nBut that same tale is all too long to tell,\nAnd, too, it's nearly day, I must not dwell\nUpon this; I but say, concluding here,\nThat from this vision I have cause to fear\nAdversity; and I say, furthermore,\nThat I do set by laxatives no store,\nFor they are poisonous, I know it well.\nThem I defy and love not, truth to tell.\nBut let us speak of mirth and stop all this;\nMy lady Pertelote, on hope of bliss,\nIn one respect God's given me much grace;\nFor when I see the beauty of your face,\nYou are so rosy-red beneath each eye,\nIt makes my dreadful terror wholly die.\nFor there is truth in In principio\nMulier est hominis confusio\n(Madam, the meaning of this latin is,\nWoman is man's delight and all his bliss).\nFor when I feel at night your tender side,\nAlthough I cannot then upon you ride,\nBecause our perch so narrow is, alas!\nI am so full of joy and all solace\nThat I defy, then, vision, aye and dream.\nAnd with that word he flew down from the beam,\nFor it was day, and down went his hens all;\nAnd with a cluck he them began to call,\nFor he had found some corn within the yard.\nRegal he was, and fears he did discard.\nHe feathered Pertelote full many a time\nAnd twenty times he trod her ere 'twas prime.\nHe looked as if he were a grim lion\nAs on his toes he strutted up and down;\nHe deigned not set his foot upon the ground.\nHe clucked when any grain of corn he found,\nAnd all his wives came running at his call.\nThus regal, as a prince is in his hall,\nI'll now leave busy Chanticleer to feed,\nAnd with events that followed I'll proceed.\nWhen that same month wherein the world began,\nWhich is called March, wherein God first made man,\nWas ended, and were passed of days also,\nSince March began, full thirty days and two,\nIt fell that Chanticleer, in all his pride,\nHis seven wives a-walking by his side,\nCast up his two eyes toward the great bright sun\n(Which through die sign of Taurus now had run\nTwenty degrees and one, and somewhat more),\nAnd knew by instinct and no other lore\nThat it was prime, and joyfully he crew,\nThe sun, my love, he said, has climbed anew\nForty degrees and one, and somewhat more.\nMy lady Pertelote, whom I adore,\nMark now these happy birds, hear how they sing,\nAnd see all these fresh flowers, how they spring;\nFull is my heart of revelry and grace.\nBut suddenly he fell in grievous case;\nFor ever the latter end of joy is woe.\nGod knows that worldly joys do swiftly go;\nAnd if a rhetorician could but write,\nHe in some chronicle might well indite\nAnd mark it down as sovereign in degree.\nNow every wise man, let him hark to me:\nThis tale is just as true, I undertake,\nAs is the book of Launcelot of the Lake,\nWhich women always hold in such esteem.\nBut now I must take up my proper theme.\nA brant-fox, full of sly iniquity,\nThat in the grove had lived two years, or three,\nNow by a fine premeditated plot\nThat same night, breaking through the hedge, had got\nInto the yard where Chanticleer the fair\nWas wont, and all his wives too, to repair;\nAnd in a bed of greenery still he lay\nTill it was past the quarter of the day,\nWaiting his chance on Chanticleer to fall,\nAs gladly do these killers one and all\nWho lie in ambush for to murder men.\nO murderer false, there lurking in your den!\nO new Iscariot, O new Ganelon!\nO false dissimulator, Greek Sinon\nThat brought down Troy all utterly to sorrow!\nO Chanticleer, accursed be that morrow\nWhen you into that yard flew from the beams!\nYou were well warned, and fully, by your dreams\nThat this day should hold peril damnably.\nBut that which God foreknows, it needs must be,\nSo says the best opinion of the clerks.\nWitness some cleric perfect for his works,\nThat in the schools there's a great altercation\nIn this regard, and much high disputation\nThat has involved a hundred thousand men.\nBut I can't sift it to the bran with pen,\nAs can the holy Doctor Augustine,\nOr Boethius, or Bishop Bradwardine,\nWhether the fact of God's great foreknowing\nMakes it right needful that I do a thing\n(By needful, I mean, of necessity);\nOr else, if a free choice he granted me,\nTo do that same thing, or to do it not,\nThough God foreknew before the thing was wrought;\nOr if His knowing constrains never at all,\nSave by necessity conditional.\nI have no part in matters so austere;\nMy tale is of a cock, as you shall hear,\nThat took the counsel of his wife, with sorrow,\nTo walk within the yard upon that morrow\nAfter he'd had the dream whereof I told.\nNow women's counsels oft are ill to hold;\nA woman's counsel brought us first to woe,\nAnd Adam caused from Paradise to go,\nWherein he was right merry and at ease.\nBut since I know not whom it may displease\nIf woman's counsel I hold up to blame,\nPass over, I but said it in my game.\nRead authors where such matters do appear,\nAnd what they say of women, you may hear.\nThese are the cock's words, they are none of mine;\nNo harm in women can I e'er divine.\nAll in the sand, a-bathing merrily,\nLay Pertelote, with all her sisters by,\nThere in the sun; and Chanticleer so free\nSang merrier than a mermaid in the sea\n(For Physiologus says certainly\nThat they do sing, both well and merrily).\nAnd so befell that, as he cast his eye\nAmong the herbs and on a butterfly,\nHe saw this fox that lay there, crouching low.\nNothing of urge was in him, then, to crow;\nBut he cried Cock-cock-cock and did so start\nAs man who has a sudden fear at heart.\nFor naturally a beast desires to flee\nFrom any enemy that he may see,\nThough never yet he's clapped on such his eye.\nWhen Chanticleer the fox did then espy,\nHe would have fled but that the fox anon\nSaid: Gentle sir, alas! Why be thus gone?\nAre you afraid of me, who am your friend?\nNow, surely, I were worse than any fiend\nIf I should do you harm or villainy.\nI came not here upon your deeds to spy;\nBut, certainly, the cause of my coming\nWas only just to listen to you sing.\nFor truly, you have quite as fine a voice\nAs angels have that Heaven's choirs rejoice;\nBoethius to music could not bring\nSuch feeling, nor do others who can sing.\nMy lord your father (God his soul pray bless!)\nAnd too your mother, of her gentleness,\nHave been in my abode, to my great ease;\nAnd truly, sir, right fain am I to please.\nBut since men speak of singing, I will say\n(As I still have my eyesight day by day),\nSave you, I never heard a man so sing\nAs did your father in the grey dawning;\nTruly 'twas from the heart, his every song.\nAnd that his voice might ever be more strong,\nHe took such pains that, with his either eye,\nHe had to blink, so loudly would he cry,\nA-standing on his tiptoes therewithal,\nStretching his neck till it grew long and small.\nAnd such discretion, too, by him was shown,\nThere was no man in any region known\nThat him in song or wisdom could surpass.\nI have well read, in Dan Burnell the Ass,\nAmong his verses, how there was a cock,\nBecause a priest's son gave to him a knock\nUpon the leg, while young and not yet wise,\nHe caused the boy to lose his benefice.\nBut, truly, there is no comparison\nWith the great wisdom and the discretion\nYour father had, or with his subtlety.\nNow sing, dear sir, for holy charity,\nSee if you can your father counterfeit.\nThis Chanticleer his wings began to beat,\nAs one that could no treason there espy,\nSo was he ravished by this flattery\nAlas, you lords! Full many a flatterer\nIs in your courts, and many a cozener,\nThat please your honours much more, by my fay,\nThan he that truth and justice dares to say.\nGo read the Ecclesiast on flattery;\nBeware, my lords, of all their treachery!\nThis Chanticleer stood high upon his toes,\nStretching his neck, and both his eyes did close,\nAnd so did crow right loudly, for the nonce;\nAnd Russel Fox, he started up at once,\nAnd by the gorget grabbed our Chanticleer,\nFlung him on back, and toward the wood did steer,\nFor there was no man who as yet pursued.\nO destiny, you cannot be eschewed!\nAlas, that Chanticleer flew from the beams!\nAlas, his wife recked nothing of his dreams!\nAnd on a Friday fell all this mischance.\nO Venus, who art goddess of pleasance,\nSince he did serve thee well, this Chanticleer,\nAnd to the utmost of his power here,\nMore for delight than cocks to multiply,\nWhy would'st thou suffer him that day to die?\nO Gaufred, my dear master sovereign,\nWho, when King Richard Lionheart was slain\nBy arrow, sang his death with sorrow sore,\nWhy have I not your faculty and lore\nTo chide Friday, as you did worthily?\n(For truly, on a Friday slain was he).\nThen would I prove how well I could complain\nFor Chanticleer's great fear and all his pain.\nCertainly no such cry and lamentation\nWere made by ladies at Troy's debolation,\nWhen Pyrrhus with his terrible bared sword\nHad taken old King Priam by the beard\nAnd slain him (as the Aeneid tells to us),\nAs made then all those hens in one chorus\nWhen they had caught a sight of Chanticleer.\nBut fair Dame Pertelote assailed the ear\nFar louder than did Hasdrubal's good wife\nWhen that her husband bold had lost his life,\nAnd Roman legionaries burned Carthage;\nFor she so full of torment was, and rage,\nShe voluntarily to the fire did start\nAnd burned herself there with a steadfast heart.\nAnd you, O woeful hens, just so you cried\nAs when base Nero burned the city wide\nOf Rome, and wept the senators' stern wives\nBecause their husbands all had lost their lives,\nFor though not guilty, Nero had them slain.\nNow will I turn back to my tale again.\nThis simple widow and her daughters two\nHeard these hens cry and make so great ado,\nAnd out of doors they started on the run\nAnd saw the fox into the grove just gone,\nBearing upon his back the cock away.\nAnd then they cried, Alas, and weladay!\nOh, oh, the fox! and after him they ran,\nAnd after them, with staves, went many a man;\nRan Coll, our dog, ran Talbot and Garland,\nAnd Malkin with a distaff in her hand;\nRan cow and calf and even the very hogs,\nSo were they scared by barking of the dogs\nAnd shouting men and women all did make,\nThey all ran so they thought their hearts would break.\nThey yelled as very fiends do down in Hell;\nThe ducks they cried as at the butcher fell;\nThe frightened geese flew up above the trees;\nOut of the hive there came the swarm of bees;\nSo terrible was the noise, ah ben'cite!\nCertainly old Jack Straw and his army\nNever raised shouting half so loud and shrill\nWhen they were chasing Flemings for to kill,\nAs on that day was raised upon the fox.\nThey brought forth trumpets made of brass, of box,\nOf horn, of bone, wherein they blew and pooped,\nAnd therewithal they screamed and shrieked and whooped;\nIt seemed as if the heaven itself should fall!\nAnd now, good men, I pray you hearken all.\nBehold how Fortune turns all suddenly\nThe hope and pride of even her enemy!\nThis cock, which lay across the fox's back,\nIn all his fear unto the fox did clack\nAnd say: Sir, were I you, as I should be,\nThen would I say (as God may now help me!),\n'Turn back again, presumptuous peasants all!\nA very pestilence upon you fall!\nNow that I've gained here to this dark wood's side,\nIn spite of you this cock shall here abide.\nI'll eat him, by my faith, and that anon!'\nThe fox replied: In faith, it shall be done!\nAnd as he spoke that word, all suddenly\nThis cock broke from his mouth, full cleverly,\nAnd high upon a tree he flew anon.\nAnd when the fox saw well that he was gone,\nAlas, quoth he, O Chanticleer, alas!\nI have against you done a base trespass\nIn that I frightened you, my dear old pard,\nWhen you I seized and brought from out that yard;\nBut, sir, I did it with no foul intent;\nCome down, and I will tell you what I meant.\nI'll tell the truth to you, God help me so!\nNay then, said he, beshrew us both, you know,\nBut first, beshrew myself, both blood and bones,\nIf you beguile me, having done so once,\nYou shall no more, with any flattery,\nCause me to sing and close up either eye.\nFor he who shuts his eyes when he should see,\nAnd wilfully, God let him ne'er be free!\nNay, said the fox, but, God give him mischance\nWho is so indiscreet in governance\nHe chatters when he ought to hold his peace.\nLo, such it is when watch and ward do cease,\nAnd one grows negligent with flattery.\nBut you that hold this tale a foolery,\nAs but about a fox, a cock, a hen,\nYet do not miss the moral, my good men.\nFor Saint Paul says that all that's written well\nIs written down some useful truth to tell.\nThen take the wheat and let the chaff lie still.\nAnd now, good God, and if it be Thy will,\nAs says Lord Christ, so make us all good men\nAnd bring us into His high bliss. Amen.\n\n\n### The Nun's Priest's Epilogue\n\nSir nun's priest, said our host, and that anon,\nNow blessed be your breech and every stone!\nThis was a merry tale of Chanticleer.\nBut, truth, if you were secular, I swear\nYou would have been a hen-hopper, all right!\nFor if you had the heart, as you have might,\nYou'd need some hens, I think it will be seen,\nAnd many more than seven times seventeen.\nFor see what muscles has this noble priest,\nSo great a neck and such a splendid chest!\nHe's got a hawk's fierce fire within his eye;\nAnd certainly he has no need to dye\nHis cheeks with any stain from Portugal.\nSir, for your tale, may blessings on you fall!\nAnd after that he, with right merry cheer,\nSpoke to another one, as you shall hear.\n\n\n### The Second Nun's Prologue\n\nThat servant and that nurse unto the vices\nWhich men do call in English Idleness,\nPortress at Pleasure's gate, by all advices\nWe should avoid, and by her foe express,\nThat is to say, by lawful busyness,\nWe ought to live with resolute intent,\nLest by the Fiend through sloth we should be rent.\nFor he, that with his thousand cords and sly\nContinually awaits us all to trap,\nWhen he a man in idleness may spy\nHe easily the hidden snare will snap,\nAnd till the man has met the foul mishap,\nHe's not aware the Fiend has him in hand;\nWe ought to work and idleness withstand.\nAnd though men never dreaded they must die,\nYet men see well, by reason, idleness\nIs nothing more than rotten sluggardry,\nWhereof comes never good one may possess;\nAnd see sloth hold her in a leash, no less,\nOnly to sleep and eat and always drink\nAnd to absorb all gain of others' swink.\nAnd so, to save us from such idleness\nThrough which great trouble and distress have grown,\nI have here done my faithful busyness,\nTranslating the old legend, to make known\nAll of that glorious life which was thine own,\nThou ever with the rose and lily crowned,\nCecilia, for virtues high renowned.\nInvocatio ad Mariam\nAnd Thou that art the flower of virgins all\nOf whom Saint Bernard loved so well to write,\nTo Thee at my beginning do I call;\nThou comfort of us wretches, help me indite\nThy maiden's death, who won through her merit\nThe eternal life, and from the Fiend such glory\nAs men may read hereafter in her story.\nThou Maid and Mother, Daughter of Thy Son,\nThou well of ruth, of sinful souls the cure,\nIn Whom, for goodness, God was embryon,\nThou humble One, high over each creature,\nThou did'st ennoble so far our nature\nThat no disdain God had of humankind\nHis Son in blood and flesh to clothe and wind.\nWithin the blessed cloister of Thy sides\nTook human shape eternal love and peace\nWho all the threefold world as sovereign guides,\nWhom earth and sea and heaven, without cease,\nDo praise; and Thou, O stainless Maid, increase\nBore of Thy body- and wert kept a maid-\nThe mighty God Who every creature made.\nAssembled is in Thee magnificence,\nWith mercy, goodness, and with such pity\nThat Thou, Who art the sun of excellence,\nNot only keepest those that pay to Thee,\nBut oftentimes, of Thy benignity,\nFreely, or ever men Thy help beseech,\nThou goest before and art their spirits' leech.\nNow help, Thou meek and blessed, Thou fair Maid,\nMe, banished wretch, in wilderness of gall;\nThink how the Canaanitish woman said\nThat even dogs may eat of the crumbs all\nWhich from the master's laden table fall;\nAnd though I, now, unworthy son of Eve,\nAm sinful, yet accept me, who believe.\nAnd since all faith is dead divorced from works,\nThat I may do the right, O give me space\nTo free me from that darkness of deep murks!\nO Thou, Who art so fair and full of grace,\nBe Thou my advocate in that high place\nWhere without ever end is sung Hosanna,\nThou, Mother of Christ and daughter of Saint Anna!\nAnd of Thy light my soul illuminate,\nThat troubled is by the contagion sown\nHere in my body, also by the weight\nOf earthly lust and false loves I have known;\nO haven of refuge, O salvation shown\nTo those that are in sorrow and distress,\nNow help, for to my work I'll me address.\nYet pray I all who read what I do write,\nForgive me that I do no diligence\nBy subtle change to make the story right;\nFor I have taken both the words and sense\nFrom him who wrote the tale in reverence\nOf this one saint; I follow her legend\nAnd pray you that you will my work amend.\nInterpretacio Nominis Caecilie\nQuam Ponit Frater Iacobus\nIanuensis in Legenda Aurea.\nFirst would I you the name of Saint Cecilia\nExpound, as men may in her story see.\nIt is to say, in English, Heaven's lily,\nSymbol of pure and virgin chastity;\nOr, since she had the white of modesty,\nAnd green of good conscience, and of good fame\nThe savour sweet, so lily was her name.\nOr else Cecilia means path for the blind,\nFor she example was, by good teaching;\nOr else Cecilia, as I written find,\nIs made, after a manner of joining,\nOf Heaven and Lia; and, in figuring,\nThe Heaven is put for thought of holiness\nAnd Lia for enduring busyness.\nCecilia may mean, too, in this wise,\nLacking in blindness, for her shining light\nOf sapience, and for good qualities;\nOr else, behold! this maiden's name so bright\nFrom Heaven and leos comes, for which, by right,\nMen well might her the Heaven of people call,\nExample of good and wise works unto all.\nLeos is folk in English, so to say,\nAnd just as men may in the heavens see\nThe sun and moon and stars strewn every way,\nJust so men ghostly, in this maiden free,\nSee of her faith the magnanimity,\nAnd the whole glory of her sapience,\nAnd many actions, bright of excellence.\nAnd just as these philosophers do write\nThat heaven is round and moving and burning,\nJust so was fair Cecilia the white\nEager and busy ever in good working,\nLarge and whole-hearted, steadfast in each thing,\nAnd shining ever in charity full bright;\nNow have I told you of her name aright.\n\n\n### The Second Nun's Tale\n\nThis maiden bright, Cecilia, her life saith,\nWas Roman born and of a noble kind,\nAnd from the cradle tutored in the faith\nOf Christ, and bore His gospel in her mind;\nShe never ceased, as written do I find,\nTo pray to God, and love Him, and to dread,\nBeseeching Him to keep her maidenhead.\nAnd when this maiden must unto a man\nBe wedded, who was a young man in age,\nAnd who had to his name Valerian,\nAnd when the day was come for her marriage,\nShe, meek of heart, devout, and ever sage,\nUnder her robe of gold, well-made and fair,\nHad next her body placed a shirt of hair.\nAnd while the organ made its melody,\nTo God alone within her heart sang she:\nO Lord, my soul and body guide to The\nUnsoiled, lest I in spirit ruined be.\nAnd for His love Who died upon a tree,\nEach second or third day she used to fast,\nAnd ever prayed she till the day was past.\nThe night came, and to bed she must be gone\nWith her young husband, but she had no fear,\nAnd privately to him she said anon:\nO sweet and well-beloved spouse so dear,\nThere is a secret, if you will to hear,\nWhich I am fain enough to you to say,\nSo that you swear that me you'll not betray.\nValerian to her his oath did swear\nThat evermore, whatever thing might be,\nHe never would betray what she said there\nAnd so beginning straightway thus said she:\nI have an angel lover that loves me,\nAnd with a great love, whether I wake or sleep,\nHe will my body ever guard and keep.\nAnd if he feels (and this is truth, she said)\nThat you will touch or love me vulgarly,\nAt once he'll slay and leave you with the dead,\nAnd in your days of youth thus shall you die;\nAnd if you love me cleanly, so say I,\nHe'll love you as now me, for your cleanness,\nAnd show you all his joy and his brightness.\nValerian, checked thus as God would mould,\nReplied: If I'm to trust you, let me see\nThat angel with my eyes and him behold;\nAnd if that it a very angel be,\nThen will I do as you have asked of me;\nAnd if you love another man, forsooth\nRight with this sword then will I slay you both.\nCecilia replied right in this wise:\nIf you so wish, that angel shall you see,\nSo you believe in Christ and you baptize.\nGo forth to Via Appia, said she,\nThat from this town is distant but miles three,\nAnd to the poor folk who in that place dwell\nSay to them what I'll now proceed to tell.\nTell them that I, Cecilia, have sent\nYou to the good man Urban, who is old,\nFor secret need, and with a good intent.\nAnd when this holy Urban you behold,\nTell him the thing that I to you have told;\nAnd when he shall have purged you of your sin,\nThat angel shall you see ere thence you win.\nValerian to that place got him gone,\nAnd just as he'd been told about the thing,\nHe found this ancient saint, Urban, anon,\nAmong the holy catacombs lurking.\nAnd he anon, with never tarrying,\nTold him his errand; and when it was told,\nUrban for joy his two hands did uphold.\nSome teardrops from his two eyes he let fall-\nAlmighty Lord, O Jesus Christ, said he,\nSower of counsel chaste, herd of us all,\nThe fruit of that same seed of chastity\nWhich Thou sowed'st in Cecilia, take to Thee!\nLo, like a busy bee, and without guile,\nThy thrall Cecilia serves Thee all the while!\nFor that same spouse that lately wedded she,\nWho was like lion fierce, she sends him here,\nAs meek as ever was a lamb, to Thee!\nAnd with that word anon there did appear\nAn old, old man, clothed all in white clothes clear,\nWho had a golden-lettered book in hand,\nAnd who before Valerian did stand.\nValerian for fear fell down as dead\nWhen him he saw, who raised him from the floor,\nAnd from his book (whereof I told) he read-\nOne Lord, one faith, one God with never more,\nOne Christian Church, One Father of all to adore,\nAbove all, over all, and everywhere-\nThese words in very gold were written there.\nWhen this was read, then said the ancient man:\nDo you believe or not? Say 'Yea' or 'Nay.'\nI do believe this, said Valerian,\nFor truer thing than this, I dare well say,\nUnder the heavens none can think, nor may.\nThen vanished the old man, he knew not where,\nAnd Pope Urban baptized him even there.\nValerian, going home, Cecilia found\nIn chamber, wherein did an angel stand;\nThis angel had two coronals, woven round\nOf roses and of lilies, in his hand;\nAnd to Cecilia, as I understand,\nHe gave the one, and gave the other straight\nUnto this said Valerian, her mate.\nWith body clean and with unsullied thought\nKeep well these crowns for ever, then said he;\nTo you from Paradise have I them brought,\nNor ever shall they fade or withered be,\nNor lose their perfume sweet, so you trust me;\nAnd never man shall see them with his eye,\nSave he be chaste and hate depravity.\nAnd you, Valerian, since you so soon\nConsented to accept the Faith also,\nSay what you will and you shall have your boon.\nI have a brother, said Valerian, Oh,\nAnd in the wide world I love no man so.\nI pray you that my brother may have grace\nTo know the truth, as I do in this place.\nThe angel answered: God likes your request,\nAnd both of you, with palm of martyrdom,\nShall come at last unto His blessed rest.\nWhereon his brother Tibertius was come.\nAnd when he smelled the sweet perfume that from\nThe roses and the lilies filled the air,\nIn heart he wondered much how came it there,\nAnd said: I wonder much, this time of year,\nWhence comes the sweetness that arises so,\nOf rose and lily, to my senses here?\nFor though I held them in my two hands- no\nThe savour could in me no deeper go.\nThe gentle scent that in my heart I find\nHas changed me to a man of other kind.\nValerian replied: Two crowns have we,\nSnow white and rose red, and they're bright and fair,\nThe which your two eyes have no power to see;\nAnd as you smell them, brother, through my prayer,\nSo shall you see them also, brother dear,\nIf you but will, without delay forsooth,\nRightly believe and know the very truth.\nTibertius answered: Say you this to me\nIn truth? Or do I dream I hear all this?\nIn dreams, replied Valerian, then, have we\nLived to this time, O brother mine, ywis.\nIn truth now for the first time our life is.\n\nHow know you? asked Tibertius: In what wise?\nValerian said: You will I now apprise.\nGod's angel unto me the truth has taught,\nWhich you shall see, if only you'll put by\nAll idols and be clean, else you'll learn naught.\n(And of these crowns miraculous, say I,\nSaint Ambrose of the two does testify\nIn his Preface; this noble doctor dear\nCommends the story, making it all clear:\nThe palm of martyrdom, thus to receive,\nThis Saint Cecilia, filled with God's gift,\nThe world and even her chamber did she leave;\nWitness Tibertius' and Valerian's shrift,\nTo whom the good God sent by angel swift\nTwo crowns of flowers fair and sweet smelling,\nAnd bade the angel take them as fitting.\nThe maiden brought these men to bliss above;\nThe world has learned what it is worth, 'tis plain,\nDevotion to fair chastity to love.)\nThen did Cecilia show him and explain\nThat every idol is a thing all vain;\nFor they are dumb, and they are deaf also,\nAnd charged him that his idols he forgo.\nWhoso believes not this, a beast he is,\nSaid then Tibertius, if I shall not lie.\nAnd then she kissed his breast, when she heard this,\nAnd was full glad that truth he could espy.\nThis day I take you for my own ally,\nSo said this blessed, lovely maiden dear;\nAnd after that said on as you shall hear:\nLo, even as the love of Christ, said she,\nMade me your brother's wife, just in that wise\nI take you now my close ally to be,\nSince you'll forgo your idols and despise.\nGo with your brother, let them you baptize\nAnd make you clean; so that you may behold\nThe angel's face whereof your brother told.\nTibertius answered, saying: Brother dear,\nFirst tell me where to go and to what man.\nTo whom? said he, Come forth, and with good cheer,\nFor I will lead you unto Pope Urban.\nTo Urban? Brother mine, Valerian,\nTibertius said, and thither will you lead?\nI think this were a wondrous thing indeed.\nSurely you mean not Urban! he cried out,\nWho's been so often ordered to be dead,\nAnd lives in corners, dodging ever about,\nAnd dares not once by day to show his head?\nWhy, men would burn him in a fire right red\nIf he were found, or any him could spy;\nAnd us, if we should bear him company.\nAnd while we seek for that Divinity\nWho is in Heaven where we may not see,\nBurned in this world to ashes shall we be!\nTo whom Cecilia answered, and boldly:\nMen might well dread, and very reasonably,\nThis life on earth to lose, my own dear brother,\nIf this alone were living, and no other.\nBut there's a better life in other place,\nThat never shall be lost, nay, fear you naught,\nWhereof God's Son has told us, through His grace;\nThat Father's Son all things that He has wrought,\nAnd all that is has made with reasoned thought,\nThe Spirit which from Father did proceed\nHas given a soul to each, fear not indeed.\nBy word and miracle God's only Son,\nWhen He was in this world, declared us here\nThere was another life that could be won.\nTo whom replied Tibertius: Sister dear,\nDid you not say, just now, in manner clear,\nThere's but one God, the Lord in truth, no less;\nAnd now to three, how can you bear witness?\nThat will I tell, said she, before I go.\nJust as a man has kinds of wisdom three,\nMemory, genius, intellect also,\nSo in one Being of Divinity\nthree Persons, truly may there right well be.\nThen she to him full earnestly did preach\nOf Jesus' coming, and of His pain did teach,\nAnd many points His agony had shown:\nHow God's Son in this world a time did hold\nTo man a full remission to make known,\nWho had been bound in sin and care of old:\nAll these things to Tibertius first she told.\nAnd then Tibertius, with a good intent,\nHe with Valerian to Pope Urban went,\nWho thanked God; and with a glad heart and light\nHe christened him, and made him in that place\nPerfect in knowledge, and God's very knight.\nAnd after this Tibertius got such grace\nThat every day he saw, in time and space,\nGod's angel; aye, and every kind of boon\nHe asked of God, the same was granted soon.\n'Twere hard in proper order to explain\nHow many wonders Jesus for them wrought;\nBut at the last, to tell it short and plain,\nThey by the sergeants of Rome town were sought,\nAnd to Almachius the prefect brought,\nWho questioned them and learned their whole intent,\nAnd unto Jupiter's image had them sent,\nSaying: Who will not go and sacrifice,\nStrike off his head, that is my sentence here.\nThese martyrs, then, of whom I do apprise,\nOne Maximus, who was an officer\nOf the prefect's, and his corniculer,\nTook them; and when the saints forth he had led,\nHimself he wept, for pity that he had.\nWhen Maximus had learned their creed and lore,\nOf executioners obtained he leave,\nAnd to his house he led them, without more;\nAnd by their preaching, ere it came to eve,\nThey from the executioners did reave,\nAnd Maximus and from his folk, each one,\nThe false faith, to believe in God alone.\nCecilia came, when it was fully night,\nWith priests, who christened them together there;\nAnd afterward, when day came with its light,\nCecilia them bade, with steadfast cheer:\nNow Christ's own knights together, lief and dear,\nThe works of darkness cast you all away,\nAnd arm you in the armour of the day.\nYou have indeed fought the good fight- all hail!\nYour course is done, your faith you have preserved,\nGo to the crown of life that shall not fail;\nThe Righteous judge, Whom you have so well served,\nWill give it to you, since you've it deserved.\nAnd when, as I have told this thing was said,\nTo make the sacrifice they forth were led.\nBut when before the image they were brought,\nBriefly to tell the end as it is known,\nThey'd not incense, and sacrificed they naught,\nBut on their knees they reverently knelt down,\nWith humble heart and firm devotion shown,\nAnd so they lost their heads there in that place.\nTheir spirits went unto the King of Grace.\nThis Maximus, who saw this thing betide,\nWith pitying tears he told folk then, forthright.\nThat he their souls had seen to Heaven glide\nWith angels full of glory and of light,\nAnd by his words converted many a wight;\nFor which Almachius had him beaten so,\nWith whips of lead, he did his life forgo.\nCecilia him buried with the others,\nValerian and Tibertius, quietly.\nThus in the tomb he rested with the brothers;\nAnd after this Almachius speedily\nOrdered his servants fetch him openly\nCecilia, that she might in his presence\nMake sacrifice to Jove and burn incense.\nBut since they were converted by her lore,\nThey wept, and to a full belief they came\nIn what she said, and cried out more and more,\nO Christ, God's Son, Whose substance is the same,\nThou'rt very God, and blessed be Thy name,\nWho hast so good a servant Thee to serve;\nThis with one voice we say, nor will we swerve.\nAlmachius, who heard of this same thing,\nCommanded that they bring her him to see,\nAnd when she came, this was his questioning:\nWhat manner of woman are you? then asked he.\nI am a noblewoman born, said she.\nI ask, said he, though to your harm and grief,\nOf your religion and of your belief.\nYou have begun your questions foolishly,\nSaid she, who would two answers so include\nIn one demand; you asked me ignorantly.\nAlmachius answered that exactitude:\nWhence comes your answering so rough and rude?\nWhence? asked she, when that she was thus constrained,\nFrom conscience and from simple faith unfeigned.\nAlmachius said: And do you take no heed\nOf power I wield? And she replied like this:\nYour might, said she, is scarce a thing to dread;\nFor power of every mortal man but is\nLike to a bladder full of wind, ywis.\nFor with a needle's point, when it is blown,\nPrick it, and all the pride of it comes down.\nErroneously have you begun, said he,\nAnd deep in error do you still remain;\nKnow you not how our mighty princes free\nHave ordered us such error to restrain,\nThat every Christian man shall suffer pain,\nUnless his Christianity he deny?\nHe shall be free if he'll do that, say I.\nYour princes err, and your nobility,\nCecilia said, and with a mad sentence\nCondemn our guilt all guiltless though we be;\nAnd you, who know full well our innocence,\nMerely because we do our. reverence\nTo Christ and bear ourselves the Christian name,\nYou thus impute to us a crime and blame.\nBut we, who know far better than can you\nIts virtue, will not once the name gainsay.\nAlmachius said: Choose one of these things two:\nDeny that faith, or sacrifice today,\nThat you may now escape from death that way.\nWhereat the holy, blessed, lovely maid\nBegan to laugh, and to the judge she said:\nO judge, convicted by your own folly,\nWill you that I deny my innocence\nAnd make myself a criminal? asked she.\nLo, he dissimulates in audience,\nHe glares and rages in his violence!\nTo whom Almachius: O unhappy wretch,\nDo you not know how far my might may stretch?\nDid not our mighty princes to me give,\nAye, both the power and authority\nTo give to people death or make them live?\nWhy do you speak so proudly then to me?\nI speak to you but steadfastly, said she,\nNot proudly, for I say, upon my side,\nWe've deadly hatred for the vice of pride.\nAnd if to hear a truth you do not fear,\nThen will I show, all openly, by right,\nThat you have said a full great falsehood here.\nYou say, your princes have you given the might\nBoth to condemn and give life to a wight;\nBut you can merely him of life bereave,\nYou have no other power or other leave!\nYou may but say, your princes did declare\nYou were death's officer; if more you claim,\nYou lie, for of more power you are bare.\nThis bold speech drop! Almachius did exclaim,\nAnd do your sacrifice in our gods' name.\nI care not what you wrongfully impute;\nLike a philosopher I'll bear it, mute;\nBut those same wrongs which I cannot endure\nAre those you speak against our gods, said he.\nCecilia replied: O vain creature,\nYou've nothing said, since speaking first to me,\nThat I've not learned thereby your great folly,\nAnd that you were and are, in every wise,\nAn ignorant officer and vain justice.\nThere is no proving, by your outward eye,\nThat you're not blind; what can be seen by all,\nThat it is stone- that men see well, say I-\nYet that same stone a god you think and call.\nI charge you, let your hand upon it fall,\nAnd test it well, and 'twill be stone, you'll find,\nSince you can see it not with your eyes blind.\nIt is a shame that all the people shall\nSo scorn you, judge, and laugh at your folly;\nFor commonly men know it above all\nThat mighty God is in His heaven high,\nAnd idols such as these, they testify,\nMay bring no profit to themselves or you-\nThey have no power, nothing can they do.\nThese words and many other such said she,\nAnd he grew wroth and bade she should be led\nHome to her house. And in her house, said he,\nBoil her in bath heated by great flames red.\nAnd as he bade, so was it done, 'tis said;\nFor in a bath they locked her and began\n(All night and day) a great fire there to fan.\nThe long night through, and a long day also,\nFor all the fire and all the bath's great heat,\nShe sat there cool and calm and felt no woe,\nNor did it make her any drop to sweat.\nBut in that bath her life should she lose yet;\nFor he, Almachius, with bad intent,\nTo slay her in the bath his headsman sent.\nThe executioner three times her smote\nUpon the neck, and could not strike again,\nAlthough he failed to cut in two her throat,\nFor at that time the ordinance was plain\nThat no man might another give the pain\nOf striking four blows, whether soft or sore;\nThis executioner dared do no more.\nBut half dead, with her neck cut three times there,\nHe let her lie, and on his way he went.\nThe Christian folk that all about her were,\nWith sheets caught up the precious blood she spent;\nAnd three days lived she in this same torment,\nBut never ceased at all the faith to teach,\nThat she had fostered; dying did she preach;\nTo them she gave her goods and everything,\nAnd of Pope Urban put them in the care,\nAnd said: This much I asked of Heaven's King,\nA respite of three days, that you might share\nWith me these souls; and too I would prepare\nBefore I go my house a church to make,\nThat it be kept forever for my sake.\nSaint Urban, with his deacons, privately,\nThe body took and buried it by night\nAmong his other saints, right honourably.\nHer house is Church of Saint Cecilia hight;\nSaint Urban hallowed it, as well he might;\nWherein in noble wise unto this day\nTo Christ and to His saint men service pay.\n\n"},{"index":11,"markdown":"### The Canon's Yeoman's Prologue\n\nWhen Saint Cecilia's Life was done, and whiles\nWe had not farther gone a good five miles,\nAt Boughton-under-Blean us did o'ertake\nA man, who was clothed all in clothes of black,\nAnd underneath he had a surplice white.\nHis hackney was of dappled-grey, so bright\nWith sweat that it was marvelous to see;\nIt seemed that he had spurred him for miles three.\nThe horse too that his yeoman rode upon\nSo sweat that scarcely could it go; and on\nThe breast strap of the harness foam stood high,\nWhereof he was as flecked as is a pie.\nA double wallet on his crupper lay,\nAnd as it seemed, he went in light array.\nLightly, for summer, rode this worthy man,\nAnd in my heart to wonder I began\nWhat he could be, until I understood\nThe way he had his cloak sewed to his hood;\nFrom which, when long I had communed with me,\nI judged at length some canon he must be.\nHis hat hung on his back down by a lace,\nFor he had ridden more than trot or pace;\nHe had spurred hard, indeed, as madman would.\nA burdock leaf he had beneath his hood\nTo curb the sweat and keep his head from heat\nBut what a joy it was to see him sweat!\nHis forehead dripped as a distillatory\nWere full of plantain and of pellitory.\nAnd this man when he came began to cry:\nGod save, said he, this jolly company!\nFast I have spurred, said he then, for your sake,\nBecause I wanted you to overtake,\nTo ride on in this merry company.\nHis yeoman too was full of courtesy,\nAnd said: Good sirs, all in the morningtide\nOut of your hostelry I saw you ride,\nAnd warned my lord and master, full and plain,\nAnd he to ride with you is truly fain\nFor his amusement; he loves dalliance.\nFriend, for your warning, God give you good chance,\nSaid then our host, for truly it would seem\nYour lord is wise, and so I may well deem;\nHe is right jocund also, I dare lay.\nCan he a merry tale tell, on the way,\nWherewith to gladden this our company?\nWho, sir? My lord? Yea, yea, without a lie,\nHe knows of mirth and of all jollity\nNot but enough; and also, sir, trust me,\nIf you but knew him as well as do I,\nYou'd wonder much how well and craftily\nHe can behave, and that in different wise.\nHe's taken on him many an enterprise\nThat were right hard for anyone that's here\n(Unless he learned it) to effect, I fear.\nAs plainly as he rides, here among you,\nIt would be to your profit if you knew\nHim well; you'd not give up his acquaintance\nFor much of wealth, I dare lay in balance\nAll that I have of goods in my possession.\nHe is a man of wondrous high discretion,\nI warn you well, he's a surpassing man.\nWell, said our host, then pray tell, if you can,\nIs he a clerk, or not? Tell what he is.\nNay, he is greater than a clerk, ywis,\nThis yeoman said, and briefly, if you'll wait,\nHost, of his craft a little I'll relate.\nI say, my lord has so much subtlety\n(But all his art you cannot learn from me,\nAnd yet I help by working at his side),\nThat all this pleasant land through which we ride,\nFrom here right into Canterbury town,\nWhy, he could turn it all clean upside-down\nAnd pave it all with silver and with gold.\nAnd when this yeoman had this story told\nUnto our host, our host said: Ben' cite!\nThis thing is wondrous marvelous to me,\nSince your lord is a man of such science,\nFor which men should hold him in reverence,\nThat of his dignity his care's so slight;\nHis over-garment is not worth a mite\nFor such a man as he, so may I go!\nIt is all dirty and it's torn also.\nWhy is your lord so slovenly, pray I,\nAnd yet has power better clothes to buy,\nIf but his deeds accord well with your speech?\nTell me that, sir, and that I do beseech.\nWhy? asked this yeoman, Why ask this of me?\nGod help me, wealthy he will never be!\n(But I will, not stand back of what I say,\nAnd therefore keep it secret, I you pray).\nHe is too wise, in faith, as I believe;\nThat which is overdone, as I conceive,\nWon't turn out right, clerks say, and that's a vice.\nIn that, I hold him ignorantly nice.\nFor when a man has overmuch of wit,\nIt often happens he misuses it;\nSo does my lord, and this thing grieves me sore.\nMay God amend it, I can say no more.\nNo matter then, good yeoman, said our host;\nSince of the learning of your lord you boast,\nTell how he works, I pray you heartily,\nSince he's so clever and withal so sly.\nWhere do you dwell, if you may tell it me?\nWithin the suburbs of a town, said he,\nLurking in corners and in alleys blind,\nWherein these thieves and robbers, every kind,\nHave all their privy fearful residence,\nAs those who dare not show men their presence;\nSo do we live, if I'm to tell the truth.\nNow, said our host, Let me go on, forsooth.\nWhy are you so discoloured in the face?\nPeter! cried he. God give it evil grace!\nI am so wont upon the fire to blow\nThat it has changed my colour, as I trow.\nI'm not wont in a mirror, sir, to pry,\nBut I work hard to learn to multiply.\nWe stir and mix and stare into the fire,\nBut for all that we fail of our desire,\nAnd never do we come to our conclusion.\nTo many folk we bring about illusion,\nAnd borrow gold, perhaps a pound or two,\nOr ten, or twelve, or any sum will do,\nAnd make them think, aye, at the least, it's plain,\nThat from a pound of gold we can make twain!\nIt is all false, but yet we have great hope\nThat we can do it, and after it we grope.\nBut that science is so far us before,\nWe never can, in spite of all we swore,\nCome up with it, it slides away so fast;\nAnd it will make us beggars at the last.\nThe while this yeoman chattered on like this,\nThe canon nearer drew and did not miss\nA thing he said; suspicion always woke\nIn him, indeed, when anybody spoke.\nFor Cato says suspicion's ever fed\nIn any guilty man when aught is said.\nThat was the reason why he drew so near\nTo his yeoman, his gossiping to hear.\nAnd thus he said unto his yeoman then:\nNow hold your peace and do not speak again,\nFor if you do you'll pay it ruefully;\nYou slander me, here in this company,\nAnd you uncover that which you should hide.\nYea? said our host, Tell on, whate'er betide;\nFor all his threatening do not care a mite!\nIn faith, said he, my caring is but slight.\nAnd when this canon saw how it would be,\nThat his yeoman would tell his privity,\nHe fled away for very grief and shame.\nAh, said the yeoman, hence shall come a game.\nAll that I know anon now will I tell.\nSince he is gone, the Fiend take him to Hell!\nWith him hereafter I'll have naught to do\nFor penny or for pound, I promise you!\nHe that first brought me into that ill game,\nBefore he die, sorrow have he and shame!\nFor it's no game to me, sirs, by my fay;\nThat I feel well, whatever men may say.\nAnd yet, for all my smart and all my grief,\nFor all the sorrow, labour, and mischief,\nI never could leave off, in any wise.\nNow would to God that my wit might suffice\nTo tell of all pertaining to that art!\nNevertheless, I will relate a part;\nSince now my lord is gone, I will not spare;\nThe things I know about I will declare.\n\n\n### The Canon's Yeoman's Tale\n\nSeven years I've served this canon, but no more\nI know about his science than before.\nAll that I had I have quite lost thereby;\nAnd, God knows, so have many more than I.\nWhere I was wont to be right fresh and gay\nOf clothing and of other good array,\nNow may I wear my old hose on my head;\nAnd where my colour was both fresh and red,\nNow it is wan and of a leaden hue;\nWhoso this science follows, he shall rue.\nAnd from my toil yet bleary is my eye,\nBehold the gain it is to multiply!\nThat slippery science has made me so bare\nThat I've no goods, wherever I may fare;\nAnd I am still indebted so thereby\nFor gold that I have borrowed, truthfully,\nThat while I live I shall repay it never.\nLet every man be warned by me for ever!\nAnd any man who casts his lot thereon,\nIf he continue, I hold his thrift gone.\nSo help me God, thereby he shall not win,\nBut empty purse and have his wits grow thin.\nAnd when he, through his madness and folly,\nHas lost his own, by willing jeopardy,\nThen will he incite others, many a one,\nTo lose their wealth as he himself has done.\nFor unto scoundrels it's a pleasant thing\nTheir fellows in distress and pain to bring,\nThus was I taught once by a learned clerk.\nOf that no matter, I'll speak of our work.\nWhen we are where we choose to exercise\nOur elvish craft, why, we seem wondrous wise,\nOur terms are all so learned and so quaint.\nI blow the fire till my heart's like to faint.\nWhy tell you what proportions of things went\nIn working out each new experiment,\nAs five ounces, or six, it may well be,\nOf silver, or some other quantity?\nOr tell you all the names, my memory fails,\nOf orpiment, burnt bones, and iron scales\nThat into powder we ground fine and small?\nOr in an earthen pot how we put all,\nAnd salt put in, and also pepper dear,\nBefore these powders that I speak of here,\nAnd covered all these with a plate of glass,\nAnd of the various other gear there was?\nAnd of the sealing of the pot and glass,\nSo that the air might no way from it pass?\nAnd of the slow fire and the forced also,\nWhich we made there, and of the care and woe\nThat we took in our matter's sublimating,\nAnd in calcining and amalgamating\nQuicksilver, which is known as mercury crude?\nFor all our skill, we never could conclude.\nOur orpiment and sublimed mercury,\nOur litharge that we ground on porphyry,\nOf each some certain ounces- it is plain\nNaught helped us, all our labour was in vain.\nNeither the gases that by nature rose\nNor solid matter either- none of those\nMight, in our working, anything avail.\nFor lost was all our labour and travail,\nAnd all the cost, the devil's own to pay,\nWas lost also, for we made no headway.\nThere is also full many another thing\nThat to our craft pertains in labouring.\nThough name them properly I never can,\nBecause, indeed, I am an ignorant man,\nYet will I tell them as they come to mind,\nThough I'll not try to class each one by kind;\nArmenian bole, borax, the green of brass,\nAnd sundry vessels made of earth and glass,\nOur urinals and all our descensories,\nVials and crucibles, sublimatories,\nCucurbites, and alembics, and such freaks,\nAll dear enough if valued at two leeks.\nThere is no need to specify them all,\nThe reddening waters and the dark bull's gall,\nArsenic, sal ammoniac, and brimstone;\nAnd, too, of herbs could I name many a one,\nValerian, agrimony, and lunary,\nAnd others such, if I but wished to tarry.\nOur lamps that burned by day and burned by night\nTo bring about our end, if but we might,\nOur furnace, too, white-hot for calcination,\nAnd waters all prepared for albication,\nUnslaked lime, chalk, and white of egg, I say,\nPowders diverse, and ashes, dung, piss, clay,\nLittle waxed bags, saltpetre, vitriol;\nAnd many a different fire of wood and coal;\nAlkali, salt, potassium carbonate,\nAnd our burnt matters, and coagulate,\nClay mixed with horses' or men's hair, and oil\nOf tartar, alum, glass, yeast, wort, argoil,\nRealgar, and our matters absorbent,\nAnd with them, too, our matters resorbent,\nAnd how we practised silver citrination\nAnd our cementing and our fermentation,\nOur moulds and testers, aye, and many more.\nI will tell you, as I was taught before,\nThe bodies seven and the spirits four,\nIn order, as my master named of yore.\nThe first of spirits, then, quicksilver is,\nThe second arsenic, the third, ywis,\nIs sal ammoniac, the fourth brimstone.\nThe seven bodies I'll describe anon:\nSol, gold is, Luna's silver, as we see,\nMars iron, and quicksilver's Mercury,\nSaturn is lead, and Jupiter is tin,\nAnd Venus copper, by my father's kin!\nThis wicked craft, whoso will exercise,\nHe shall gain never wealth that may suffice;\nFor all the coin he spends therein goes out\nAnd is but lost, of which I have no doubt.\nWhoso, then, will exhibit such folly,\nLet him come forth and learn to multiply;\nAnd every man that has aught in coffer,\nLet him appear and be philosopher.\nPerhaps that craft is easy to acquire?\nNay, nay, God knows! And be he monk or friar\nCanon, or priest, or any other wight,\nThough he sit at his books both day and night\nIn learning of this elvish, fruitless lore,\nAll is in vain, and by gad it's much more!\nTo teach an ignorant man this subtlety-\nFie! Speak not of it, for it cannot be;\nAnd though he has booklore, or though he's none,\nIn final count he shall find it all one.\nFor both of them, and this by my salvation,\nCome to one end seeking multiplication;\nThey fare the same when they've done everything;\nThat is to say, they both fail, sorrowing.\nYet I forgot to tell you in detail\nOf the corrosive waters and limaille,\nAnd of some bodies the mollification,\nAnd on the other hand of induration,\nOils, and ablutions, metals fusible-\nMore than a bible it would need to tell,\nThe largest ever; therefore I think best\nThat of these names I say no more, but rest.\nFor I believe that I've told you enough\nTo raise a devil, be he never so rough.\n\nAh no! Let be; the old philosopher's stone\nIs called elixir, which we seek, each one;\nFor had we that, then were we safe enow.\nBut unto God in Heaven do I vow,\nFor all our art, when we've done all things thus,\nAnd all our tricks, it will not come to us.\nThe thing has caused us to spend all we had,\nFor grief of which almost we should go mad,\nSave that good hope comes creeping in the heart,\nSupposing ever, though we sorely smart,\nThe elixir will relieve us afterward;\nThe tension of such hope is sharp and hard;\nI warn you well, it means go seeking ever;\nThat future time has made men to dissever,\nTrusting that hope, from all that ever they had.\nYet of that art they cannot well grow sad,\nFor unto them it is a bitter-sweet;\nSo it appears; for had they but a sheet\nWith which to wrap themselves about by night,\nAnd a coarse cloak to walk in by daylight,\nThey'd sell them both and spend it on this craft;\nThey can withhold naught till there's nothing left\nAnd evermore, wherever they'll be gone,\nMen know them by their smell of foul brimstone;\nFor all the world they stink as does a goat;\nTheir savour is so rammish and so hot\nThat, though a man a mile away may be,\nThe odour will infect him, trust to me!\nThus by their smell and their threadbare array,\nIf men but wish, these folk they'll know, I say.\nAnd if a man but ask them privately\nWhy they do go clothed so unthriftily,\nThey right away will whisper in his ear\nAnd say that if they should be noticed here,\nWhy, men would slay them, what of their science;\nLo, thus these folk impose on innocence!\nPass over this; unto my tale I'll run.\nBefore the pot upon the fire be done,\nOf metals in a certain quantity\nMy lord it tempers, and no man save he-\nNow he is gone I dare say this boldly-\nFor, as men say, he can work artfully;\nAlways I well know be has such a name,\nAnd yet full often has he been to blame;\nAnd know you how? Full oft it happens so,\nThe pot broke, and farewell! All vanished, O!\nThese metals have such violence and force\nThat crucibles cannot resist their course\nUnless they are built up of lime and stone;\nThey penetrate, and through the wall they're gone,\nAnd some of them sink right into the ground-\nThus have we lost, at times, full many a pound-\nAnd some are scattered all the floor about,\nSome leap up to the roof. Beyond a doubt,\nAlthough the Fiend's to us not visible,\nI think he's with us, aye, that same scoundrel!\nIn Hell, wherein he is the lord and sire,\nThere's not more woe, nor ****rancour, nor more ire.\nFor when our pot is broken, as I've said,\nEach man will scold and think that he's been bled.\nOne said that it was due to fire-making,\nOne said it was the blowing of the thing\n(There I was scared, for that was what I did);\nO straw! You silly fool! the third one chid,\nIt was not tempered as it ought to be.\nNay, said the fourth, shut up and list to me;\nIt was because our fire was not of beech,\nThat's why, by all the wealth I hope to reach!\nI cannot tell where one should put the blame;\nThere was a dreadful quarrel, just the same.\nWhat! cried my lord, there's no more to be done,\nWhatever 'twas, I'll know the reason soon;\nI am quite certain that the pot was crazed.\nBe as it may, do not stand there amazed;\nAs always, sweep the floor up quickly lad,\nPluck up your hearts and be both blithe and glad.\nThe rubbish in a heap then swept up was,\nAnd on the floor was spread a large canvas,\nAnd all this rubbish in a sieve was thrown,\nAnd sifted, picked, and whirled, both up and down.\nBy gad, said one, something of our metal\nThere is yet here, although we have not all.\nAlthough this thing has gone awry for now,\nAnother time it may be well enow.\nWe must put all our wealth at adventure;\nA merchant's luck, gad! will not aye endure,\nBelieve me, in his high prosperity;\nSometimes his freight will sink beneath the sea,\nAnd sometimes comes it safely unto land.\nPeace, said my lord, next time I'll understand\nHow to proceed and with a better aim;\nAnd, save I do, sirs, let me be to blame;\nThere was defect in something, well I know 't.\nAnother said the fire was far too hot.\nBut were it hot or cold, I dare say this,\nThat we concluded evermore amiss.\nWe fail of that which we desire to have,\nAnd in our madness evermore we rave.\nAnd when we're all together, then each one\nSeems as he were a very Solomon.\nBut everything that glisters like fine gold\nIs not gold, as I've often heard it told;\nAnd every apple that is fair to eye\nIs yet not sound, whatever hucksters cry;\nAnd even so, that's how it fares with us:\nFor he that seems the wisest, by Jesus,\nIs greatest fool, when proof is asked, in brief;\nAnd he that seems the truest is a thief;\nThat shall you know ere I from you do wend,\nWhen of my tale I've made at length an end.\nExplicit prima pars.\nEt sequitur pars secunda.\nThere is a canon of religion known\nAmong us, who'd contaminate a town,\nThough 'twere as great as Nineveh the free,\nRome, Alexandria, Troy, and others three.\nHis tricks and all his infinite treacherousness\nNo man could write down fully, as I guess,\nThough he should live unto his thousandth year.\nIn all this world for falsehood he's no peer;\nFor in his terms he will so twist and wind\nAnd speak in words so slippery of kind,\nWhen he communicates with any wight,\nThat he soon makes a fool of him, outright,\nUnless it be a devil, as he is.\nFull many a man has he beguiled ere this,\nAnd will, if he may live a further while;\nAnd yet men walk and ride full many a mile\nTo seek him out and have his acquaintance,\nNaught knowing of his treacherous simulance.\nAnd if you care to listen to me here,\nI'll make the proof of what I say quite clear.\nBut most religious canons, just and true,\nDon't think I'm slandering your house, or you,\nAlthough my tale may of a canon be.\nSome rogue's in every order, pardon me,\nAnd God forbid that for one rascal's sake\nAgainst a group we condemnation make.\nTo slander you is nowise my intent,\nBut to correct what is amiss I'm bent.\nThis tale I tell here not alone for you,\nBut even for others, too; you know well how\nAmong Christ's twelve disciples there was not\nOne to play traitor, save Iscariot.\nThen why should all the rest be put to blame\nWho guiltless were? Of you I say the same.\nSave only this, if you will list to me,\nIf any Judas in your convent be,\nRemove the man betimes, I counsel you,\nLest shame or loss or trouble should ensue.\nAnd be displeased in nothing, I you pray,\nBut hear what on this matter I may say.\nIn London was a priest, an annualeer\nWho had therein dwelt many a quiet year,\nA man so pleasant and so serviceable\nTo the goodwife who shared with him her table,\nThat she would never suffer him to pay\nFor board or clothing, went he ever so gay;\nOf spending-silver, too, he had enow.\nNo matter; I'll proceed as I said, now,\nAnd tell about the canon all my tale,\nWho gave this priest good cause to weep and wail.\nThis canon false, he came, upon a day\nInto the chaplain's chamber, where he lay,\nBeseeching him to lend him a certain\nAmount in gold, the which he'd pay again.\nLend me a mark, said he, for three days, say,\nAnd when that time's done, I will it repay.\nAnd if you find me false, I shall not reck\nIf, on a day, you hang me by the neck!\nThis priest brought him a mark, and quickly, too,\nWhereat this canon thanked him, said adieu,\nAnd took his leave and went forth on his way,\nAnd brought the money back on the third day,\nAnd to the priest he gave his gold again,\nWhereof this priest was wondrous glad, 'tis plain.\nTruly, he said, it no wise bothers me\nTo lend a man a noble, or two, or three,\nOr any modest thing that is my own,\nTo him who has the disposition shown\nThat in no wise will he forgo to pay;\nTo such a man I never can say nay.\nWhat! cried this canon, Should I be untrue?\nNay, that for me would be a thing quite new.\nTruth is a thing that I will ever keep\nUnto that day, at last, when I shall creep\nInto my grave, or elsewise God forbid!\nTrust this as surely as you trust your creed.\nI thank God, and in good time be it said,\nThat there was never yet man ill repaid\nFor gold or silver that to me he lent,\nNor ever falsehood in my heart I've meant.\nAnd, sir, said he, out of my privity,\nSince you have been so very good to me,\nAnd showed to me so great a nobleness,\nSomewhat to quit you for your kindliness,\nI'll show to you, and if you'd learn it here,\nI'll teach you plainly all the methods dear\nI use in working at philosophy.\nGive it good heed, for you'll see with your eye\nI'll do a masterpiece before I go.\nYes? asked the priest, Yes, sir, and will you so?\nMary! Thereof I pray you heartily.\nRight at your service, sir, and truthfully,\nReplied the canon, else, may God forbid!\nService this thief could offer, and he did!\nFull true it is that service in this guise\nStinks, as take witness of these old men wise;\nAnd soon enough I will this verify\nBy this canon, the root of treachery,\nWho always had delight, nor could refrain-\nSuch devilish thoughts within his heart did reign-\nWhen he brought Christian folk to tribulation.\nGod keep us from his false dissimulation!\nNaught understood this priest with whom he dealt,\nAnd of his coming harm he nothing felt.\nO hapless priest! O hapless innocent!\nBlinded by avarice malevolent!\nO luckless one, full blind is your conceit,\nNothing are you aware of the deceit\nWhich this sly fox arranges here to be!\nHis wily stratagems you cannot flee.\nWherefore, at once to make the ending known,\nBy which your troubles will be clearly shown,\nUnhappy man, I'll hasten on to tell\nThe folly into which you blindly fell,\nAnd, too, the treachery of that other wretch,\nAs far as what I know of him may stretch.\nThis canon was my lord, you think I mean?\nSir host, in faith, and by the Heaven's Queen,\nIt was another canon, and not he,\nWho has a hundred-fold more subtlety!\nHe has betrayed the people many a time;\nOf his deceit it wearies me to rhyme.\nWhatever of his falsehood I have said,\nFor shame of him I feel my cheeks grow red;\nAt any rate, my cheeks begin to glow,\nFor redness have I none, right well I know,\nIn all my visage; for the fumes diverse\nOf metals, whereof you've heard me rehearse,\nHave all consumed and wasted my redness.\nNow take heed of this canon's wickedness.\nSir, this to the priest, let your man be gone\nFor quicksilver, that we have some anon;\nAnd let him bring us ounces two or three;\nAnd when he comes, just so soon shall you see\nA wondrous thing you've never seen ere this.\nSir, said the priest, it shall be done, ywis.\nHe bade his servant go to fetch them all,\nAnd since the lad was ready at his call,\nHe got him forth and came anon again\nWith this quicksilver, truly to explain,\nAnd gave these ounces three to the canon;\nAnd he took them and laid them fairly down,\nAnd bade the servant coals to go and bring,\nThat he might get to work with everything.\nThe coals at once were brought, and all was well;\nAnd then this canon took a crucible\nOut of his bosom, showing it to the priest.\nThis instrument, said he, you see- at least\nTake in your hand, and put yourself therein\nAn ounce of quicksilver, and here begin,\nAnd in God's name, to be philosopher!\nThere are but few to whom I would proffer\nTo make my science clear and evident.\nFor you shall learn here, by experiment,\nThat this quicksilver will I mortify\nRight in your sight anon, without a lie,\nAnd make it as good silver and as fine\nAs any that's in your purse or in mine,\nOr elsewhere, aye, and make it malleable;\nOtherwise hold me false, unfit as well\nAmong good folk for ever to appear.\nI have a powder here that cost me dear,\nShall do all this, for it's the root of all\nMy craft; you'll see what shall therewith befall.\nDismiss your man and let him stay without,\nAnd shut the door fast while we are about\nOur secret work, that no man may espy\nThe way we work in this philosophy.\nAll was then done as canon had decreed;\nThis servant took himself straight out, indeed,\nWhereat his master barred the door anon,\nAnd to their labour quickly they were gone.\nThe priest, at this damned canon's ordering,\nUpon the fire anon did set this thing,\nAnd blew the fire and busied him full fast;\nWithin the crucible the canon cast\nA powder (I know not whereof it was\nCompounded, whether of chalk, or maybe glass,\nOr something else- it was not worth a fly)\nTo blind the priest with; and he bade him high\nThe coals to pile the crucible above.\nIn token of how much I bear you love,\nThis canon said, your own two hands, and none\nOther, shall do this thing that shall be done.\nThank you, the priest replied, and was right glad,\nAnd heaped the coals up as the canon bade.\nAnd while he laboured thus, this fiendish wretch,\nThis canon false- may him the foul Fiend fetch!-\nOut of his bosom took a beechen coal,\nWherein right cunningly he'd bored a hole\nIn which, before, he'd put of silver limail\nAn ounce, and which he'd stopped up, without fail,\nWith blackened wax, to keep the filings in.\nAnd understand you well that this false gin\nWas not made there, but it was made before;\nAnd there were other things I'll tell you more\nAbout hereafter, which with him he'd brought;\nEre he came there, to cheat he'd taken thought,\nAnd ere they parted he did even so;\nTill he had skinned him he could not forgo.\nIt wearies me when of him I do speak,\nFor on his falsehood I myself would wreak,\nIf I knew how; but he is here and there;\nHe is so restless he abides nowhere.\n\nBut take heed now, sirs, for God's very love!\nHe took this coal whereof I spoke above,\nAnd in his hand he bore it privily.\nAnd while the priest did pile up busily\nThe burning coals, as I told you ere this,\nThis canon said: My friend, you do amiss;\nThis is not piled up as it ought to be;\nBut soon I shall amend all that, said he.\nNow let me thereof have a hand the whiles,\nFor I've great pity on you, by Saint Giles!\nYou are right hot, I see well how you sweat,\nTake here a cloth and wipe away the wet.\nAnd while the simple priest did wipe his face,\nThis canon took his coal, and with grave grace,\nLaid it above and well to middleward\nUpon the crucible, and blew it hard\nUntil the flames did blaze, up hot again.\nNow give us drink, sir, said the canon then,\nFor soon all shall be well, I undertake;\nLet us sit down, and let us merry make.\nAnd when this treacherous canon's beechen coal\nWas burnt, then all the filings from the hole\nInto the crucible fell down anon;\nAs so, in reason, it must needs have done,\nSince so well centred over it was;\nBut thereof nothing knew the priest, alas!\nHe deemed that all the coals alike were good,\nFor of the trick he nothing understood.\nAnd when this alchemist was ready, he\nSaid to the priest: Rise up and stand by me;\nAnd since I know that metal mould you've none,\nGo sally forth and bring here a chalk-stone;\nFor I will make one of the very shape\nThat ingot moulds have, if I can them ape.\nAnd, too, bring in with you a bowl or pan\nFull of clear water, and you'll see, dear man,\nHow well our business here shall thrive, in brief.\nAnd yet, that you may have no unbelief,\nOr think that somehow I'm not doing right,\nI'll never be a moment out of sight,\nBut go with you and come with you again.\nThe chamber door, then, briefly to explain,\nThey opened and they shut, and went their way.\nAnd as they went they took the key, I say,\nAnd came again, without a long delay,\nWhy should I tarry here the livelong day?\nHe took the chalk and shaped it in such wise\nAs moulds are made, as further I'll apprise.\nI say, he took, then, out of his own sleeve\nA tain of silver (Hell the man receive!)\nWhich was an ounce, no more or less, in weight;\nNow here's the trick, the way of which I'll state!\nHe shaped his mould in length and breadth to be\nLike to the tain of silver, as you see,\nSo slyly that the priest this never spied;\nAnd in his sleeve did then the model hide;\nAnd from the fire he took his crucible\nAnd poured it in the mould, for all went well,\nAnd in the bowl of water then did cast\nThe mould and all, and bade the priest, at last:\nSeek what there is, put in your hand and grope,\nAnd you shall find there silver, as I hope;\nWhat- devils out of Hell!- should it else be?\nFiling of silver silver is! cried he.\nHe put his hand in and a tain took out\nOf silver fine, and glad, you cannot doubt,\nWas this priest when he saw that it was so.\nGod's blessing, and His Mother's dear also,\nAnd all the saints', too, may you have, my friend,\nThe priest replied, and may they curse my end\nUnless you will vouchsafe to teach to me\nThis noble craft and all this subtlety;\nI will be yours in all that ever I may!\nSaid then the canon: Yet will I essay\nA second time, that you may take good heed\nAnd be expert in this, and at your need\nWhen I am absent on another day,\nYou may this science and its arts essay.\nQuicksilver take, said he, one ounce, no more,\nAs you'll remember that we did before,\nAnd as you treated that, so do with this\nAnd like the first 'twill change, which silver is.\nThe priest then followed carefully the plan,\nAs he'd been bidden by this cursed man,\nThe canon; long and hard he blew the fire\nTo bring about the thing he did desire.\nAnd this said canon waited all the while,\nAll ready there the poor priest to beguile,\nAnd, for assurance in his hand did bear\nA hollow stick (take heed, sirs, and beware!),\nIn end of which an ounce was, and no more,\nOf silver filings put, all as before\nWithin the coal, and stopped with wax, a bit,\nTo keep the filings in the hole of it.\nAnd while the priest was busy, as I say,\nThis canon, drawing close, got in his way,\nAnd unobserved he threw the powder in\nJust as before (the Devil from his skin\nStrip him, I pray to God, for lies he wrought;\nFor he was ever false in deed and thought);\nAnd with his stick, above the crucible,\nArranged for knavish trickery so well,\nHe stirred the coals until to melt began\nThe thin wax in the fire, as every man,\nExcept a fool, knows well it must, sans doubt,\nAnd all that was within the stick slipped out,\nAnd quickly in the crucible it fell.\nGood sirs, what better do you wish than well?\nWhen now the priest was thus beguiled again,\nSupposing naught but truth, I should explain,\nHe was so glad that I cannot express,\nIn any way, his mirth and his gladness;\nAnd to the canon he did proffer soon\nBody and goods. Yea, was the canon's tune,\nThough I am poor, I'm artful as you'll find;\nI warn you plainly, there's yet more behind.\nIs there some copper in your place? asked he.\nYea, said the priest, I think there may well be.\nIf not, go buy us some, and quickly too,\nGood sir, make haste and fetch us it, pray do.\nHe went his way, and with the copper came,\nAnd in his hands this canon took the same,\nAnd of the copper weighed out but an ounce.\nMy tongue is far too simple to pronounce,\nAs servant to my wit, the doubleness\nWithin this canon, root of wickedness.\nFriendly he seemed to those that knew him not\nBut he was fiendly both in heart and thought.\nIt wearies me to tell of his falseness,\nNevertheless yet will I it express\nTo end that all men may be warned thereby,\nAnd for no other reason, truthfully.\nWithin the crucible he puts the ounce\nOf copper which upon the fire he mounts,\nAnd casts in powder, making the priest blow,\nAnd at his labouring to stoop down low,\nAll as before, and all was but a jape;\nJust as he pleased, he made the priest his ape.\nAnd afterward into the mould he cast\nThe copper; into the water pan at last\nPlunging the whole, and thrust therein his hand.\nAnd in his sleeve (as you did understand\nBefore) he had a certain silver tain.\nHe slyly took it out, this damned villain,\nWhile still the priest saw nothing of the plan,\nAnd left it in the bottom of the pan;\nAnd in the water groped he to and fro\nAnd very stealthily took up also\nThe copper tain, of which the priest knew naught,\nAnd hiding it, he by the breast him caught,\nAnd spoke to him, thus carrying on his game:\nStoop lower down, by God, you are to blame!\nCome, help me now, as I did you whilere,\nPut in your hand and search and learn what's there.\nThis priest took up the silver tain anon,\nAnd then the canon said: Let us be gone\nWith these three plates, the which we have so wrought,\nTo some goldsmith, to learn if they're worth aught.\nFor by my faith, I wouldn't, for my hood,\nHave them, save they are silver fine and good,\nAnd that immediately proved shall be.\nUnto the goldsmith, then, with these tains three,\nThey went, and put the metal in assay\nBy fire and hammer; no man could say nay,\nBut they were silver, as the ought to be.\nThis foolish priest, who was more glad than he?\nNever was gladder bird for dawn of day,\nNor nightingale in season of the May,\nNor was there ever one more fain to sing;\nNor lady happier in carolling\nOr speaking much of love and woman's meed;\nNor knight in arms to do a hardy deed\nTo stand in graces of his lady dear-\nThan was the priest this sorry craft to hear;\nAnd to the canon thus he spoke and said:\nFor love of God, Who for us all was dead,\nAnd as I may requite it unto you,\nWhat shall this recipe cost? Come, tell me now?\nBy 'r Lady, said this canon, it is dear,\nI warn you well; for now in England here\nOne friar and I are all who can it make.\nNo matter, said he, now, sir, for God's sake,\nWhat shall I pay? Oh, tell me this, I pray!\nTruly, said he, it is right dear, I say;\nSir, in one word, if this thing you will have,\nYou shall pay forty pounds, so God me save!\nAnd were it not for friendship shown ere this\nTo me, you should pay more than that, ywis.\nThis priest the sum of forty pounds anon\nIn nobles fetched, and gave them, every one,\nTo this said canon for this said receipt;\nHis business was all fraud and all deceit.\nSir priest, he said, I do not care to lose\nMy secret craft, and I would 'twere kept close;\nSo, as you love me, keep it privily;\nFor if men knew all of my subtlety,\nBy God above, they'd have so great envy\nOf me, because of my philosophy,\nI should be slain, there'd be no other way.\nNay, God forbid! replied the priest. What say?\nFar rather would I spend all coin, by gad,\nThat I possess (and else may I grow mad!)\nThan that you fall in any such distress.\nFor your good will, I wish you all success,\nReplied the canon, farewell, many thanks.\nHe went, and ne'er the priest this mountebank's\nFace saw thereafter; and when this priest would\nMake his own test, at such time as he could,\nOf this receipt, farewell! it would not be!\nLo, thus bejaped and thus beguiled was he!\nAnd thus he had his introduction in\nThe way men fall to ruin and to sin.\nConsider, sirs, how that, in each estate,\nBetween men and their gold there is debate\nTo such degree that gold is nearly done.\nThis multiplying blinds so many a one\nThat in good faith I think that it may be\nThe greatest cause of this said scarcity.\nPhilosophers they speak so mistily\nAbout this craft, plain men can't come thereby\nWith any wit that men have nowadays.\nThey may well chatter, as do all these jays,\nAnd in vague cant set their desire and pain,\nBut to their purpose shall they ne'er attain.\nA man may easily learn, if he have aught,\nTo multiply, and bring his wealth to naught.\nLo, such a gain is in this pleasant game\nA man's mirth it will turn to grief and shame,\nAnd it will empty great and heavy purses,\nAnd causes alchemists to get the curses\nOf all of those who thereunto have lent.\nO fie! For shame! Those who the fire resent,\nAlas! can they not flee the fire's fierce heat?\nIf you have tried it, leave it, I repeat,\nLest you lose all; better than never is late.\nNever to thrive at all were a long date.\nAnd though you prowl, you never gold shall find;\nYou are as bold as Bayard is, the blind,\nThat blunders forth and thinks of danger, none;\nHe is as bold to run against a stone\nAs to go ambling down the broad highway.\nAnd so fare you who multiply, I say.\nIf your two fleshly eyes can't see aright,\nLook to it that your mind lack not for sight.\nFor, though you look about and though you stare,\nYou shall not win a mite in traffic there,\nBut you shall waste all you may scrape and turn.\nAvoid that fire, lest much too fast it burn;\nMeddle no more with that base art, I mean,\nFor if you do, you'll lose your savings clean.\nAnd now I'll tell you briefly, if I may,\nWhat the philosophers about this say.\nArnold of Villanovana I will cite.\nIn his Rosarium he brings to light\nThese facts, and says- in this I do not lie:\nNo man can mercury ever mortify,\nUnless its brother's aid to it he bring,\nAnd also he who first did say this thing\nWas father of philosophers, Hermes;\nHe said the dragon, doubtless, takes his ease\nAnd never dies, unless there's also slain\nHis brother, which, to make the matter plain,\nMeans, by the dragon, mercury, none other,\nAnd brimstone's understood to mean the brother,\nThat out of Sol and Luna we can draw.\nAnd therefore, said he, give heed to my saw,\nLet no man busy him ever with this art\nUnless philosophers to him impart\nTheir meaning clearly, for unless he can\nTheir language grasp, he's but an ignorant man.\nThis science and this learning, too, said he,\nMust ever the most secret secrets be.\nAlso there was a student of Plato\nWho on a time said to his master so,\nAs his book Senior will bear witness;\nAnd this was his demand, in truthfulness:\nTell me the name, sir, of the Secret Stone.\nAnd Plato answered in this wise anon:\nTake, now, the stone that Titanos men name.\nWhat's that? asked he. Magnesia is the same,\nPlato replied. Yea, sir, and is it thus?\nThis is ignotum per ignotius.\nWhat is magnesia, good sir, I do pray?\nIt is a water that is made, I say,\nOut of four elements,' replied Plato.\nTell me the root, good sir, said he, if so,\nWhat then, is water, tell me if you will.\nNay, nay, said Plato, and now peace, be still.\nPhilosophers are sworn, aye, every one,\nThat they will thus discover it to none,\nNor in a book will write it for men here;\nFor unto Christ it is so lief and dear\nThat He wills that it not discovered be,\nSave where it's pleasing to His deity\nMan to inspire, and also, to defend\nWhom that He will; and lo, this is the end.\nAnd thus do I conclude: Since God in Heaven\nWills that philosophers shall not say even\nHow any man may come upon that stone,\nI say, as for the best, let it alone.\nFor whoso makes of God his adversary,\nTo work out anything that is contrary\nTo what He wills, he'll surely never thrive,\nThough he should multiply while he's alive.\nAnd there's the end; for finished is my tale.\nMay God's salvation to no good man fail! Amen.\n\n\n### The Manciple's Prologue\n\nDo you not know where stands a little town\nThat's called by all about Bob-up-and-down,\nUnder the Blean, down Canterbury way?\nThere did our host begin to jape and play,\nAnd he said: Sirs, what! Dun is in the mire!\nIs there no man, then, who, for prayer or hire,\nWill wake our comrade who's so far behind?\nA thief might easily rob him and bind.\nSee how he's nodding! See, now, by Cock's bones,\nAs if he'd fall down from his horse at once.\nIs that a cook of London, with mischance?\nMake him come forward, he knows his penance,\nFor he shall tell a tale here, by my fay,\nAlthough it be not worth a bunch of hay.\nAwake, you cook, cried he, God give you sorrow!\nWhat ails you that you sleep thus? It's good morrow!\nHave you had fleas all night, or are you drunk?\nOr did you toil all night in some quean's bunk?\nSo that you cannot now hold up your head?\nThe cook, who was all pale and nothing red,\nSaid to our host: So may God my soul bless,\nAs there is on me such a drowsiness,\nI know not why, that I would rather sleep\nThan drink a gallon of best wine in Cheap.\nWell, said the manciple, if 'twill give ease\nTo you, sir cook, and in no way displease\nThe folk that ride here in this company,\nAnd if our host will, of his courtesy,\nI will, for now, excuse you from your tale.\nFor in good faith, your visage is full pale,\nYour eyes are bleary also, as I think,\nAnd I know well your breath right sour does stink,\nAll of which shows that you are far from well;\nNo flattering lies about you will I tell.\nSee how he yawns. Just look, the drunken wight,\nAs if he'd swallow all of us outright.\nNow close your mouth, man, by your father's kin;\nAh, may Hell's devil set his foot therein!\nYour cursed breath will soon infect us all;\nFie, stinking swine, fie! Evil you befall!\nAh, take you heed, sirs, of this lusty man.\nNow, sweet sir, would you like to ride at fan?\nIt seems to me you're in the proper shape!\nYou've drunk the wine that makes a man an ape,\nAnd that is when a man plays with a straw.\nThe cook grew wroth, for this had touched the raw,\nAnd at the manciple he nodded fast\nFor lack of speech, and him his horse did cast,\nAnd there he lay till up the rest him took,\nWhich was a feat of riding for a cook!\nAlas! That he had kept not to his ladle!\nFor ere he was again within his saddle,\nThere was a mighty shoving to and fro\nTo lift him up, and hugeous care and woe,\nSo all unwieldy was this sorry ghost.\nAnd to the manciple then spoke our host:\nSince drink has got such utter domination\nOver this fellow here, by my salvation,\nI think that badly he would tell his tale.\nFor whether wine or old or musty ale\nIs what he's drunk, he speaks all through his nose;\nHe snorts hard and with cold he's lachrymose.\nAlso he has more than enough to do\nTo keep him and his nag out of the slough;\nAnd if he fall down off his horse again,\nWe'll all have quite enough of labour then\nIn lifting up his heavy drunken corse.\nTell on your tale, he matters not, of course.\nYet, manciple, in faith, you are not wise\nThus openly to chide him for his vice.\nSome day he'll get revenge, you may be sure,\nAnd call you like a falcon to the lure;\nI mean he'll speak of certain little things,\nAs, say, to point out in your reckonings\nThings not quite honest, were they put to proof.\nNay, said the manciple, that were ill behoof!\nSo might he easily catch me in his snare.\nYet would I rather pay him for the mare\nWhich he rides on than have him with me strive;\nI will not rouse his rage, so may I thrive!\nThat which I said, I said as jesting word;\nAnd know you what? I have here, in a gourd,\nA draught of wine, yea, of a good ripe grape,\nAnd now anon you shall behold a jape.\nThis cook shall drink thereof, sir, if I may;\nOn pain of death he will not say me nay!\nAnd certainly, to tell it as it was,\nOut of this gourd the cook drank deep, alas!\nWhat need had he? He'd drunk enough that morn\nAnd when he had blown into this said horn,\nHe gave the manciple the gourd again;\nAnd of that drink the cook was wondrous fain,\nAnd thanked him then in such wise as he could.\nThen did our host break into laughter loud,\nAnd said: I see well it is necessary,\nWhere'er we go, good drink with us we carry;\nFor that will turn rancour and all unease\nTo accord and love, and many a wrong appease.\nO Bacchus, thou, all blessed be thy name\nWho canst so turn stern earnest into game!\nHonour and thanks be to thy deity!\nConcerning which you'll get no more from me.\nTell on your tale, good manciple, I pray.\nWell, sir, said he, now hear what I will say.\n\n\n### The Manciple's Tale\n\nWhen Phoebus once on earth was dwelling, here,\nAs in the ancient books it is made clear,\nHe was the lustiest of bachelors\nIn all this world, and even the best archer;\nHe slew Python, the serpent, as he lay\nSleeping within the sunlight, on a day;\nAnd many another noble, worthy deed\nHe with his bow wrought, as all men may read.\nHe played all instruments of minstrelsy,\nAnd sang so that it made great harmony\nTo hear his clear voice in the joyous sun.\nTruly the king of Thebes, that Amphion\nWho, by his singing, walled that great city,\nCould never sing one half so well as he.\nTherewith he was the handsomest young man\nThat is or was since first the world began.\nWhat needs it that his features I revive?\nFor in the world was none so fair alive.\nCompact of honour and of nobleness,\nPerfect he was in every worthiness.\nThis Phoebus, of all youthful knights the flower,\nWhom generous chivalry did richly dower,\nFor his amusement (sign of victory\nOver that Python, says the old story),\nWas wont to bear in hand a golden bow.\nNow Phoebus had within his house a crow,\nWhich in a cage he'd fostered many a day,\nAnd taught to speak, as men may teach a jay.\nWhite was this crow as is a snow white swan,\nAnd counterfeit the speech of any man\nHe could, when he desired to tell a tale.\nTherewith, in all this world, no nightingale\nCould, by a hundred-thousandth part, they tell,\nCarol and sing so merrily and well.\nNow had this Phoebus in his house a wife,\nWhom he loved better than he loved his life,\nAnd night and day he used much diligence\nTo please her and to do her reverence,\nSave only, if it's truth that I shall say,\nJealous he was and so did guard her aye;\nFor he was very loath befooled to be.\nAnd so is everyone in such degree;\nBut all in vain, for it avails one naught.\nA good wife, who is clean in deed and thought,\nShould not be kept a prisoner, that's plain;\nAnd certainly the labour is in vain\nThat guards a slut, for, sirs, it just won't be.\nThis hold I for an utter idiocy,\nThat men should lose their labour guarding wives;\nSo say these wise old writers in their lives.\nBut now to purpose, as I first began:\nThis worthy Phoebus did all that a man\nCould do to please, thinking that by such pleasures,\nAnd by his manhood and his other measures\nTo make her love him and keep faithful, too.\nBut God knows well that nothing man may do\nWill ever keep restrained a thing that nature\nHas made innate in any human creature.\nTake any bird and put it in a cage\nAnd do your best affection to engage\nAnd rear it tenderly with meat and drink\nOf all the dainties that you can bethink,\nAnd always keep it cleanly as you may;\nAlthough its cage of gold be never so gay,\nYet would this bird, by twenty thousand-fold,\nRather, within a forest dark and cold,\nGo to eat worms and all such wretchedness.\nFor ever this bird will do his business\nTo find some way to get outside the wires.\nAbove all things his freedom he desires.\nOr take a cat, and feed him well with milk\nAnd tender flesh, and make his bed of silk,\nAnd let him see a mouse go by the wall;\nAnon he leaves the milk and flesh and all\nAnd every dainty that is in that house,\nSuch appetite has he to eat a mouse.\nDesire has here its mighty power shown,\nAnd inborn appetite reclaims its own.\nA she-wolf also has a vulgar mind;\nThe wretchedest he-wolf that she may find,\nOr least of reputation, she'll not hate\nWhenever she's desirous of a mate.\nAll these examples speak I of these men\nWho are untrue, and not of sweet women.\nFor men have aye a lickerish appetite\nOn lower things to do their base delight\nThan on their wives, though they be ne'er so fair\nAnd ne'er so true and ne'er so debonair.\nFlesh is so fickle, lusting beyond measure,\nThat we in no one thing can long have pleasure\nOr virtuous keep more than a little while.\nThis Phoebus, who was thinking of no guile,\nHe was deceived, for all his quality;\nFor under him a substitute had she,\nA man of little reputation, one\nWorth naught to Phoebus, by comparison.\nThe more harm that; it often happens so,\nWhereof there come so much of harm and woe.\nAnd so befell, when Phoebus was absent,\nHis wife has quickly for her leman sent.\nHer leman? Truly, 'tis a knavish speech!\nForgive it me, I do indeed beseech.\nThe wise old Plato says, as you may read,\nThe word must needs accord well with the deed.\nAnd if a man tell properly a thing,\nThe word must suited be to the acting.\nBut I'm a vulgar man, and thus say I,\nThere is no smallest difference, truly,\nBetween a wife who is of high degree,\nIf of her body she dishonest be,\nAnd a poor unknown wench, other than this-\nIf it be true that both do what's amiss-\nThe gentlewoman, in her state above,\nShe shall be called his lady, in their love;\nAnd since the other's but a poor woman,\nShe shall be called his wench or his leman.\nAnd God knows very well, my own dear brother,\nMen lay the one as low as lies the other.\nBetween a tyrant or usurping chief\nAnd any outlawed man or errant thief,\nIt's just the same, there is no difference.\nOne told to Alexander this sentence:\nThat, since the tyrant is of greater might,\nBy force of numbers, to slay men outright\nAnd burn down house and home even as a plane,\nLot for that he's a captain, that's certain;\nAnd since the outlaw has small company\nAnd may not do so great a harm as he,\nNor bring a nation into such great grief,\nWhy, he's called but an outlaw or a thief.\nBut since I'm not a man the texts to spell,\nNothing at all from texts now will I tell;\nI'll go on with my tale as I began.\nWhen Phoebus' wife had sent for her leman,\nAt once they wrought all of their libertinage.\nAnd the white crow, aye hanging in the cage,\nSaw what they did, and never said a word.\nAnd when again came Phoebus home, the lord,\nThis crow sang loud Cuckoo! Cuckoo! Cuckoo!\nWhat, bird? asked Phoebus, What song now sing you?\nWere you not wont so merrily to sing\nThat in my heart it was a joyful thing\nTo hear your voice? Alas! What song is this?\nBy God, said he, I do not sing amiss;\nPhoebus, said he, for all your worthiness,\nFor all your beauty and your nobleness,\nFor all your song and all your minstrelsy,\nFor all your watching, bleared is your bright eye\nBy one of small repute, as well is known,\nNot worth, when I compare it with your own,\nThe value of a gnat, as I may thrive.\nFor on your bed your wife I saw him swive.\nWhat will you more? The crow thereafter told,\nIn sober fashion, giving witness bold,\nHow that his wife had done her lechery\nTo his great shame and with great villainy;\nRepeating that he'd seen it with his eyes.\nThen Phoebus turned away in sad surprise;\nHe thought his wretched heart would break for woe;\nHis bow he bent and set there an arrow,\nAnd in his angry mood his wife did slay.\nThis the result; there is no more to say;\nFor grief of which he ceased his minstrelsy,\nBroke harp and lute, gittern and psaltery;\nAnd, too, he broke his arrows and his bow.\nAnd after that he spoke thus to the crow.\nTraitor, cried he, with tongue of scorpion,\nYou have brought me to ruin, treacherous one!\nAlas, that I was born! Why died I not?\nO my dear wife, jewel of joy, God wot,\nWho were to me so trusty and so true,\nNow you lie dead, with face all pale of hue,\nAnd you were guiltless, I dare swear to this!\nO hasty hand, to do so foul amiss!\nO stupid brain, O anger all reckless,\nThat unadvisedly struck the guiltless!\nO ill distrust that jealousy had sown!\nWhere were your thought and your discretion flown?\nO every man, beware of hastiness,\nDo not believe without a strong witness;\nStrike not too soon, before you reason why,\nAnd be advised full well and soberly\nEre you do any execution thus\nIn your wild anger when it is jealous.\nAlas! A thousand folk has hasty ire\nRuined, and left them bleeding in the mire.\nAlas! I'll slay myself forthwith for grief!\nAnd to the crow he said, O you false thief!\nI will anon requite you that false tale!\nYou sang but lately like a nightingale;\nNow, you false thief, your songs are over and done,\nAnd you'll all those white feathers lose, each one,\nNor ever in your life more shall you speak.\nThus men on traitors shall their justice wreak;\nYou and your offspring ever shall be black,\nNor evermore sweet noises shall you make,\nBut you shall cry in tempest and in rain\nIn token that through you my wife was slain.\nAnd on the crow he leaped, and that anon,\nAnd plucked out his white feathers, every one,\nAnd made him black, and stilled for evermore\nHis song and speech, and flung him out the door\nUnto the devil, where I leave this jack;\nAnd for this reason, now all crows are black.\nMasters, by this example, I do pray\nYou will beware and heed what I shall say:\nNever tell any man, through all your life,\nHow that another man has humped his wife;\nHe'll hate you mortally, and that's certain.\nDan Solomon, as these wise clerks explain,\nTeaches a man to keep his tongue from all;\nBut, as I said, I am not textual.\nNevertheless, thus taught me my good dame:\nMy son, think of the crow, in high God's name;\nMy son, keep your tongue still, and keep your friend.\nA wicked tongue is worse than any fiend.\nMy son, from devils men themselves may bless;\nMy son, high God, of His endless goodness,\nWalled up the tongue with teeth and lips and cheeks\nThat man should speak advisedly when he speaks.\nMy son, full oftentimes, for too much speech,\nHas many a man been killed, as clerics teach;\nBut, speaking little and advisedly,\nIs no man harmed, to put it generally.\nMy son, your foolish tongue you should restrain\nAt all times, save those when your soul is fain\nTo speak of God, in honour and in prayer.\nThe first of virtues, son, if you'll but hear,\nIs to restrain and to guard well your tongue-\nThus teach the children while they yet are young-\nMy son, of too much speaking, ill advised,\nWhere less had been enough and had sufficed,\nMuch harm may come; thus was I told and taught.\nIn fluent speaking evil wants for naught.\nKnow you of where a rash tongue has well served?\nJust as a sword has cut deep and has carved\nA many an arm in two, dear son, just so\nA tongue can cut a friendship, well I know.\nA gossip is to God abominable.\nRead Solomon, so wise and honourable,\nOr David's Psalms, what Seneca has said.\nMy son, speak not, but merely bow your head.\nDissemble like one deaf, if you but hear\nA chatterer speak what's dangerous in your ear.\nThe Fleming says, and learn it, for it's best,\nThat little prattle gives us all much rest.\nMy son, if you no wicked word have said,\nTo be betrayed you need not ever dread;\nBut he that has missaid, I dare explain,\nHe may not aye recall his words again.\nThat which is said, is said, and goes, in truth,\nThough he repent, and be he lief or loath.\nA man's the slave of him to whom he's told\nA tale to which he can no longer hold.\nMy son, beware and be not author new\nOf tidings, whether they be false or true.\nWhere'er you come, among the high or low,\nGuard well your tongue, and think upon the crow.\n\n"},{"index":12,"markdown":"### The Parson's Prologue\n\nWhat time the manciple his tale had ended,\nThe sun down from the south line had descended\nSo low that he was not, unto my sight,\nDegrees full nine and twenty yet in height.\nFour of the clock it was then, as I guess:\nFour feet eleven, little more or less,\nMy shadow was extended then and there,\nA length as if the shadow parted were\nIn six-foot equal parts, as I have shown.\nTherewith the moon's high exaltation known,\nI mean the sign of Libra, did ascend\nAs we were entering a village-end;\nWhereat our host, since wont to guide was he,\nAs in this case, our jolly company,\nSaid in this wise: Now, masters, every one,\nWe lack no tales except a single one.\nMy judgment is fulfilled and my decree,\nI think that we have heard from each degree.\nAlmost fulfilled is all my ordinance;\nI pray to God to give him right good chance\nWho tells to us this story pleasantly.\nSir priest, he asked, can you a vicar be?\nAre you a parson? Tell truth, by your fay!\nBe what you will, break not our jolly play;\nFor every man, save you, has told his tale,\nUnbuckle, show us what is in your mail;\nFor truly, I think, judging by your cheer,\nYou should knit up a mighty matter here.\nTell us a fable now, by Cock's dear bones!\nThis parson then replied to him at once:\nYou'll get no foolish fable told by me;\nFor Paul, when writing unto Timothy,\nReproves all those that veer from truthfulness\nAnd tell false fables and such wretchedness.\nWhy should I sow chaff out of my own fist\nWhen I may sow good wheat, if I but list?\nBut if, I say, you something wish to hear\nIn which the moral virtues will appear,\nAnd if you now will give me audience,\nI will right gladly, in Christ's reverence,\nGive you such lawful pleasure as I can.\nBut trust me, since I am a Southern man,\nI can't romance with 'rum, ram, ruff', by letter,\nAnd, God knows, rhyme I hold but little better;\nBut if you wish the truth made plain and straight,\nA pleasant tale in prose I will relate\nTo weave our feast together at the end.\nMay Jesus, of His grace, the wit me send\nTo show you, as we journey this last stage,\nThe way of that most perfect pilgrimage\nTo heavenly Jerusalem on high.\nAnd if you will vouchsafe, anon shall I\nBegin my tale, concerning which, I pray,\nChoose what you will, I can no better say.\nYet this my meditation is, I own,\nPerhaps not free from errors to be shown\nBy clerks, since I am not a learned man;\nI do but grasp the meaning as I can.\nTherefore, I do protest, I shall prepare\nTo take what comes, and all correction bear.\nWhen he had spoken thus, we all agreed,\nFor, as it seemed to us, 'twas right indeed\nTo end with something virtuous in its sense,\nAnd so to give him time and audience.\nWe bade our host that he to him convey\nThe wish of all that he begin straightway.\nOur host, he had the very words for all.\nSir priest, said he, may good to you befall!\nSay what you wish, and we will gladly hear.\nAnd after that he added, for his ear:\nTell us, he said, your meditation grown,\nBut pray make haste, the sun will soon be down;\nBe fruitful, tell us in a little space,\nAnd to do well God send to you His grace!\n\n\n### The Parson's Tale\n\nOur sweet Lord God of Heaven, that no man will perish, but will that we come all to the knowledge of him, and to the blissful life that is perdurable, admonishes us by the prophet Jeremiah, that saith in this wise: \"Stand upon the ways, and see and ask of old paths, that is to say, of old sentences, which is the good way, and walk in that way, and ye shall find refreshing for your souls,\" &c. Many be the spiritual ways that lead folk to our Lord Jesus Christ, and to the reign of glory; of which ways there is a full noble way, and full convenable, which may not fail to man nor to woman, that through sin hath misgone from the right way of Jerusalem celestial; and this way is called penitence. Of which men should gladly hearken and inquire with all their hearts, to wit what is penitence, and whence it is called penitence, and in what manner, and in how many manners, be the actions or workings of penitence, and how many species there be of penitences, and what things appertain and behove to penitence, and what things disturb penitence.\n\nCertes, all the sorrow that a man might make from the beginning of the world, is but a little thing, at retard of the sorrow of hell. The cause why that Job calleth hell the land of darkness; understand, that he calleth it land or earth, for it is stable and never shall fail, and dark, for he that is in hell hath default of light natural; for certes the dark light, that shall come out of the fire that ever shall burn, shall turn them all to pain that be in hell, for it sheweth them the horrible devils that them torment. Covered with the darkness of death; that is to say, that he that is in hell shall have default of the sight of God; for certes the sight of God is the life perdurable. The darkness of death, be the sins that the wretched man hath done, which that disturb him to see the face of God, right as a dark cloud doth between us and the sun. Land of misease, because there be three manner of defaults against three things that folk of this world have in this present life; that is to say, honours, delights, and riches. Against honour have they in hell shame and confusion: for well ye wot, that men call honour the reverence that man doth to man; but in hell is no honour nor reverence; for certes no more reverence shall be done there to a king than to a knave. For which God saith by the prophet Jeremiah; \"The folk that me despise shall be in despite.\" Honour is also called great lordship. There shall no wight serve other, but of harm and torment. Honour is also called great dignity and highness; but in hell shall they be all fortrodden of devils. As God saith, \"The horrible devils shall go and come upon the heads of damned folk;\" and this is, forasmuch as the higher that they were in this present life, the more shall they be abated and defouled in hell. Against the riches of this world shall they have misease of poverty, and this poverty shall be in four things: in default of treasure; of which David saith, \"The rich folk that embraced and oned all their heart to treasure of this world, shall sleep in the sleeping of death, and nothing shall they find in their hands of all their treasure.\" And moreover, the misease of hell shall be in default of meat and drink. For God saith thus by Moses, \"They shall be wasted with hunger, and the birds of hell shall devour them with bitter death, and the gall of the dragon shall be their drink, and the venom of the dragon their morsels.\" And furthermore, their misease shall be in default of clothing, for they shall be naked in body, as of clothing, save the fire in which they burn, and other filths; and naked shall they be in soul, of all manner virtues, which that is the clothing of the soul. Where be then the gay robes, and the soft sheets, and the fine shirts? Lo, what saith of them the prophet Isaiah, that under them shall be strewed moths, and their covertures shall be of worms of hell. And furthermore, their misease shall be in default of friends, for he is not poor that hath good friends: but there is no friend; for neither God nor any good creature shall be friend to them, and evereach of them shall hate other with deadly hate. The Sons and the daughters shall rebel against father and mother, and kindred against kindred, and chide and despise each other, both day and night, as God saith by the prophet Micah. And the loving children, that whom loved so fleshly each other, would each of them eat the other if they might. For how should they love together in the pains of hell, when they hated each other in the prosperity of this life? For trust well, their fleshly love was deadly hate; as saith the prophet David; \"Whoso loveth wickedness, he hateth his own soul:\" and whoso hateth his own soul, certes he may love none other wight in no manner: and therefore in hell is no solace nor no friendship, but ever the more kindreds that be in hell, the more cursing, the more chiding, and the more deadly hate there is among them. And furtherover, they shall have default of all manner delights; for certes delights be after the appetites of the five wits; as sight, hearing, smelling, savouring, and touching. But in hell their sight shall be full of darkness and of smoke, and their eyes full of tears; and their hearing full of waimenting and grinting of teeth, as saith Jesus Christ; their nostrils shall be full of stinking; and, as saith Isaiah the prophet, their savouring shall be full of bitter gall; and touching of all their body shall be covered with fire that never shall quench, and with worms that never shall die, as God saith by the mouth of Isaiah. And forasmuch as they shall not ween that they may die for pain, and by death flee from pain, that may they understand in the word of Job, that saith, \"There is the shadow of death.\" Certes a shadow hath the likeness of the thing of which it is shadowed, but the shadow is not the same thing of which it is shadowed: right so fareth the pain of hell; it is like death, for the horrible anguish; and why? for it paineth them ever as though they should die anon; but certes they shall not die. For, as saith Saint Gregory, \"To wretched caitiffs shall be given death without death, and end without end, and default without failing; for their death shall always live, and their end shall evermore begin, and their default shall never fail.\" And therefore saith Saint John the Evangelist, \"They shall follow death, and they shall not find him, and they shall desire to die, and death shall flee from them.\" And eke Job saith, that in hell is no order of rule. And albeit that God hath created all things in right order, and nothing without order, but all things be ordered and numbered, yet nevertheless they that be damned be not in order, nor hold no order. For the earth shall bear them no fruit (for, as the prophet David saith, \"God shall destroy the fruit of the earth, as for them\"); nor water shall give them no moisture, nor the air no refreshing, nor the fire no light. For as saith Saint Basil, \"The burning of the fire of this world shall God give in hell to them that be damned, but the light and the clearness shall be given in heaven to his children; right as the good man giveth flesh to his children, and bones to his hounds.\" And for they shall have no hope to escape, saith Job at last, that there shall horror and grisly dread dwell without end. Horror is always dread of harm that is to come, and this dread shall ever dwell in the hearts of them that be damned. And therefore have they lost all their hope for seven causes. First, for God that is their judge shall be without mercy to them; nor they may not please him; nor none of his hallows; nor they may give nothing for their ransom; nor they have no voice to speak to him; nor they may not flee from pain; nor they have no goodness in them that they may shew to deliver them from pain.\n\nThe courteous Lord Jesus Christ will that no good work be lost, for in somewhat it shall avail. But forasmuch as the good works that men do while they be in good life be all amortised by sin following, and also since all the good works that men do while they be in deadly sin be utterly dead, as for to have the life perdurable, well may that man that no good works doth, sing that new French song, J'ai tout perdu — mon temps et mon labour. For certes, sin bereaveth a man both the goodness of nature, and eke the goodness of grace. For soothly the grace of the Holy Ghost fareth like fire, that may not be idle; for fire faileth anon as it forleteth its working, and right so grace faileth anon as it forleteth its working. Then loseth the sinful man the goodness of glory, that only is to good men that labour and work. Well may he be sorry then, that oweth all his life to God, as long as he hath lived, and also as long as he shall live, that no goodness hath to pay with his debt to God, to whom he oweth all his life: for trust well he shall give account, as saith Saint Bernard, of all the goods that have been given him in his present life, and how he hath them dispended, insomuch that there shall not perish an hair of his head, nor a moment of an hour shall not perish of his time, that he shall not give thereof a reckoning.\n\nThis is to say, at every time that a man eateth and drinketh more than sufficeth to the sustenance of his body, in certain he doth sin; eke when he speaketh more than it needeth, he doth sin; eke when he heareth not benignly the complaint of the poor; eke when he is in health of body, and will not fast when other folk fast, without cause reasonable; eke when he sleepeth more than needeth, or when he cometh by that occasion too late to church, or to other works of charity; eke when he useth his wife without sovereign desire of engendrure, to the honour of God, or for the intent to yield his wife his debt of his body; eke when he will not visit the sick, or the prisoner, if he may; eke if he love wife, or child, or other worldly thing, more than reason requireth; eke if he flatter or blandish more than he ought for any necessity; eke if he minish or withdraw the alms of the poor; eke if he apparail his meat more deliciously than need is, or eat it too hastily by likerousness; eke if he talk vanities in the church, or at God's service, or that he be a talker of idle words of folly or villainy, for he shall yield account of them at the day of doom; eke when he behighteth or assureth to do things that he may not perform; eke when that by lightness of folly he missayeth or scorneth his neighbour; eke when he hath any wicked suspicion of thing, that he wot of it no soothfastness: these things, and more without number, be sins, as saith Saint Augustine.\n\nNow it is behovely to tell which be deadly sins, that is to say, chieftains of sins; forasmuch as all they run in one leash, but in diverse manners. Now be they called chieftains, forasmuch as they be chief, and of them spring all other sins. The root of these sins, then, is pride, the general root of all harms. For of this root spring certain branches: as ire, envy, accidie or sloth, avarice or covetousness (to common understanding), gluttony, and lechery: and each of these sins hath his branches and his twigs, as shall be declared in their chapters following. And though so be, that no man can tell utterly the number of the twigs, and of the harms that come of pride, yet will I shew a part of them, as ye shall understand. There is inobedience, vaunting, hypocrisy, despite, arrogance, impudence, swelling of hearte, insolence, elation, impatience, strife, contumacy, presumption, irreverence, pertinacity, vain- glory and many another twig that I cannot tell nor declare...\n\nAnd yet there is a privy species of pride that waiteth first to be saluted ere he will salute, all be he less worthy than that other is; and eke he waiteth or desireth to sit or to go above him in the way, or kiss the pax, or be incensed, or go to offering before his neighbour, and such semblable things, against his duty peradventure, but that he hath his heart and his intent in such a proud desire to be magnified and honoured before the people. Now be there two manner of prides; the one of them is within the heart of a man, and the other is without. Of which soothly these foresaid things, and more than I have said, appertain to pride that is within the heart of a man and there be other species of pride that be without: but nevertheless, the one of these species of pride is sign of the other, right as the gay levesell at the tavern is sign of the wine that is in the cellar. And this is in many things: as in speech and countenance, and outrageous array of clothing; for certes, if there had been no sin in clothing, Christ would not so soon have noted and spoken of the clothing of that rich man in the gospel. And Saint Gregory saith, that precious clothing is culpable for the dearth of it, and for its softness, and for its strangeness and disguising, and for the superfluity or for the inordinate scantness of it; alas! may not a man see in our days the sinful costly array of clothing, and namely in too much superfluity, or else in too disordinate scantness? As to the first sin, in superfluity of clothing, which that maketh it so dear, to the harm of the people, not only the cost of the embroidering, the disguising, indenting or barring, ounding, paling, winding, or banding, and semblable waste of cloth in vanity; but there is also the costly furring in their gowns, so much punching of chisels to make holes, so much dagging of shears, with the superfluity in length of the foresaid gowns, trailing in the dung and in the mire, on horse and eke on foot, as well of man as of woman, that all that trailing is verily (as in effect) wasted, consumed, threadbare, and rotten with dung, rather than it is given to the poor, to great damage of the foresaid poor folk, and that in sundry wise: this is to say, the more that cloth is wasted, the more must it cost to the poor people for the scarceness; and furthermore, if so be that they would give such punched and dagged clothing to the poor people, it is not convenient to wear for their estate, nor sufficient to boot their necessity, to keep them from the distemperance of the firmament. Upon the other side, to speak of the horrible disordinate scantness of clothing, as be these cutted slops or hanselines , that through their shortness cover not the shameful member of man, to wicked intent alas! some of them shew the boss and the shape of the horrible swollen members, that seem like to the malady of hernia, in the wrapping of their hosen, and eke the buttocks of them, that fare as it were the hinder part of a she-ape in the full of the moon. And more over the wretched swollen members that they shew through disguising, in departing of their hosen in white and red, seemeth that half their shameful privy members were flain. And if so be that they depart their hosen in other colours, as is white and blue, or white and black, or black and red, and so forth; then seemeth it, by variance of colour, that the half part of their privy members be corrupt by the fire of Saint Anthony, or by canker, or other such mischance. And of the hinder part of their buttocks it is full horrible to see, for certes, in that part of their body where they purge their stinking ordure, that foul part shew they to the people proudly in despite of honesty, which honesty Jesus Christ and his friends observed to shew in his life. Now as of the outrageous array of women, God wot, that though the visages of some of them seem full chaste and debonair, yet notify they, in their array of attire, likerousness and pride. I say not that honesty in clothing of man or woman unconvenable but, certes, the superfluity or disordinate scarcity of clothing is reprovable. Also the sin of their ornament, or of apparel, as in things that appertain to riding, as in too many delicate horses, that be holden for delight, that be so fair, fat, and costly; and also in many a vicious knave, that is sustained because of them; in curious harness, as in saddles, cruppers, peytrels, and bridles, covered with precious cloth and rich bars and plates of gold and silver. For which God saith by Zechariah the prophet, \"I will confound the riders of such horses.\" These folk take little regard of the riding of God's Son of heaven, and of his harness, when he rode upon an ass, and had no other harness but the poor clothes of his disciples; nor we read not that ever he rode on any other beast. I speak this for the sin of superfluity, and not for reasonable honesty, when reason it requireth. And moreover, certes, pride is greatly notified in holding of great meinie, when they be of little profit or of right no profit, and namely when that meinie is felonous and damageous to the people by hardiness of high lordship, or by way of office; for certes, such lords sell then their lordship to the devil of hell, when they sustain the wickedness of their meinie. Or else, when these folk of low degree, as they that hold hostelries, sustain theft of their hostellers, and that is in many manner of deceits: that manner of folk be the flies that follow the honey, or else the hounds that follow the carrion. Such foresaid folk strangle spiritually their lordships; for which thus saith David the prophet, \"Wicked death may come unto these lordships, and God give that they may descend into hell adown; for in their houses is iniquity and shrewedness, and not God of heaven.\" And certes, but if they do amendment, right as God gave his benison to Laban by the service of Jacob, and to Pharaoh by the service of Joseph; right so God will give his malison to such lordships as sustain the wickedness of their servants, but they come to amendment. Pride of the table apaireth eke full oft; for, certes, rich men be called to feasts, and poor folk be put away and rebuked; also in excess of divers meats and drinks, and namely such manner bake-meats and dish-meats burning of wild fire, and painted and castled with paper, and semblable waste, so that it is abuse to think. And eke in too great preciousness of vessel, and curiosity of minstrelsy, by which a man is stirred more to the delights of luxury, if so be that he set his heart the less upon our Lord Jesus Christ, certain it is a sin; and certainly the delights might be so great in this case, that a man might lightly fall by them into deadly sin.\n\nNow be there three manners of humility; as humility in heart, and another in the mouth, and the third in works. The humility in the heart is in four manners: the one is, when a man holdeth himself as nought worth before God of heaven; the second is, when he despiseth no other man; the third is, when he recketh not though men hold him nought worth; the fourth is, when he is not sorry of his humiliation. Also the humility of mouth is in four things: in temperate speech; in humility of speech; and when he confesseth with his own mouth that he is such as he thinketh that he is in his heart; another is, when he praiseth the bounte of another man and nothing thereof diminisheth. Humility eke in works is in four manners: the first is, when he putteth other men before him; the second is, to choose the lowest place of all; the third is, gladly to assent to good counsel; the fourth is, to stand gladly by the award of his sovereign, or of him that is higher in degree: certain this is a great work of humility.\n\nAfter Avarice cometh Gluttony, which is express against the commandment of God. Gluttony is unmeasurable appetite to eat or to drink; or else to do in aught to the unmeasurable appetite and disordered covetousness to eat or drink. This sin corrupted all this world, as is well shewed in the sin of Adam and of Eve. Look also what saith Saint Paul of gluttony: \"Many,\" saith he, \"go, of which I have oft said to you, and now I say it weeping, that they be enemies of the cross of Christ, of which the end is death, and of which their womb is their God and their glory;\" in confusion of them that so savour earthly things. He that is usant to this sin of gluttony, he may no sin withstand, he must be in servage of all vices, for it is the devil's hoard, where he hideth him in and resteth. This sin hath many species. The first is drunkenness, that is the horrible sepulture of man's reason: and therefore when a man is drunken, he hath lost his reason; and this is deadly sin. But soothly, when that a man is not wont to strong drink, and peradventure knoweth not the strength of the drink, or hath feebleness in his head, or hath travailed, through which he drinketh the more, all be he suddenly caught with drink, it is no deadly sin, but venial. The second species of gluttony is, that the spirit of a man waxeth all troubled for drunkenness, and bereaveth a man the discretion of his wit. The third species of gluttony is, when a man devoureth his meat, and hath no rightful manner of eating. The fourth is, when, through the great abundance of his meat, the humours of his body be distempered. The fifth is, forgetfulness by too much drinking, for which a man sometimes forgetteth by the morrow what be did at eve. In other manner be distinct the species of gluttony, after Saint Gregory. The first is, for to eat or drink before time. The second is, when a man getteth him too delicate meat or drink. The third is, when men take too much over measure. The fourth is curiosity with great intent to make and apparel his meat. The fifth is, for to eat too greedily. These be the five fingers of the devil's hand, by which he draweth folk to the sin.\n\nAgainst gluttony the remedy is abstinence, as saith Galen; but that I hold not meritorious, if he do it only for the health of his body. Saint Augustine will that abstinence be done for virtue, and with patience. Abstinence, saith he, is little worth, but if a man have good will thereto, and but it be enforced by patience and by charity, and that men do it for God's sake, and in hope to have the bliss in heaven. The fellows of abstinence be temperance, that holdeth the mean in all things; also shame, that escheweth all dishonesty, sufficiency, that seeketh no rich meats nor drinks, nor doth no force of no outrageous apparelling of meat; measure also, that restraineth by reason the unmeasurable appetite of eating; soberness also, that restraineth the outrage of drink; sparing also, that restraineth the delicate ease to sit long at meat, wherefore some folk stand of their own will to eat, because they will eat at less leisure.\n\nAlso thou shalt shrive thee of all thy sins to one man, and not a parcel to one man, and a parcel to another; that is to understand, in intent to depart thy confession for shame or dread; for it is but strangling of thy soul. For certes Jesus Christ is entirely all good, in him is none imperfection, and therefore either he forgiveth all perfectly, or else never a deal. I say not that if thou be assigned to thy penitencer for a certain sin, that thou art bound to shew him all the remnant of thy sins, of which thou hast been shriven of thy curate, but if it like thee of thy humility; this is no departing of shrift. And I say not, where I speak of division of confession, that if thou have license to shrive thee to a discreet and an honest priest, and where thee liketh, and by the license of thy curate, that thou mayest not well shrive thee to him of all thy sins: but let no blot be behind, let no sin be untold as far as thou hast remembrance. And when thou shalt be shriven of thy curate, tell him eke all the sins that thou hast done since thou wert last shriven. This is no wicked intent of division of shrift. Also, very shrift asketh certain conditions. First, that thou shrive thee by thy free will, not constrained, nor for shame of folk, nor for malady, or such things: for it is reason, that he that trespasseth by his free will, that by his free will he confess his trespass; and that no other man tell his sin but himself; nor he shall not nay nor deny his sin, nor wrath him against the priest for admonishing him to leave his sin. The second condition is, that thy shrift be lawful, that is to say, that thou that shrivest thee, and eke the priest that heareth thy confession, be verily in the faith of Holy Church, and that a man be not despaired of the mercy of Jesus Christ, as Cain and Judas were. And eke a man must accuse himself of his own trespass, and not another: but he shall blame and wite himself of his own malice and of his sin, and none other: but nevertheless, if that another man be occasion or else enticer of his sin, or the estate of the person be such by which his sin is aggravated, or else that be may not plainly shrive him but he tell the person with which he hath sinned, then may he tell, so that his intent be not to backbite the person, but only to declare his confession. Thou shalt not eke make no leasings in thy confession for humility, peradventure, to say that thou hast committed and done such sins of which that thou wert never guilty. For Saint Augustine saith, \"If that thou, because of humility, makest a leasing on thyself, though thou were not in sin before, yet art thou then in sin through thy leasing.\" Thou must also shew thy sin by thine own proper mouth, but thou be dumb, and not by letter; for thou that hast done the sin, thou shalt have the shame of the confession. Thou shalt not paint thy confession with fair and subtle words, to cover the more thy sin; for then beguilest thou thyself, and not the priest; thou must tell it plainly, be it never so foul nor so horrible. Thou shalt eke shrive thee to a priest that is discreet to counsel thee; and eke thou shalt not shrive thee for vain-glory, nor for hypocrisy, nor for no cause but only for the doubt of Jesus' Christ and the health of thy soul. Thou shalt not run to the priest all suddenly, to tell him lightly thy sin, as who telleth a jape or a tale, but advisedly and with good devotion; and generally shrive thee oft; if thou oft fall, oft arise by confession. And though thou shrive thee oftener than once of sin of which thou hast been shriven, it is more merit; and, as saith Saint Augustine, thou shalt have the more lightly release and grace of God, both of sin and of pain. And certes, once a year at the least way, it is lawful to be houseled, for soothly once a year all things in the earth renovelen.\n\nDe Tertia Parte Poenitentiae.\n\nNow have I told you of very confession, that is the second part of penitence: The third part of penitence is satisfaction, and that standeth generally in almsdeed and bodily pain. Now be there three manner of almsdeed: contrition of heart, where a man offereth himself to God; the second is, to have pity of the default of his neighbour; the third is, in giving of good counsel and comfort, ghostly and bodily, where men have need, and namely sustenance of man's food. And take keep that a man hath need of these things generally; he hath need of food, of clothing, and of herberow, he hath need of charitable counsel and visiting in prison and malady, and sepulture of his dead body. And if thou mayest not visit the needful with thy person, visit them by thy message and by thy gifts. These be generally alms or works of charity of them that have temporal riches or discretion in counselling. Of these works shalt thou hear at the day of doom. This alms shouldest thou do of thine own proper things, and hastily, and privily if thou mayest; but nevertheless, if thou mayest not do it privily, thou shalt not forbear to do alms, though men see it, so that it be not done for thank of the world, but only for thank of Jesus Christ. For, as witnesseth Saint Matthew, chap. v., \"A city may not be hid that is set on a mountain, nor men light not a lantern and put it under a bushel, but men set it on a candlestick, to light the men in the house; right so shall your light lighten before men, that they may see your good works, and glorify your Father that is in heaven.\"\n\nNow as to speak of bodily pain, it is in prayer, in wakings, in fastings, and in virtuous teachings. Of orisons ye shall understand, that orisons or prayers is to say a piteous will of heart, that redresseth it in God, and expresseth it by word outward, to remove harms, and to have things spiritual and durable, and sometimes temporal things. Of which orisons, certes in the orison of the Pater noster hath our Lord Jesus Christ enclosed most things. Certes, it is privileged of three things in its dignity, for which it is more digne than any other prayer: for Jesus Christ himself made it: and it is short, for it should be coude the more lightly, and to withhold it the more easy in heart, and help himself the oftener with this orison; and for a man should be the less weary to say it; and for a man may not excuse him to learn it, it is so short and so easy: and for it comprehendeth in itself all good prayers. The exposition of this holy prayer, that is so excellent and so digne, I betake to these masters of theology; save thus much will I say, when thou prayest that God should forgive thee thy guilts, as thou forgivest them that they guilt to thee, be full well ware that thou be not out of charity. This holy orison aminisheth eke venial sin, and therefore it appertaineth specially to penitence. This prayer must be truly said, and in very faith, and that men pray to God ordinately, discreetly, and devoutly; and always a man shall put his will to be subject to the will of God. This orison must eke be said with great humbleness and full pure, and honestly, and not to the annoyance of any man or woman. It must eke be continued with the works of charity. It availeth against the vices of the soul; for, assaith Saint Jerome, by fasting be saved the vices of the flesh, and by prayer the vices of the soul\n\nAfter this thou shalt understand, that bodily pain stands in waking. For Jesus Christ saith \"Wake and pray, that ye enter not into temptation.\" Ye shall understand also, that fasting stands in three things: in forbearing of bodily meat and drink, and in forbearing of worldly jollity, and in forbearing of deadly sin; this is to say, that a man shall keep him from deadly sin in all that he may. And thou shalt understand eke, that God ordained fasting; and to fasting appertain four things: largeness to poor folk; gladness of heart spiritual; not to be angry nor annoyed nor grudge for he fasteth; and also reasonable hour for to eat by measure; that is to say, a man should not eat in untime, nor sit the longer at his meal for he fasteth. Then shalt thou understand, that bodily pain standeth in discipline, or teaching, by word, or by writing, or by ensample. Also in wearing of hairs or of stamin, or of habergeons on their naked flesh for Christ's sake; but ware thee well that such manner penance of thy flesh make not thine heart bitter or angry, nor annoyed of thyself; for better is to cast away thine hair than to cast away the sweetness of our Lord Jesus Christ. And therefore saith Saint Paul, \"Clothe you, as they that be chosen of God in heart, of misericorde, debonairte, sufferance, and such manner of clothing,\" of which Jesus Christ is more apaid than of hairs or of hauberks. Then is discipline eke in knocking of thy breast, in scourging with yards, in kneelings, in tribulations, in suffering patiently wrongs that be done to him, and eke in patient sufferance of maladies, or losing of worldly catel, or of wife, or of child, or of other friends.\n\nThen shalt thou understand which things disturb penance, and this is in four things; that is dread, shame, hope, and wanhope, that is, desperation. And for to speak first of dread, for which he weeneth that he may suffer no penance, thereagainst is remedy for to think that bodily penance is but short and little at the regard of the pain of hell, that is so cruel and so long, that it lasteth without end. Now against the shame that a man hath to shrive him, and namely these hypocrites, that would be holden so perfect, that they have no need to shrive them; against that shame should a man think, that by way of reason he that hath not been ashamed to do foul things, certes he ought not to be ashamed to do fair things, and that is confession. A man should eke think, that God seeth and knoweth all thy thoughts, and all thy works; to him may nothing be hid nor covered. Men should eke remember them of the shame that is to come at the day of doom, to them that be not penitent and shriven in this present life; for all the creatures in heaven, and in earth, and in hell, shall see apertly all that he hideth in this world.\n\nNow for to speak of them that be so negligent and slow to shrive them; that stands in two manners. The one is, that he hopeth to live long, and to purchase much riches for his delight, and then he will shrive him: and, as he sayeth, he may, as him seemeth, timely enough come to shrift: another is, the surquedrie that he hath in Christ's mercy. Against the first vice, he shall think that our life is in no sickerness, and eke that all the riches in this world be in adventure, and pass as a shadow on the wall; and, as saith St Gregory, that it appertaineth to the great righteousness of God, that never shall the pain stint of them, that never would withdraw them from sin, their thanks, but aye continue in sin; for that perpetual will to do sin shall they have perpetual pain. Wanhope is in two manners. The first wanhope is, in the mercy of God: the other is, that they think they might not long persevere in goodness. The first wanhope cometh of that he deemeth that he sinned so highly and so oft, and so long hath lain in sin, that he shall not be saved. Certes against that cursed wanhope should he think, that the passion of Jesus Christ is more strong for to unbind, than sin is strong for to bind. Against the second wanhope he shall think, that as oft as he falleth, he may arise again by penitence; and though he never so long hath lain in sin, the mercy of Christ is always ready to receive him to mercy. Against the wanhope that he thinketh he should not long persevere in goodness, he shall think that the feebleness of the devil may nothing do, but men will suffer him; and eke he shall have strength of the help of God, and of all Holy Church, and of the protection of angels, if him list.\n\nThen shall men understand, what is the fruit of penance; and after the word of Jesus Christ, it is the endless bliss of heaven, where joy hath no contrariety of woe nor of penance nor grievance; there all harms be passed of this present life; there as is the sickerness from the pain of hell; there as is the blissful company, that rejoice them evermore each of the other's joy; there as the body of man, that whilom was foul and dark, is more clear than the sun; there as the body of man that whilom was sick and frail, feeble and mortal, is immortal, and so strong and so whole, that there may nothing apair it; there is neither hunger, nor thirst, nor cold, but every soul replenished with the sight of the perfect knowing of God. This blissful regne may men purchase by poverty spiritual, and the glory by lowliness, the plenty of joy by hunger and thirst, the rest by travail, and the life by death and mortification of sin; to which life He us bring, that bought us with his precious blood! Amen.\n\n\n## Prayer of Chaucer\n\nNow do I pray all those who hear this little treatise, or\nread it, that, if there be within it anything that pleases them,\nthey thank Our Lord Jesus Christ, from Whom proceeds\nall understanding and all goodness. And if there be anything that\ndispleases them, I pray them, also, that they impute it\nto the fault of my ignorance and not to my intention, which would\nfain have better said if I had had knowledge. For our\nBook says, All that is written is written for our instruction;\nand that was my intention. Wherefore I meekly beseech you that, for\nthe sake of God's mercy, you pray for me that Christ have mercy\nupon me and forgive me my trespasses and especially for my translations\nand the writing of worldly vanities, the which I withdraw in my\nretractations:\nas, The Book of Troilus; also The Book of Fame; The Book of\nthe Nineteen Ladies; The Book of the Duchess; The Book of Saint\nValentine's Day, Of the Parliament of Birds; The Tales of Canterbury,\nthose that tend toward sin; The Book of the Lion; and many\nanother book, were they in my remembrance; and many a song and\nmany a lecherous lay,- as to which may Christ, of His great mercy, forgive\nme the sin. But for the translation of Boethius's de Consolatione,\nand other books of legends of saints, and homilies, and of morality\nand devotion- for those I thank Our Lord Jesus Christ and His Blessed\nMother and all the saints of Heaven; beseeching them that they,\nhenceforth unto my life's end, send me grace whereof to bewail my\nsins, and to study for the salvation of my soul:- and grant\nme the grace of true penitence, confession, and expiation\nin this present life; through the benign grace of Him Who\nis King of kings and Priest over all priests, Who redeemed us\nwith the precious blood of His heart; so that I may be one of\nthose, at the day of doom, that shall be saved: Qui cum patre, etc.\nHere Ends The Book Of The Tales Of Canterbury, Written By\nGeoffrey Chaucer, On Whose Soul May Jesus Christ Have Mercy. Amen.\n\n"}]};
